/* ===== XSS mitigation helpers (v6.7.1-fix) ===== */
function escapeHtml(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function safeAttr(str) {
  return escapeHtml(str).replace(/`/g, '&#96;');
}
/** Allow only http(s) or data:image/* URLs for img/src links */
function safeUrl(url) {
  if (url == null || url === '') return '';
  var u = String(url).trim();
  if (/^https?:\/\//i.test(u)) return u.replace(/"/g, '%22').replace(/'/g, '%27');
  if (/^data:image\/(png|jpeg|jpg|gif|webp|svg\+xml);/i.test(u)) return u;
  return '';
}
function safeAddr(addr) {
  if (!addr) return '';
  var a = String(addr);
  if (/^0x[a-fA-F0-9]{40}$/.test(a)) return a;
  // still escape non-standard values
  return escapeHtml(a);
}
try {
  window.escapeHtml = escapeHtml;
  window.safeAttr = safeAttr;
  window.safeUrl = safeUrl;
  window.safeAddr = safeAddr;
} catch (e) {}

/* ===== Native-safe open (web + Capacitor) ===== */
function brOpen(url) {
  if (!url) return;
  try {
    if (window.BRNative && typeof BRNative.openExternal === 'function') {
      BRNative.openExternal(url);
      return;
    }
  } catch (e) {}
  try {
    window.open(url, '_blank', 'noopener,noreferrer');
  } catch (e2) {
    try { window.open(url, '_blank'); } catch (e3) {}
  }
}
try { window.brOpen = brOpen; } catch (e) {}

