function brWarn(){ if (window.BR_DEBUG && typeof console !== 'undefined') console.warn.apply(console, arguments); }

function loadNetworkTokens(netId){
  var list = NET_TOKENS[netId] || NET_TOKENS.base;
  // merge custom tokens for this network
  var custom = [];
  try{ custom = JSON.parse(localStorage.getItem('br_custom_'+netId)||'[]'); }catch(e){}
  state.tokens = list.map(function(t){ return Object.assign({}, t); }).concat(custom);
  state.balances = {};
  // native symbol id for balance
  state.swapFrom = state.tokens[0] ? state.tokens[0].id : 'ETH';
  state.swapTo = state.tokens[1] ? state.tokens[1].id : state.swapFrom;
}

function renderManageTokens(){
  if(!state.hiddenTokens) state.hiddenTokens = JSON.parse(localStorage.getItem('br_hidden_tokens')||'[]');
  var q = ((document.getElementById('mtSearch')||{}).value||'').toLowerCase();
  var active = document.getElementById('mtActive');
  var popular = document.getElementById('mtPopular');
  if(!active || !popular) return;

  function row(t, isPopular){
    var hid = state.hiddenTokens.indexOf(t.id) >= 0;
    if(isPopular && !hid && state.tokens.find(function(x){return x.id===t.id;})) {
      // already in active list
    }
    var bal = state.balances[t.id]||0;
    var price = state.prices[t.id]||0;
    var usd = bal*price;
    var risk = (t.symbol && t.symbol.length > 8) ? '<span class="badge-risk">⚠</span>' : '';
    var checked = !hid;
    var rawAddr = t.address ? (String(t.address).slice(0,4)+'...'+String(t.address).slice(-4)) : (t.name||'');
    var addr = escapeHtml(rawAddr);
    var sym = escapeHtml(t.symbol || '');
    var tid = safeAttr(t.id || '');
    var icon = safeUrl(t.icon || '');
    return '<div class="mt-row">'+
      '<div class="token-icon"><img src="'+icon+'" alt=""></div>'+
      '<div class="info"><div class="n">'+sym+' '+risk+'</div><div class="s">'+addr+'</div></div>'+
      '<div class="bal"><div class="a">'+fmtAmt(bal)+'</div><div class="u">'+fmtUsd(usd)+'</div></div>'+
      '<label class="toggle"><input type="checkbox" data-tid="'+tid+'" '+(checked?'checked':'')+'><span class="slider"></span></label>'+
      '</div>';
  }

  var filtered = state.tokens.filter(function(t){
    if(!q) return true;
    return (t.symbol||'').toLowerCase().indexOf(q)>=0 || (t.name||'').toLowerCase().indexOf(q)>=0 || (t.address||'').toLowerCase().indexOf(q)>=0;
  });
  active.innerHTML = filtered.map(function(t){ return row(t,false); }).join('') || '<div class="empty">Tidak ada token</div>';

  // popular = default list for current net not yet emphasized
  var netId = state.network || 'base';
  var pop = (NET_TOKENS[netId]||[]).filter(function(t){
    if(!q) return true;
    return (t.symbol||'').toLowerCase().indexOf(q)>=0 || (t.name||'').toLowerCase().indexOf(q)>=0;
  });
  popular.innerHTML = pop.map(function(t){ return row(t,true); }).join('');

  document.querySelectorAll('#screen-manage input[data-tid]').forEach(function(inp){
    inp.onchange = function(){
      var id = inp.getAttribute('data-tid');
      if(!state.hiddenTokens) state.hiddenTokens = [];
      var i = state.hiddenTokens.indexOf(id);
      if(inp.checked){
        if(i>=0) state.hiddenTokens.splice(i,1);
      } else {
        if(i<0) state.hiddenTokens.push(id);
      }
      localStorage.setItem('br_hidden_tokens', JSON.stringify(state.hiddenTokens));
      if(typeof renderHome==='function') renderHome(); if(typeof updateBerandaHeader==='function') updateBerandaHeader();
    };
  });
}

function currentNet(){
  return NETWORKS.find(function(n){return n.id===(state.network||'base')}) || NETWORKS[0];
}

function openNetworkPicker(){
  var html = '<div class="flex-between" style="margin-bottom:12px"><h3 style="margin:0">Pilih jaringan</h3><button class="btn btn-sm btn-ghost" onclick="closeModal()">✕</button></div>';
  html += '<div class="field" style="margin-bottom:10px"><input id="netSearch" placeholder="🔍 Cari jaringan" oninput="filterNets()"></div>';
  html += '<div id="netList"></div>';
  html += '<button class="btn btn-ghost" style="max-width:none;margin-top:12px;border-radius:24px" onclick="showToast(\'Jaringan kustom: hubungi pengembang\')">+ Tambahkan jaringan</button>';
  openModal(html);
  renderNetList('');
}
function filterNets(){
  var q = (document.getElementById('netSearch')&&document.getElementById('netSearch').value||'').toLowerCase();
  renderNetList(q);
}

function renderNetList(q){
  var list = document.getElementById('netList'); if(!list) return;
  var nets = NETWORKS.filter(function(n){return !q || n.name.toLowerCase().indexOf(q)>=0});
  list.innerHTML = nets.map(function(n){
    var on = (state.network||'base') === n.id;
    if(n.id==='all' && state.network==='all') on = true;
    var tag = (n.kind!=='evm' && n.kind!=='all') ? ' <span class="dep-badge">Non-EVM</span>' : '';
    var img = '<img src="'+n.ico+'" alt="" class="net-logo" onerror="this.parentNode.textContent=\'●\'">';
    return '<div class="net-item'+(on?' on':'')+'" data-net="'+n.id+'"><div class="net-ico" style="background:'+n.color+'22">'+img+'</div><div class="net-name">'+n.name+tag+'</div>'+(on?'<span class="net-check">✓</span>':'')+'</div>';
  }).join('');
  list.querySelectorAll('[data-net]').forEach(function(el){
    el.onclick = function(){ selectNetwork(el.getAttribute('data-net')); };
  });
}



async function brRequireSolanaUnlock(nextNetworkId){
  // Solana in-wallet secrets are PIN-encrypted. Never enter Solana while the
  // PIN vault is locked, and never bypass the existing PIN overlay.
  var encrypted = false;
  try {
    encrypted = !!(typeof PinCrypto !== 'undefined' && PinCrypto.isEncrypted && PinCrypto.isEncrypted());
  } catch (e) {}

  var unlocked = false;
  try {
    unlocked = !!(state && state._unlocked && typeof PinCrypto !== 'undefined' && PinCrypto._sessionKey);
  } catch (e2) {}

  if (encrypted && unlocked) return true;

  // A PIN vault exists but is locked: show the real PIN screen and resume the
  // requested network switch after successful verification.
  if (encrypted) {
    state._pinMode = 'unlock';
    state.pinMode = 'unlock';
    state.pinBuffer = '';
    state._pinBuf = '';
    state._pinCallback = async function () {
      state._pinCallback = null;
      try { await selectNetwork(nextNetworkId); }
      catch (e) { console.warn('[Sol] resume network switch failed', e); }
    };
    showPinOverlay('Unlock PIN', 'Buka PIN untuk menggunakan wallet Solana');
    return false;
  }

  // No PIN has been configured yet. Set one up before entering Solana so the
  // newly generated/imported secret can be encrypted immediately.
  state._pinMode = 'setup';
  state.pinMode = 'setup';
  state.pinBuffer = '';
  state._pinBuf = '';
  state.pinTemp = '';
  state._pinTemp = '';
  state._pinCallback = async function () {
    state._pinCallback = null;
    try { await selectNetwork(nextNetworkId); }
    catch (e) { console.warn('[Sol] resume network switch failed', e); }
  };
  showPinOverlay('Buat PIN baru', 'Buat PIN sebelum menggunakan wallet Solana');
  return false;
}

async function selectNetwork(id){
  var net = NETWORKS.find(function(n){ return n.id === id; });
  if(!net) return;
  if(net.kind === 'all'){
    id = 'base';
    net = NETWORKS.find(function(n){ return n.id === 'base'; });
  }
  // Solana supported (Jupiter); other non-EVM still blocked
  if(net.kind !== 'evm' && net.kind !== 'sol'){
    showToast(net.name + ' belum didukung — gunakan wallet khusus.', 'warn');
    return;
  }
  if(net.kind === 'sol'){
    // IMPORTANT: do this before changing the active network or closing the
    // network picker. The user must see the PIN overlay immediately.
    if (!(await brRequireSolanaUnlock(id))) return;

    state.network = id;

    RPCS = (net.rpc && net.rpc.length) ? net.rpc.slice() : ['https://api.mainnet-beta.solana.com'];
    CHAIN_ID = null;
    _provider = null; _providerNet = null;
    try{ localStorage.setItem('br_v4_network', id); }catch(e){}
    if(typeof loadNetworkTokens === 'function') loadNetworkTokens(id);
    closeModal();
    if(typeof updateNetworkUI === 'function') updateNetworkUI();
    // CRITICAL: render home token list for Solana (was missing → empty UI)
    try{ if(typeof renderHome === 'function') renderHome(); }catch(e){}
    try{ if(typeof window.applyNetworkUi === 'function') window.applyNetworkUi('sol'); }catch(e){}
    try{ if(typeof window.forceSolRows === 'function') window.forceSolRows(true); }catch(e){}
    showToast('Jaringan: Solana · swap via Jupiter');
    try {
      setTimeout(async function () {
        try {
          if (typeof window.ensureSolanaWallet === 'function') {
            await window.ensureSolanaWallet({ quiet: true });
          }
          if (typeof window.refreshSolanaBalances === 'function') {
            await window.refreshSolanaBalances();
          }
          if (typeof window.forceSolRows === 'function') window.forceSolRows(true);
          if (typeof window.renderReceive === 'function') window.renderReceive();
          if (typeof renderHome === 'function') renderHome();
        } catch (e) { console.warn('[sol select]', e); }
      }, 200);
    } catch (e) {}
    return;
  }
  RPCS = net.rpc.slice();
  CHAIN_ID = net.chainId;
  _provider = null; _providerNet = null;

  try{ localStorage.setItem('br_v4_network', id); }catch(e){}
  if(typeof loadNetworkTokens === 'function') loadNetworkTokens(id);
  closeModal();
  if(typeof updateNetworkUI === 'function') updateNetworkUI();
  showToast('Jaringan: ' + net.name);
  try{ if(window.ethereum){ window.ethereum.chainId = '0x'+getChainId().toString(16); window.ethereum.selectedAddress = state.address; } }catch(e){}

  if(state.address){
    if(typeof refresh === 'function') await refresh(true);
    else if(typeof refreshBalances === 'function') await refreshBalances(true);
  }
  if(typeof renderHome === 'function') renderHome();
  if(typeof renderManageTokens === 'function') renderManageTokens();
}


