function startSeedConfirm(){const words=state.phrase.split(' ');const indices=[];while(indices.length<3){const i=Math.floor(Math.random()*12);if(!indices.includes(i))indices.push(i)}indices.sort((a,b)=>a-b);state.confirmWords=indices.map(i=>({index:i,word:words[i]}));state.confirmStep=0;state.confirmAnswers=[];renderConfirmStep();showScreen('confirm-seed')}
function renderConfirmStep(){const step=state.confirmStep,target=state.confirmWords[step];document.getElementById('confirmWordNum').textContent=target.index+1;document.getElementById('confirmSteps').innerHTML=[0,1,2].map(i=>'<div class="step-dot '+(i<step?'done':i===step?'active':'')+'"></div>').join('');const all=state.phrase.split(' ');const opts=new Set([target.word]);while(opts.size<6)opts.add(all[Math.floor(Math.random()*12)]);document.getElementById('confirmOptions').innerHTML=[...opts].sort(()=>Math.random()-0.5).map(w=>'<button class="confirm-opt" data-word="'+safeAttr(w)+'" onclick="selectConfirmWord(this)">'+escapeHtml(w)+'</button>').join('');document.getElementById('confirmNextBtn').style.display='none'}
