function persistWallet(){
  if(!state.wallet) return;
  var all = [];
  try{ all = JSON.parse(localStorage.getItem('br_wallets_v3')||'[]'); }catch(e){}
  var pinOn = false;
  try {
    pinOn = !!(localStorage.getItem(PIN_KEY) || localStorage.getItem('br_pin_hash') ||
      localStorage.getItem('br_pin_v6') || localStorage.getItem('br_pin_verifier_v2'));
  } catch (e) {}
  // Multi-wallet list: NEVER store privateKey (shell only)
  var shell = {
    address: state.address,
    hasMnemonic: !!state.phrase,
    name: state.walletName || ('Wallet '+(all.length+1)),
    created: Date.now(),
    encrypted: !!pinOn
  };
  var idx = all.findIndex(function(w){ return w.address && state.address && w.address.toLowerCase()===state.address.toLowerCase(); });
  if(idx >= 0) all[idx] = Object.assign({}, all[idx], shell, { privateKey: undefined, phrase: undefined, mnemonic: undefined });
  else all.push(shell);
  // Strip any lingering secrets from list
  all = all.map(function(w){
    if(!w) return w;
    var c = Object.assign({}, w);
    delete c.privateKey; delete c.phrase; delete c.mnemonic; delete c.pk;
    return c;
  });
  localStorage.setItem('br_wallets_v3', JSON.stringify(all));
  // Single-wallet storage: shell only if PIN on; legacy plain only if no PIN
  if (pinOn) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(shell));
  } else {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      address: state.address,
      privateKey: state.wallet.privateKey,
      hasMnemonic: !!state.phrase,
      name: state.walletName || shell.name,
      created: Date.now()
    }));
  }
  var custom = state.tokens.filter(function(t){ return !DEFAULT_TOKENS.find(function(d){ return d.id===t.id; }); });
  localStorage.setItem(TOKENS_KEY, JSON.stringify(custom));
}

function loadWallet(){
  try{
    var data = null;
    var raw = localStorage.getItem(STORAGE_KEY);
    if(raw){
      try{ data = JSON.parse(raw); }catch(e){ data = null; }
    }
    // Fallback: multi-wallet list
    if(!data || (!data.privateKey && !data.address)){
      try{
        var all = JSON.parse(localStorage.getItem('br_wallets_v3')||'[]');
        if(Array.isArray(all) && all.length){
          var active = localStorage.getItem('br_active_addr');
          data = all.find(function(w){ return active && w.address && w.address.toLowerCase()===active.toLowerCase(); }) || all[0];
        }
      }catch(e){}
    }
    if(!data) return false;

    // Full wallet (has private key)
    if (data.privateKey) {
      try {
        var w = new ethers.Wallet(data.privateKey);
        state.wallet = w;
        state.address = w.address;
      } catch (e) {
        state.wallet = null;
        state.address = data.address || null;
      }
    } else if (data.address) {
      // Shell-only (PIN/encrypted) — still restore address for UI
      state.wallet = null;
      state.address = data.address;
    } else {
      return false;
    }

    state.phrase = null;
    state.walletName = data.name || 'Wallet';
    state._unlocked = !!data.privateKey || state._unlocked;
    try{ if (state.address) localStorage.setItem('br_active_addr', state.address); }catch(e){}

    // ALWAYS restore network-specific tokens
    try{
      var netId = state.network || localStorage.getItem('br_v4_network') || 'base';
      state.network = netId;
      if (typeof loadNetworkTokens === 'function') {
        loadNetworkTokens(netId);
      } else if (typeof NET_TOKENS !== 'undefined') {
        state.tokens = (NET_TOKENS[netId] || NET_TOKENS.base || []).map(function(t){ return Object.assign({}, t); });
      }
    }catch(e){}
    return !!state.address;
  }catch(e){ return false; }
}

function lockWallet(){
  // Soft-lock: keep encrypted wallets, ask PIN — jangan buang session ke onboard
  state.wallet=null;
  state.phrase=null;
  state._unlocked=false;
  var hasStored=false;
  try{
    hasStored=!!(localStorage.getItem(STORAGE_KEY)||localStorage.getItem('br_wallets_v3'));
  }catch(e){}
  if(hasStored && localStorage.getItem(PIN_KEY)){
    // stay on a lock screen with PIN
    try{
      state.pinMode='unlock';
      state.pinBuffer='';
      state._pinCallback=function(){
        try{
          if(typeof loadWallet==='function') loadWallet();
          if(state.address){ showScreen('home'); if(typeof refreshBalances==='function') refreshBalances(true); }
          else showScreen('home');
        }catch(e){ showScreen('home'); }
      };
      var pt=document.getElementById('pinTitle');
      var ph=document.getElementById('pinHint');
      if(pt) pt.textContent='Masukkan PIN';
      if(ph) ph.textContent='Wallet terkunci';
      if(typeof updatePinDots==='function') updatePinDots();
      var ov=document.getElementById('pinOverlay');
      if(ov) ov.classList.add('show');
      showToast('Dikunci');
      return;
    }catch(e){}
  }
  // Tidak ada wallet tersimpan → onboard
  state.address=null;
  state.balances={};
  showScreen('onboard');
  showToast('Dikunci');
}
function wipeWallet(){if(!confirm('Hapus semua data wallet? Pastikan sudah backup seed!'))return;['br_wallets_v3','br_active_addr','br_pin_hash','br_pin_v6','br_pin','br_pin_verifier_v2','br_pin_enabled','br_pin_salt','br_kdf_salt','br_kdf_salt_v2','br_enc_verify','br_mnemonic','mnemonic','br_pk','privateKey','br_phrase','br_pending_seed','br_v4_mnemonic','br_v4_pk','br_secure_meta_v1','br_secure_blob_v1','br_vault_v1','br_e2e_vault','br_seed_vault_v1','br_sec_sol_secret_v1','br_sol_secret_v1'].forEach(function(k){try{localStorage.removeItem(k)}catch(e){}});localStorage.removeItem(STORAGE_KEY);localStorage.removeItem(TOKENS_KEY);localStorage.removeItem(PIN_KEY);state={wallet:null,address:null,phrase:null,balances:{},prices:state.prices,tokens:DEFAULT_TOKENS.map(t=>({...t})),hiddenTokens:[], history:[],pinMode:null,pinBuffer:'',pinTemp:'',confirmWords:[],confirmStep:0,confirmAnswers:[],network:'base', swapFrom:'ETH',swapTo:'USDC',tokenPickerSide:null,pinEnabled:false,pinHash:''};showScreen('onboard');showToast('Dihapus')}
/* Strengthened PIN hash (v6.7.1-fix)
 * - Keeps sync API for legacy callers
 * - Much stronger mixing + fixed domain salt + longer output
 * - New setups should prefer PinCrypto (PBKDF2 + AES-GCM verifier)
 * - Verification accepts both new strong form and old weak form (migration)
 */
function hashPinLegacyWeak(pin) {
  var h = 0;
  pin = String(pin || '');
  for (var i = 0; i < pin.length; i++) h = ((h << 5) - h + pin.charCodeAt(i)) | 0;
  return 'br_' + Math.abs(h).toString(36) + pin.length;
}
function hashPin(pin) {
  pin = String(pin || '');
  // Stronger deterministic hash for sync paths (not a substitute for PinCrypto)
  var salt = 'baserocky_v6.7.1_pin_domain_v2';
  var s = salt + '|' + pin + '|' + pin.length + '|' + salt;
  var h1 = 0x811c9dc5, h2 = 0x01000193;
  for (var i = 0; i < s.length; i++) {
    var c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x811c9dc5) >>> 0;
    h1 = (h1 + Math.imul(h2, 0x85ebca6b)) >>> 0;
    h2 = (h2 + Math.imul(h1, 0xc2b2ae35)) >>> 0;
  }
  // Extra mixing rounds
  for (var r = 0; r < 8; r++) {
    h1 = Math.imul(h1 ^ (h1 >>> 16), 0x85ebca6b) >>> 0;
    h2 = Math.imul(h2 ^ (h2 >>> 13), 0xc2b2ae35) >>> 0;
    h1 = (h1 + h2) >>> 0;
    h2 = (h2 + h1) >>> 0;
  }
  var hex = (h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0'));
  return 'br7_' + hex + pin.length.toString(16);
}
/** Verify PIN hash against stored value (supports new + legacy weak) */
function verifyPinHash(pin, stored) {
  if (!stored) return false;
  pin = String(pin || '');
  try {
    if (hashPin(pin) === stored) return true;
  } catch (e) {}
  try {
    if (hashPinLegacyWeak(pin) === stored) return true;
  } catch (e) {}
  return false;
}
function requirePin(cb){if(!localStorage.getItem(PIN_KEY) && !localStorage.getItem('br_pin_verifier_v2') && !localStorage.getItem('br_pin_v6')){cb();return}state.pinMode='verify';state.pinBuffer='';state._pinCallback=cb;document.getElementById('pinTitle').textContent='Masukkan PIN';document.getElementById('pinHint').textContent='Verifikasi identitas';updatePinDots();document.getElementById('pinOverlay').classList.add('show')}
function handlePinComplete(){
  if(state.pinMode==='setup'){
    if(!state.pinTemp){
      state.pinTemp=state.pinBuffer;state.pinBuffer='';
      document.getElementById('pinTitle').textContent='Konfirmasi PIN';
      document.getElementById('pinHint').textContent='Masukkan ulang PIN';
      updatePinDots();return;
    }
    if(state.pinBuffer!==state.pinTemp){
      showToast('PIN tidak cocok');state.pinTemp='';state.pinBuffer='';
      document.getElementById('pinTitle').textContent='Buat PIN Baru';
      document.getElementById('pinHint').textContent='Masukkan 6-digit PIN';
      updatePinDots();return;
    }
    var pinVal = state.pinBuffer;
    state.pinEnabled = true;
    state.pinHash = 'v2';
    document.getElementById('pinOverlay').classList.remove('show');
    state.pinMode = null;
    // Single path: PinCrypto / savePinUnified (async)
    Promise.resolve()
      .then(function () {
        if (typeof savePinUnified === 'function') return savePinUnified(pinVal);
        if (typeof PinCrypto !== 'undefined' && PinCrypto.setup) return PinCrypto.setup(pinVal);
      })
      .then(function () {
        try { if (typeof brAutoMigrateSecrets === 'function') brAutoMigrateSecrets(pinVal); } catch (e) {}
        showToast('PIN terenkripsi aktif');
        try { openSecurityCenter(); } catch (e) {}
      })
      .catch(function (e) {
        showToast('Gagal menyimpan PIN');
        if (window.BR_DEBUG) console.warn(e);
      });
    return;
  }
  if(state.pinMode==='verify'||state.pinMode==='unlock'){
    var pinVal = state.pinBuffer;
    function _onPinOk(){
      document.getElementById('pinOverlay').classList.remove('show');
      state.pinMode=null;
      state._unlocked=true;
      try { if(typeof brAutoMigrateSecrets==='function') brAutoMigrateSecrets(pinVal); } catch (e) {}
      if(state._pinCallback){var cb=state._pinCallback;state._pinCallback=null;cb();}
    }
    function _onPinFail(){
      showToast('PIN salah');state.pinBuffer='';updatePinDots();
    }
    // Prefer PinCrypto (async); legacy sync only as fallback
    if(typeof PinCrypto!=='undefined' && PinCrypto.verify){
      Promise.resolve(PinCrypto.verify(pinVal)).then(function(ok){
        if(ok) _onPinOk(); else _onPinFail();
      }).catch(_onPinFail);
      return;
    }
    var stored=localStorage.getItem(PIN_KEY)||localStorage.getItem('br_pin_v6')||localStorage.getItem('br_pin_hash');
    var ok = (typeof verifyPinHash==='function') ? verifyPinHash(pinVal,stored) : (hashPin(pinVal)===stored);
    if(ok) _onPinOk(); else _onPinFail();
  }
}
/* getProvider: owned by js/network.js (async + RPC failover). Do not redefine here — core loads after network. */

async function refreshBalances(showLoad){
  if(!state.address) return;
  if(showLoad) setLoading(true);
  try{
    // try each RPC until one works
    var provider = null;
    var lastErr = null;
    for(var ri=0; ri<RPCS.length; ri++){
      try{
        provider = new ethers.JsonRpcProvider(RPCS[ri], CHAIN_ID);
        await provider.getBlockNumber();
        state.rpcIdx = ri;
        break;
      }catch(e){ lastErr = e; provider = null; }
    }
    if(!provider) throw lastErr || new Error('No RPC');

    // Fetch ETH balance
    var ethBal = await provider.getBalance(state.address);
    var __nativeBal = Number(ethers.formatEther(ethBal));
    state.balances['ETH'] = __nativeBal;
    var __net = state.network || 'base';
    if(__net === 'bnb') state.balances['BNB'] = __nativeBal;
    if(__net === 'pol'){ state.balances['MATIC'] = __nativeBal; state.balances['POL'] = __nativeBal; }


    // Fetch all known ERC20 in parallel
    var erc20 = state.tokens.filter(function(t){ return t.address; });
    var results = await Promise.all(erc20.map(async function(t){
      try{
        var c = new ethers.Contract(t.address, ['function balanceOf(address) view returns (uint256)'], provider);
        var bal = await c.balanceOf(state.address);
        return {id:t.id, bal:Number(ethers.formatUnits(bal, t.decimals))};
      }catch(e){ return {id:t.id, bal:0}; }
    }));
    results.forEach(function(r){ state.balances[r.id] = r.bal; });

    // Auto-discover tokens via Basescan tokentx (tokens this address has interacted with)
    try{
      await discoverTokens(provider);
    }catch(e){ console.log('discover skip', e); }

    await fetchPrices();
    renderHome();
    if(document.getElementById('screen-swap') && document.getElementById('screen-swap').classList.contains('active')) renderSwapUI();
  }catch(e){
    console.error(e);
    // Still paint token list at 0 so home is never blank
    try {
      if (!state.tokens || !state.tokens.length) {
        var netId = state.network || localStorage.getItem('br_v4_network') || 'base';
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens(netId);
      }
      if (typeof renderHome === 'function') renderHome();
    } catch (e2) {}
    showToast('Gagal memuat saldo — coba Refresh');
  }finally{
    if(showLoad) setLoading(false);
  }
}


async function discoverTokens(provider){
  // Use Basescan API to find ERC20 tokens held
  try{
    var url = 'https://api.basescan.org/api?module=account&action=addresstokenbalance&address='+state.address+'&page=1&offset=50';
    var res = await fetch(url, {signal: AbortSignal.timeout(6000)});
    var data = await res.json();
    if(data.status === '1' && Array.isArray(data.result)){
      data.result.forEach(function(item){
        var addr = (item.TokenAddress || item.tokenAddress || '').toLowerCase();
        if(!addr || addr === '0x') return;
        var exists = state.tokens.find(function(t){ return t.address && t.address.toLowerCase() === addr; });
        if(exists){
          // update balance from API if available
          var raw = item.TokenQuantity || item.tokenQuantity || item.balance;
          if(raw !== undefined){
            var dec = parseInt(item.TokenDivisor || item.tokenDivisor || exists.decimals || 18);
            state.balances[exists.id] = Number(raw) / Math.pow(10, dec);
          }
          return;
        }
        var sym = item.TokenSymbol || item.tokenSymbol || 'TKN';
        var name = item.TokenName || item.tokenName || sym;
        var dec = parseInt(item.TokenDivisor || item.tokenDivisor || 18);
        var id = sym.toUpperCase() + '_' + addr.slice(2,6);
        var qty = item.TokenQuantity || item.tokenQuantity || '0';
        state.tokens.push({
          id: id, symbol: sym.toUpperCase(), name: name, decimals: dec,
          address: item.TokenAddress || item.tokenAddress,
          icon: 'https://assets.coingecko.com/coins/images/1/small/bitcoin.png',
          coingecko: null
        });
        state.balances[id] = Number(qty) / Math.pow(10, dec);
      });
      persistWallet();
      return;
    }
  }catch(e){ console.log('basescan tokenbalance fail', e); }

  // Fallback: recent tokentx
  try{
    var url2 = 'https://api.basescan.org/api?module=account&action=tokentx&address='+state.address+'&page=1&offset=100&sort=desc';
    var res2 = await fetch(url2, {signal: AbortSignal.timeout(6000)});
    var data2 = await res2.json();
    if(data2.status === '1' && Array.isArray(data2.result)){
      var seen = {};
      data2.result.forEach(function(tx){
        var addr = (tx.contractAddress || '').toLowerCase();
        if(!addr || seen[addr]) return;
        seen[addr] = true;
        var exists = state.tokens.find(function(t){ return t.address && t.address.toLowerCase() === addr; });
        if(exists) return;
        var sym = tx.tokenSymbol || 'TKN';
        var dec = parseInt(tx.tokenDecimal || 18);
        var id = sym.toUpperCase() + '_' + addr.slice(2,6);
        state.tokens.push({
          id: id, symbol: sym.toUpperCase(), name: tx.tokenName || sym, decimals: dec,
          address: tx.contractAddress,
          icon: 'https://assets.coingecko.com/coins/images/1/small/bitcoin.png',
          coingecko: null
        });
      });
      // re-fetch balances for newly added
      var newly = state.tokens.filter(function(t){ return t.address && seen[t.address.toLowerCase()]; });
      await Promise.all(newly.map(async function(t){
        try{
          var c = new ethers.Contract(t.address, ['function balanceOf(address) view returns (uint256)'], provider);
          var bal = await c.balanceOf(state.address);
          state.balances[t.id] = Number(ethers.formatUnits(bal, t.decimals));
        }catch(e){}
      }));
      persistWallet();
    }
  }catch(e){ console.log('tokentx fail', e); }
}




async function fetchPrices(){
  if(!state.changes) state.changes = {};
  if(!state.prices) state.prices = {};

  var ids = [];
  state.tokens.forEach(function(t){
    var k = t.cg || t.coingecko;
    if(k && ids.indexOf(k) < 0) ids.push(k);
  });

  var gotAny = false;

  // 1) Primary: CoinGecko simple price
  if(ids.length){
    try{
      var url = 'https://api.coingecko.com/api/v3/simple/price?ids='+encodeURIComponent(ids.join(','))+'&vs_currencies=usd&include_24hr_change=true';
      var res = await fetch(url, { signal: AbortSignal.timeout(9000), headers: { 'Accept': 'application/json' } });
      if(res.ok){
        var data = await res.json();
        state.tokens.forEach(function(t){
          var key = t.cg || t.coingecko;
          if(key && data[key]){
            if(data[key].usd != null){ state.prices[t.id] = data[key].usd; gotAny = true; }
            if(typeof data[key].usd_24h_change === 'number') state.changes[t.id] = data[key].usd_24h_change;
          }
        });
      }
    }catch(e){ console.log('coingecko fail', e && e.message); }
  }

  // 2) Fallback: Binance 24hr ticker for majors
  if(!gotAny || !state.prices.ETH){
    try{
      var map = { ethereum:'ETHUSDT', 'usd-coin':'USDCUSDT', tether:'USDTUSDT', 'binancecoin':'BNBUSDT', 'matic-network':'MATICUSDT' };
      var pairs = [];
      state.tokens.forEach(function(t){
        var key = t.cg || t.coingecko;
        if(key && map[key]) pairs.push({ id:t.id, pair:map[key] });
      });
      await Promise.all(pairs.map(async function(p){
        try{
          var r = await fetch('https://api.binance.com/api/v3/ticker/24hr?symbol='+p.pair, { signal: AbortSignal.timeout(5000) });
          if(!r.ok) return;
          var d = await r.json();
          if(d.lastPrice){ state.prices[p.id] = parseFloat(d.lastPrice); gotAny = true; }
          if(d.priceChangePercent != null) state.changes[p.id] = parseFloat(d.priceChangePercent);
        }catch(err){}
      }));
    }catch(e2){}
  }

  // 3) DexScreener for Base tokens missing price (by contract)
  try{
    var missing = (state.tokens || []).filter(function(t){
      return t.address && (state.prices[t.id] == null || state.prices[t.id] === 0);
    }).slice(0, 8);
    await Promise.all(missing.map(async function(t){
      try{
        var r = await fetch('https://api.dexscreener.com/latest/dex/tokens/' + t.address, { signal: AbortSignal.timeout(6000) });
        if(!r.ok) return;
        var d = await r.json();
        var pairs = d && d.pairs;
        if(!pairs || !pairs.length) return;
        // Prefer Base chain pair with highest liquidity
        var basePairs = pairs.filter(function(p){ return (p.chainId || '').toLowerCase() === 'base'; });
        var best = (basePairs.length ? basePairs : pairs).sort(function(a,b){
          return (parseFloat(b.liquidity && b.liquidity.usd) || 0) - (parseFloat(a.liquidity && a.liquidity.usd) || 0);
        })[0];
        if(best && best.priceUsd){
          state.prices[t.id] = parseFloat(best.priceUsd);
          gotAny = true;
          if(best.priceChange && typeof best.priceChange.h24 === 'number'){
            state.changes[t.id] = best.priceChange.h24;
          }
        }
      }catch(err){}
    }));
  }catch(e3){}

  // Stable defaults
  if(state.prices.ETH) state.prices.WETH = state.prices.ETH;
  if(!state.prices.USDC) state.prices.USDC = 1;
  if(!state.prices.USDT) state.prices.USDT = 1;
  if(!state.prices.DAI) state.prices.DAI = 1;
  if(!state.prices.ETH) state.prices.ETH = state.prices.ETH || 3000;

  state._lastPriceAt = Date.now();
  try{ localStorage.setItem('br_prices_cache', JSON.stringify({ at: state._lastPriceAt, prices: state.prices, changes: state.changes })); }catch(e){}
  return gotAny;
}



function fmtAmt(n){if(n===0)return'0';if(n<0.000001)return n.toExponential(2);if(n<1)return n.toFixed(6).replace(/\.?0+$/,'');if(n<1000)return n.toFixed(4).replace(/\.?0+$/,'');return n.toLocaleString('en-US',{maximumFractionDigits:2})}
function fmtUsd(n){if(n>0&&n<0.01)return'<$0.01';return'$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}

function renderHome(){

  var sec = document.querySelector('.section-token');
  if(!sec){
    var tl = document.getElementById('tokenList');
    if(tl && !document.getElementById('tokenFilterBtn')){
      var bar = document.createElement('div');
      bar.className = 'section-token';
      bar.innerHTML = '<span class="left">Token <span id="tokenTotalLabel"></span></span><button class="filter-btn" id="tokenFilterBtn" onclick="openTokenSettings()">⚙</button>';
      tl.parentNode.insertBefore(bar, tl);
    }
  }

  var total=0;
  // Always-visible defaults per network (0 balance still shown)
  var core=['ETH','BROCK','USDC','USDT','AERO','WETH','SOL','BNB','MATIC','POL','AVAX','BTC','BONK','JUP','WIF'];
  if(!state.tokens || !state.tokens.length){
    try{
      if(typeof loadNetworkTokens==='function') loadNetworkTokens(state.network||'base');
    }catch(e){}
  }
  var rows=(state.tokens||[]).map(function(t){
    var bal=state.balances[t.id]||0;
    var price=state.prices[t.id]||0;
    var usd=bal*price;
    total+=usd;
    return {t:t,bal:bal,price:price,usd:usd};
  }).filter(function(x){
    if(state.hiddenTokens && state.hiddenTokens.indexOf(x.t.id)>=0) return false;
    if(state.hideDust && x.usd < 0.1 && core.indexOf(x.t.id)<0 && core.indexOf(x.t.symbol)<0) return false;
    if(state.hideRisk && x.t.symbol && x.t.symbol.length>6 && x.usd<1 && core.indexOf(x.t.id)<0) return false;
    // Show if has balance OR is a core/default token for the list
    if(x.bal>1e-12) return true;
    if(core.indexOf(x.t.id)>=0 || core.indexOf(x.t.symbol)>=0) return true;
    // On Solana show all configured SPL defaults even at 0
    if((state.network==='sol') && (x.t.mint || x.t.symbol==='SOL')) return true;
    return false;
  })
    .sort(function(a,b){ return b.usd-a.usd; });

  var list=document.getElementById('tokenList');
  if(!list){
    try{ if(typeof window.ensureTokenListEl==='function') list=window.ensureTokenListEl(); }catch(e){}
  }
  if(!list) return;
  
  list.innerHTML=rows.map(function(r){
    var t=r.t, bal=r.bal, price=r.price, usd=r.usd;
    var chg = state.changes && state.changes[t.id];
    var chgHtml = '';
    if(typeof chg === 'number'){
      var cls = chg>=0 ? 'tok-up' : 'tok-down';
      var sign = chg>=0 ? '+' : '';
      chgHtml = '<span class="'+cls+'">'+sign+chg.toFixed(2)+'%</span>';
    } else {
      chgHtml = '<span class="tok-flat">—</span>';
    }
    var priceStr = '';
    if(price >= 1000) priceStr = '$'+price.toLocaleString('en-US',{maximumFractionDigits:2});
    else if(price >= 1) priceStr = '$'+price.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
    else if(price >= 0.01) priceStr = '$'+price.toFixed(4);
    else if(price > 0) priceStr = '$'+price.toPrecision(4);
    var img = safeUrl(t.icon || '');
    var balStr = fmtAmt(bal);
    if(bal > 0 && bal < 0.0001) balStr = '&lt;0.0001';
    var sym = escapeHtml(t.symbol || '');
    var tid = safeAttr(t.id || '');
    return '<div class="token-row" data-tid="'+tid+'">'+
      '<div class="token-icon"><img src="'+img+'" alt="'+sym+'" loading="lazy" referrerpolicy="no-referrer"></div>'+
      '<div class="token-info"><div class="name">'+sym+'</div>'+
      '<div class="sym"><span class="tok-price">'+priceStr+'</span> '+chgHtml+'</div></div>'+
      '<div class="token-bal"><div class="amt">'+balStr+'</div>'+
      '<div class="usd">'+fmtUsd(usd)+'</div></div></div>';
  }).join('') || '<div class="empty">Tidak ada token</div>';

  list.querySelectorAll('.token-row').forEach(function(row){
    row.onclick=function(){ if(typeof showToken==='function') showToken(row.getAttribute('data-tid')); else if(typeof showTokenDetail==='function') showTokenDetail(row.getAttribute('data-tid')); };
  });
  var tu=document.getElementById('totalUsd'); if(tu) tu.textContent=fmtUsd(total);
  var ttl=document.getElementById('tokenTotalLabel'); if(ttl) ttl.textContent=fmtUsd(total);
  var hn=document.getElementById('homeWalletName'); if(hn) hn.textContent=state.walletName||'Wallet';
  var hs=document.getElementById('homeWalletShort'); if(hs&&state.address) hs.textContent='('+state.address.slice(-4)+')';
  var bb=document.getElementById('berandaBal'); if(bb) bb.textContent=fmtUsd(total);
  var shortEl=document.getElementById('addrShort');
  if(shortEl) shortEl.textContent=state.address?state.address.slice(0,6)+'...'+state.address.slice(-4):'—';
}





function populateSendTokens(){document.getElementById('sendToken').innerHTML=state.tokens.filter(t=>(state.balances[t.id]||0)>0||['ETH','BROCK','USDC'].includes(t.id)).map(t=>'<option value="'+safeAttr(t.id)+'">'+escapeHtml(t.symbol)+' — '+escapeHtml(t.name||'')+'</option>').join('')}
function updateSendAvail(){const id=document.getElementById('sendToken').value;document.getElementById('sendAvail').textContent=fmtAmt(state.balances[id]||0)+' '+id;estimateGas()}
function setMaxSend(){const id=document.getElementById('sendToken').value;let bal=state.balances[id]||0;if(id==='ETH')bal=Math.max(0,bal-0.0001);document.getElementById('sendAmt').value=bal>0?String(bal):'0';estimateGas()}
async function sendTx(){const id=document.getElementById('sendToken').value;const to=(document.getElementById('sendTo').value||'').trim();const amtStr=(document.getElementById('sendAmt').value||'').trim();if(!ethers.isAddress(to))return showToast('Alamat tidak valid');if(!amtStr||isNaN(amtStr)||Number(amtStr)<=0)return showToast('Jumlah tidak valid');const token=state.tokens.find(t=>t.id===id);if(!token)return;requirePin(async()=>{setLoading(true);try{const provider=await getProvider();const signer=state.wallet.connect(provider);let tx;if(!token.address)tx=await signer.sendTransaction({to,value:ethers.parseEther(amtStr)});else{const c=new ethers.Contract(token.address,['function transfer(address,uint256) returns (bool)'],signer);tx=await c.transfer(to,ethers.parseUnits(amtStr,token.decimals))}showToast('Dikirim…');await tx.wait();showToast('Berhasil!');document.getElementById('sendTo').value='';document.getElementById('sendAmt').value='';refreshBalances(false);showScreen('home')}catch(e){showToast((e.reason||e.shortMessage||e.message||'Gagal').slice(0,80))}finally{setLoading(false)}})}
function copyAddress(){if(!state.address)return;navigator.clipboard.writeText(state.address).then(()=>showToast('Alamat disalin')).catch(()=>{})}
function openExplorer(){if(state.address)openExplorerAddr()}
async function loadHistory(force){if(!state.address)return;const list=document.getElementById('txList');if(!force&&state.history.length){renderHistory();return}list.innerHTML='<div class="empty-state"><div class="spinner" style="margin:0 auto 10px"></div><p>'+((typeof I18N!=='undefined'&&I18N.t)?I18N.t('loading'):'Memuat…')+'</p></div>';try{const url='https://api.basescan.org/api?module=account&action=txlist&address='+state.address+'&startblock=0&endblock=99999999&page=1&offset=25&sort=desc';const res=await fetch(url,{signal:AbortSignal.timeout(8000)});const data=await res.json();state.history=(data.status==='1'&&Array.isArray(data.result))?data.result.slice(0,25):[];renderHistory()}catch{list.innerHTML='<div class="empty-state"><div class="ico">📜</div><p>Gagal memuat</p><button class="btn btn-ghost btn-sm mt-12" onclick="openExplorer()">Basescan</button></div>'}}
function renderHistory(){
  var list=document.getElementById('txList');
  if(!state.history.length){list.innerHTML='<div class="empty-state" data-i18n-stable="1"><div class="ico">📜</div><p>'+(typeof I18N!=='undefined'&&I18N.t?I18N.t('empty_tx'):'Belum ada transaksi')+'</p></div>';return}
  list.innerHTML=state.history.map(function(tx){
    var isOut=tx.from.toLowerCase()===state.address.toLowerCase();
    var failed=tx.isError==='1';
    var val=Number(ethers.formatEther(tx.value||'0'));
    var date=new Date(Number(tx.timeStamp)*1000);
    var timeStr=date.toLocaleDateString('id-ID',{day:'numeric',month:'short'})+' '+date.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});
    var iconClass=failed?'fail':(isOut?'out':'in');
    var icon=failed?'x':(isOut?'↑':'↓');
    var title=failed?'Gagal':((typeof I18N!=='undefined'&&I18N.t?(isOut?I18N.t('tx_send'):I18N.t('tx_receive')):(isOut?'Kirim':'Terima')));
    var counter=isOut?tx.to:tx.from;
    var short=counter?escapeHtml(String(counter).slice(0,6)+'...'+String(counter).slice(-4)):'—';
    var hash = String(tx.hash||'').replace(/[^a-fA-F0-9x]/g,'');
    var safeHash = /^0x[a-fA-F0-9]{64}$/.test(hash) ? hash : '';
    var openJs = safeHash ? ("brOpen('https://basescan.org/tx/"+safeHash+"')") : "void(0)";
    return '<div class="tx-row" onclick="'+openJs+'"><div class="tx-icon '+iconClass+'">'+icon+'</div><div class="tx-info"><div class="title">'+escapeHtml(title)+'</div><div class="meta">'+short+' · '+escapeHtml(timeStr)+'</div></div><div class="tx-amt '+(isOut?'':'pos')+'">'+(isOut?'-':'+')+fmtAmt(val)+' ETH</div></div>';
  }).join('');
}

function getToken(id){return state.tokens.find(t=>t.id===id)}
function renderSwapUI(){const from=getToken(state.swapFrom),to=getToken(state.swapTo);if(!from||!to)return;document.getElementById('swapFromSym').textContent=from.symbol;document.getElementById('swapToSym').textContent=to.symbol;var fi=document.getElementById('swapFromIcon'),ti=document.getElementById('swapToIcon');if(fi)fi.src=safeUrl(from.icon)||'';if(ti)ti.src=safeUrl(to.icon)||'';document.getElementById('swapFromBal').textContent=fmtAmt(state.balances[from.id]||0)+' '+from.symbol;document.getElementById('swapToBal').textContent=fmtAmt(state.balances[to.id]||0)+' '+to.symbol;calcSwapOut()}
function calcSwapOut(){const from=getToken(state.swapFrom),to=getToken(state.swapTo);if(!from||!to)return;const amt=parseFloat(document.getElementById('swapAmtFrom').value)||0;const pFrom=state.prices[from.id]||0,pTo=state.prices[to.id]||1;const fromUsdEl=document.getElementById('swapFromUsd');const toUsdEl=document.getElementById('swapToUsd');if(fromUsdEl)fromUsdEl.textContent=(amt*pFrom).toFixed(2);if(pFrom&&pTo&&amt>0){const out=(amt*pFrom/pTo)*0.997;document.getElementById('swapAmtTo').value=fmtAmt(out);if(toUsdEl)toUsdEl.textContent=(out*pTo).toFixed(2);document.getElementById('swapRate').textContent='1 '+from.symbol+' ≈ '+fmtAmt(pFrom/pTo)+' '+to.symbol}else{document.getElementById('swapAmtTo').value='';if(toUsdEl)toUsdEl.textContent='0.00';document.getElementById('swapRate').textContent='1 '+from.symbol+' ≈ — '+to.symbol}}
function flipSwap(){const tmp=state.swapFrom;state.swapFrom=state.swapTo;state.swapTo=tmp;const a=document.getElementById('swapAmtFrom').value;document.getElementById('swapAmtFrom').value=document.getElementById('swapAmtTo').value;document.getElementById('swapAmtTo').value=a;renderSwapUI()}
function setMaxSwap(){const bal=state.balances[state.swapFrom]||0;let max=bal;if(state.swapFrom==='ETH')max=Math.max(0,bal-0.00015);document.getElementById('swapAmtFrom').value=max>0?String(max):'0';calcSwapOut()}
function openTokenPicker(side){
  state.tokenPickerSide=side;
  var html=state.tokens.map(function(t){
    return '<div class="token-row" style="margin-bottom:4px" onclick="pickSwapToken(\''+t.id+'\')"><div class="token-icon"><img src="'+t.icon+'" alt=""></div><div class="token-info"><div class="name">'+t.name+'</div><div class="sym">'+t.symbol+'</div></div><div class="token-bal"><div class="amt">'+fmtAmt(state.balances[t.id]||0)+'</div></div></div>';
  }).join('');
  openModal('<h3>Pilih Token</h3>'+html);
}

function pickSwapToken(id){if(state.tokenPickerSide==='from'){if(id===state.swapTo)state.swapTo=state.swapFrom;state.swapFrom=id}else{if(id===state.swapFrom)state.swapFrom=state.swapTo;state.swapTo=id}closeModal();renderSwapUI()}
function executeSwap(){const from=getToken(state.swapFrom),to=getToken(state.swapTo);const amt=document.getElementById('swapAmtFrom').value;if(!amt||Number(amt)<=0)return showToast((typeof I18N!=='undefined'&&I18N.t)?I18N.t('enter_amount'):'Masukkan jumlah');const tokenMap={ETH:'ETH',BROCK:BROCK,USDC:'0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913',AERO:'0x940181a94A35A4569E4529A3CDfB74e38FD98631',WETH:'0x4200000000000000000000000000000000000006'};const url='https://app.uniswap.org/swap?chain=base&inputCurrency='+(tokenMap[from.id]||'ETH')+'&outputCurrency='+(tokenMap[to.id]||'ETH')+'&value='+amt;brOpen(url);showToast('Membuka Uniswap untuk konfirmasi')}





function filterDappCat(btn){document.querySelectorAll('.dapp-cat').forEach(function(b){b.classList.remove('active')});btn.classList.add('active');dappCat=btn.dataset.cat;filterDapps()}
function filterDapps(){
  var q=(document.getElementById('dappSearch')&&document.getElementById('dappSearch').value||'').toLowerCase();
  var list=document.getElementById('dappList');
  if(!list) return;
  var filtered=DAPPS.filter(function(d){
    var matchCat=dappCat==='all'||d.cat===dappCat||d.cat==='all';
    var matchQ=!q||d.name.toLowerCase().indexOf(q)>=0||d.desc.toLowerCase().indexOf(q)>=0;
    return matchCat&&matchQ;
  });
  list.innerHTML=filtered.map(function(d){
    return '<div class="token-row" style="cursor:pointer" onclick="brOpen(\''+d.url+'\')"><div class="token-icon" style="font-size:1.3rem;background:var(--card2)">'+d.ico+'</div><div class="token-info"><div class="name">'+d.name+'</div><div class="sym">'+d.desc+'</div></div><div style="color:var(--muted)">></div></div>';
  }).join('')||'<div class="empty-state"><p>Tidak ada DApp</p></div>';
}


