    var words=state.phrase.split(' ').map(function(w,i){return '<div class="seed-word"><span>'+(i+1)+'.</span>'+w+'</div>'}).join('');
    openModal('<h3>Secret Phrase</h3><div class="card danger-box">Jangan bagikan. Simpan offline.</div><div class="seed-grid">'+words+'</div><button class="btn btn-primary" style="max-width:none;margin-top:10px" onclick="navigator.clipboard.writeText(state.phrase);showToast(\'Disalin\');closeModal()">Salin</button>');
