async function addCustomToken(){const addr=(document.getElementById('addTokenAddr').value||'').trim();if(!ethers.isAddress(addr))return showToast('Alamat tidak valid');if(state.tokens.find(t=>t.address&&t.address.toLowerCase()===addr.toLowerCase()))return showToast('Sudah ada');setLoading(true);try{const provider=await getProvider();const c=new ethers.Contract(addr,['function symbol() view returns (string)','function name() view returns (string)','function decimals() view returns (uint8)'],provider);let symbol=(document.getElementById('addTokenSym').value||'').trim();let decimals=parseInt(document.getElementById('addTokenDec').value)||18;let name=symbol||'Token';try{symbol=symbol||await c.symbol();name=await c.name().catch(()=>symbol);decimals=await c.decimals().catch(()=>decimals)}catch(_){}const id=symbol.toUpperCase()+'_'+addr.slice(2,6);state.tokens.push({id,symbol:symbol.toUpperCase(),name,decimals,address:addr,icon:'https://assets.coingecko.com/coins/images/1/small/bitcoin.png',coingecko:null});persistWallet();closeModal();showToast(symbol.toUpperCase()+' ditambahkan');refreshBalances(true)}catch{showToast('Gagal')}finally{setLoading(false)}}

function listWallets(){
  try{ return JSON.parse(localStorage.getItem('br_wallets_v3')||'[]'); }catch(e){ return []; }
}
function switchWallet(address){
  var all = listWallets();
  var found = all.find(function(w){ return w.address && w.address.toLowerCase()===address.toLowerCase(); });
  if(!found) return showToast('Wallet tidak ditemukan');
  try{
    var w = found.privateKey ? new ethers.Wallet(found.privateKey) : null;
    state.wallet = w;
    state.address = found.address;
    state.phrase = null;
    state.walletName = found.name || 'Wallet';
    state.balances = {};
    state.history = [];
    state.tokenHistoryCache = {};
    localStorage.setItem(STORAGE_KEY, JSON.stringify(found));
    localStorage.setItem('br_active_addr', found.address);
    closeModal();
    showScreen('home');
    refreshBalances(true);
    showToast('Beralih ke '+(found.name||address.slice(0,8)));
  }catch(e){ showToast('Gagal beralih'); }
}
function openWalletSwitcher(){
  var all = listWallets();
  var html = '<h3>Ganti Dompet</h3>';
  html += '<div class="text-muted" style="font-size:.8rem;margin-bottom:12px">Total: '+all.length+' wallet</div>';
  all.forEach(function(w){
    var active = state.address && w.address.toLowerCase()===state.address.toLowerCase();
    var short = w.address.slice(0,6)+'...'+w.address.slice(-4);
    html += '<div class="token-row" style="margin-bottom:6px;border:'+(active?'1px solid var(--mint)':'1px solid var(--border)')+'" onclick="switchWallet(\''+w.address+'\')">';
    html += '<div class="token-icon" style="background:var(--card2);font-size:1.2rem">🐕</div>';
    html += '<div class="token-info"><div class="name">'+(w.name||'Wallet')+(active?' ✓':'')+'</div>';
    html += '<div class="sym">Base: '+short+'</div></div></div>';
  });
  html += '<button class="btn btn-primary" style="max-width:none;margin-top:12px" onclick="closeModal();lockWallet();showScreen(\'onboard\')">+ Tambah Dompet</button>';
  openModal(html);
}

