/* ===== Preferences (Bitget-style full page + pickers) ===== */
state.currency = localStorage.getItem('br_currency') || state.currency || 'USD';
state.theme = localStorage.getItem('br_theme') || state.theme || 'dark';
state.defaultPage = localStorage.getItem('br_default_page') || state.defaultPage || 'home';
state.priceColor = localStorage.getItem('br_price_color') || 'standard';
state.lang = localStorage.getItem('br_lang') || state.lang || 'id';

var PREF_LABELS = {
  currency: { USD: 'USD ($)', IDR: 'IDR (Rp)', EUR: 'EUR (€)' },
  theme: { dark: 'Gelap', light: 'Terang', system: 'Sistem' },
  themeEn: { dark: 'Dark', light: 'Light', system: 'System' },
  defaultPage: { home: 'Dompet', dapps: 'Beranda', discover: 'Temukan' },
  lang: { id: 'Bahasa Indonesia', en: 'English' }
};

function prefIsId() {
  return (state.lang || localStorage.getItem('br_lang') || 'id') === 'id';
}

function refreshPrefLabels() {
  var lang = state.lang || 'id';
  var cur = state.currency || 'USD';
  var theme = state.theme || 'dark';
  var page = state.defaultPage || 'home';
  var inv = (state.priceColor || 'standard') === 'inverted';
  var el;
  el = document.getElementById('prefLangVal');
  if (el) el.textContent = PREF_LABELS.lang[lang] || lang;
  el = document.getElementById('prefCurVal');
  if (el) el.textContent = PREF_LABELS.currency[cur] || cur;
  el = document.getElementById('prefThemeVal');
  if (el) {
    var map = prefIsId() ? PREF_LABELS.theme : PREF_LABELS.themeEn;
    el.textContent = map[theme] || theme;
  }
  el = document.getElementById('prefHomeVal');
  if (el) {
    var pages = prefIsId()
      ? { home: 'Dompet', dapps: 'Beranda', discover: 'Temukan' }
      : { home: 'Wallet', dapps: 'Home', discover: 'Discover' };
    el.textContent = pages[page] || page;
  }
  el = document.getElementById('prefColorVal');
  if (el) {
    el.innerHTML = inv
      ? '<span class="down">↑</span> <span class="up">↓</span>'
      : '<span class="up">↑</span> <span class="down">↓</span>';
  }
}

function applyTheme() {
  var mode = state.theme || localStorage.getItem('br_theme') || 'dark';
  var resolved = mode;
  if (mode === 'system') {
    try {
      resolved = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
    } catch (e) {
      resolved = 'dark';
    }
  }
  document.documentElement.setAttribute('data-theme', resolved);
  document.documentElement.setAttribute('data-theme-pref', mode);
  try {
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', resolved === 'light' ? '#F5F6F8' : '#0B0E11');
  } catch (e) {}
}

function applyPriceColor() {
  var inv = (state.priceColor || localStorage.getItem('br_price_color') || 'standard') === 'inverted';
  document.documentElement.setAttribute('data-price-color', inv ? 'inverted' : 'standard');
}

function openPreferences() {
  refreshPrefLabels();
  if (typeof showScreen === 'function') showScreen('preferences');
}

function openPrefPicker(key) {
  var title = '';
  var options = [];
  var current = '';
  if (key === 'lang') {
    title = prefIsId() ? 'Bahasa' : 'Language';
    current = state.lang || 'id';
    options = [
      { id: 'id', label: 'Bahasa Indonesia' },
      { id: 'en', label: 'English' }
    ];
  } else if (key === 'currency') {
    title = prefIsId() ? 'Mata uang' : 'Currency';
    current = state.currency || 'USD';
    options = [
      { id: 'USD', label: 'USD ($)' },
      { id: 'IDR', label: 'IDR (Rp)' },
      { id: 'EUR', label: 'EUR (€)' }
    ];
  } else if (key === 'theme') {
    title = prefIsId() ? 'Tema' : 'Theme';
    current = state.theme || 'dark';
    options = prefIsId()
      ? [
          { id: 'dark', label: 'Gelap' },
          { id: 'light', label: 'Terang' },
          { id: 'system', label: 'Sistem' }
        ]
      : [
          { id: 'dark', label: 'Dark' },
          { id: 'light', label: 'Light' },
          { id: 'system', label: 'System' }
        ];
  } else if (key === 'priceColor') {
    title = prefIsId() ? 'Warna perubahan harga' : 'Price change color';
    current = state.priceColor || 'standard';
    options = [
      {
        id: 'standard',
        label: prefIsId() ? 'Standar (hijau naik)' : 'Standard (green up)',
        html: '<span style="color:var(--green)">↑</span> <span style="color:var(--red)">↓</span>'
      },
      {
        id: 'inverted',
        label: prefIsId() ? 'Terbalik (merah naik)' : 'Inverted (red up)',
        html: '<span style="color:var(--red)">↑</span> <span style="color:var(--green)">↓</span>'
      }
    ];
  } else if (key === 'defaultPage') {
    title = prefIsId() ? 'Halaman awal default' : 'Default home page';
    current = state.defaultPage || 'home';
    options = prefIsId()
      ? [
          { id: 'home', label: 'Dompet' },
          { id: 'dapps', label: 'Beranda' },
          { id: 'discover', label: 'Temukan' }
        ]
      : [
          { id: 'home', label: 'Wallet' },
          { id: 'dapps', label: 'Home' },
          { id: 'discover', label: 'Discover' }
        ];
  } else return;

  var html = '<h3>' + title + '</h3>';
  options.forEach(function (opt) {
    var on = opt.id === current ? ' pref-opt-on' : '';
    var right = opt.html
      ? '<span class="pref-opt-extra">' + opt.html + '</span>'
      : opt.id === current
        ? '<span class="pref-opt-check">✓</span>'
        : '';
    html +=
      '<div class="pref-opt' +
      on +
      '" onclick="setPref(\'' +
      key +
      '\',\'' +
      opt.id +
      '\')"><span>' +
      opt.label +
      '</span>' +
      right +
      '</div>';
  });
  openModal(html);
}

function setPref(key, value) {
  if (key === 'dir') {
    try {
      if (typeof I18N !== 'undefined' && I18N.setDir) I18N.setDir(value);
      else {
        localStorage.setItem('br_dir', value);
        document.documentElement.setAttribute('dir', value === 'rtl' ? 'rtl' : 'ltr');
      }
    } catch (e) {}
    try { refreshPrefLabels(); } catch (e) {}
    try { closePrefPicker(); } catch (e) {}
    return;
  }
  if (key === 'lang') {
    state.lang = value;
    localStorage.setItem('br_lang', value);
    if (typeof I18N !== 'undefined' && I18N.setLang) {
      try { I18N.setLang(value); } catch (e) {}
    } else {
      showToast(value === 'id' ? 'Bahasa: Indonesia' : 'Language: English');
    }
    try { if (typeof I18N !== 'undefined' && I18N.apply) I18N.apply(); } catch (e) {}
  } else if (key === 'currency') {
    state.currency = value;
    localStorage.setItem('br_currency', value);
    showToast((prefIsId() ? 'Mata uang: ' : 'Currency: ') + value);
    try { if (typeof renderHome === 'function') renderHome(); } catch (e) {}
  } else if (key === 'theme') {
    state.theme = value;
    localStorage.setItem('br_theme', value);
    applyTheme();
    var label = (prefIsId() ? PREF_LABELS.theme : PREF_LABELS.themeEn)[value] || value;
    showToast((prefIsId() ? 'Tema: ' : 'Theme: ') + label);
  } else if (key === 'priceColor') {
    state.priceColor = value;
    localStorage.setItem('br_price_color', value);
    applyPriceColor();
    showToast(
      value === 'inverted'
        ? (prefIsId() ? 'Warna harga: terbalik' : 'Price color: inverted')
        : (prefIsId() ? 'Warna harga: standar' : 'Price color: standard')
    );
    try { if (typeof renderHome === 'function') renderHome(); } catch (e) {}
  } else if (key === 'defaultPage') {
    state.defaultPage = value;
    localStorage.setItem('br_default_page', value);
    var pages = prefIsId()
      ? { home: 'Dompet', dapps: 'Beranda', discover: 'Temukan' }
      : { home: 'Wallet', dapps: 'Home', discover: 'Discover' };
    showToast((prefIsId() ? 'Halaman awal: ' : 'Default page: ') + (pages[value] || value));
  }
  closeModal();
  refreshPrefLabels();
}

(function patchFmtMoney() {
  var _fmtUsd = typeof fmtUsd === 'function' ? fmtUsd : null;
  window.fmtUsd = function (n) {
    var cur = (state && state.currency) || localStorage.getItem('br_currency') || 'USD';
    var num = Number(n) || 0;
    if (cur === 'IDR') {
      var idr = num * 16000;
      if (idr > 0 && idr < 1) return 'Rp <1';
      return 'Rp ' + Math.round(idr).toLocaleString('id-ID');
    }
    if (cur === 'EUR') {
      var eur = num * 0.92;
      if (eur > 0 && eur < 0.01) return '<€0.01';
      return '€' + eur.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    if (_fmtUsd) return _fmtUsd(num);
    if (num > 0 && num < 0.01) return '<$0.01';
    return '$' + num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };
})();

try { applyTheme(); applyPriceColor(); } catch (e) {}
try {
  if (window.matchMedia) {
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function () {
      if ((state.theme || localStorage.getItem('br_theme')) === 'system') applyTheme();
    });
  }
} catch (e) {}

function pickPref(key) {
  openPrefPicker(key);
}




/* ===== Token detail + Transfer (Bitget style) ===== */
state.tdToken = null;
state.tfAmt = '0';
state.tfTo = '';
