/* ===== Token detail + Transfer (Bitget) ===== */
if(typeof state.tdToken === 'undefined') state.tdToken = null;
if(typeof state.tfAmt === 'undefined') state.tfAmt = '0';
if(typeof state.tfTo === 'undefined') state.tfTo = '';
if(typeof state.recentAddrs === 'undefined'){
  try{ state.recentAddrs = JSON.parse(localStorage.getItem('br_recent_addr')||'[]'); }
  catch(e){ state.recentAddrs = []; }
}

/* Per-token / per-wallet history cache: key = address|network|tokenId */
if (typeof state.tokenHistoryCache === 'undefined') state.tokenHistoryCache = {};

function tokenHistoryKey(token) {
  var addr = (state.address || '').toLowerCase();
  var net = state.network || 'base';
  var tid = (token && (token.id || token.address || token.symbol)) || 'unknown';
  return addr + '|' + net + '|' + String(tid).toLowerCase();
}

function getExplorerApiForNet(netId) {
  var map = {
    base: { api: 'https://api.basescan.org/api', web: 'https://basescan.org' },
    eth: { api: 'https://api.etherscan.io/api', web: 'https://etherscan.io' },
    bnb: { api: 'https://api.bscscan.com/api', web: 'https://bscscan.com' },
    pol: { api: 'https://api.polygonscan.com/api', web: 'https://polygonscan.com' },
    arb: { api: 'https://api.arbiscan.io/api', web: 'https://arbiscan.io' },
    op: { api: 'https://api-optimistic.etherscan.io/api', web: 'https://optimistic.etherscan.io' }
  };
  return map[netId] || map.base;
}

function formatTokenTxTime(ms) {
  if (!ms) return '';
  try {
    var n = Number(ms);
    // Explorer sometimes returns seconds; local may be ms
    if (n > 0 && n < 1e12) n = n * 1000;
    var d = new Date(n);
    if (isNaN(d.getTime())) return '';
    return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' }) +
      ', ' +
      d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
  } catch (e) {
    return '';
  }
}

function normalizeTxTime(raw) {
  var n = Number(raw || 0);
  if (!n || isNaN(n)) return 0;
  if (n < 1e12) n = n * 1000; // seconds → ms
  return n;
}

function resolveTxDirection(tx, me) {
  me = (me || (state && state.address) || '').toLowerCase();
  if (!me) {
    if (tx.isOut === true || tx.dir === 'out') return 'out';
    if (tx.isOut === false || tx.dir === 'in') return 'in';
    return 'out';
  }
  var from = String(tx.from || '').toLowerCase();
  var to = String(tx.to || '').toLowerCase();
  if (from && from === me && to !== me) return 'out';
  if (to && to === me && from !== me) return 'in';
  if (from === me) return 'out';
  if (to === me) return 'in';
  if (tx.dir === 'in' || tx.isOut === false) return 'in';
  if (tx.dir === 'out' || tx.isOut === true) return 'out';
  return 'out';
}

function formatTokenAmount(val) {
  if (val == null || isNaN(Number(val))) return '0';
  var n = Number(val);
  if (typeof fmtAmt === 'function') {
    try { return fmtAmt(n); } catch (e) {}
  }
  if (n >= 1e6) return n.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (n >= 1) return n.toLocaleString('en-US', { maximumFractionDigits: 4 });
  if (n > 0) return n.toPrecision(4);
  return '0';
}

function renderTokenTxList(token, rows) {
  var txBox = document.getElementById('tdTxList');
  if (!txBox) return;
  var net = (typeof currentNet === 'function') ? currentNet() : { explorer: 'https://basescan.org' };
  var exp = (net && net.explorer) || getExplorerApiForNet(state.network || 'base').web;
  var sym = escapeHtml((token && token.symbol) || '');
  var me = ((state && state.address) || '').toLowerCase();
  if (!rows || !rows.length) {
    txBox.innerHTML = '<div class="empty" style="padding:12px;font-size:.82rem">Belum ada transaksi ' + sym + '</div>';
    return;
  }
  // Deduplicate by hash, newest first (always)
  var seen = {};
  var sorted = [];
  rows.slice().forEach(function (tx) {
    if (!tx) return;
    var h = String(tx.hash || '');
    if (h && seen[h]) return;
    if (h) seen[h] = 1;
    var t = normalizeTxTime(tx.time);
    if (t && !tx.time) tx.time = t;
    else if (t) tx.time = t;
    sorted.push(tx);
  });
  sorted.sort(function (a, b) {
    return (normalizeTxTime(b.time) || 0) - (normalizeTxTime(a.time) || 0);
  });
  txBox.innerHTML = sorted.slice(0, 25).map(function (tx) {
    var dir = resolveTxDirection(tx, me);
    var isOut = dir === 'out';
    var val = tx.valueDisplay != null ? tx.valueDisplay : tx.value;
    var ts = formatTokenTxTime(tx.time || tx.timeStamp);
    var hash = String(tx.hash || '').replace(/[^a-fA-F0-9x]/g, '');
    var safeHash = /^0x[a-fA-F0-9]{64}$/.test(hash) ? hash : '';
    var title = isOut
      ? ((typeof I18N !== 'undefined' && I18N.t) ? I18N.t('tx_send') : 'Kirim')
      : ((typeof I18N !== 'undefined' && I18N.t) ? I18N.t('tx_receive') : 'Terima');
    var amtColor = isOut ? 'out' : 'in';
    return '<div class="tx-row" style="padding:8px 0;background:transparent;cursor:pointer" data-hash="' + safeAttr(safeHash) + '">' +
      '<div class="tx-ico ' + (isOut ? 'out' : 'in') + '">' + (isOut ? '↑' : '↓') + '</div>' +
      '<div class="tx-info"><div class="t">' + escapeHtml(title) + '</div><div class="m">' + escapeHtml(ts) + '</div></div>' +
      '<div class="tx-amt ' + amtColor + '">' + (isOut ? '-' : '+') + formatTokenAmount(val) + ' ' + sym + '</div></div>';
  }).join('');
  txBox.querySelectorAll('[data-hash]').forEach(function (el) {
    el.onclick = function () {
      var h = el.getAttribute('data-hash');
      if (h) brOpen(exp + '/tx/' + h);
    };
  });
}

async function loadTokenHistory(token, force) {
  if (!token || !state.address) {
    renderTokenTxList(token, []);
    return [];
  }
  var key = tokenHistoryKey(token);
  if (!force && state.tokenHistoryCache[key] && state.tokenHistoryCache[key].length) {
    renderTokenTxList(token, state.tokenHistoryCache[key]);
    return state.tokenHistoryCache[key];
  }
  var txBox = document.getElementById('tdTxList');
  if (txBox) {
    txBox.innerHTML = '<div class="empty" style="padding:12px;font-size:.82rem">Memuat riwayat ' + escapeHtml(token.symbol || '') + '…</div>';
  }
  var netId = state.network || 'base';
  var exp = getExplorerApiForNet(netId);
  var me = state.address.toLowerCase();
  var rows = [];
  try {
    var url;
    var isNative = !token.address;
    var params;
    if (isNative) {
      params = {
        module: 'account', action: 'txlist', address: state.address,
        startblock: 0, endblock: 99999999, page: 1, offset: 30, sort: 'desc'
      };
    } else {
      params = {
        module: 'account', action: 'tokentx', contractaddress: token.address,
        address: state.address, page: 1, offset: 30, sort: 'desc'
      };
    }
    if (typeof ExplorerAPI !== 'undefined' && ExplorerAPI.buildUrl) {
      url = ExplorerAPI.buildUrl(netId, params);
    } else {
      url = exp.api + '?' + Object.keys(params).map(function (k) {
        return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]);
      }).join('&');
    }
    var res = await fetch(url, { signal: AbortSignal.timeout(10000) });
    var data = await res.json();
    if (data && typeof data.result === 'string' && /rate limit|Invalid API/i.test(data.result)) {
      console.warn('loadTokenHistory API:', data.result);
    }
    var list = (data.status === '1' && Array.isArray(data.result)) ? data.result : [];
    rows = list.map(function (tx) {
      var from = (tx.from || '').toLowerCase();
      var to = (tx.to || '').toLowerCase();
      // Direction relative to active wallet only
      var isOut = from === me;
      if (from === me && to === me) isOut = true; // self-transfer as out
      if (to === me && from !== me) isOut = false;
      var val = 0;
      try {
        if (isNative) {
          val = Number(ethers.formatEther(tx.value || '0'));
        } else {
          // Prefer on-chain explorer decimals, then token config
          var dec = Number(tx.tokenDecimal);
          if (isNaN(dec) || dec < 0 || dec > 36) {
            dec = token.decimals != null ? Number(token.decimals) : 18;
          }
          val = Number(ethers.formatUnits(String(tx.value || '0'), dec));
        }
      } catch (e) {
        try {
          var d2 = token.decimals != null ? Number(token.decimals) : 18;
          val = Number(tx.value) / Math.pow(10, d2);
        } catch (e2) {}
      }
      var ts = normalizeTxTime(tx.timeStamp);
      return {
        hash: tx.hash,
        from: tx.from,
        to: tx.to,
        value: val,
        valueDisplay: val,
        isOut: isOut,
        dir: isOut ? 'out' : 'in',
        time: ts,
        timeLabel: formatTokenTxTime(ts),
        tokenId: token.id,
        symbol: token.symbol,
        contract: token.address || tx.contractAddress || null,
        success: true
      };
    });
    // Drop dust/noise: zero-value rows (keep if list otherwise empty)
    var withVal = rows.filter(function (r) { return r.value > 0; });
    if (withVal.length) rows = withVal;

    // Merge local pending txs that match this token (strict)
    try {
      var locals = [];
      try { locals = locals.concat(JSON.parse(localStorage.getItem('br_local_tx') || '[]')); } catch (e) {}
      try { locals = locals.concat(JSON.parse(localStorage.getItem('br_local_txs_v1') || '[]')); } catch (e) {}
      var symU = String(token.symbol || '').toUpperCase();
      var cAddr = token.address ? String(token.address).toLowerCase() : null;
      locals.forEach(function (t) {
        if (!t) return;
        var matchSym = t.symbol && String(t.symbol).toUpperCase() === symU;
        var matchId = t.tokenId && String(t.tokenId).toUpperCase() === String(token.id || '').toUpperCase();
        var matchC = cAddr && t.contract && String(t.contract).toLowerCase() === cAddr;
        // native match
        var matchNative = !cAddr && !t.contract && (matchSym || matchId);
        if (!(matchSym || matchId || matchC || matchNative)) return;
        if (t.hash && rows.some(function (r) { return r.hash && r.hash === t.hash; })) return;
        var dir = resolveTxDirection(t, me);
        var lt = normalizeTxTime(t.time) || Date.now();
        rows.push({
          hash: t.hash,
          from: t.from || state.address,
          to: t.to,
          value: Number(t.value) || 0,
          valueDisplay: Number(t.value) || 0,
          isOut: dir === 'out',
          dir: dir,
          time: lt,
          timeLabel: formatTokenTxTime(lt),
          tokenId: token.id,
          symbol: token.symbol,
          contract: token.address || null,
          success: t.success !== false
        });
      });
    } catch (e) {}

    // Dedup + newest first
    var seenH = {};
    rows = rows.filter(function (r) {
      if (!r || !r.hash) return true;
      if (seenH[r.hash]) return false;
      seenH[r.hash] = 1;
      return true;
    });
    rows.sort(function (a, b) {
      return (normalizeTxTime(b.time) || 0) - (normalizeTxTime(a.time) || 0);
    });
    state.tokenHistoryCache[key] = rows;
    state.tokenHistoryCache[key + '_at'] = Date.now();
  } catch (e) {
    console.log('loadTokenHistory', e);
    rows = state.tokenHistoryCache[key] || [];
  }
  renderTokenTxList(token, rows);
  return rows;
}

function showToken(id){
  var t = state.tokens.find(function(x){ return x.id === id; });
  if(!t) return;
  state.tdToken = t;
  var bal = state.balances[id] || 0;
  var price = state.prices[id] || 0;
  var chg = state.changes && state.changes[id];
  var net = (typeof currentNet === 'function') ? currentNet() : { name: 'Base', explorer: 'https://basescan.org' };

  var set = function(id, val){ var el = document.getElementById(id); if(el) el.textContent = val; };
  var setHtml = function(id, val){ var el = document.getElementById(id); if(el) el.innerHTML = val; };
  var img = document.getElementById('tdIcon'); if(img) img.src = (typeof safeUrl === 'function' ? safeUrl(t.icon || '') : (t.icon || ''));
  set('tdSymbol', t.symbol);
  set('tdChain', net.name || 'Base');
  set('tdBal', fmtAmt(bal));
  set('tdUsd', '≈ ' + fmtUsd(bal * price));
  if(typeof chg === 'number'){
    var cls = chg >= 0 ? 'up' : 'down';
    var sign = chg >= 0 ? '+' : '';
    setHtml('tdChg', 'Perubahan hari ini <span class="'+cls+'">'+sign+chg.toFixed(2)+'%</span>');
  } else set('tdChg', 'Perubahan hari ini —');
  set('tdAddr', state.address ? (state.address.slice(0,8)+'...'+state.address.slice(-6)) : '—');
  set('tdPriceLabel', 'Harga ' + t.symbol);
  var priceStr = price >= 1 ? '$'+price.toLocaleString('en-US',{maximumFractionDigits:2}) : (price > 0 ? '$'+price.toPrecision(4) : '$0');
  var chgStr = typeof chg === 'number' ? ((chg>=0?'+':'')+chg.toFixed(2)+'%') : '';
  setHtml('tdPrice', priceStr+' <span class="'+(chg>=0?'tok-up':'tok-down')+'">'+chgStr+'</span>');

  // Per-token history — refresh if cache older than 45s
  var hk = typeof tokenHistoryKey === 'function' ? tokenHistoryKey(t) : '';
  var cacheAt = (state.tokenHistoryCache && state.tokenHistoryCache[hk + '_at']) || 0;
  var forceHist = !cacheAt || (Date.now() - cacheAt > 45000);
  loadTokenHistory(t, forceHist);

  wireTokenDetailBtns();
  showScreen('token');
}
function showTokenDetail(id){ showToken(id); }

function wireTokenDetailBtns(){
  var tr = document.getElementById('tdTransfer');
  if(tr) tr.onclick = function(){ if(state.tdToken) openTransfer(state.tdToken.id); };
  var cp = document.getElementById('tdCopy');
  if(cp) cp.onclick = function(){
    if(state.address) navigator.clipboard.writeText(state.address).then(function(){ showToast('Alamat disalin'); });
  };
  var qr = document.getElementById('tdQr');
  if(qr) qr.onclick = function(){ showScreen('receive'); };
}

function openTransfer(tokenId){
  // Always use Bitget-style multi-step transfer flow
  if (typeof openBitgetTransfer === 'function') {
    try {
      var t = (state.tokens || []).find(function(x){ return x.id === tokenId; }) || state.tdToken;
      if (t) state.tdToken = t;
      openBitgetTransfer(tokenId || (t && t.id) || null);
      return;
    } catch (e) {
      console.warn('openBitgetTransfer failed, legacy fallback', e);
    }
  }
  var t = state.tokens.find(function(x){ return x.id === tokenId; }) || state.tdToken;
  if(!t) return;
  state.tdToken = t;
  state.tfAmt = '0';
  var icon = document.getElementById('tfIcon'); if(icon) icon.src = t.icon || '';
  var sym = document.getElementById('tfSymBal');
  if(sym) sym.textContent = t.symbol + ': ' + fmtAmt(state.balances[t.id]||0);
  updateTfDisplay();
  var toEl = document.getElementById('tfTo');
  if(toEl) toEl.textContent = state.tfTo ? (state.tfTo.slice(0,6)+'...'+state.tfTo.slice(-4)+' ›') : 'Pilih alamat ›';
  var net = (typeof currentNet === 'function') ? currentNet() : { name: 'Base' };
  var netEl = document.getElementById('tfNet'); if(netEl) netEl.textContent = net.name || 'Base';
  buildTfPad();
  updateTfNextState();
  showScreen('transfer');
}

function updateTfDisplay(){
  var t = state.tdToken;
  var amtEl = document.getElementById('tfAmt');
  var disp = document.getElementById('tfDisplay');
  var a = state.tfAmt || '0';
  if(amtEl) amtEl.value = a;
  if(disp){
    var sym = t ? t.symbol : '';
    disp.innerHTML = '<span class="cursor"></span>'+a+'<span class="cur">'+sym+'</span>';
  }
  tfUpdateUsd();
  updateTfNextState();
}

function updateTfNextState(){
  var btn = document.getElementById('tfNext');
  if(!btn) return;
  var ok = state.tfTo && ethers.isAddress(state.tfTo) && state.tfAmt && Number(state.tfAmt) > 0;
  btn.classList.toggle('ready', !!ok);
}

function buildTfPad(){
  var pad = document.getElementById('tfPad');
  if(!pad) return;
  var keys = ['1','2','3','4','5','6','7','8','9','.','0','⌫'];
  pad.innerHTML = keys.map(function(k){
    return '<button type="button" data-k="'+k+'">'+(k==='⌫'?'⌫':k)+'</button>';
  }).join('');
  pad.querySelectorAll('button').forEach(function(b){
    b.onclick = function(){ tfKey(b.getAttribute('data-k')); };
  });
  document.querySelectorAll('.tf-pct button').forEach(function(b){
    b.onclick = function(){
      var t = state.tdToken; if(!t) return;
      var bal = state.balances[t.id]||0;
      var pct = Number(b.getAttribute('data-pct'))/100;
      var v = bal * pct;
      if((t.id==='ETH'||!t.address) && pct===1) v = Math.max(0, bal - 0.00015);
      state.tfAmt = v > 0 ? trimAmount(String(v), (t.decimals!=null?Math.min(t.decimals,8):8)) : '0';
      updateTfDisplay();
    };
  });
  var next = document.getElementById('tfNext');
  if(next) next.onclick = tfSubmit;
  // field clicks
  var fields = document.querySelectorAll('#screen-transfer .tf-field');
  if(fields[0]) fields[0].onclick = openAddressPicker;
  if(fields[1]) fields[1].onclick = function(){ if(typeof openNetworkPicker==='function') openNetworkPicker(); };
}


function tfKey(k){
  var t = state.tdToken;
  var decimals = t && typeof t.decimals === 'number' ? t.decimals : 18;
  var maxDec = Math.min(decimals, 8); // UI precision
  var a = String(state.tfAmt == null ? '0' : state.tfAmt);

  if(k === '⌫'){
    a = a.length <= 1 ? '0' : a.slice(0, -1);
    if(a === '.' || a === '-') a = '0';
    state.tfAmt = a;
    updateTfDisplay();
    return;
  }

  if(k === '.'){
    if(a.indexOf('.') >= 0) return; // already has decimal
    a = (a === '' ? '0' : a) + '.';
    state.tfAmt = a;
    updateTfDisplay();
    return;
  }

  // digit 0-9
  if(!/^[0-9]$/.test(k)) return;

  // leading zeros: "0" + digit => digit (unless decimal "0.x")
  if(a === '0'){
    a = k; // replace leading zero
  } else if(a === '0' && k === '0'){
    return; // stay at 0
  } else {
    // decimal part length limit
    var dot = a.indexOf('.');
    if(dot >= 0){
      var decPart = a.slice(dot + 1);
      if(decPart.length >= maxDec) return;
    } else {
      // integer length limit
      if(a.length >= 12) return;
    }
    a = a + k;
  }

  // validate numeric
  if(!/^\d+(\.\d*)?$/.test(a) && a !== '0') return;

  // optional: do not exceed balance * 1.0 (soft — hard check on submit)
  var bal = t ? (state.balances[t.id] || 0) : 0;
  var num = parseFloat(a);
  if(bal > 0 && num > bal * 1.0000001){
    // clamp to balance
    a = trimAmount(String(bal), maxDec);
    showToast('Melebihi saldo');
  }

  state.tfAmt = a;
  updateTfDisplay();
}

function trimAmount(str, maxDec){
  var n = parseFloat(str);
  if(!isFinite(n) || n <= 0) return '0';
  var s = n.toFixed(maxDec);
  // strip trailing zeros
  s = s.replace(/\.?0+$/, '');
  return s || '0';
}


function tfUpdateUsd(){
  var t = state.tdToken;
  var el = document.getElementById('tfUsd');
  if(!el) return;
  if(!t){ el.textContent = '$0.00'; return; }
  var n = parseFloat(state.tfAmt) || 0;
  var price = state.prices[t.id] || 0;
  el.textContent = fmtUsd(n * price);
}

function tfSubmit(){
  var _v = validateRecipient(state.tfTo);
  if(!_v.ok) return showToast(_v.msg);
  state.tfTo = _v.address;
  if(!securityConfirmSend(state.tfTo, state.tfAmt, (state.tdToken&&state.tdToken.symbol)||'')) return;

  var t = state.tdToken;
  if(!t) return;
  var amt = state.tfAmt;
  var to = state.tfTo;
  if(!to || !ethers.isAddress(to)) return showToast('Pilih alamat penerima');
  if(!amt || Number(amt) <= 0) return showToast((typeof I18N!=='undefined'&&I18N.t)?I18N.t('enter_amount'):'Masukkan jumlah');
  // Go to classic send with prefilled values, or send directly
  showScreen('send');
  setTimeout(function(){
    var sel = document.getElementById('sendToken');
    if(sel){
      // ensure option exists
      var found = false;
      for(var i=0;i<sel.options.length;i++){ if(sel.options[i].value===t.id) found=true; }
      if(!found){
        var opt = document.createElement('option');
        opt.value = t.id; opt.textContent = t.symbol;
        sel.appendChild(opt);
      }
      sel.value = t.id;
      if(typeof updateSendAvail === 'function') updateSendAvail();
    }
    var toEl = document.getElementById('sendTo'); if(toEl) toEl.value = to;
    var amtEl = document.getElementById('sendAmt'); if(amtEl) amtEl.value = amt;
  }, 30);
}

function apShortAddr(a){
  if(!a || a.length < 10) return a || '';
  return a.slice(0, 4) + '...' + a.slice(-4);
}

function apFormatTs(ts){
  if(!ts) return '';
  try{
    var d = new Date(ts);
    var mm = String(d.getMonth() + 1).padStart(2, '0');
    var dd = String(d.getDate()).padStart(2, '0');
    var hh = String(d.getHours()).padStart(2, '0');
    var mi = String(d.getMinutes()).padStart(2, '0');
    return mm + '-' + dd + ' ' + hh + ':' + mi;
  }catch(e){ return ''; }
}

function apFolderIcon(){
  return '<span class="ap-folder" aria-hidden="true">' +
    '<svg width="22" height="22" viewBox="0 0 24 24" fill="none">' +
    '<path d="M3 7.5A2.5 2.5 0 015.5 5H9l2 2h7.5A2.5 2.5 0 0121 9.5v7A2.5 2.5 0 0118.5 19h-13A2.5 2.5 0 013 16.5v-9z" fill="currentColor" opacity=".35"/>' +
    '<path d="M3 9h18v7.5A2.5 2.5 0 0118.5 19h-13A2.5 2.5 0 013 16.5V9z" fill="currentColor" opacity=".55"/>' +
    '<path d="M8 13h8" stroke="#0b0e11" stroke-width="1.6" stroke-linecap="round"/>' +
    '</svg></span>';
}

function apSyncInputTools(){
  var inp = document.getElementById('apInput');
  var val = ((inp && inp.value) || '').trim();
  var has = !!val;
  var clr = document.getElementById('apClear');
  var cp = document.getElementById('apCopy');
  if(clr) clr.style.display = has ? 'flex' : 'none';
  if(cp) cp.style.display = has ? 'flex' : 'none';
}

function apSelectAddr(addr, name){
  if(!addr) return;
  var inp = document.getElementById('apInput');
  if(inp) inp.value = addr;
  state.tfTo = addr;
  if(name) state._tfToName = name;
  apSyncInputTools();
  // Auto-confirm like Bitget when picking from list
  apConfirmAndBack();
}

function apConfirmAndBack(){
  var inp = document.getElementById('apInput');
  var v = ((inp && inp.value) || state.tfTo || '').trim();
  if(!v) return showToast('Masukkan alamat', 'warn');
  try{
    if(typeof ethers !== 'undefined' && !ethers.isAddress(v)) return showToast('Alamat tidak valid', 'error');
  }catch(e){
    if(!/^0x[a-fA-F0-9]{40}$/.test(v)) return showToast('Alamat tidak valid', 'error');
  }
  state.tfTo = v;
  state.recentAddrs = (state.recentAddrs || []).filter(function(a){
    return (a.addr || '').toLowerCase() !== v.toLowerCase();
  });
  state.recentAddrs.unshift({ addr: v, ts: Date.now() });
  state.recentAddrs = state.recentAddrs.slice(0, 20);
  try{ localStorage.setItem('br_recent_addr', JSON.stringify(state.recentAddrs)); }catch(e){}
  var tfTo = document.getElementById('tfTo');
  if(tfTo) tfTo.textContent = apShortAddr(v) + ' ›';
  if(typeof updateTfNextState === 'function') updateTfNextState();
  showScreen('transfer');
}

function openAddressPicker(){
  var inp = document.getElementById('apInput');
  if(inp) inp.value = state.tfTo || '';
  apSyncInputTools();
  state._apTab = state._apTab || 'recent';
  document.querySelectorAll('.ap-tab').forEach(function(t){
    t.classList.toggle('on', t.getAttribute('data-tab') === state._apTab);
  });
  renderApList(state._apTab);
  showScreen('addrpick');
}

function renderRecentAddrs(){ renderApList('recent'); }

function renderApList(tab){
  tab = tab || state._apTab || 'recent';
  state._apTab = tab;
  var box = document.getElementById('apList');
  if(!box) return;

  document.querySelectorAll('.ap-tab').forEach(function(t){
    t.classList.toggle('on', t.getAttribute('data-tab') === tab);
  });

  var html = '';
  if(tab === 'recent'){
    var list = state.recentAddrs || [];
    try{
      if(!list.length) list = JSON.parse(localStorage.getItem('br_recent_addr') || '[]');
    }catch(e){ list = []; }
    state.recentAddrs = list;
    if(!list.length){
      html = '<div class="ap-empty">Belum ada alamat yang baru digunakan</div>';
    } else {
      list.forEach(function(a){
        var addr = a.addr || a.address || '';
        if(!addr) return;
        html += '<button type="button" class="ap-row" data-a="'+addr+'">';
        html += apFolderIcon();
        html += '<div class="ap-row-body">';
        html += '<div class="ap-row-title">'+apShortAddr(addr)+'</div>';
        html += '<div class="ap-row-addr">'+addr+'</div>';
        if(a.ts) html += '<div class="ap-row-time">'+apFormatTs(a.ts)+'</div>';
        html += '</div></button>';
      });
    }
  } else if(tab === 'mine'){
    var wallets = [];
    try{ wallets = JSON.parse(localStorage.getItem('br_wallets_v3') || '[]'); }catch(e){}
    if(!wallets.length && state.address){
      wallets = [{ address: state.address, name: state.walletName || 'Dompet saya' }];
    }
    if(!wallets.length){
      html = '<div class="ap-empty">Belum ada dompet</div>';
    } else {
      wallets.forEach(function(w){
        var addr = w.address || w.addr || '';
        if(!addr) return;
        var nm = w.name || 'Dompet';
        html += '<button type="button" class="ap-row" data-a="'+addr+'" data-n="'+String(nm).replace(/"/g,'')+'">';
        html += '<span class="ap-avatar">'+String(nm).charAt(0).toUpperCase()+'</span>';
        html += '<div class="ap-row-body">';
        html += '<div class="ap-row-title">'+nm+'</div>';
        html += '<div class="ap-row-addr">'+addr+'</div>';
        html += '</div></button>';
      });
    }
  } else {
    var book = [];
    try{ book = JSON.parse(localStorage.getItem('br_address_book') || '[]'); }catch(e){}
    if(!book.length){
      html = '<div class="ap-empty">Buku alamat kosong</div>';
    } else {
      book.forEach(function(w){
        var addr = w.address || w.addr || '';
        if(!addr) return;
        var nm = w.name || 'Kontak';
        html += '<button type="button" class="ap-row" data-a="'+addr+'" data-n="'+String(nm).replace(/"/g,'')+'">';
        html += apFolderIcon();
        html += '<div class="ap-row-body">';
        html += '<div class="ap-row-title">'+nm+'</div>';
        html += '<div class="ap-row-addr">'+addr+'</div>';
        html += '</div></button>';
      });
    }
  }

  box.innerHTML = html;
  box.querySelectorAll('.ap-row').forEach(function(el){
    el.onclick = function(){
      apSelectAddr(el.getAttribute('data-a'), el.getAttribute('data-n') || '');
    };
  });
}

function wireAddressPicker(){
  var paste = document.getElementById('apPaste');
  if(paste) paste.onclick = async function(){
    try{
      var t = await navigator.clipboard.readText();
      t = (t || '').trim().replace(/\s+/g, '');
      var inp = document.getElementById('apInput');
      if(inp && t){
        inp.value = t;
        apSyncInputTools();
        showToast('Ditempel', 'success');
      }
    }catch(e){ showToast('Tidak bisa akses clipboard', 'error'); }
  };

  var scan = document.getElementById('apScan');
  if(scan) scan.onclick = function(){
    if (typeof window.openQrScanner === 'function') {
      window.openQrScanner(function (addr) {
        var inp = document.getElementById('apInput');
        if (inp) {
          inp.value = addr;
          try { if (typeof apSyncInputTools === 'function') apSyncInputTools(); } catch (e) {}
        }
      });
      return;
    }
    showToast('Pemindai QR belum siap — gunakan Tempel', 'info');
  };

  var clr = document.getElementById('apClear');
  if(clr) clr.onclick = function(){
    var inp = document.getElementById('apInput');
    if(inp) inp.value = '';
    apSyncInputTools();
  };

  var cp = document.getElementById('apCopy');
  if(cp) cp.onclick = function(){
    var inp = document.getElementById('apInput');
    var v = ((inp && inp.value) || '').trim();
    if(!v) return;
    try{
      navigator.clipboard.writeText(v).then(function(){
        showToast('Alamat disalin', 'success');
      }).catch(function(){ showToast('Gagal salin', 'error'); });
    }catch(e){ showToast('Clipboard tidak tersedia', 'warn'); }
  };

  var inp = document.getElementById('apInput');
  if(inp && !inp.dataset.apBound){
    inp.dataset.apBound = '1';
    inp.addEventListener('input', apSyncInputTools);
    inp.addEventListener('change', apSyncInputTools);
    // Confirm on Enter / blur with valid address
    inp.addEventListener('keydown', function(e){
      if(e.key === 'Enter'){
        e.preventDefault();
        apConfirmAndBack();
      }
    });
  }

  document.querySelectorAll('.ap-tab').forEach(function(tab){
    if(tab.dataset.bound) return;
    tab.dataset.bound = '1';
    tab.onclick = function(){
      renderApList(tab.getAttribute('data-tab'));
    };
  });
}

