/* ===== Encrypted localStorage ===== */
var SecureStore = {
  _key: null,
  _encKeyName: 'br_enc_v1',

  async deriveKey(pin, salt){
    var enc = new TextEncoder();
    var base = await crypto.subtle.importKey('raw', enc.encode(pin), 'PBKDF2', false, ['deriveKey']);
    return crypto.subtle.deriveKey(
      { name:'PBKDF2', salt: salt, iterations: 100000, hash:'SHA-256' },
      base,
      { name:'AES-GCM', length:256 },
      false,
      ['encrypt','decrypt']
    );
  },

  async unlock(pin){
    var saltB64 = localStorage.getItem('br_kdf_salt');
    var salt;
    if(!saltB64){
      salt = crypto.getRandomValues(new Uint8Array(16));
      localStorage.setItem('br_kdf_salt', btoa(String.fromCharCode.apply(null, salt)));
    } else {
      salt = Uint8Array.from(atob(saltB64), function(c){ return c.charCodeAt(0); });
    }
    this._key = await this.deriveKey(pin, salt);
    // verify if verifier exists
    var ver = localStorage.getItem('br_enc_verify');
    if(ver){
      try{
        await this.get('__verify__');
      }catch(e){
        this._key = null;
        throw new Error('PIN salah (dekripsi gagal)');
      }
    } else {
      await this.set('__verify__', 'ok');
      localStorage.setItem('br_enc_verify', '1');
    }
    return true;
  },

  async set(key, value){
    if(!this._key){
      // Do NOT write plaintext secrets. Keep in memory only until PIN unlock.
      console.warn('[SecureStore] set() called while locked — secret not written to disk:', key);
      return;
    }
    var enc = new TextEncoder();
    var iv = crypto.getRandomValues(new Uint8Array(12));
    var data = enc.encode(typeof value === 'string' ? value : JSON.stringify(value));
    var cipher = await crypto.subtle.encrypt({ name:'AES-GCM', iv: iv }, this._key, data);
    var packed = new Uint8Array(iv.length + cipher.byteLength);
    packed.set(iv, 0);
    packed.set(new Uint8Array(cipher), iv.length);
    var b64 = btoa(String.fromCharCode.apply(null, packed));
    localStorage.setItem(this._encKeyName+'_'+key, b64);
    // remove plain if any
    localStorage.removeItem('br_plain_'+key);
  },

  async get(key){
    var b64 = localStorage.getItem(this._encKeyName+'_'+key);
    if(!b64){
      var plain = localStorage.getItem('br_plain_'+key);
      if(plain != null) return plain;
      // legacy keys
      if(key === 'mnemonic') return localStorage.getItem('br_mnemonic') || localStorage.getItem('mnemonic') || '';
      if(key === 'pk') return localStorage.getItem('br_pk') || localStorage.getItem('privateKey') || '';
      return null;
    }
    if(!this._key) throw new Error('Locked');
    var packed = Uint8Array.from(atob(b64), function(c){ return c.charCodeAt(0); });
    var iv = packed.slice(0, 12);
    var data = packed.slice(12);
    var dec = await crypto.subtle.decrypt({ name:'AES-GCM', iv: iv }, this._key, data);
    return new TextDecoder().decode(dec);
  },

  async setSensitive(mnemonic, pk){
    if(mnemonic) await this.set('mnemonic', mnemonic);
    if(pk) await this.set('pk', pk);
    // wipe legacy plaintext
    ['br_mnemonic','mnemonic','br_pk','privateKey','br_v4_mnemonic','br_v4_pk'].forEach(function(k){
      try{ localStorage.removeItem(k); }catch(e){}
    });
  },

  async loadSensitive(){
    var m = await this.get('mnemonic');
    var p = await this.get('pk');
    return { mnemonic: m || '', pk: p || '' };
  }
};

// Hook: after PIN setup/unlock, unlock SecureStore
async function unlockSecureStore(pin){
  try{
    await SecureStore.unlock(pin);
    var sens = await SecureStore.loadSensitive();
    if(sens.mnemonic) state.mnemonic = sens.mnemonic;
    if(sens.pk) state.privateKey = sens.pk;
    return true;
  }catch(e){
    console.log('secure unlock', e);
    return false;
  }
}

// Migrate plaintext seed to encrypted after PIN set
async function migrateToEncrypted(pin){
  await SecureStore.unlock(pin);
  var m = state.mnemonic || localStorage.getItem('br_mnemonic') || localStorage.getItem('mnemonic') || '';
  var p = state.privateKey || localStorage.getItem('br_pk') || localStorage.getItem('privateKey') || '';
  if(m || p) await SecureStore.setSensitive(m, p);
}

