state._guideStep = 0;
function showBackupGuide(){
  state._guideStep = 0;
  document.getElementById('guideSeedArea').style.display = 'none';
  document.getElementById('guideNextBtn').style.display = 'block';
  document.getElementById('guideNextBtn').disabled = false;
  renderGuideSteps();
  showScreen('backup-guide');
}
function renderGuideSteps(){
  var steps = [
    { t:'Siapkan kertas & pena', d:'Jangan gunakan notes HP, email, atau cloud. Tulis tangan di kertas tahan air jika memungkinkan.' },
    { t:'Pastikan tidak ada yang melihat', d:'Backup di tempat privat. Matikan screen recording / kamera sekitar.' },
    { t:'Tulis 12/24 kata berurutan', d:'Salin setiap kata beserta nomor urutnya. Satu kata salah = dompet tidak bisa dipulihkan.' },
    { t:'Simpan di 2 lokasi aman', d:'Contoh: brankas rumah + lokasi terpisah. Jangan simpan digital.' },
    { t:'Uji pemulihan (opsional)', d:'Di perangkat lain, coba import seed (tanpa kirim aset dulu) untuk memastikan tulisan benar.' }
  ];
  var el = document.getElementById('guideSteps');
  el.innerHTML = steps.map(function(s,i){
    var on = i === state._guideStep;
    var done = i < state._guideStep;
    return '<div class="guide-step" style="opacity:'+(i>state._guideStep?'0.4':'1')+'"><div class="num">'+(done?'✓':(i+1))+'</div><div class="body"><b>'+s.t+'</b><span>'+s.d+'</span></div></div>';
  }).join('');
}
function guideNext(){
  if(state._guideStep < 4){
    state._guideStep++;
    renderGuideSteps();
    if(state._guideStep === 4){
      document.getElementById('guideNextBtn').textContent = 'Tampilkan seed phrase';
    }
    return;
  }
  // show seed
  showGuideSeed();
}
async function showGuideSeed(){
  document.getElementById('guideNextBtn').style.display = 'none';
  document.getElementById('guideSeedArea').style.display = 'block';
  var phrase = state.mnemonic || '';
  if(!phrase && SecureStore._key){
    try{ phrase = (await SecureStore.get('mnemonic')) || ''; }catch(e){}
  }
  if(!phrase){
    phrase = localStorage.getItem('br_mnemonic') || localStorage.getItem('mnemonic') || '';
  }
  var grid = document.getElementById('guideSeedGrid');
  if(!phrase){
    grid.innerHTML = '<div class="empty" style="grid-column:1/-1">Seed tidak tersedia. Import / buat wallet dulu.</div>';
    return;
  }
  var words = phrase.trim().split(/\s+/);
  grid.innerHTML = words.map(function(w,i){ return '<div class="w"><i>'+(i+1)+'</i>'+w+'</div>'; }).join('');
}
function finishBackupGuide(){
  localStorage.setItem('br_seed_backed_up', '1');
  showToast('Backup ditandai selesai');
  showScreen('settings');
}

/* ===== Hardware Wallet: Ledger / Trezor ===== */
async function connectLedger(){
  var st = document.getElementById('hwStatus');
  st.innerHTML = '<p style="margin:0">Menghubungkan Ledger… Buka app Ethereum.</p>';
  try{
    if(!navigator.usb){
      st.innerHTML = '<p style="margin:0;color:#F6465D">WebUSB tidak tersedia. Gunakan Chrome/Edge desktop.</p>';
      return;
    }
    // Dynamic import from CDN (Ledger transport + eth app)
    await loadScriptOnce('https://cdn.jsdelivr.net/npm/@ledgerhq/hw-transport-webusb@6.28.4/lib/webusb.min.js', 'LedgerTransportWebUSB');
    // Fallback minimal WebUSB HID-like flow using ledgerhq umd if present
    var Transport = window.TransportWebUSB || window['@ledgerhq/hw-transport-webusb'];
    if(!Transport && window.TransportWebUSB) Transport = window.TransportWebUSB;
    // Try official pattern
    if(typeof window.TransportWebUSB === 'undefined'){
      await loadScriptOnce('https://unpkg.com/@ledgerhq/hw-transport-webusb@6.28.4/lib/webusb.min.js');
    }
    Transport = window.TransportWebUSB || window.default || null;
    if(!Transport || !Transport.create){
      // Manual WebUSB device pick + message
      st.innerHTML = '<p style="margin:0">Ledger library dimuat terbatas di lingkungan ini. Gunakan Chrome, colokan Ledger, buka Ethereum app, lalu coba lagi.</p><p class="hint">Alternatif: ekspor alamat dari Ledger Live lalu gunakan sebagai watch-only.</p>';
      await connectLedgerManual(st);
      return;
    }
    var transport = await Transport.create();
    await loadScriptOnce('https://cdn.jsdelivr.net/npm/@ledgerhq/hw-app-eth@6.35.6/lib/eth.min.js');
    var Eth = window.Eth || window['@ledgerhq/hw-app-eth'];
    var eth = new Eth(transport);
    var path = "44'/60'/0'/0/0";
    var result = await eth.getAddress(path, false, true);
    state.hwType = 'ledger';
    state.hwPath = path;
    state.address = result.address;
    state.walletName = 'Ledger';
    st.innerHTML = '<p style="margin:0;color:#0ECB81">✓ Ledger terhubung</p><p class="hint" style="margin:6px 0 0;font-family:monospace">'+escapeHtml(result.address||'')+'</p>';
    showToast('Ledger terhubung');
    if(typeof refresh === 'function') await refresh(true);
    showScreen('home');
  }catch(e){
    console.error(e);
    st.innerHTML = '<p style="margin:0;color:#F6465D">Gagal: '+escapeHtml(String(e.message||e))+'</p><p class="hint">Pastikan Ledger terbuka, app Ethereum aktif, dan browser mengizinkan USB.</p>';
  }
}

async function connectLedgerManual(st){
  try{
    var device = await navigator.usb.requestDevice({ filters: [{ vendorId: 0x2c97 }, { vendorId: 0x2581 }] });
    st.innerHTML = '<p style="margin:0;color:#0ECB81">Perangkat terdeteksi: '+escapeHtml(device.productName||'Ledger')+'</p><p class="hint">Untuk penandatanganan penuh, buka di Chrome dan izinkan USB. Alamat diambil via Ledger Live bila library terbatas.</p>';
    state.hwType = 'ledger';
    state.walletName = 'Ledger';
  }catch(e){
    st.innerHTML = '<p style="margin:0;color:#F6465D">USB dibatalkan atau gagal: '+escapeHtml(String(e.message||e))+'</p>';
  }
}

async function connectTrezor(){
  var st = document.getElementById('hwStatus');
  st.innerHTML = '<p style="margin:0">Menghubungkan Trezor…</p>';
  try{
    await loadScriptOnce('https://connect.trezor.io/9/trezor-connect.js', 'TrezorConnect');
    var TrezorConnect = window.TrezorConnect;
    if(!TrezorConnect){
      st.innerHTML = '<p style="margin:0;color:#F6465D">Trezor Connect tidak termuat. Cek koneksi internet.</p>';
      return;
    }
    TrezorConnect.manifest({
      email: 'support@baserocky.local',
      appUrl: location.href
    });
    var res = await TrezorConnect.ethereumGetAddress({ path: "m/44'/60'/0'/0/0", showOnTrezor: true });
    if(!res.success){
      st.innerHTML = '<p style="margin:0;color:#F6465D">'+escapeHtml(String((res.payload&&res.payload.error) || 'Dibatalkan'))+'</p>';
      return;
    }
    state.hwType = 'trezor';
    state.hwPath = "m/44'/60'/0'/0/0";
    state.address = res.payload.address;
    state.walletName = 'Trezor';
    st.innerHTML = '<p style="margin:0;color:#0ECB81">✓ Trezor terhubung</p><p class="hint" style="margin:6px 0 0;font-family:monospace">'+escapeHtml(res.payload.address||'')+'</p>';
    showToast('Trezor terhubung');
    if(typeof refresh === 'function') await refresh(true);
    showScreen('home');
  }catch(e){
    console.error(e);
    st.innerHTML = '<p style="margin:0;color:#F6465D">Gagal: '+escapeHtml(String(e.message||e))+'</p>';
  }
}

function loadScriptOnce(src, globalName){
  return new Promise(function(resolve, reject){
    if(globalName && window[globalName]) return resolve();
    var existing = document.querySelector('script[data-src="'+src+'"]');
    if(existing){
      existing.addEventListener('load', function(){ resolve(); });
      existing.addEventListener('error', reject);
      return;
    }
    var s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.dataset.src = src;
    s.onload = function(){ resolve(); };
    s.onerror = function(){ reject(new Error('Gagal muat '+src)); };
    document.head.appendChild(s);
  });
}


