async function connectInjectedWallet(){
  if(isMetaMaskInstalled()){ closeModal(); return connectMetaMask(); }

  showLoading('Menghubungkan browser wallet…');
  try{
    var eth = window.ethereum;
    // prefer non-BaseRocky injected
    if(eth && eth.providers){
      eth = eth.providers.find(function(p){ return p.isMetaMask || p.isRabby; }) || eth.providers[0];
    }
    if(!eth || eth.isBaseRocky){
      hideLoading();
      showToast('Tidak ada MetaMask/Rabby. Install ekstensi dulu.');
      return;
    }
    var accounts = await eth.request({ method: 'eth_requestAccounts' });
    if(!accounts || !accounts.length) throw new Error('Tidak ada akun');
    state.address = accounts[0];
    state.walletName = eth.isMetaMask ? 'MetaMask' : (eth.isRabby ? 'Rabby' : 'Browser');
    state.hwType = 'injected';
    state.externalProvider = eth;
    hideLoading();
    closeModal();
    showToast('Terhubung: '+state.address.slice(0,6)+'…');
    if(typeof refreshWeb3 === 'function') await refreshWeb3(true);
    showScreen('home');
  }catch(e){
    hideLoading();
    showToast(e.message || 'Gagal koneksi');
  }
}



// Periodic light health check of active RPC
if(typeof window !== 'undefined' && !window._rpcHealthTimer){
  window._rpcHealthTimer = setInterval(async function(){
    if(!state.address) return;
    var url = state.activeRpc || (getRpcList()[0]);
    if(!url) return;
    var r = await pingRpc(url, 2500);
    state.rpcHealth[url] = { ok:r.ok, ms:r.ms, at:Date.now() };
    if(!r.ok){
      // auto failover
      _provider = null;
      try{
        await getProviderWithFallback(true);
        console.log('RPC failover →', state.activeRpc);
      }catch(e){}
    }
  }, 60000);
}


