var WC = {
  projectId: localStorage.getItem('br_wc_project_id') || '5cb934775791f3b1dd513f241ba9ee3c',
  provider: null,      // ethereum-provider (BaseRocky as dApp)
  web3wallet: null,    // web3wallet (BaseRocky as Wallet)
  core: null,
  sessions: {},
  pendingProposal: null,
  pendingRequest: null
};

function getWcMetadata(){
  return {
    name: 'BaseRocky Wallet',
    description: 'BaseRocky Web3 Wallet on Base',
    url: (typeof location !== 'undefined' && location.origin) ? location.origin : 'https://baserocky.com',
    icons: ['https://baserocky.com/favicon.ico']
  };
}

function openWcProjectIdSetup(thenFn){
  var html = '<h3>WalletConnect Project ID</h3>';
  html += '<p class="hint">Daftar gratis di <a href="https://cloud.walletconnect.com" target="_blank" rel="noopener" style="color:var(--mint)">cloud.walletconnect.com</a>, buat project, lalu tempel Project ID.</p>';
  html += '<div class="wc-pid"><input id="wcPidInput" placeholder="contoh: a1b2c3d4e5f6..." value="'+(WC.projectId||'')+'"></div>';
  html += '<button class="btn btn-primary" style="max-width:none;margin-top:12px" id="wcPidSave">Simpan & lanjut</button>';
  openModal(html);
  document.getElementById('wcPidSave').onclick = function(){
    var v = (document.getElementById('wcPidInput').value||'').trim();
    if(v.length < 8){ showToast('Project ID tidak valid'); return; }
    WC.projectId = v;
    localStorage.setItem('br_wc_project_id', v);
    showToast('Project ID disimpan');
    closeModal();
    if(typeof thenFn === 'function') setTimeout(thenFn, 200);
  };
}

async function loadWcEthereumProvider(){
  if(window.EthereumProvider) return window.EthereumProvider;
  // ESM dynamic import via esm.sh
  try{
    var mod = await import('https://esm.sh/@walletconnect/ethereum-provider@2.17.3');
    window.EthereumProvider = mod.EthereumProvider || mod.default;
    return window.EthereumProvider;
  }catch(e){
    console.error(e);
    throw new Error('Gagal memuat WalletConnect SDK. Cek koneksi internet.');
  }
}

async function loadWcWeb3Wallet(){
  if(WC.web3wallet) return WC.web3wallet;
  try{
    var coreMod = await import('https://esm.sh/@walletconnect/core@2.17.3');
    var w3wMod = await import('https://esm.sh/@walletconnect/web3wallet@1.16.1');
    var Core = coreMod.Core || coreMod.default;
    var Web3Wallet = w3wMod.Web3Wallet || w3wMod.default;
    WC.core = new Core({ projectId: WC.projectId });
    WC.web3wallet = await Web3Wallet.init({
      core: WC.core,
      metadata: getWcMetadata()
    });
    wireWeb3WalletEvents();
    return WC.web3wallet;
  }catch(e){
    console.error('Web3Wallet load', e);
    throw new Error('Gagal init Web3Wallet: '+(e.message||e));
  }
}

function wireWeb3WalletEvents(){
  var w = WC.web3wallet;
  if(!w || w.__brWired) return;
  w.__brWired = true;

  w.on('session_proposal', async function(proposal){
    WC.pendingProposal = proposal;
    showWcSessionProposal(proposal);
  });

  w.on('session_request', async function(event){
    WC.pendingRequest = event;
    await handleWcSessionRequest(event);
  });

  w.on('session_delete', function(){
    showToast('Sesi WalletConnect berakhir');
    WC.sessions = w.getActiveSessions() || {};
  });
}

function showWcSessionProposal(proposal){
  var params = proposal.params || {};
  var proposer = (params.proposer && params.proposer.metadata) || {};
  var chains = [];
  try{
    var ns = params.requiredNamespaces || {};
    Object.keys(ns).forEach(function(k){
      (ns[k].chains||[]).forEach(function(c){ chains.push(c); });
    });
  }catch(e){}
  var html = '<h3>Permintaan koneksi</h3>';
  html += '<div class="wc-session"><div class="n">'+(proposer.name||'DApp')+'</div>';
  html += '<div class="u">'+(proposer.url||'')+'</div></div>';
  html += '<p class="hint">Chain: '+(chains.join(', ')||'eip155')+'</p>';
  html += '<p class="hint">Izinkan DApp terhubung ke alamat BaseRocky Anda?</p>';
  html += '<div style="display:flex;gap:8px;margin-top:12px">';
  html += '<button class="btn btn-ghost" id="wcReject" style="flex:1">Tolak</button>';
  html += '<button class="btn btn-primary" id="wcApprove" style="flex:1">Setujui</button></div>';
  openModal(html);
  document.getElementById('wcReject').onclick = async function(){
    try{ await WC.web3wallet.rejectSession({ id: proposal.id, reason: { code: 5000, message: 'User rejected' } }); }catch(e){}
    WC.pendingProposal = null;
    closeModal();
    showToast('Ditolak');
  };
  document.getElementById('wcApprove').onclick = async function(){
    if(!state.address){ showToast('Import/buat wallet dulu'); return; }
    showLoading('Menyetujui sesi…');
    try{
      var namespaces = buildApprovedNamespaces(proposal);
      await WC.web3wallet.approveSession({ id: proposal.id, namespaces: namespaces });
      WC.sessions = WC.web3wallet.getActiveSessions() || {};
      hideLoading();
      closeModal();
      showToast('DApp terhubung');
    }catch(e){
      hideLoading();
      showToast(e.message || 'Gagal approve');
    }
    WC.pendingProposal = null;
  };
}

function buildApprovedNamespaces(proposal){
  var chainId = (typeof getChainId === 'function') ? getChainId() : 8453;
  var accounts = ['eip155:'+chainId+':'+state.address];
  // also expose eth mainnet account format for compatibility
  if(chainId !== 1) accounts.push('eip155:1:'+state.address);
  if(chainId !== 8453) accounts.push('eip155:8453:'+state.address);
  var methods = ['eth_sendTransaction','eth_signTransaction','eth_sign','personal_sign','eth_signTypedData','eth_signTypedData_v4','wallet_switchEthereumChain','wallet_addEthereumChain'];
  var events = ['chainChanged','accountsChanged'];
  var required = (proposal.params && proposal.params.requiredNamespaces) || {};
  var optional = (proposal.params && proposal.params.optionalNamespaces) || {};
  var namespaces = {};
  var keys = Object.keys(required).concat(Object.keys(optional));
  if(keys.indexOf('eip155') < 0) keys.push('eip155');
  keys.filter(function(v,i,a){return a.indexOf(v)===i;}).forEach(function(ns){
    var chains = (required[ns] && required[ns].chains) || (optional[ns] && optional[ns].chains) || ['eip155:'+chainId];
    namespaces[ns] = {
      accounts: accounts,
      methods: (required[ns] && required[ns].methods) || methods,
      events: (required[ns] && required[ns].events) || events,
      chains: chains
    };
  });
  return namespaces;
}

async function handleWcSessionRequest(event){
  var topic = event.topic;
  var params = event.params || {};
  var req = params.request || {};
  var method = req.method;
  var p = req.params || [];
  var html = '<h3>Tanda tangan diminta</h3>';
  html += '<p class="hint"><b>'+method+'</b></p>';
  html += '<div class="wc-uri-box">'+JSON.stringify(p).slice(0,280)+'</div>';
  html += '<div style="display:flex;gap:8px;margin-top:12px">';
  html += '<button class="btn btn-ghost" id="wcReqReject" style="flex:1">Tolak</button>';
  html += '<button class="btn btn-primary" id="wcReqApprove" style="flex:1">Tanda tangani</button></div>';
  openModal(html);

  document.getElementById('wcReqReject').onclick = async function(){
    try{
      await WC.web3wallet.respondSessionRequest({
        topic: topic,
        response: { id: event.id, jsonrpc: '2.0', error: { code: 5000, message: 'User rejected' } }
      });
    }catch(e){}
    closeModal();
  };

  document.getElementById('wcReqApprove').onclick = async function(){
    showLoading('Menandatangani…');
    try{
      var result = await executeWcRequest(method, p);
      await WC.web3wallet.respondSessionRequest({
        topic: topic,
        response: { id: event.id, jsonrpc: '2.0', result: result }
      });
      hideLoading();
      closeModal();
      showToast('Berhasil');
      if(typeof refreshWeb3 === 'function') refreshWeb3(false);
    }catch(e){
      hideLoading();
      try{
        await WC.web3wallet.respondSessionRequest({
          topic: topic,
          response: { id: event.id, jsonrpc: '2.0', error: { code: 5000, message: e.message || 'Error' } }
        });
      }catch(e2){}
      showToast(e.message || 'Gagal');
      closeModal();
    }
  };
}

async function executeWcRequest(method, params){
  if(method === 'personal_sign'){
    var msg = params[0];
    var signer = await getSigner();
    if(typeof msg === 'string' && msg.startsWith('0x')){
      return signer.signMessage(ethers.getBytes(msg));
    }
    return signer.signMessage(msg);
  }
  if(method === 'eth_sign'){
    var signer = await getSigner();
    return signer.signMessage(ethers.getBytes(params[1]));
  }
  if(method === 'eth_sendTransaction'){
    var txReq = params[0];
    var signer = await getSigner();
    var tx = await signer.sendTransaction({
      to: txReq.to,
      value: txReq.value || 0,
      data: txReq.data || '0x',
      gasLimit: txReq.gas || txReq.gasLimit
    });
    await tx.wait();
    return tx.hash;
  }
  if(method === 'eth_signTypedData' || method === 'eth_signTypedData_v4'){
    var signer = await getSigner();
    var data = typeof params[1] === 'string' ? JSON.parse(params[1]) : params[1];
    return signer.signTypedData(data.domain, data.types, data.message || data.value);
  }
  if(method === 'wallet_switchEthereumChain'){
    var cid = parseInt(params[0].chainId, 16);
    var found = Object.keys(RPC_CONFIG||{}).find(function(k){ return RPC_CONFIG[k].chainId === cid; });
    if(found && typeof selectNetwork === 'function') await selectNetwork(found);
    return null;
  }
  throw new Error('Method tidak didukung: '+method);
}

/** BaseRocky as WALLET: show pair URI / paste wc: URI from dapp */
async function startWcAsWallet(){
  if(!WC.projectId){ openWcProjectIdSetup(startWcAsWallet); return; }
  showLoading('Init WalletConnect…');
  try{
    await loadWcWeb3Wallet();
    hideLoading();
    var html = '<h3>WalletConnect v2</h3>';
    html += '<p class="hint">Sebagai <b>wallet</b>: tempel URI dari DApp, atau biarkan menunggu proposal.</p>';
    html += '<input id="wcPairUri" placeholder="wc:...." style="font-family:monospace;font-size:.8rem">';
    html += '<button class="btn btn-primary" style="max-width:none;margin-top:10px" id="wcPairBtn">Pair</button>';
    html += '<div style="margin-top:14px" id="wcSessList"></div>';
    html += '<button class="btn btn-ghost btn-sm" style="margin-top:8px" onclick="openWcProjectIdSetup()">Ganti Project ID</button>';
    openModal(html);
    renderWcSessions();
    document.getElementById('wcPairBtn').onclick = async function(){
      var uri = (document.getElementById('wcPairUri').value||'').trim();
      if(!uri || uri.indexOf('wc:') !== 0){ showToast('URI tidak valid'); return; }
      showLoading('Pairing…');
      try{
        await WC.web3wallet.core.pairing.pair({ uri: uri });
        hideLoading();
        showToast('Menunggu persetujuan DApp…');
      }catch(e){
        hideLoading();
        showToast(e.message || 'Pair gagal');
      }
    };
  }catch(e){
    hideLoading();
    showToast(e.message || 'Gagal init WC');
  }
}

function renderWcSessions(){
  var box = document.getElementById('wcSessList');
  if(!box || !WC.web3wallet) return;
  var sessions = WC.web3wallet.getActiveSessions() || {};
  var keys = Object.keys(sessions);
  if(!keys.length){ box.innerHTML = '<p class="hint">Belum ada sesi aktif</p>'; return; }
  box.innerHTML = '<p class="hint">Sesi aktif</p>' + keys.map(function(topic){
    var s = sessions[topic];
    var meta = (s.peer && s.peer.metadata) || {};
    return '<div class="wc-session"><div class="n">'+(meta.name||'DApp')+'</div><div class="u">'+(meta.url||topic.slice(0,16))+'</div></div>';
  }).join('');
}

/** BaseRocky as DAPP: connect external mobile wallet via QR */
async function connectWalletConnectQR(){
  if(!WC.projectId){ openWcProjectIdSetup(connectWalletConnectQR); return; }
  showLoading('Menghubungkan WalletConnect…');
  try{
    var EthereumProvider = await loadWcEthereumProvider();
    var chainId = (typeof getChainId === 'function') ? getChainId() : 8453;
    var provider = await EthereumProvider.init({
      projectId: WC.projectId,
      metadata: getWcMetadata(),
      showQrModal: true,
      optionalChains: [chainId, 1, 8453, 56, 137, 42161, 10],
      chains: [chainId],
      rpcMap: buildWcRpcMap(),
      methods: ['eth_sendTransaction','personal_sign','eth_signTypedData','eth_signTypedData_v4','eth_accounts','eth_requestAccounts','wallet_switchEthereumChain'],
      events: ['chainChanged','accountsChanged']
    });
    WC.provider = provider;
    await provider.connect();
    var accounts = provider.accounts || [];
    if(!accounts.length) throw new Error('Tidak ada akun');
    state.address = accounts[0];
    state.walletName = 'WalletConnect';
    state.hwType = 'walletconnect';
    state.externalProvider = provider;
    provider.on('accountsChanged', function(acc){
      if(acc && acc[0]){ state.address = acc[0]; if(typeof renderHome==='function') renderHome(); }
    });
    provider.on('chainChanged', function(cid){
      var n = parseInt(cid, 16);
      var found = Object.keys(RPC_CONFIG||{}).find(function(k){ return RPC_CONFIG[k].chainId === n; });
      if(found) state.network = found;
    });
    provider.on('disconnect', function(){
      showToast('WalletConnect terputus');
    });
    hideLoading();
    closeModal();
    showToast('WC terhubung: '+state.address.slice(0,6)+'…');
    if(typeof refreshWeb3 === 'function') await refreshWeb3(true);
    showScreen('home');
  }catch(e){
    hideLoading();
    console.error(e);
    showToast(e.message || 'WalletConnect gagal');
  }
}

function buildWcRpcMap(){
  var map = {};
  if(typeof RPC_CONFIG === 'undefined') return map;
  Object.keys(RPC_CONFIG).forEach(function(k){
    var c = RPC_CONFIG[k];
    if(c.rpcs && c.rpcs[0]) map[c.chainId] = c.rpcs[0];
  });
  return map;
}

