  html += '<div class="wc-opt" id="wcInjected"><div class="ico">🦊</div><div><div class="t">Browser Wallet</div><div class="s">MetaMask / Rabby</div></div></div>';
  html += '<div class="wc-opt" id="wcAsWallet"><div class="ico">📲</div><div><div class="t">WC: Terima koneksi DApp</div><div class="s">BaseRocky sebagai wallet · pair URI</div></div></div>';
  html += '<div class="wc-opt" id="wcAsDapp"><div class="ico">🔗</div><div><div class="t">WC: Hubungkan wallet mobile</div><div class="s">QR modal · Trust / MetaMask Mobile</div></div></div>';
  html += '<div class="wc-opt" id="wcLedger"><div class="ico">🛡️</div><div><div class="t">Ledger</div><div class="s">WebUSB</div></div></div>';
  html += '<div class="wc-opt" id="wcPid"><div class="ico">⚙️</div><div><div class="t">Project ID</div><div class="s">cloud.walletconnect.com</div></div></div>';
