function getWalletAvatar() {
  var saved = localStorage.getItem('br_avatar');
  if (saved) return saved;
  try {
    var el = document.getElementById('setAvatar');
    if (el && el.src && el.src.indexOf('data:') !== 0 && el.src.length > 10) return el.src;
  } catch (e) {}
  if (typeof LOGO !== 'undefined' && LOGO) return LOGO;
  return AVATAR_PRESETS[0];
}

function setWalletAvatar(url) {
  localStorage.setItem('br_avatar', url);
  ['setAvatar', 'profAvatar', 'homeAvatar'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.src = url;
  });
  document.querySelectorAll('.acc-avatar, .bg-top .avatar img, .home-avatar').forEach(function(el) {
    try { el.src = url; } catch (e) {}
  });
}

function getSecurityLevel() {
  var hasPin = !!(localStorage.getItem(PIN_KEY) || localStorage.getItem('br_pin_v6'));
  var hasBackup = localStorage.getItem('br_seed_backed_up') === '1';
  var has2fa = localStorage.getItem('br_totp_secret') ? true : false;
  var score = 0;
  if (hasPin) score += 1;
  if (hasBackup) score += 1;
  if (has2fa) score += 1;
  if (score >= 3) return { label: 'Tinggi', cls: 'ok', icon: '' };
  if (score >= 1) return { label: 'Sedang', cls: 'mid', icon: '⚠ ' };
  return { label: 'Rendah', cls: 'low', icon: '⚠ ' };
}

