/* --- Private key --- */
function showPrivateKey() {
  if (!state.address) return showToast('Tidak ada wallet');
  requirePin(function() {
    var pk = '';
    try {
      if (state.wallet && state.wallet.privateKey) pk = state.wallet.privateKey;
      else if (state.privateKey) pk = state.privateKey;
      else pk = localStorage.getItem('br_pk') || '';
    } catch (e) {}

    if (!pk && typeof SecureStore !== 'undefined') {
      SecureStore.get('pk').then(function(p) {
        _showPkModal(p || '');
      }).catch(function() { _showPkModal(''); });
      return;
    }
    _showPkModal(pk);
  });
}

function _showPkModal(pk) {
  if (!pk) {
    openModal(
      '<div class="modal-handle"></div><h3>Kunci pribadi</h3>' +
      '<div class="sec-card sec-warn"><p style="margin:0">Kunci tidak tersedia (wallet eksternal / hardware).</p></div>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:12px" onclick="openAccountManage()">Kembali</button>'
    );
    return;
  }
  openModal(
    '<div class="modal-handle"></div><h3>Kunci pribadi</h3>' +
    '<div class="sec-card sec-warn"><p style="margin:0 0 8px;font-weight:600">Jangan pernah dibagikan!</p>' +
    '<p style="margin:0;word-break:break-all;font-family:var(--mono);font-size:.78rem" id="pkRevealText">' + pk + '</p></div>' +
    '<button class="btn btn-primary" style="max-width:none;margin-top:12px" onclick="navigator.clipboard.writeText(document.getElementById(\'pkRevealText\').textContent).then(function(){showToast(\'Kunci disalin\')})">Salin kunci</button>' +
    '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="openAccountManage()">Kembali</button>'
  );
}

/* --- Seed phrase --- */
function viewSeedPhrase() {
  if (!state.address) return showToast('Tidak ada wallet');
  requirePin(function() {
    var phrase = state.phrase || localStorage.getItem('br_phrase') || '';
    if (!phrase && state.wallet && state.wallet.mnemonic) {
      try { phrase = state.wallet.mnemonic.phrase || ''; } catch (e) {}
    }
    if (!phrase) {
      openModal(
        '<div class="modal-handle"></div><h3>Seed phrase</h3>' +
        '<div class="sec-card sec-warn"><p style="margin:0">Seed tidak tersedia. Wallet mungkin diimpor dari private key atau terhubung eksternal.</p></div>' +
        '<button class="btn btn-ghost" style="max-width:none;margin-top:12px" onclick="openAccountManage()">Kembali</button>'
      );
      return;
    }
    var words = phrase.trim().split(/\s+/);
    var grid = words.map(function(w, i) {
      return '<div class="seed-word"><span class="n">' + (i + 1) + '</span>' + w + '</div>';
    }).join('');
    openModal(
      '<div class="modal-handle"></div><h3>Seed phrase</h3>' +
      '<div class="sec-card sec-warn"><p style="margin:0;font-size:.8rem">Tulis di kertas & simpan offline. Jangan screenshot atau bagikan.</p></div>' +
      '<div class="seed-grid" style="margin:12px 0">' + grid + '</div>' +
      '<button class="btn btn-primary" style="max-width:none" onclick="navigator.clipboard.writeText(\'' + phrase.replace(/'/g, "") + '\').then(function(){showToast(\'Seed disalin\');localStorage.setItem(\'br_seed_backed_up\',\'1\')})">Salin seed</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="localStorage.setItem(\'br_seed_backed_up\',\'1\');showToast(\'Ditandai sudah di-backup\');openAccountManage()">Saya sudah backup</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:4px" onclick="openAccountManage()">Kembali</button>'
    );
  });
}

/* --- Google Authenticator (local TOTP-style secret) --- */
function openAuthenticator() {
  var secret = localStorage.getItem('br_totp_secret');
  if (secret) {
    openModal(
      '<div class="modal-handle"></div><h3>Google Authenticator</h3>' +
      '<div class="sec-card"><p style="margin:0 0 6px;font-weight:600;color:var(--green)">✓ Terikat</p>' +
      '<p class="hint" style="margin:0">Secret tersimpan lokal. Verifikasi memakai kode 6 digit saat fitur sensitif diaktifkan.</p></div>' +
      '<div class="field" style="margin-top:12px"><label>Uji kode</label>' +
      '<input id="totpTestInput" inputmode="numeric" maxlength="6" placeholder="000000" autocomplete="off"></div>' +
      '<button class="btn btn-primary" style="max-width:none" onclick="verifyTotpTest()">Verifikasi</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px;color:var(--red)" onclick="unlinkAuthenticator()">Hapus ikatan</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:4px" onclick="openAccountManage()">Kembali</button>'
    );
    return;
  }
  // Generate new secret (base32-like)
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  var s = '';
  for (var i = 0; i < 16; i++) s += chars[Math.floor(Math.random() * chars.length)];
  state._pendingTotp = s;
  var account = encodeURIComponent(state.walletName || 'BaseRocky');
  var otpauth = 'otpauth://totp/BaseRocky:' + account + '?secret=' + s + '&issuer=BaseRocky&digits=6&period=30';
  openModal(
    '<div class="modal-handle"></div><h3>Google Authenticator</h3>' +
    '<p class="hint">Scan QR atau masukkan secret ke aplikasi Authenticator.</p>' +
    '<div class="qr-wrap qr-wrap-modern" style="margin:12px auto;width:fit-content"><div id="totpQrHost" class="qr-host"></div></div>' +
    '<div class="sec-card" style="text-align:center"><p style="margin:0;font-family:var(--mono);letter-spacing:.12em;font-weight:700" id="totpSecretText">' + s + '</p></div>' +
    '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="navigator.clipboard.writeText(document.getElementById(\'totpSecretText\').textContent).then(function(){showToast(\'Secret disalin\')})">Salin secret</button>' +
    '<div class="field" style="margin-top:12px"><label>Kode dari Authenticator</label>' +
    '<input id="totpConfirmInput" inputmode="numeric" maxlength="6" placeholder="000000" autocomplete="off"></div>' +
    '<button class="btn btn-primary" style="max-width:none" onclick="confirmAuthenticator()">Aktifkan</button>' +
    '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="openAccountManage()">Batal</button>'
  );
  setTimeout(function() {
    if (typeof renderModernQR === 'function') {
      renderModernQR('totpQrHost', otpauth, { size: 180, withLogo: false, dark: '#0a1628', ecl: 'M' });
    }
  }, 60);
}

/** Simple TOTP (SHA-1 via SubtleCrypto) — demo verification */
async function _totpCode(secret, at) {
  // Base32 decode
  var alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  var bits = '';
  secret = secret.toUpperCase().replace(/=+$/, '');
  for (var i = 0; i < secret.length; i++) {
    var val = alphabet.indexOf(secret[i]);
    if (val < 0) continue;
    bits += val.toString(2).padStart(5, '0');
  }
  var bytes = [];
  for (var j = 0; j + 8 <= bits.length; j += 8) {
    bytes.push(parseInt(bits.slice(j, j + 8), 2));
  }
  var key = new Uint8Array(bytes);
  var counter = Math.floor((at || Date.now()) / 30000);
  var buf = new ArrayBuffer(8);
  var view = new DataView(buf);
  view.setUint32(4, counter >>> 0);
  view.setUint32(0, Math.floor(counter / 0x100000000));
  try {
    var cryptoKey = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-1' }, false, ['sign']);
    var sig = new Uint8Array(await crypto.subtle.sign('HMAC', cryptoKey, buf));
    var off = sig[sig.length - 1] & 0xf;
    var code = ((sig[off] & 0x7f) << 24 | (sig[off + 1] & 0xff) << 16 | (sig[off + 2] & 0xff) << 8 | (sig[off + 3] & 0xff)) % 1000000;
    return String(code).padStart(6, '0');
  } catch (e) {
    // Fallback: not cryptographically ideal but functional offline demo
    var h = 0;
    var str = secret + ':' + counter;
    for (var k = 0; k < str.length; k++) h = (h * 31 + str.charCodeAt(k)) >>> 0;
    return String(h % 1000000).padStart(6, '0');
  }
}

async function confirmAuthenticator() {
  var input = (document.getElementById('totpConfirmInput') || {}).value || '';
  input = input.trim();
  var secret = state._pendingTotp;
  if (!secret) return showToast('Sesi berakhir, coba lagi');
  if (!/^\d{6}$/.test(input)) return showToast('Masukkan 6 digit kode');
  var now = Date.now();
  var c0 = await _totpCode(secret, now);
  var c1 = await _totpCode(secret, now - 30000);
  var c2 = await _totpCode(secret, now + 30000);
  if (input !== c0 && input !== c1 && input !== c2) {
    return showToast('Kode salah — coba lagi');
  }
  localStorage.setItem('br_totp_secret', secret);
  state._pendingTotp = null;
  showToast('Authenticator diaktifkan');
  openAccountManage();
}

async function verifyTotpTest() {
  var input = ((document.getElementById('totpTestInput') || {}).value || '').trim();
  var secret = localStorage.getItem('br_totp_secret');
  if (!secret) return showToast('Belum terikat');
  if (!/^\d{6}$/.test(input)) return showToast('Masukkan 6 digit');
  var now = Date.now();
  var codes = [await _totpCode(secret, now), await _totpCode(secret, now - 30000), await _totpCode(secret, now + 30000)];
  if (codes.indexOf(input) >= 0) showToast('Kode valid ✓');
  else showToast('Kode tidak valid');
}

function unlinkAuthenticator() {
  if (!confirm('Hapus ikatan Google Authenticator?')) return;
  localStorage.removeItem('br_totp_secret');
  showToast('Ikatan dihapus');
  openAccountManage();
}

/* --- Authorization verification --- */
function openAuthVerification() {
  var hasPin = !!(localStorage.getItem(PIN_KEY) || localStorage.getItem('br_pin_v6'));
  var has2fa = !!localStorage.getItem('br_totp_secret');
  var hasBackup = localStorage.getItem('br_seed_backed_up') === '1';
  var sec = getSecurityLevel();

  var html = '<div class="modal-handle"></div><h3>Verifikasi otorisasi</h3>';
  html += '<p class="hint">Status keamanan akun Anda.</p>';
  html += '<div class="acc-list" style="margin-top:8px">';
  html += rowCheck('PIN keamanan', hasPin, hasPin ? 'Ubah PIN' : 'Atur PIN', hasPin ? 'openSecurityCenter()' : 'openSecurityCenter()');
  html += rowCheck('Backup seed phrase', hasBackup, hasBackup ? 'Lihat lagi' : 'Backup sekarang', 'viewSeedPhrase()');
  html += rowCheck('Google Authenticator', has2fa, has2fa ? 'Kelola' : 'Aktifkan', 'openAuthenticator()');
  html += '</div>';
  html += '<div class="sec-card" style="margin-top:12px"><p style="margin:0;font-size:.85rem">Tingkat: <strong class="acc-sec-badge ' + sec.cls + '">' + sec.label + '</strong></p>';
  html += '<p class="hint" style="margin:6px 0 0">Lengkapi semua item untuk tingkat Tinggi.</p></div>';
  html += '<button class="btn btn-primary" style="max-width:none;margin-top:12px" onclick="runAuthChallenge()">Uji verifikasi sekarang</button>';
  html += '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="openAccountManage()">Kembali</button>';
  openModal(html);

  function rowCheck(label, ok, actionLabel, action) {
    return '<div class="acc-row" onclick="' + action + '">' +
      '<span>' + (ok ? '✓ ' : '○ ') + label + '</span>' +
      '<span class="acc-row-right"><span class="acc-muted">' + actionLabel + '</span>' +
      '<svg class="acc-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 18l6-6-6-6"/></svg></span></div>';
  }
}

function runAuthChallenge() {
  requirePin(function() {
    var secret = localStorage.getItem('br_totp_secret');
    if (!secret) {
      showToast('Verifikasi PIN berhasil ✓');
      return;
    }
    openModal(
      '<div class="modal-handle"></div><h3>Kode Authenticator</h3>' +
      '<p class="hint">Masukkan kode 6 digit dari aplikasi Authenticator.</p>' +
      '<div class="field"><input id="authChallengeInput" inputmode="numeric" maxlength="6" placeholder="000000" autocomplete="off"></div>' +
      '<button class="btn btn-primary" style="max-width:none" onclick="completeAuthChallenge()">Verifikasi</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="openAuthVerification()">Batal</button>'
    );
  });
}

async function completeAuthChallenge() {
  var input = ((document.getElementById('authChallengeInput') || {}).value || '').trim();
  var secret = localStorage.getItem('br_totp_secret');
  if (!secret) return showToast('OK');
  var now = Date.now();
  var codes = [await _totpCode(secret, now), await _totpCode(secret, now - 30000), await _totpCode(secret, now + 30000)];
  if (codes.indexOf(input) >= 0) {
    showToast('Verifikasi lengkap ✓');
    openAccountManage();
  } else {
    showToast('Kode salah');
  }
}

