function executeDeleteWallet() {
  var v = ((document.getElementById('deleteConfirmInput') || {}).value || '').trim();
  if (v !== 'HAPUS') return showToast('Ketik HAPUS untuk konfirmasi');
  try {
    if (typeof wipeWallet === 'function') {
      // wipeWallet has its own confirm — bypass by clearing directly
      var keys = [];
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (k && (k.indexOf('br_') === 0 || k.indexOf('baserocky') === 0)) keys.push(k);
      }
      keys.forEach(function(k) { localStorage.removeItem(k); });
    }
    state.wallet = null;
    state.address = null;
    state.phrase = null;
    state.privateKey = null;
    state._unlocked = false;
    closeModal();
    showToast('Wallet dihapus');
    if (typeof showScreen === 'function') showScreen('onboard');
  } catch (e) {
    showToast('Gagal menghapus');
  }
}

