/* ===== MetaMask integration + panel anim helpers ===== */
var MetaMask = {
  provider: null,
  accounts: [],
  chainId: null
};

function getMetaMaskProvider(){
  var eth = window.ethereum;
  if(!eth) return null;
  // Multi-injected providers
  if(eth.providers && eth.providers.length){
    var mm = eth.providers.find(function(p){ return p.isMetaMask && !p.isBraveWallet; });
    if(mm) return mm;
    mm = eth.providers.find(function(p){ return p.isMetaMask; });
    if(mm) return mm;
  }
  if(eth.isMetaMask) return eth;
  return null;
}

function isMetaMaskInstalled(){
  return !!getMetaMaskProvider();
}

async function connectMetaMask(){
  var mm = getMetaMaskProvider();
  if(!mm){
    openModal(
      '<h3>MetaMask</h3>'+
      '<p class="hint">MetaMask belum terdeteksi di browser ini.</p>'+
      '<a class="btn btn-primary" style="max-width:none;display:block;text-align:center;text-decoration:none;margin-top:12px" href="https://metamask.io/download/" target="_blank" rel="noopener">Install MetaMask</a>'+
      '<p class="hint" style="margin-top:10px">Lalu refresh halaman ini dan hubungkan lagi.</p>'
    );
    return null;
  }
  showLoading('Menghubungkan MetaMask…');
  try{
    var accounts = await mm.request({ method: 'eth_requestAccounts' });
    if(!accounts || !accounts.length) throw new Error('Tidak ada akun');
    var chainId = await mm.request({ method: 'eth_chainId' });
    MetaMask.provider = mm;
    MetaMask.accounts = accounts;
    MetaMask.chainId = chainId;

    state.address = accounts[0];
    state.walletName = 'MetaMask';
    state.hwType = 'metamask';
    state.externalProvider = mm;
    state._unlocked = true;

    wireMetaMaskEvents(mm);

    // switch to Base if possible
    try{ await switchMetaMaskChain(8453); }catch(e){ console.log('chain switch', e); }

    hideLoading();
    closeModal();
    showToast('MetaMask: '+accounts[0].slice(0,6)+'…'+accounts[0].slice(-4));
    if(typeof refreshWeb3 === 'function') await refreshWeb3(true);
    if(typeof renderHome === 'function') renderHome();
    if(typeof updateBerandaHeader === 'function') updateBerandaHeader();
    showScreen('home');
    return accounts[0];
  }catch(e){
    hideLoading();
    if(e && e.code === 4001) showToast('Permintaan ditolak di MetaMask');
    else showToast((e && e.message) || 'Gagal hubungkan MetaMask');
    return null;
  }
}

function wireMetaMaskEvents(mm){
  if(!mm || mm.__brMmWired) return;
  mm.__brMmWired = true;
  mm.on('accountsChanged', function(acc){
    if(!acc || !acc.length){
      showToast('MetaMask terputus');
      state.externalProvider = null;
      state.hwType = '';
      return;
    }
    state.address = acc[0];
    MetaMask.accounts = acc;
    showToast('Akun: '+acc[0].slice(0,6)+'…');
    if(typeof refreshWeb3 === 'function') refreshWeb3(true);
  });
  mm.on('chainChanged', function(cid){
    MetaMask.chainId = cid;
    var n = parseInt(cid, 16);
    var found = Object.keys(RPC_CONFIG||{}).find(function(k){ return RPC_CONFIG[k].chainId === n; });
    if(found){
      state.network = found;
      if(typeof updateNetworkUI === 'function') updateNetworkUI();
      if(typeof loadNetworkTokens === 'function') loadNetworkTokens(found);
      if(typeof refreshWeb3 === 'function') refreshWeb3(true);
    }
    showToast('Jaringan MetaMask: '+cid);
  });
  mm.on('disconnect', function(){
    showToast('MetaMask disconnect');
  });
}

async function switchMetaMaskChain(chainId){
  var mm = MetaMask.provider || getMetaMaskProvider();
  if(!mm) throw new Error('MetaMask tidak ada');
  var hex = '0x' + Number(chainId).toString(16);
  try{
    await mm.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: hex }] });
  }catch(e){
    // 4902 = chain not added
    if(e.code === 4902 || (e.data && e.data.originalError && e.data.originalError.code === 4902)){
      var cfg = null;
      Object.keys(RPC_CONFIG||{}).forEach(function(k){
        if(RPC_CONFIG[k].chainId === chainId) cfg = RPC_CONFIG[k];
      });
      if(!cfg) throw e;
      await mm.request({
        method: 'wallet_addEthereumChain',
        params: [{
          chainId: hex,
          chainName: cfg.name,
          nativeCurrency: { name: cfg.native, symbol: cfg.native, decimals: 18 },
          rpcUrls: cfg.rpcs.slice(0,2),
          blockExplorerUrls: [cfg.explorer]
        }]
      });
    } else throw e;
  }
}

async function metaMaskSendTransaction(tx){
  var mm = MetaMask.provider || getMetaMaskProvider();
  if(!mm) throw new Error('MetaMask tidak terhubung');
  var from = state.address;
  var params = Object.assign({ from: from }, tx);
  showLoading('Konfirmasi di MetaMask…');
  try{
    var hash = await mm.request({ method: 'eth_sendTransaction', params: [params] });
    hideLoading();
    return hash;
  }catch(e){
    hideLoading();
    throw e;
  }
}

// Override getSigner path when MetaMask connected — external txs
async function sendWithBestProvider(to, valueWei, data){
  if(state.hwType === 'metamask' || state.hwType === 'injected'){
    return metaMaskSendTransaction({
      to: to,
      value: valueWei ? (typeof valueWei === 'string' ? valueWei : ethers.toBeHex(valueWei)) : undefined,
      data: data || undefined
    });
  }
  var signer = await getSigner();
  var tx = await signer.sendTransaction({ to: to, value: valueWei || 0, data: data || '0x' });
  await tx.wait();
  return tx.hash;
}

function openMetaMaskPanel(){
  var installed = isMetaMaskInstalled();
  var connected = state.hwType === 'metamask' && state.address;
  var html = '<h3>MetaMask</h3>';
  html += '<div class="mm-card" id="mmConnectBtn">';
  html += '<div class="ico"><img src="https://images.ctfassets.net/clixtyxoaeas/1ezuBGezsmJurE5a2i5bmY/d98d15bd264c88c9793e3f6a87ad3b58/MetaMask-icon-fox.svg" alt="MM"></div>';
  html += '<div style="flex:1"><div class="t">MetaMask</div><div class="s">'+(installed?'Terdeteksi di browser':'Belum terinstall')+'</div></div>';
  html += '<span class="mm-status '+(connected?'':'off')+'">'+(connected?'Terhubung':'Hubungkan')+'</span>';
  html += '</div>';
  if(connected){
    html += '<p class="hint" style="font-family:monospace">'+state.address+'</p>';
    html += '<button class="btn btn-ghost" style="max-width:none" id="mmSwitchBase">Jaringan → Base</button>';
    html += '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" id="mmDisconnect">Putuskan</button>';
  } else {
    html += '<button class="btn btn-primary" style="max-width:none" id="mmConnectBtn2">Hubungkan MetaMask</button>';
  }
  openModal(html);
  var go = function(){ connectMetaMask(); };
  var b1 = document.getElementById('mmConnectBtn');
  var b2 = document.getElementById('mmConnectBtn2');
  if(b1 && !connected) b1.onclick = go;
  if(b2) b2.onclick = go;
  var sb = document.getElementById('mmSwitchBase');
  if(sb) sb.onclick = async function(){
    try{ await switchMetaMaskChain(8453); showToast('Base'); }catch(e){ showToast(e.message||'Gagal'); }
  };
  var dc = document.getElementById('mmDisconnect');
  if(dc) dc.onclick = function(){
    state.hwType = '';
    state.externalProvider = null;
    MetaMask.provider = null;
    closeModal();
    showToast('MetaMask diputus (di app)');
  };
}

/* Panel animation helpers */
function openProfileMenuAnimated(){
  var bg = document.getElementById('profBg');
  var panel = document.getElementById('profPanel');
  if(!bg) return;
  if(typeof openProfileMenu === 'function'){
    // call fill logic only - avoid recursion if we replace openProfileMenu
  }
  openProfileMenu();
  if(panel){
    panel.style.transform = 'translateY(12px)';
    panel.style.opacity = '0';
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){
        panel.style.transform = '';
        panel.style.opacity = '';
      });
    });
  }
}

function closeProfileMenuAnimated(){
  var bg = document.getElementById('profBg');
  var panel = document.getElementById('profPanel');
  if(!panel || !bg){ closeProfileMenu(); return; }
  panel.style.transition = 'transform .25s ease, opacity .2s ease';
  panel.style.transform = 'translateY(20px)';
  panel.style.opacity = '0';
  bg.style.opacity = '0';
  setTimeout(function(){
    closeProfileMenu();
    panel.style.transform = '';
    panel.style.opacity = '';
    bg.style.opacity = '';
  }, 240);
}


function goDefaultHomePage() {
  var p = state.defaultPage || localStorage.getItem('br_default_page') || 'home';
  // Ensure tokens for current network exist before first paint
  try {
    var netId = state.network || localStorage.getItem('br_v4_network') || 'base';
    state.network = netId;
    if (typeof loadNetworkTokens === 'function' && (!state.tokens || !state.tokens.length)) {
      loadNetworkTokens(netId);
    }
  } catch (e) {}
  if (p === 'dapps' || p === 'discover') {
    try { showScreen(p); } catch (e) { showScreen('home'); }
  } else {
    try { showScreen('home'); } catch (e) {}
  }
  // Paint token list immediately (same path as network switch — proven to work)
  try {
    if (typeof window.applyNetworkUi === 'function') {
      window.applyNetworkUi(state.network || 'base');
    } else if (typeof renderHome === 'function') {
      renderHome();
    }
  } catch (e) {}
  try {
    if (typeof window.ensureHomeTokenList === 'function') {
      setTimeout(function(){ window.ensureHomeTokenList('goDefaultHome'); }, 100);
    }
  } catch (e) {}
}

