// ---- Pull-to-refresh (simple) ----
var _ptrStartY = 0;
var _ptrPulling = false;
function initPullToRefresh() {
  var home = document.getElementById('screen-home');
  if (!home) return;
  home.addEventListener('touchstart', function(e) {
    if (home.scrollTop <= 0) {
      _ptrStartY = e.touches[0].clientY;
      _ptrPulling = true;
    }
  }, { passive: true });
  home.addEventListener('touchend', function(e) {
    if (!_ptrPulling) return;
    _ptrPulling = false;
    var dy = e.changedTouches[0].clientY - _ptrStartY;
    if (dy > 80 && state.address) {
      showToast('Memperbarui…');
      if (typeof refreshBalances === 'function') refreshBalances(true);
    }
  }, { passive: true });
}

// ---- Boot v6 enhancements ----
function bootV6() {
  try { startAutoLockWatcher(); } catch (e) {}
  try { updateNetworkStatus(); } catch (e) {}
  try { initPullToRefresh(); } catch (e) {}
  try { ensureSendGasUI(); } catch (e) {}

  // Add Address Book entry point in settings if possible
  try {
    var settingsScreen = document.getElementById('screen-settings');
    if (settingsScreen && !document.getElementById('v6AddrBookBtn')) {
      // non-destructive: users can call openAddressBookFromSettings from console or we hook existing
    }
  } catch (e) {}

  // Intercept send screen open to show gas selector
  var origShowScreen = typeof showScreen === 'function' ? showScreen : null;
  if (origShowScreen) {
    window.showScreen = function(name) {
      origShowScreen(name);
      if (name === 'send') {
        setTimeout(function() {
          ensureSendGasUI();
          var box = document.getElementById('gasSelectorSend');
          if (box && !box.innerHTML) {
            renderGasSelector('gasSelectorSend');
            estimateGasWithLevels();
          }
        }, 100);
      }
    };
  }

  brLog('%cBaseRocky Wallet v6 enhancements loaded', 'color:#00e6b8;font-weight:bold');
}

// Run after original boot
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function() { setTimeout(bootV6, 300); });
} else {
  setTimeout(bootV6, 300);
}


/* ============================================================
   BaseRocky Referral Center (Bitget-style)
   Local referral code, invite list, tiers, bind code
   ============================================================ */

const REF_KEY = 'br_referral_v6';
const REF_TIERS = [
  { id: 1, name: 'Tier 1', need: 0,  rate: '10%', bonus: 50,  color: '#848E9C' },
  { id: 2, name: 'Tier 2', need: 5,  rate: '12%', bonus: 75,  color: '#00D4AA' },
  { id: 3, name: 'Tier 3', need: 20, rate: '15%', bonus: 100, color: '#F0B90B' },
  { id: 4, name: 'Elite',  need: 50, rate: '20%', bonus: 150, color: '#8B5CF6' }
];

function getRefData() {
  try {
    var raw = localStorage.getItem(REF_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return { code: null, boundCode: null, invites: [], points: 0, created: Date.now() };
}
function saveRefData(data) {
  localStorage.setItem(REF_KEY, JSON.stringify(data));
}

/** Generate short referral code from wallet address */
function generateRefCode(address) {
  if (!address) return 'ROCKY0';
  var h = 0;
  var s = address.toLowerCase();
  for (var i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  var code = 'BR';
  var n = Math.abs(h);
  for (var j = 0; j < 4; j++) {
    code += chars[n % chars.length];
    n = Math.floor(n / chars.length) + (j + 1) * 17;
  }
  return code;
}

function ensureRefCode() {
  var data = getRefData();
  if (!data.code && state.address) {
    data.code = generateRefCode(state.address);
    saveRefData(data);
  }
  return data.code || '------';
}

function getRefLink() {
  var code = ensureRefCode();
  // Shareable link — opens app with ?ref=CODE
  var base = location.href.split('?')[0].split('#')[0];
  return base + '?ref=' + code;
}

function getCurrentTier(inviteCount) {
  var tier = REF_TIERS[0];
  for (var i = 0; i < REF_TIERS.length; i++) {
    if (inviteCount >= REF_TIERS[i].need) tier = REF_TIERS[i];
  }
  return tier;
}

function renderReferralCenter() {
  var data = getRefData();
  var code = ensureRefCode();
  data = getRefData(); // refresh after ensure

  var count = (data.invites || []).length;
  var tier = getCurrentTier(count);
  var points = data.points || 0;

  var el;
  if ((el = document.getElementById('refCodeDisplay'))) el.textContent = code;
  if ((el = document.getElementById('refLinkInput'))) el.value = getRefLink();
  if ((el = document.getElementById('refCount'))) el.textContent = count;
  if ((el = document.getElementById('refTier'))) el.textContent = tier.name;
  if ((el = document.getElementById('refPoints'))) el.textContent = points.toLocaleString();
  if ((el = document.getElementById('refListCount'))) el.textContent = count ? '(' + count + ')' : '';

  // Tiers
  var tiersEl = document.getElementById('refTiersList');
  if (tiersEl) {
    tiersEl.innerHTML = REF_TIERS.map(function(t) {
      var isCurrent = t.id === tier.id;
      var locked = count < t.need;
      return '<div class="ref-tier' + (isCurrent ? ' current' : '') + '">' +
        '<div class="ref-tier-badge">' + (isCurrent ? '✓' : 'T' + t.id) + '</div>' +
        '<div class="ref-tier-info">' +
          '<div class="tn">' + t.name + (isCurrent ? ' · Aktif' : '') + '</div>' +
          '<div class="td">' + (t.need === 0 ? 'Default' : 'Min. ' + t.need + ' undangan') +
            (locked && t.need > 0 ? ' · butuh ' + (t.need - count) + ' lagi' : '') + '</div>' +
        '</div>' +
        '<div class="ref-tier-rate">' + t.rate + '</div>' +
      '</div>';
    }).join('');
  }

  // Bound code info
  var bindInfo = document.getElementById('refBoundInfo');
  var bindCard = document.getElementById('refBindCard');
  if (data.boundCode) {
    if (bindInfo) {
      bindInfo.style.display = 'block';
      bindInfo.innerHTML = '✅ Terikat ke kode: <b style="color:var(--mint)">' + escapeHtml(data.boundCode) + '</b>';
    }
    var inp = document.getElementById('refBindInput');
    if (inp) { inp.disabled = true; inp.value = data.boundCode; }
  } else {
    if (bindInfo) bindInfo.style.display = 'none';
    var inp2 = document.getElementById('refBindInput');
    if (inp2) { inp2.disabled = false; inp2.value = ''; }
  }

  // Invite list
  var listEl = document.getElementById('refInviteList');
  if (listEl) {
    var invites = data.invites || [];
    if (!invites.length) {
      listEl.innerHTML = '<div class="empty-state" style="padding:20px"><p class="hint">Belum ada teman yang bergabung</p></div>';
    } else {
      listEl.innerHTML = invites.map(function(inv) {
        var initial = escapeHtml(String((inv.name || inv.code || '?')[0] || '?').toUpperCase());
        var date = inv.at ? new Date(inv.at).toLocaleDateString('id-ID') : '';
        return '<div class="ref-invite-row">' +
          '<div class="ref-invite-av">' + initial + '</div>' +
          '<div class="ref-invite-info">' +
            '<div class="n">' + escapeHtml(inv.name || 'Teman') + '</div>' +
            '<div class="s">' + escapeHtml(inv.code || '') + (date ? ' · ' + escapeHtml(date) : '') + '</div>' +
          '</div>' +
          '<div class="ref-invite-pts">+' + escapeHtml(String(inv.points || 0)) + '</div>' +
        '</div>';
      }).join('');
    }
  }
}

function copyRefLink() {
  var link = getRefLink();
  navigator.clipboard.writeText(link).then(function() {
    showToast('Link disalin');
  }).catch(function() {
    showToast('Gagal menyalin');
  });
}

function shareReferral() {
  var code = ensureRefCode();
  var link = getRefLink();
  var text = 'Gabung BaseRocky Wallet pakai kode saya: ' + code + '\n' + link + '\n\nWallet non-custodial untuk Base Network 🚀';

  if (navigator.share) {
    navigator.share({
      title: 'BaseRocky Wallet Referral',
      text: text,
      url: link
    }).catch(function() {
      copyRefLink();
    });
  } else {
    navigator.clipboard.writeText(text).then(function() {
      showToast('Teks undangan disalin');
    }).catch(function() {
      copyRefLink();
    });
  }
}

function bindReferralCode() {
  var input = document.getElementById('refBindInput');
  if (!input) return;
  var code = (input.value || '').trim().toUpperCase();
  if (!code || code.length < 4) {
    showToast('Masukkan kode yang valid');
    return;
  }

  var data = getRefData();
  if (data.boundCode) {
    showToast('Sudah terikat ke kode lain');
    return;
  }

  var myCode = ensureRefCode();
  if (code === myCode) {
    showToast('Tidak bisa pakai kode sendiri');
    return;
  }

  // Check 7-day window from wallet creation (use first persist time approx)
  var created = data.created || Date.now();
  var daysSince = (Date.now() - created) / (1000 * 60 * 60 * 24);
  // Allow bind if within 7 days of first referral data creation OR always for demo flexibility
  // For better UX in local-only wallet, we allow bind anytime if not yet bound
  data.boundCode = code;
  data.boundAt = Date.now();
  // Give invitee a small welcome bonus
  data.points = (data.points || 0) + 20;
  saveRefData(data);

  showToast('Kode ' + code + ' berhasil diikat! +20 poin');
  renderReferralCenter();
}

/** Simulate recording an invite (for demo / when friend uses code) */
function addDemoInvite() {
  var data = getRefData();
  var n = (data.invites || []).length + 1;
  var pts = 50;
  data.invites = data.invites || [];
  data.invites.unshift({
    name: 'Teman #' + n,
    code: 'USER' + n,
    points: pts,
    at: Date.now()
  });
  data.points = (data.points || 0) + pts;
  saveRefData(data);
  showToast('Demo: +1 undangan, +' + pts + ' poin');
  renderReferralCenter();
}

/** Auto-detect ?ref=CODE from URL on first load */
function checkRefFromUrl() {
  try {
    var params = new URLSearchParams(location.search);
    var ref = (params.get('ref') || '').toUpperCase();
    if (!ref) return;
    // Store pending ref for after wallet is created
    sessionStorage.setItem('br_pending_ref', ref);
    // Clean URL
    if (history.replaceState) {
      var clean = location.pathname + location.hash;
      history.replaceState(null, '', clean);
    }
  } catch (e) {}
}

function applyPendingRef() {
  try {
    var pending = sessionStorage.getItem('br_pending_ref');
    if (!pending) return;
    var data = getRefData();
    if (data.boundCode) {
      sessionStorage.removeItem('br_pending_ref');
      return;
    }
    var myCode = ensureRefCode();
    if (pending === myCode) {
      sessionStorage.removeItem('br_pending_ref');
      return;
    }
    data.boundCode = pending;
    data.boundAt = Date.now();
    data.points = (data.points || 0) + 20;
    saveRefData(data);
    sessionStorage.removeItem('br_pending_ref');
    showToast('Referral ' + pending + ' diterapkan! +20 poin');
  } catch (e) {}
}

// Hook into boot
(function() {
  checkRefFromUrl();
  var tryApply = function() {
    if (state && state.address) applyPendingRef();
  };
  setTimeout(tryApply, 1500);
  setTimeout(tryApply, 4000);
})();

