/* ============================================================
   Modern QR helper — performance optimized
   - Instance reuse via update()
   - Result cache (data+opts hash)
   - rAF batching + debounce
   - Fallback to qrcode@1.5.4
   ============================================================ */

var _qrInstances = {};   // hostId -> { qr, hash, el }
var _qrCache = {};       // hash -> dataURL (fallback path)
var _qrPending = {};     // hostId -> rAF id
var _qrDebounce = {};    // hostId -> timer

function _qrHash(data, opts) {
  opts = opts || {};
  return [
    data,
    opts.size || 200,
    opts.dark || '',
    opts.light || '',
    opts.dotType || 'rounded',
    opts.ecl || 'M',
    opts.withLogo ? '1' : '0',
    opts.margin != null ? opts.margin : 6
  ].join('|');
}

function _qrDefaultOptions(data, opts) {
  opts = opts || {};
  var size = opts.size || 200;
  return {
    width: size,
    height: size,
    type: 'canvas',
    data: data,
    margin: opts.margin != null ? opts.margin : 6,
    qrOptions: {
      typeNumber: 0,
      mode: 'Byte',
      errorCorrectionLevel: opts.ecl || 'M'
    },
    imageOptions: {
      hideBackgroundDots: true,
      imageSize: 0.32,
      margin: 4,
      crossOrigin: 'anonymous'
    },
    dotsOptions: {
      type: opts.dotType || 'rounded',
      color: opts.dark || '#0a1628'
    },
    backgroundOptions: {
      color: opts.light || '#ffffff'
    },
    cornersSquareOptions: {
      type: 'extra-rounded',
      color: opts.dark || '#0a1628'
    },
    cornersDotOptions: {
      type: 'dot',
      color: opts.cornerDot || '#00c9a0'
    },
    image: opts.withLogo && typeof LOGO !== 'undefined' ? LOGO : undefined
  };
}

/**
 * High-performance modern QR renderer.
 * Skips work if same data already shown; reuses QRCodeStyling instance.
 */
function renderModernQR(hostId, data, opts) {
  opts = opts || {};
  if (!hostId || !data) return;

  var host = document.getElementById(hostId);
  if (!host) return;

  var hash = _qrHash(data, opts);
  var prev = _qrInstances[hostId];

  // Fast path: identical content already rendered
  if (prev && prev.hash === hash && host.childNodes.length) {
    return;
  }

  // Debounce rapid successive calls for same host (e.g. resize / re-entry)
  if (_qrDebounce[hostId]) clearTimeout(_qrDebounce[hostId]);
  _qrDebounce[hostId] = setTimeout(function() {
    _qrDebounce[hostId] = null;
    _renderModernQRNow(hostId, data, opts, hash);
  }, 16);
}

function _renderModernQRNow(hostId, data, opts, hash) {
  var host = document.getElementById(hostId);
  if (!host || !data) return;

  // Cancel pending rAF
  if (_qrPending[hostId]) {
    cancelAnimationFrame(_qrPending[hostId]);
    _qrPending[hostId] = null;
  }

  _qrPending[hostId] = requestAnimationFrame(function() {
    _qrPending[hostId] = null;
    var size = (opts && opts.size) || 200;

    // --- Primary: qr-code-styling with instance reuse ---
    if (typeof QRCodeStyling !== 'undefined') {
      try {
        var prev = _qrInstances[hostId];
        var cfg = _qrDefaultOptions(data, opts);

        if (prev && prev.qr && typeof prev.qr.update === 'function') {
          // Reuse instance — much cheaper than new + append
          prev.qr.update(cfg);
          prev.hash = hash;
          return;
        }

        // First mount for this host
        host.innerHTML = '';
        var qr = new QRCodeStyling(cfg);
        qr.append(host);
        _qrInstances[hostId] = { qr: qr, hash: hash };
        return;
      } catch (e) {
        console.log('QRCodeStyling fail, fallback', e);
      }
    }

    // --- Fallback: qrcode lib + canvas cache ---
    var cacheKey = hash;
    host.innerHTML = '';
    var canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    canvas.style.display = 'block';
    host.appendChild(canvas);

    if (_qrCache[cacheKey]) {
      var img = new Image();
      img.onload = function() {
        var ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, size, size);
        ctx.drawImage(img, 0, 0, size, size);
      };
      img.src = _qrCache[cacheKey];
      _qrInstances[hostId] = { hash: hash };
      return;
    }

    if (typeof QRCode !== 'undefined') {
      QRCode.toCanvas(canvas, data, {
        width: size,
        margin: 2,
        color: {
          dark: (opts && opts.dark) || '#0a1628',
          light: (opts && opts.light) || '#ffffff'
        },
        errorCorrectionLevel: (opts && opts.ecl) || 'M'
      }, function(err) {
        if (err) {
          console.log('QR fallback err', err);
          return;
        }
        try {
          // Cap cache size
          var keys = Object.keys(_qrCache);
          if (keys.length > 20) delete _qrCache[keys[0]];
          _qrCache[cacheKey] = canvas.toDataURL('image/png');
        } catch (e) {}
        _qrInstances[hostId] = { hash: hash };
      });
    }
  });
}

/** Preload QR for a host (idle time) */
function preloadQR(hostId, data, opts) {
  if (!data) return;
  if (typeof requestIdleCallback === 'function') {
    requestIdleCallback(function() { renderModernQR(hostId, data, opts); }, { timeout: 1500 });
  } else {
    setTimeout(function() { renderModernQR(hostId, data, opts); }, 100);
  }
}

/** Clear cached QR for host (e.g. on logout) */
function clearQR(hostId) {
  if (_qrDebounce[hostId]) {
    clearTimeout(_qrDebounce[hostId]);
    _qrDebounce[hostId] = null;
  }
  if (_qrPending[hostId]) {
    cancelAnimationFrame(_qrPending[hostId]);
    _qrPending[hostId] = null;
  }
  var prev = _qrInstances[hostId];
  if (prev && prev.qr && typeof prev.qr.clear === 'function') {
    try { prev.qr.clear(); } catch (e) {}
  }
  delete _qrInstances[hostId];
  var host = document.getElementById(hostId);
  if (host) host.innerHTML = '';
}

// Override receive QR — modern + cached
function renderReceive() {
  var addr = state.address || '';
  var addrEl = document.getElementById('receiveAddr');
  if (addrEl) addrEl.textContent = addr;

  var host = document.getElementById('qrCanvasHost');
  if (host && addr) {
    renderModernQR('qrCanvasHost', addr, {
      size: 200,
      withLogo: true,
      dark: '#0a1628',
      cornerDot: '#00c9a0',
      dotType: 'rounded',
      ecl: 'H'
    });
    return;
  }
  // Legacy canvas fallback
  var canvas = document.getElementById('qrCanvas');
  if (!canvas || !addr) return;
  canvas.style.display = 'block';
  canvas.width = 200;
  canvas.height = 200;
  if (typeof QRCode !== 'undefined') {
    QRCode.toCanvas(canvas, addr, {
      width: 200, margin: 2,
      color: { dark: '#000000', light: '#ffffff' },
      errorCorrectionLevel: 'M'
    }, function() {});
  }
}

