/* ============================================================
   Web3 Provider — EIP-1193 enhanced (BaseRocky Provider)
   Compatible with ethers BrowserProvider & DApps
   ============================================================ */

var Web3Provider = (function() {
  var _listeners = {};
  var _chainId = null;

  function emit(event, data) {
    var list = _listeners[event] || [];
    list.forEach(function(fn) {
      try { fn(data); } catch (e) { console.log('provider listener', e); }
    });
  }

  function currentChainIdHex() {
    try {
      var id = typeof getChainId === 'function' ? getChainId() : 8453;
      return '0x' + Number(id).toString(16);
    } catch (e) {
      return '0x2105'; // Base
    }
  }

  function getAccounts() {
    if (state.externalProvider && MetaMask && MetaMask.accounts && MetaMask.accounts.length) {
      return MetaMask.accounts.slice();
    }
    if (state.address) return [state.address];
    return [];
  }

  async function personalSign(params) {
    // params: [data, address] for personal_sign
    var data = params[0];
    var address = (params[1] || '').toLowerCase();

    // External wallet
    if (state.externalProvider && typeof state.externalProvider.request === 'function') {
      return state.externalProvider.request({ method: 'personal_sign', params: params });
    }

    if (!state.wallet && !state.address) {
      throw { code: 4001, message: 'Wallet not connected' };
    }

    // Confirm UI
    var preview = typeof data === 'string' && data.startsWith('0x')
      ? data.slice(0, 42) + '…'
      : String(data).slice(0, 80);
    var ok = confirm('Tanda tangani pesan?\n\n' + preview);
    if (!ok) throw { code: 4001, message: 'User rejected' };

    var signer = typeof getSigner === 'function' ? await getSigner() : state.wallet;
    if (!signer) throw { code: 4001, message: 'No signer' };

    if (typeof data === 'string' && data.startsWith('0x')) {
      try {
        return await signer.signMessage(ethers.getBytes(data));
      } catch (e) {
        return await signer.signMessage(ethers.toUtf8Bytes(ethers.toUtf8String(data)));
      }
    }
    return await signer.signMessage(data);
  }

  async function sendTransaction(txReq) {
    if (state.externalProvider && typeof state.externalProvider.request === 'function') {
      return state.externalProvider.request({
        method: 'eth_sendTransaction',
        params: [txReq]
      });
    }

    if (!state.address) throw { code: 4001, message: 'Wallet not connected' };

    var to = txReq.to || '';
    var value = txReq.value ? ethers.formatEther(txReq.value) : '0';
    var ok = confirm(
      'Kirim transaksi?\n\nKe: ' + (to ? to.slice(0, 10) + '…' : '(contract)') +
      '\nValue: ' + value + ' ETH\n\nPastikan data benar. Tidak bisa dibatalkan.'
    );
    if (!ok) throw { code: 4001, message: 'User rejected' };

    var signer = typeof getSigner === 'function' ? await getSigner() : null;
    if (!signer && state.wallet) {
      var p = await getProvider();
      signer = state.wallet.connect(p);
    }
    if (!signer) throw { code: -32603, message: 'No signer' };

    if (typeof setLoading === 'function') setLoading(true);
    try {
      var tx = await signer.sendTransaction({
        to: txReq.to,
        value: txReq.value || 0n,
        data: txReq.data || '0x',
        gasLimit: txReq.gas || txReq.gasLimit || undefined,
        maxFeePerGas: txReq.maxFeePerGas || undefined,
        maxPriorityFeePerGas: txReq.maxPriorityFeePerGas || undefined,
        nonce: txReq.nonce != null ? Number(txReq.nonce) : undefined
      });
      if (typeof showToast === 'function') showToast('Tx dikirim…');
      return tx.hash;
    } finally {
      if (typeof setLoading === 'function') setLoading(false);
    }
  }

  async function signTypedData(params) {
    // eth_signTypedData_v4: [address, stringified typedData]
    if (state.externalProvider && typeof state.externalProvider.request === 'function') {
      return state.externalProvider.request({ method: 'eth_signTypedData_v4', params: params });
    }
    var typed = typeof params[1] === 'string' ? JSON.parse(params[1]) : params[1];
    var ok = confirm('Tanda tangani TypedData?\n\nDomain: ' + (typed.domain && typed.domain.name ? typed.domain.name : 'unknown'));
    if (!ok) throw { code: 4001, message: 'User rejected' };

    var signer = typeof getSigner === 'function' ? await getSigner() : state.wallet;
    if (!signer) throw { code: 4001, message: 'No signer' };

    var domain = typed.domain || {};
    var types = Object.assign({}, typed.types || {});
    delete types.EIP712Domain;
    var value = typed.message || typed.value || {};
    return signer.signTypedData(domain, types, value);
  }

  async function request(args) {
    var method = (args && args.method) || '';
    var params = (args && args.params) || [];

    // Prefer external provider when connected (MetaMask etc.)
    if (state.externalProvider && state.hwType === 'metamask' && typeof state.externalProvider.request === 'function') {
      // Still handle account queries from our state for consistency
      if (method === 'eth_accounts') return getAccounts();
      if (method === 'eth_requestAccounts') {
        var acc = await state.externalProvider.request({ method: 'eth_requestAccounts' });
        if (acc && acc[0]) {
          state.address = acc[0];
          MetaMask.accounts = acc;
          emit('accountsChanged', acc);
        }
        return acc;
      }
      return state.externalProvider.request(args);
    }

    switch (method) {
      case 'eth_chainId':
        return currentChainIdHex();
      case 'net_version':
        return String(typeof getChainId === 'function' ? getChainId() : 8453);
      case 'eth_accounts':
        return getAccounts();
      case 'eth_requestAccounts': {
        if (!state.address) {
          // Prompt user to create/import or connect external
          if (typeof openWalletConnect === 'function') openWalletConnect();
          throw { code: 4001, message: 'No wallet connected' };
        }
        var accs = getAccounts();
        emit('accountsChanged', accs);
        emit('connect', { chainId: currentChainIdHex() });
        return accs;
      }
      case 'personal_sign':
        return personalSign(params);
      case 'eth_sign':
        // eth_sign is discouraged; treat similar
        return personalSign([params[1], params[0]]);
      case 'eth_signTypedData':
      case 'eth_signTypedData_v3':
      case 'eth_signTypedData_v4':
        return signTypedData(params);
      case 'eth_sendTransaction':
        return sendTransaction(params[0] || {});
      case 'eth_getBalance': {
        var p = await getProvider();
        var bal = await p.getBalance(params[0]);
        return ethers.toBeHex(bal);
      }
      case 'eth_estimateGas': {
        var p2 = await getProvider();
        var est = await p2.estimateGas(params[0] || {});
        return ethers.toBeHex(est);
      }
      case 'eth_gasPrice': {
        var p3 = await getProvider();
        var fee = await p3.getFeeData();
        return ethers.toBeHex(fee.gasPrice || fee.maxFeePerGas || 0n);
      }
      case 'eth_blockNumber': {
        var p4 = await getProvider();
        var n = await p4.getBlockNumber();
        return ethers.toBeHex(n);
      }
      case 'eth_call': {
        var p5 = await getProvider();
        return p5.call(params[0] || {}, params[1] || 'latest');
      }
      case 'eth_getCode': {
        var p6 = await getProvider();
        return p6.getCode(params[0], params[1] || 'latest');
      }
      case 'eth_getTransactionCount': {
        var p7 = await getProvider();
        var c = await p7.getTransactionCount(params[0], params[1] || 'latest');
        return ethers.toBeHex(c);
      }
      case 'eth_getTransactionByHash': {
        var p8 = await getProvider();
        var tx = await p8.getTransaction(params[0]);
        return tx;
      }
      case 'eth_getTransactionReceipt': {
        var p9 = await getProvider();
        return p9.getTransactionReceipt(params[0]);
      }
      case 'wallet_switchEthereumChain': {
        var cid = parseInt(params[0].chainId, 16);
        var netMap = { 8453: 'base', 1: 'eth', 56: 'bnb', 137: 'pol', 42161: 'arb' };
        var netId = netMap[cid];
        if (netId && typeof selectNetwork === 'function') {
          await selectNetwork(netId);
          _chainId = '0x' + cid.toString(16);
          emit('chainChanged', _chainId);
          return null;
        }
        // try MetaMask if external
        if (state.externalProvider) {
          return state.externalProvider.request(args);
        }
        throw { code: 4902, message: 'Unrecognized chain' };
      }
      case 'wallet_addEthereumChain': {
        if (state.externalProvider) return state.externalProvider.request(args);
        // Accept Base defaults silently
        var add = params[0] || {};
        var addId = parseInt(add.chainId, 16);
        if (addId === 8453) return null;
        throw { code: 4001, message: 'Add chain not supported in-app' };
      }
      case 'wallet_getPermissions':
      case 'wallet_requestPermissions':
        return [{ parentCapability: 'eth_accounts' }];
      case 'wallet_revokePermissions':
        return null;
      default: {
        // Forward unknown methods to JSON-RPC provider
        var rpc = await getProvider();
        if (rpc && typeof rpc.send === 'function') {
          return rpc.send(method, params);
        }
        throw { code: -32601, message: 'Method not found: ' + method };
      }
    }
  }

  function create() {
    _chainId = currentChainIdHex();
    var provider = {
      isBaseRocky: true,
      isMetaMask: false,
      _meet: true,
      chainId: _chainId,
      networkVersion: String(parseInt(_chainId, 16)),
      selectedAddress: state.address || null,
      request: request,
      // Legacy web3 compat
      enable: async function() {
        return request({ method: 'eth_requestAccounts' });
      },
      send: function(methodOrPayload, paramsOrCb) {
        if (typeof methodOrPayload === 'string') {
          return request({ method: methodOrPayload, params: paramsOrCb || [] });
        }
        // payload object
        var payload = methodOrPayload;
        var cb = paramsOrCb;
        var p = request({ method: payload.method, params: payload.params || [] });
        if (typeof cb === 'function') {
          p.then(function(r) { cb(null, { id: payload.id, jsonrpc: '2.0', result: r }); })
           .catch(function(e) { cb(e, null); });
          return;
        }
        return p;
      },
      sendAsync: function(payload, cb) {
        request({ method: payload.method, params: payload.params || [] })
          .then(function(r) { cb(null, { id: payload.id, jsonrpc: '2.0', result: r }); })
          .catch(function(e) { cb(e, null); });
      },
      on: function(event, handler) {
        if (!_listeners[event]) _listeners[event] = [];
        _listeners[event].push(handler);
        return provider;
      },
      removeListener: function(event, handler) {
        if (!_listeners[event]) return provider;
        _listeners[event] = _listeners[event].filter(function(fn) { return fn !== handler; });
        return provider;
      },
      removeAllListeners: function(event) {
        if (event) delete _listeners[event];
        else _listeners = {};
        return provider;
      },
      emit: emit,
      // helpers
      isConnected: function() { return !!state.address || !!(MetaMask && MetaMask.accounts && MetaMask.accounts.length); },
      _sync: function() {
        provider.selectedAddress = state.address || null;
        provider.chainId = currentChainIdHex();
        provider.networkVersion = String(parseInt(provider.chainId, 16));
      }
    };
    return provider;
  }

  return {
    install: function(force) {
      var existing = window.ethereum;
      // Don't overwrite real MetaMask unless forced or it's our own
      if (existing && existing.isMetaMask && !existing.isBaseRocky && !force) {
        // Announce our provider alongside
        window.baseRocky = create();
        // Multi-provider array
        if (!existing.providers) {
          try {
            existing.providers = [existing, window.baseRocky];
          } catch (e) {}
        }
        brLog('%cBaseRocky Web3Provider ready (alongside injected wallet)', 'color:#00e6b8');
        return window.baseRocky;
      }
      if (existing && existing.isBaseRocky && !force) {
        existing._sync && existing._sync();
        return existing;
      }
      var p = create();
      window.ethereum = p;
      window.baseRocky = p;
      // EIP-6963 announce
      try {
        var info = {
          uuid: 'baserocky-' + Math.random().toString(36).slice(2),
          name: 'BaseRocky Wallet',
          icon: (typeof LOGO !== 'undefined' ? LOGO : ''),
          rdns: 'com.baserocky.wallet'
        };
        window.dispatchEvent(new CustomEvent('eip6963:announceProvider', {
          detail: Object.freeze({ info: info, provider: p })
        }));
        window.addEventListener('eip6963:requestProvider', function() {
          window.dispatchEvent(new CustomEvent('eip6963:announceProvider', {
            detail: Object.freeze({ info: info, provider: p })
          }));
        });
      } catch (e) {}
      brLog('%cBaseRocky Web3Provider installed (EIP-1193 + EIP-6963)', 'color:#00e6b8;font-weight:bold');
      return p;
    },
    notifyAccountsChanged: function(accounts) {
      if (window.ethereum && window.ethereum.emit) {
        window.ethereum.selectedAddress = accounts[0] || null;
        window.ethereum.emit('accountsChanged', accounts || []);
      }
    },
    notifyChainChanged: function(chainIdHex) {
      if (window.ethereum && window.ethereum.emit) {
        window.ethereum.chainId = chainIdHex;
        window.ethereum.emit('chainChanged', chainIdHex);
      }
    },
    getBrowserProvider: function() {
      if (typeof ethers === 'undefined' || !ethers.BrowserProvider) return null;
      return new ethers.BrowserProvider(window.ethereum);
    }
  };
})();

// Upgrade installWalletProvider to use enhanced version
function installWalletProvider() {
  return Web3Provider.install(false);
}

// Sync provider when wallet loads / network changes
(function hookProviderSync() {
  var origShowScreen = typeof showScreen === 'function' ? showScreen : null;
  // After boot, ensure provider installed
  function ensure() {
    try { Web3Provider.install(false); } catch (e) {}
    try {
      if (window.ethereum && window.ethereum._sync) window.ethereum._sync();
    } catch (e) {}
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() { setTimeout(ensure, 100); });
  } else {
    setTimeout(ensure, 100);
  }
  // Also after a short delay post-boot
  setTimeout(ensure, 800);
})();

/** Connect injected browser wallet (MetaMask / Rabby / Brave) via UI */
function openWeb3Connect() {
  var hasMM = typeof isMetaMaskInstalled === 'function' && isMetaMaskInstalled();
  var html = '<div class="modal-handle"></div><h3>Hubungkan Web3</h3>';
  html += '<p class="hint" style="margin-bottom:12px">Pilih provider untuk login atau tandatangani transaksi.</p>';

  html += '<div class="wc-opt" id="w3Inapp" style="cursor:pointer">';
  html += '<div class="ico">💎</div><div><div class="t">BaseRocky (in-app)</div><div class="s">Dompet lokal di browser ini</div></div></div>';

  html += '<div class="wc-opt" id="w3MM" style="cursor:pointer">';
  html += '<div class="ico">🦊</div><div><div class="t">MetaMask</div><div class="s">'+(hasMM?'Terdeteksi · klik untuk hubungkan':'Tidak terdeteksi · install dulu')+'</div></div></div>';

  html += '<div class="wc-opt" id="w3WC" style="cursor:pointer">';
  html += '<div class="ico">🔗</div><div><div class="t">WalletConnect</div><div class="s">QR · Trust / MetaMask Mobile</div></div></div>';

  html += '<div class="wc-opt" id="w3Ledger" style="cursor:pointer">';
  html += '<div class="ico">🛡️</div><div><div class="t">Hardware Wallet</div><div class="s">Ledger WebUSB</div></div></div>';

  openModal(html);

  var el;
  if ((el = document.getElementById('w3Inapp'))) el.onclick = function() {
    closeModal();
    if (state.address) { showScreen('home'); showToast('BaseRocky aktif'); }
    else showScreen('onboard');
    Web3Provider.install(true);
  };
  if ((el = document.getElementById('w3MM'))) el.onclick = function() {
    closeModal();
    if (typeof connectMetaMask === 'function') connectMetaMask();
    else showToast('MetaMask module tidak tersedia');
  };
  if ((el = document.getElementById('w3WC'))) el.onclick = function() {
    closeModal();
    if (typeof connectWalletConnectQR === 'function') connectWalletConnectQR();
    else if (typeof openWalletConnect === 'function') openWalletConnect();
  };
  if ((el = document.getElementById('w3Ledger'))) el.onclick = function() {
    closeModal();
    showScreen('hardware');
  };
}

