/* ============================================================
   EIP-6963 Multi-Injected Provider Discovery
   Auto Gas Manager (EIP-1559)
   BaseRocky Signer Module
   ============================================================ */

/* ---------- EIP-6963 ---------- */
var EIP6963 = (function() {
  var ANNOUNCE = 'eip6963:announceProvider';
  var REQUEST = 'eip6963:requestProvider';
  var UUID = 'br-wallet-' + (function() {
    try {
      if (crypto && crypto.randomUUID) return crypto.randomUUID();
    } catch (e) {}
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
      var r = Math.random() * 16 | 0;
      return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
  })();

  var _info = {
    uuid: UUID,
    name: 'BaseRocky Wallet',
    icon: (typeof LOGO !== 'undefined' ? LOGO : 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect fill="#00e6b8" width="64" height="64" rx="14"/><text x="32" y="42" text-anchor="middle" font-size="28" font-family="sans-serif" font-weight="700" fill="#031510">BR</text></svg>')),
    rdns: 'com.baserocky.wallet'
  };

  var _provider = null;
  var _wired = false;

  function detail() {
    return Object.freeze({ info: Object.freeze(Object.assign({}, _info)), provider: _provider });
  }

  function announce() {
    if (!_provider) return;
    try {
      window.dispatchEvent(new CustomEvent(ANNOUNCE, { detail: detail() }));
    } catch (e) {
      console.log('EIP-6963 announce fail', e);
    }
  }

  function onRequest() {
    announce();
  }

  function install(provider) {
    _provider = provider;
    if (!_wired) {
      _wired = true;
      window.addEventListener(REQUEST, onRequest);
    }
    // Announce immediately + next tick (some DApps listen late)
    announce();
    setTimeout(announce, 0);
    setTimeout(announce, 250);
    return true;
  }

  /** Discover other injected wallets via EIP-6963 */
  function discover(timeoutMs) {
    timeoutMs = timeoutMs || 800;
    return new Promise(function(resolve) {
      var found = [];
      function onAnnounce(e) {
        if (!e.detail || !e.detail.info) return;
        // skip ourselves
        if (e.detail.info.rdns === _info.rdns) return;
        found.push(e.detail);
      }
      window.addEventListener(ANNOUNCE, onAnnounce);
      try {
        window.dispatchEvent(new Event(REQUEST));
      } catch (e) {}
      setTimeout(function() {
        window.removeEventListener(ANNOUNCE, onAnnounce);
        resolve(found);
      }, timeoutMs);
    });
  }

  return {
    install: install,
    announce: announce,
    discover: discover,
    getInfo: function() { return Object.assign({}, _info); },
    UUID: UUID
  };
})();

/* ---------- Auto Gas Manager ---------- */
var GasManager = (function() {
  var _cache = { at: 0, fee: null, chainId: null };
  var CACHE_MS = 12000;

  var SPEEDS = {
    slow:   { mult: 0.90, priorityMult: 0.85, label: 'Hemat',  eta: '~30 dtk' },
    normal: { mult: 1.00, priorityMult: 1.00, label: 'Normal', eta: '~15 dtk' },
    fast:   { mult: 1.25, priorityMult: 1.35, label: 'Cepat',  eta: '~8 dtk' }
  };

  function getSpeed() {
    var pref = (typeof getGasPref === 'function' ? getGasPref() : null) || localStorage.getItem('br_gas_pref') || 'normal';
    return SPEEDS[pref] || SPEEDS.normal;
  }

  async function getFeeData(force) {
    var chainId = typeof getChainId === 'function' ? getChainId() : 8453;
    if (!force && _cache.fee && _cache.chainId === chainId && (Date.now() - _cache.at) < CACHE_MS) {
      return _cache.fee;
    }
    var provider = await getProvider();
    var fee = await provider.getFeeData();
    _cache = { at: Date.now(), fee: fee, chainId: chainId };
    return fee;
  }

  function applySpeed(fee, speed) {
    speed = speed || getSpeed();
    var maxFee = fee.maxFeePerGas || fee.gasPrice || 0n;
    var priority = fee.maxPriorityFeePerGas || 0n;
    var gasPrice = fee.gasPrice || maxFee;

    function scale(v, m) {
      if (!v || v === 0n) return v;
      // scale using integer math (m is float)
      var base = Number(v);
      if (!isFinite(base) || base <= 0) return v;
      return BigInt(Math.floor(base * m));
    }

    return {
      maxFeePerGas: scale(maxFee, speed.mult),
      maxPriorityFeePerGas: scale(priority || (maxFee / 10n), speed.priorityMult),
      gasPrice: scale(gasPrice, speed.mult),
      eip1559: !!(fee.maxFeePerGas && fee.maxPriorityFeePerGas),
      speed: speed
    };
  }

  /** Estimate gas limit for a tx request */
  async function estimateLimit(txRequest) {
    var provider = await getProvider();
    try {
      var est = await provider.estimateGas({
        from: txRequest.from || state.address,
        to: txRequest.to,
        value: txRequest.value || 0n,
        data: txRequest.data || '0x'
      });
      // +15% buffer
      return est + (est / 7n);
    } catch (e) {
      // Fallback defaults
      if (txRequest.data && txRequest.data !== '0x') return 120000n;
      return 21000n;
    }
  }

  /**
   * Build complete gas fields for a transaction.
   * @returns { maxFeePerGas?, maxPriorityFeePerGas?, gasPrice?, gasLimit, estimatedCostWei, speed }
   */
  async function buildTxGas(txRequest, opts) {
    opts = opts || {};
    var speedKey = opts.speed || null;
    var speed = speedKey && SPEEDS[speedKey] ? SPEEDS[speedKey] : getSpeed();
    var fee = await getFeeData(!!opts.force);
    var priced = applySpeed(fee, speed);

    var gasLimit = opts.gasLimit;
    if (!gasLimit) {
      gasLimit = await estimateLimit(txRequest || {});
    }

    var result = {
      gasLimit: gasLimit,
      speed: speed,
      eip1559: priced.eip1559
    };

    if (priced.eip1559) {
      result.maxFeePerGas = priced.maxFeePerGas;
      result.maxPriorityFeePerGas = priced.maxPriorityFeePerGas;
      result.estimatedCostWei = gasLimit * priced.maxFeePerGas;
    } else {
      result.gasPrice = priced.gasPrice;
      result.estimatedCostWei = gasLimit * priced.gasPrice;
    }

    return result;
  }

  /** Format cost for UI */
  function formatCost(gas) {
    if (!gas || !gas.estimatedCostWei) return '—';
    var eth = Number(ethers.formatEther(gas.estimatedCostWei));
    var usd = eth * ((state.prices && state.prices.ETH) || 0);
    var ethStr = eth < 0.0001 ? eth.toExponential(2) : eth.toFixed(6);
    var usdStr = usd > 0 ? ' ($' + (usd < 0.01 ? '<0.01' : usd.toFixed(3)) + ')' : '';
    return '~' + ethStr + ' ETH' + usdStr;
  }

  /** Update send screen gas UI if present */
  async function refreshSendGasUI() {
    var gasEl = document.getElementById('gasInfo');
    var gasVal = document.getElementById('gasEstimate');
    if (!gasEl || !gasVal) return;
    try {
      var id = (document.getElementById('sendToken') || {}).value;
      var to = ((document.getElementById('sendTo') || {}).value || '').trim();
      if (!to || !ethers.isAddress(to)) {
        gasEl.style.display = 'none';
        return;
      }
      var token = (state.tokens || []).find(function(t) { return t.id === id; });
      var txReq = {
        from: state.address,
        to: token && token.address ? token.address : to,
        value: (!token || !token.address) ? 1n : 0n,
        data: token && token.address ? '0xa9059cbb' : '0x' // transfer selector hint
      };
      var gas = await buildTxGas(txReq);
      gasVal.textContent = formatCost(gas) + ' · ' + (gas.speed.label || '');
      gasEl.style.display = 'flex';

      // Update level cards if visible
      if (typeof estimateGasWithLevels === 'function') {
        try { await estimateGasWithLevels(); } catch (e) {}
      }
    } catch (e) {
      gasEl.style.display = 'none';
    }
  }

  return {
    SPEEDS: SPEEDS,
    getSpeed: getSpeed,
    getFeeData: getFeeData,
    buildTxGas: buildTxGas,
    estimateLimit: estimateLimit,
    formatCost: formatCost,
    refreshSendGasUI: refreshSendGasUI,
    clearCache: function() { _cache = { at: 0, fee: null, chainId: null }; }
  };
})();

/* ---------- Signer Module ---------- */
var RockySigner = (function() {
  /**
   * Get an ethers Signer for the active wallet.
   * Priority: external (MetaMask) BrowserProvider → in-app Wallet
   */
  async function getEthersSigner() {
    // External injected wallet
    if (state.externalProvider && state.hwType === 'metamask') {
      var bp = new ethers.BrowserProvider(state.externalProvider);
      return bp.getSigner();
    }
    // WalletConnect external
    if (state.externalProvider && typeof state.externalProvider.request === 'function' && state.hwType === 'walletconnect') {
      var bp2 = new ethers.BrowserProvider(state.externalProvider);
      return bp2.getSigner();
    }
    // In-app key
    if (typeof getSigner === 'function') {
      try {
        var s = await getSigner();
        if (s) return s;
      } catch (e) {}
    }
    if (state.wallet) {
      var provider = await getProvider();
      return state.wallet.connect(provider);
    }
    throw new Error('No signer available — hubungkan wallet dulu');
  }

  /** Sign a UTF-8 or hex message (personal_sign) */
  async function signMessage(message) {
    var signer = await getEthersSigner();
    if (typeof message === 'string' && message.startsWith('0x')) {
      try {
        return await signer.signMessage(ethers.getBytes(message));
      } catch (e) {
        return await signer.signMessage(message);
      }
    }
    return await signer.signMessage(message);
  }

  /** Sign EIP-712 typed data */
  async function signTypedData(domain, types, value) {
    var signer = await getEthersSigner();
    return signer.signTypedData(domain, types, value);
  }

  /**
   * Send transaction with automatic gas.
   * @param {object} txRequest — { to, value?, data?, gasLimit? }
   * @param {object} opts — { speed?, skipConfirm? }
   */
  async function sendTransaction(txRequest, opts) {
    opts = opts || {};
    var signer = await getEthersSigner();
    var from = state.address || (await signer.getAddress());

    var gas = await GasManager.buildTxGas({
      from: from,
      to: txRequest.to,
      value: txRequest.value || 0n,
      data: txRequest.data || '0x'
    }, { speed: opts.speed, gasLimit: txRequest.gasLimit });

    var tx = {
      to: txRequest.to,
      value: txRequest.value || 0n,
      data: txRequest.data || '0x',
      gasLimit: gas.gasLimit
    };
    if (gas.eip1559) {
      tx.maxFeePerGas = gas.maxFeePerGas;
      tx.maxPriorityFeePerGas = gas.maxPriorityFeePerGas;
    } else {
      tx.gasPrice = gas.gasPrice;
    }

    if (!opts.skipConfirm) {
      var cost = GasManager.formatCost(gas);
      var ok = confirm(
        'Kirim transaksi?\n\nKe: ' + (tx.to || '').slice(0, 12) + '…\nGas: ' + cost +
        '\nMode: ' + (gas.speed.label || 'Normal') + '\n\nTidak dapat dibatalkan.'
      );
      if (!ok) throw Object.assign(new Error('User rejected'), { code: 4001 });
    }

    if (typeof setLoading === 'function') setLoading(true);
    try {
      var response = await signer.sendTransaction(tx);
      if (typeof showToast === 'function') showToast('Tx dikirim…');
      return response;
    } finally {
      if (typeof setLoading === 'function') setLoading(false);
    }
  }

  /** Transfer native or ERC-20 with auto gas */
  async function transfer(token, to, amountStr, opts) {
    opts = opts || {};
    if (!ethers.isAddress(to)) throw new Error('Alamat tidak valid');
    var signer = await getEthersSigner();

    if (!token || !token.address) {
      // native
      var value = ethers.parseEther(String(amountStr));
      return sendTransaction({ to: to, value: value }, opts);
    }

    var amount = ethers.parseUnits(String(amountStr), token.decimals || 18);
    var data = new ethers.Interface([
      'function transfer(address to, uint256 amount) returns (bool)'
    ]).encodeFunctionData('transfer', [to, amount]);

    return sendTransaction({ to: token.address, data: data, value: 0n }, opts);
  }

  /** Get address of active signer */
  async function getAddress() {
    if (state.address) return state.address;
    var signer = await getEthersSigner();
    return signer.getAddress();
  }

  return {
    getEthersSigner: getEthersSigner,
    signMessage: signMessage,
    signTypedData: signTypedData,
    sendTransaction: sendTransaction,
    transfer: transfer,
    getAddress: getAddress
  };
})();

