/* ---------- Optimized Gas Estimation ---------- */
(function enhanceGasManager() {
  if (typeof GasManager === 'undefined') return;

  var _limitCache = {}; // key -> { limit, at }
  var LIMIT_CACHE_MS = 30000;

  function limitKey(tx) {
    return [
      (tx.from || '').toLowerCase(),
      (tx.to || '').toLowerCase(),
      tx.data ? String(tx.data).slice(0, 10) : '0x',
      tx.value ? String(tx.value) : '0'
    ].join('|');
  }

  /**
   * Multi-step gas limit estimation:
   * 1. Cache hit
   * 2. provider.estimateGas
   * 3. eth_estimateGas via raw RPC with block tag
   * 4. Heuristic fallback by calldata
   */
  GasManager.estimateLimitOptimized = async function(txRequest) {
    txRequest = txRequest || {};
    var key = limitKey(txRequest);
    var cached = _limitCache[key];
    if (cached && (Date.now() - cached.at) < LIMIT_CACHE_MS) {
      return cached.limit;
    }

    var provider = await getProvider();
    var from = txRequest.from || state.address;
    var to = txRequest.to;
    var data = txRequest.data || '0x';
    var value = txRequest.value || 0n;

    // Parallel: estimateGas + fee (fee used elsewhere)
    var limit = null;
    try {
      limit = await provider.estimateGas({
        from: from,
        to: to,
        value: value,
        data: data
      });
    } catch (e1) {
      // Retry without value if failing (common with ERC-20)
      try {
        limit = await provider.estimateGas({
          from: from,
          to: to,
          data: data
        });
      } catch (e2) {
        // Heuristic by method selector
        var sel = (data || '0x').slice(0, 10).toLowerCase();
        if (!data || data === '0x') limit = 21000n;
        else if (sel === '0xa9059cbb') limit = 65000n;      // transfer
        else if (sel === '0x095ea7b3') limit = 55000n;      // approve
        else if (sel === '0x23b872dd') limit = 100000n;     // transferFrom
        else limit = 150000n; // generic contract
      }
    }

    // Buffer: 12% for simple, 20% for contracts
    var isSimple = !data || data === '0x';
    var buf = isSimple ? (limit / 8n) : (limit / 5n);
    var finalLimit = limit + buf;

    // Cap absurd values
    if (finalLimit > 5000000n) finalLimit = 5000000n;
    if (finalLimit < 21000n) finalLimit = 21000n;

    _limitCache[key] = { limit: finalLimit, at: Date.now() };
    return finalLimit;
  };

  // Patch buildTxGas to use optimized limit
  var _origBuild = GasManager.buildTxGas;
  GasManager.buildTxGas = async function(txRequest, opts) {
    opts = opts || {};
    if (!opts.gasLimit) {
      opts = Object.assign({}, opts, {
        gasLimit: await GasManager.estimateLimitOptimized(txRequest || {})
      });
    }
    return _origBuild.call(GasManager, txRequest, opts);
  };

  GasManager.clearLimitCache = function() {
    _limitCache = {};
  };

  /** Preload fee data on network change / idle */
  GasManager.warmup = async function() {
    try {
      await GasManager.getFeeData(true);
    } catch (e) {}
  };

  // Warmup shortly after load
  setTimeout(function() {
    if (state && state.address) GasManager.warmup();
  }, 2000);
})();

/* ---------- ENS Module ---------- */
var ENS = (function() {
  var _cache = {}; // name/addr -> { result, at }
  var CACHE_MS = 5 * 60 * 1000;
  var _mainnetProvider = null;
  var _debounce = {};

  /** Mainnet provider for ENS (names live on L1) */
  async function getMainnetProvider() {
    if (_mainnetProvider) return _mainnetProvider;
    var urls = [
      'https://eth.llamarpc.com',
      'https://rpc.ankr.com/eth',
      'https://ethereum.publicnode.com'
    ];
    for (var i = 0; i < urls.length; i++) {
      try {
        var p = new ethers.JsonRpcProvider(urls[i], 1, { staticNetwork: true });
        await p.getBlockNumber();
        _mainnetProvider = p;
        return p;
      } catch (e) {}
    }
    // last resort: use current provider (may fail off mainnet)
    return await getProvider();
  }

  function cacheGet(key) {
    var c = _cache[key];
    if (c && (Date.now() - c.at) < CACHE_MS) return c.result;
    return null;
  }
  function cacheSet(key, result) {
    _cache[key] = { result: result, at: Date.now() };
  }

  /** Resolve ENS name → address (null if not found) */
  async function resolve(name) {
    if (!name || typeof name !== 'string') return null;
    name = name.trim().toLowerCase();
    if (!name.endsWith('.eth') && !name.includes('.')) return null;

    var hit = cacheGet('r:' + name);
    if (hit !== null) return hit;

    try {
      var p = await getMainnetProvider();
      var addr = await p.resolveName(name);
      cacheSet('r:' + name, addr || null);
      return addr || null;
    } catch (e) {
      cacheSet('r:' + name, null);
      return null;
    }
  }

  /** Reverse resolve address → primary ENS name */
  async function lookup(address) {
    if (!address || !ethers.isAddress(address)) return null;
    var key = 'l:' + address.toLowerCase();
    var hit = cacheGet(key);
    if (hit !== null) return hit;

    try {
      var p = await getMainnetProvider();
      var name = await p.lookupAddress(address);
      cacheSet(key, name || null);
      return name || null;
    } catch (e) {
      cacheSet(key, null);
      return null;
    }
  }

  /**
   * Normalize user input: ENS name or address → checksum address
   * @returns {{ address, ensName, input }}
   */
  async function resolveInput(input) {
    input = (input || '').trim();
    if (!input) return { address: null, ensName: null, input: input };

    if (ethers.isAddress(input)) {
      var ens = await lookup(input);
      return {
        address: ethers.getAddress(input),
        ensName: ens,
        input: input
      };
    }

    // Treat as name
    var addr = await resolve(input);
    if (addr) {
      return {
        address: ethers.getAddress(addr),
        ensName: input.toLowerCase(),
        input: input
      };
    }
    return { address: null, ensName: null, input: input };
  }

  /** Debounced resolve for input fields */
  function resolveInputDebounced(input, cb, ms) {
    ms = ms || 400;
    var id = 'default';
    if (_debounce[id]) clearTimeout(_debounce[id]);
    _debounce[id] = setTimeout(async function() {
      try {
        var r = await resolveInput(input);
        cb(null, r);
      } catch (e) {
        cb(e, null);
      }
    }, ms);
  }

  return {
    resolve: resolve,
    lookup: lookup,
    resolveInput: resolveInput,
    resolveInputDebounced: resolveInputDebounced,
    clearCache: function() { _cache = {}; }
  };
})();

/* Send form ENS wiring */
var _sendResolvedAddress = null;

function onSendToInput() {
  var input = document.getElementById('sendTo');
  var hint = document.getElementById('sendEnsHint');
  if (!input || !hint) return;
  var val = (input.value || '').trim();
  _sendResolvedAddress = null;
  hint.textContent = '';
  hint.className = 'ens-hint';

  if (!val) {
    if (typeof estimateGas === 'function') estimateGas();
    return;
  }

  if (ethers.isAddress(val)) {
    hint.textContent = 'Resolving ENS…';
    hint.className = 'ens-hint loading';
    ENS.lookup(val).then(function(name) {
      if ((input.value || '').trim() !== val) return;
      if (name) {
        hint.textContent = name;
        hint.className = 'ens-hint ok';
      } else {
        hint.textContent = '';
        hint.className = 'ens-hint';
      }
      _sendResolvedAddress = ethers.getAddress(val);
      if (typeof estimateGas === 'function') estimateGas();
    });
    return;
  }

  // Possible ENS name
  if (val.includes('.') || val.endsWith('.eth')) {
    hint.textContent = 'Resolving ' + val + '…';
    hint.className = 'ens-hint loading';
    ENS.resolveInputDebounced(val, function(err, r) {
      if ((input.value || '').trim() !== val) return;
      if (err || !r || !r.address) {
        hint.textContent = 'Nama tidak ditemukan';
        hint.className = 'ens-hint err';
        _sendResolvedAddress = null;
        return;
      }
      hint.textContent = r.address.slice(0, 6) + '…' + r.address.slice(-4);
      hint.className = 'ens-hint ok';
      _sendResolvedAddress = r.address;
      if (typeof estimateGas === 'function') estimateGas();
    });
  }
}

// Patch sendTx to use resolved ENS address
var _sendTxWithEns = typeof sendTx === 'function' ? sendTx : null;
async function sendTx() {
  var input = document.getElementById('sendTo');
  var raw = (input && input.value || '').trim();
  var to = _sendResolvedAddress;

  if (!to) {
    if (ethers.isAddress(raw)) {
      to = ethers.getAddress(raw);
    } else if (raw.includes('.')) {
      var r = await ENS.resolveInput(raw);
      if (!r.address) return showToast('ENS / alamat tidak valid');
      to = r.address;
      _sendResolvedAddress = to;
    }
  }

  if (!to || !ethers.isAddress(to)) return showToast('Alamat tidak valid');

  // Temporarily write resolved address for underlying logic
  var prev = input ? input.value : '';
  if (input) input.value = to;

  try {
    var id = document.getElementById('sendToken').value;
    var amtStr = (document.getElementById('sendAmt').value || '').trim();
    if (!amtStr || isNaN(amtStr) || Number(amtStr) <= 0) {
      showToast('Jumlah tidak valid');
      if (input) input.value = prev;
      return;
    }
    var token = state.tokens.find(function(t) { return t.id === id; });
    if (!token) {
      if (input) input.value = prev;
      return;
    }

    requirePin(async function() {
      setLoading(true);
      try {
        var txResp = await RockySigner.transfer(token, to, amtStr, { skipConfirm: false });
        showToast('Dikirim…');
        if (txResp && txResp.wait) await txResp.wait();
        showToast('Berhasil!');
        if (input) input.value = '';
        document.getElementById('sendAmt').value = '';
        _sendResolvedAddress = null;
        var hint = document.getElementById('sendEnsHint');
        if (hint) { hint.textContent = ''; hint.className = 'ens-hint'; }
        refreshBalances(false);
        showScreen('home');
      } catch (e) {
        if (e && e.code === 4001) showToast('Dibatalkan');
        else showToast((e.reason || e.shortMessage || e.message || 'Gagal').slice(0, 80));
        if (input) input.value = prev;
      } finally {
        setLoading(false);
      }
    });
  } catch (e) {
    if (input) input.value = prev;
    showToast((e.message || 'Gagal').slice(0, 80));
  }
}

/* ---------- Transaction Examples ---------- */
var TxExamples = {
  /** Example: send native ETH/Base ETH with auto gas */
  async sendNative(to, amountEth) {
    to = (await ENS.resolveInput(to)).address || to;
    if (!ethers.isAddress(to)) throw new Error('Invalid to');
    var value = ethers.parseEther(String(amountEth));
    return RockySigner.sendTransaction({ to: to, value: value });
  },

  /** Example: ERC-20 transfer */
  async sendERC20(tokenAddress, to, amount, decimals) {
    to = (await ENS.resolveInput(to)).address || to;
    decimals = decimals != null ? decimals : 18;
    var iface = new ethers.Interface([
      'function transfer(address to, uint256 amount) returns (bool)'
    ]);
    var data = iface.encodeFunctionData('transfer', [
      to,
      ethers.parseUnits(String(amount), decimals)
    ]);
    return RockySigner.sendTransaction({ to: tokenAddress, data: data, value: 0n });
  },

  /** Example: approve spender */
  async approve(tokenAddress, spender, amount, decimals) {
    decimals = decimals != null ? decimals : 18;
    var iface = new ethers.Interface([
      'function approve(address spender, uint256 amount) returns (bool)'
    ]);
    var data = iface.encodeFunctionData('approve', [
      spender,
      amount === 'max' ? ethers.MaxUint256 : ethers.parseUnits(String(amount), decimals)
    ]);
    return RockySigner.sendTransaction({ to: tokenAddress, data: data, value: 0n });
  },

  /** Example: personal sign */
  async signLogin(message) {
    message = message || ('BaseRocky Login\nTime: ' + new Date().toISOString());
    return RockySigner.signMessage(message);
  },

  /** Example: EIP-712 typed data (simple mail) */
  async signTypedMail(fromName, toName, contents) {
    var network = await (await getProvider()).getNetwork();
    var domain = {
      name: 'BaseRocky DApp',
      version: '1',
      chainId: Number(network.chainId),
      verifyingContract: '0xCcCCccccCCCCcCCCCCCcCcCccCcCCCcCcccccccC'
    };
    var types = {
      Mail: [
        { name: 'from', type: 'Person' },
        { name: 'to', type: 'Person' },
        { name: 'contents', type: 'string' }
      ],
      Person: [
        { name: 'name', type: 'string' },
        { name: 'wallet', type: 'address' }
      ]
    };
    var value = {
      from: { name: fromName || 'Alice', wallet: state.address },
      to: { name: toName || 'Bob', wallet: state.address },
      contents: contents || 'Hello from BaseRocky'
    };
    return RockySigner.signTypedData(domain, types, value);
  },

  /** Demo runner printed to console */
  async runDemo() {
    brLog('%c--- BaseRocky TxExamples ---', 'color:#00e6b8;font-weight:bold');
    console.log('1) ENS resolve vitalik.eth');
    var addr = await ENS.resolve('vitalik.eth');
    console.log('   →', addr);
    if (state.address) {
      console.log('2) Reverse ENS for current wallet');
      console.log('   →', await ENS.lookup(state.address));
      console.log('3) Estimate gas for native transfer');
      var gas = await GasManager.buildTxGas({
        from: state.address,
        to: addr || state.address,
        value: ethers.parseEther('0.001'),
        data: '0x'
      });
      console.log('   →', GasManager.formatCost(gas), gas);
    } else {
      console.log('(Connect wallet to run gas / sign demos)');
    }
    console.log('Examples: TxExamples.sendNative / sendERC20 / approve / signLogin / signTypedMail');
    return true;
  }
};

