/* Security activity + autolock watchdog */
(function wireSecurityActivity(){
  if (window.br_security_activity_wired) return;
  window.br_security_activity_wired = true;
  function bump(){ state._lastActive = Date.now(); }
  ['click','touchstart','keydown','mousemove','scroll'].forEach(function(ev){
    document.addEventListener(ev, bump, { passive: true });
  });
  setInterval(function(){
    try {
      if (!state.pinEnabled && !localStorage.getItem(PIN_KEY)) return;
      var min = state.autoLockMin;
      if (min == null) min = parseInt(localStorage.getItem('br_autolock')||'5',10);
      if (!min || min <= 0) return;
      if (state._unlocked === false) return;
      var elapsed = Date.now() - (state._lastActive || Date.now());
      if (elapsed > min * 60 * 1000) {
        state._unlocked = false;
        if (typeof showPinOverlay === 'function') {
          state._pinMode = 'unlock';
          state.pinMode = 'unlock';
          showPinOverlay('Masukkan PIN', 'Dompet terkunci otomatis');
        } else {
          var ov = document.getElementById('pinOverlay');
          if (ov) {
            state.pinMode = 'unlock';
            state.pinBuffer = '';
            document.getElementById('pinTitle').textContent = 'Masukkan PIN';
            document.getElementById('pinHint').textContent = 'Dompet terkunci otomatis';
            if (typeof updatePinDots === 'function') updatePinDots();
            ov.classList.add('show');
          }
        }
      }
    } catch (e) {}
  }, 15000);
})();


/* ============================================================
   PIN Encryption (PBKDF2 + AES-GCM) — hardened
   Biometric Auth (WebAuthn / platform authenticator)
   ============================================================ */


/* ===== Reliable PIN digest (independent of PBKDF2 iteration drift) ===== */
async function brPinDigest(pin) {
  pin = String(pin || '');
  var enc = new TextEncoder();
  var buf = await crypto.subtle.digest(
    'SHA-256',
    enc.encode('BaseRocky.PIN.v1|' + pin + '|' + pin.length)
  );
  return Array.from(new Uint8Array(buf))
    .map(function (b) { return b.toString(16).padStart(2, '0'); })
    .join('');
}
async function brPinSaveDigest(pin) {
  var d = await brPinDigest(pin);
  localStorage.setItem('br_pin_sha256', d);
  localStorage.setItem('br_pin_enabled', '1');
  return d;
}
async function brPinCheckDigest(pin) {
  var stored = localStorage.getItem('br_pin_sha256');
  if (!stored) return null; // unknown
  var d = await brPinDigest(pin);
  return d === stored;
}

var PinCrypto = (function() {
  var ITERATIONS = (typeof CryptoTune !== 'undefined' ? CryptoTune.getIterations() : 120000);
  var VERIFY_PLAIN = 'baserocky-pin-ok-v2';

  function b64encode(buf) {
    var bytes = buf instanceof ArrayBuffer ? new Uint8Array(buf) : buf;
    var s = '';
    for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return btoa(s);
  }
  function b64decode(str) {
    var bin = atob(str);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function getSalt() {
    var s = localStorage.getItem('br_kdf_salt_v2');
    if (s) return b64decode(s);
    var salt = crypto.getRandomValues(new Uint8Array(16));
    localStorage.setItem('br_kdf_salt_v2', b64encode(salt));
    return salt;
  }

  function getPinIterations() {
    // MUST match the value used when verifier was created
    try {
      var stored = parseInt(localStorage.getItem('br_pin_kdf_iters') || '0', 10);
      if (stored >= 10000 && stored <= 500000) return stored;
    } catch (e) {}
    if (typeof CryptoTune !== 'undefined' && CryptoTune.getIterations) {
      return CryptoTune.getIterations();
    }
    return 45000; // stable default (matches CryptoTune.DEFAULT_ITERS)
  }

  async function deriveKey(pin, salt, itersOverride) {
    var enc = new TextEncoder();
    var iters = itersOverride || getPinIterations();
    var baseKey = await crypto.subtle.importKey(
      'raw', enc.encode(String(pin)), 'PBKDF2', false, ['deriveKey']
    );
    return crypto.subtle.deriveKey(
      { name: 'PBKDF2', salt: salt, iterations: iters, hash: 'SHA-256' },
      baseKey,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  }

  async function encryptString(key, plaintext) {
    var iv = crypto.getRandomValues(new Uint8Array(12));
    var data = new TextEncoder().encode(plaintext);
    var cipher = await crypto.subtle.encrypt({ name: 'AES-GCM', iv: iv }, key, data);
    var packed = new Uint8Array(iv.length + cipher.byteLength);
    packed.set(iv, 0);
    packed.set(new Uint8Array(cipher), iv.length);
    return b64encode(packed);
  }

  async function decryptString(key, b64) {
    var packed = b64decode(b64);
    var iv = packed.slice(0, 12);
    var data = packed.slice(12);
    var dec = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: iv }, key, data);
    return new TextDecoder().decode(dec);
  }

  /** Setup PIN: ONLY strong verifier (PBKDF2 + AES-GCM). Iterations frozen in storage. */
  async function setup(pin) {
    pin = String(pin);
    var salt = getSalt();
    // Freeze iterations at setup time so reload + CryptoTune calibrate cannot break verify
    var iters = 45000;
    try {
      if (typeof CryptoTune !== 'undefined' && CryptoTune.getIterations) {
        iters = CryptoTune.getIterations() || 45000;
      }
    } catch (e) {}
    try { localStorage.setItem('br_pin_kdf_iters', String(iters)); } catch (e) {}

    var key = await deriveKey(pin, salt, iters);
    var verifier = await encryptString(key, VERIFY_PLAIN);
    localStorage.setItem('br_pin_verifier_v2', verifier);
    try { localStorage.setItem('br_pin_enabled', '1'); } catch (e) {}
    // Authoritative unlock check (survives iteration/salt edge cases)
    try {
      if (typeof brPinSaveDigest === 'function') await brPinSaveDigest(pin);
    } catch (e) {}
    // Recovery hash (single key)
    try {
      if (typeof hashPin === 'function') {
        localStorage.setItem('br_pin_recovery', hashPin(pin));
      }
    } catch (e) {}

    // Clear OLD multi-hash clutter (keep recovery only)
    try {
      ['br_pin_hash', 'br_pin', 'br_pin_v6', 'br_pin_hash_v3'].forEach(function (k) {
        try { localStorage.removeItem(k); } catch (e2) {}
      });
      if (typeof PIN_KEY !== 'undefined') {
        try { localStorage.removeItem(PIN_KEY); } catch (e3) {}
      }
    } catch (e) {}

    state.pinEnabled = true;
    state.pinHash = 'v2';
    state._unlocked = true;

    // Unlock SecureStore + migrate secrets
    try {
      if (typeof SecureStore !== 'undefined') {
        await SecureStore.unlock(pin);
        var m = state.phrase || state.mnemonic || '';
        var p = (state.wallet && state.wallet.privateKey) || state.privateKey || '';
        if (!m) m = localStorage.getItem('br_phrase') || localStorage.getItem('br_mnemonic') || '';
        if (!p) p = localStorage.getItem('br_pk') || '';
        if (m || p) await SecureStore.setSensitive(m, p);
      }
    } catch (e) {
      if (window.BR_DEBUG) console.log('migrate encrypt', e);
    }

    PinCrypto._sessionKey = key;
    PinCrypto._unlocked = true;
    // Migrate any legacy Solana secret into the PIN-encrypted vault.
    try {
      if (typeof window.migrateSolanaSecretToVault === 'function') {
        await window.migrateSolanaSecretToVault();
      }
    } catch (eSol) {
      if (window.BR_DEBUG) console.warn('[Sol] legacy migration failed', eSol);
    }
    return true;
  }

  /** Verify PIN: v2 with frozen iters; recovery/legacy fallback then re-setup */
  async function verify(pin) {
    pin = String(pin);
    var ver = localStorage.getItem('br_pin_verifier_v2');
    if (ver) {
      // Try with stored iterations first
      var tryIters = [];
      try {
        var s = parseInt(localStorage.getItem('br_pin_kdf_iters') || '0', 10);
        if (s >= 10000) tryIters.push(s);
      } catch (e) {}
      // Common defaults if stored missing or mismatched (migration from broken fix9)
      [45000, 30000, 60000, 90000, 120000].forEach(function (n) {
        if (tryIters.indexOf(n) < 0) tryIters.push(n);
      });
      if (typeof CryptoTune !== 'undefined' && CryptoTune.getIterations) {
        var cur = CryptoTune.getIterations();
        if (tryIters.indexOf(cur) < 0) tryIters.push(cur);
      }

      var salt = getSalt();
      for (var i = 0; i < tryIters.length; i++) {
        try {
          var key = await deriveKey(pin, salt, tryIters[i]);
          var plain = await decryptString(key, ver);
          if (plain === VERIFY_PLAIN) {
            // Lock in the working iteration count
            try { localStorage.setItem('br_pin_kdf_iters', String(tryIters[i])); } catch (e) {}
            PinCrypto._sessionKey = key;
            PinCrypto._unlocked = true;
            try {
              if (typeof SecureStore !== 'undefined') await SecureStore.unlock(pin);
            } catch (e) {}
            try {
              if (typeof brAutoMigrateSecrets === 'function') brAutoMigrateSecrets(pin);
            } catch (eM) {}
            // Migrate any legacy Solana secret only after the correct PIN unlocks the vault.
            try {
              if (typeof window.migrateSolanaSecretToVault === 'function') {
                await window.migrateSolanaSecretToVault();
              }
            } catch (eSol) {
              if (window.BR_DEBUG) console.warn('[Sol] legacy migration failed', eSol);
            }
            return true;
          }
        } catch (e) {
          // wrong pin or wrong iters — try next
        }
      }
      // v2 present but no iter matched — fall through to recovery hash
    }

    // Recovery / legacy read-only
    var okLegacy = false;
    try {
      var h =
        localStorage.getItem('br_pin_recovery') ||
        localStorage.getItem('br_pin_v6') ||
        localStorage.getItem(typeof PIN_KEY !== 'undefined' ? PIN_KEY : 'br_pin_hash_v3') ||
        localStorage.getItem('br_pin_hash') ||
        localStorage.getItem('br_pin');
      if (h) {
        if (typeof verifyPinHash === 'function' && verifyPinHash(pin, h)) okLegacy = true;
        else if (typeof hashPin === 'function' && hashPin(pin) === h) okLegacy = true;
        else if (typeof simpleHash === 'function' && simpleHash(pin) === h) okLegacy = true;
      }
    } catch (e2) {}
    if (!okLegacy) {
      PinCrypto._sessionKey = null;
      PinCrypto._unlocked = false;
      return false;
    }
    // Re-create v2 verifier with frozen iters
    try {
      await setup(pin);
    } catch (e3) {
      PinCrypto._unlocked = true;
    }
    try {
      if (typeof brAutoMigrateSecrets === 'function') brAutoMigrateSecrets(pin);
    } catch (e4) {}
    return true;
  }

  async function encryptSecret(name, value) {
    if (!PinCrypto._sessionKey) throw new Error('Locked');
    var b64 = await encryptString(PinCrypto._sessionKey, value);
    localStorage.setItem('br_sec_' + name, b64);
    return true;
  }

  async function decryptSecret(name) {
    if (!PinCrypto._sessionKey) throw new Error('Locked');
    var b64 = localStorage.getItem('br_sec_' + name);
    if (!b64) return null;
    return decryptString(PinCrypto._sessionKey, b64);
  }

  function lock() {
    PinCrypto._sessionKey = null;
    PinCrypto._unlocked = false;
    if (typeof SecureStore !== 'undefined') SecureStore._key = null;
  }

  function isEncrypted() {
    return !!localStorage.getItem('br_pin_verifier_v2');
  }

  return {
    setup: setup,
    verify: verify,
    encryptSecret: encryptSecret,
    decryptSecret: decryptSecret,
    lock: lock,
    isEncrypted: isEncrypted,
    _sessionKey: null,
    _unlocked: false
  };
})();

/* Unified PIN API — prefer this everywhere */
window.PinAuth = {
  setup: function (pin) {
    return PinCrypto.setup(pin);
  },
  verify: function (pin) {
    return PinCrypto.verify(pin);
  },
  hasPin: function () {
    try {
      return !!(
        localStorage.getItem('br_pin_sha256') ||
        localStorage.getItem('br_pin_verifier_v2') ||
        localStorage.getItem('br_pin_enabled') ||
        localStorage.getItem(typeof PIN_KEY !== 'undefined' ? PIN_KEY : 'br_pin_hash_v3') ||
        localStorage.getItem('br_pin_v6') ||
        localStorage.getItem('br_pin_hash') ||
        localStorage.getItem('br_pin')
      );
    } catch (e) {
      return false;
    }
  },
  lock: function () {
    if (PinCrypto && PinCrypto.lock) PinCrypto.lock();
  }
};


/* ---------- Biometric (WebAuthn) ---------- */
var Biometric = (function() {
  var RP_NAME = 'BaseRocky Wallet';
  var RP_ID = (typeof location !== 'undefined' && location.hostname) ? location.hostname : 'localhost';
  var CRED_KEY = 'br_webauthn_cred';

  function supported() {
    return !!(window.PublicKeyCredential &&
      navigator.credentials &&
      typeof navigator.credentials.create === 'function');
  }

  async function platformAvailable() {
    if (!supported()) return false;
    try {
      if (typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
        return await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
      }
    } catch (e) {}
    return false;
  }

  function randomBuf(len) {
    var b = new Uint8Array(len || 32);
    crypto.getRandomValues(b);
    return b;
  }

  function bufToB64url(buf) {
    var bytes = buf instanceof ArrayBuffer ? new Uint8Array(buf) : buf;
    var str = btoa(String.fromCharCode.apply(null, bytes));
    return str.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  function b64urlToBuf(str) {
    str = str.replace(/-/g, '+').replace(/_/g, '/');
    while (str.length % 4) str += '=';
    var bin = atob(str);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out.buffer;
  }

  /** Register platform authenticator (fingerprint / Face ID) */
  async function register(userId) {
    if (!supported()) throw new Error('WebAuthn tidak didukung di browser ini');
    var avail = await platformAvailable();
    if (!avail) throw new Error('Biometrik perangkat tidak tersedia');

    var userIdBytes = new TextEncoder().encode(userId || state.address || 'baserocky-user');
    var challenge = randomBuf(32);

    var publicKey = {
      challenge: challenge,
      rp: { name: RP_NAME, id: RP_ID },
      user: {
        id: userIdBytes,
        name: (state.walletName || 'wallet') + '@baserocky',
        displayName: state.walletName || 'BaseRocky Wallet'
      },
      pubKeyCredParams: [
        { type: 'public-key', alg: -7 },   // ES256
        { type: 'public-key', alg: -257 }  // RS256
      ],
      authenticatorSelection: {
        authenticatorAttachment: 'platform',
        userVerification: 'required',
        residentKey: 'preferred',
        requireResidentKey: false
      },
      timeout: 60000,
      attestation: 'none'
    };

    var cred = await navigator.credentials.create({ publicKey: publicKey });
    if (!cred) throw new Error('Registrasi dibatalkan');

    var payload = {
      id: cred.id,
      rawId: bufToB64url(cred.rawId),
      type: cred.type,
      transports: (cred.response && cred.response.getTransports) ? cred.response.getTransports() : []
    };
    localStorage.setItem(CRED_KEY, JSON.stringify(payload));
    localStorage.setItem('br_biometric_on', '1');
    return payload;
  }

  /** Assert / authenticate with biometrics */
  async function authenticate() {
    if (!supported()) throw new Error('WebAuthn tidak didukung');
    var saved = localStorage.getItem(CRED_KEY);
    if (!saved) throw new Error('Biometrik belum didaftarkan');
    var meta = JSON.parse(saved);
    var challenge = randomBuf(32);

    var publicKey = {
      challenge: challenge,
      timeout: 60000,
      rpId: RP_ID,
      userVerification: 'required',
      allowCredentials: [{
        type: 'public-key',
        id: b64urlToBuf(meta.rawId),
        transports: meta.transports || ['internal']
      }]
    };

    var assertion = await navigator.credentials.get({ publicKey: publicKey });
    if (!assertion) throw new Error('Autentikasi dibatalkan');
    return true;
  }

  function isEnabled() {
    return localStorage.getItem('br_biometric_on') === '1' && !!localStorage.getItem(CRED_KEY);
  }

  function disable() {
    localStorage.removeItem(CRED_KEY);
    localStorage.removeItem('br_biometric_on');
  }

  return {
    supported: supported,
    platformAvailable: platformAvailable,
    register: register,
    authenticate: authenticate,
    isEnabled: isEnabled,
    disable: disable
  };
})();

/* ---------- Wire into PIN flows ---------- */

// Enhance handlePinComplete for encrypted setup / verify
var _origHandlePinComplete = typeof handlePinComplete === 'function' ? handlePinComplete : null;
async function handlePinCompleteAsync() {
  var mode = state.pinMode || state._pinMode;
  var pin = state.pinBuffer || state._pinBuf || '';

  if (mode === 'setup') {
    if (!state.pinTemp && !state._pinTemp) {
      state.pinTemp = pin;
      state._pinTemp = pin;
      state.pinBuffer = '';
      state._pinBuf = '';
      document.getElementById('pinTitle').textContent = 'Konfirmasi PIN';
      document.getElementById('pinHint').textContent = 'Masukkan ulang PIN';
      if (typeof updatePinDots === 'function') updatePinDots();
      return;
    }
    var first = state.pinTemp || state._pinTemp;
    if (pin !== first) {
      showToast('PIN tidak cocok');
      state.pinTemp = '';
      state._pinTemp = '';
      state.pinBuffer = '';
      state._pinBuf = '';
      document.getElementById('pinTitle').textContent = 'Buat PIN Baru';
      document.getElementById('pinHint').textContent = 'Masukkan 6-digit PIN';
      if (typeof updatePinDots === 'function') updatePinDots();
      return;
    }
    try {
      await PinCrypto.setup(pin);
      document.getElementById('pinOverlay').classList.remove('show');
      state.pinMode = null;
      state._pinMode = null;
      showToast('PIN terenkripsi aktif');
      try { openSecurityCenter(); } catch (e) {}
    } catch (e) {
      showToast('Gagal enkripsi PIN');
      console.log(e);
    }
    return;
  }

  if (mode === 'verify' || mode === 'unlock') {
    var ok = await PinCrypto.verify(pin);
    if (ok) {
      document.getElementById('pinOverlay').classList.remove('show');
      state.pinMode = null;
      state._pinMode = null;
      state._unlocked = true;
      state._lastActive = Date.now();
      if (state._pinCallback) {
        var cb = state._pinCallback;
        state._pinCallback = null;
        cb();
      } else {
        showToast('Dompet terbuka');
      }
    } else {
      showToast('PIN salah');
      state.pinBuffer = '';
      state._pinBuf = '';
      if (typeof updatePinDots === 'function') updatePinDots();
    }
    return;
  }

  // Fallback to original for change PIN etc.
  if (_origHandlePinComplete) _origHandlePinComplete();
}

// Override sync handlePinComplete to async path when encrypted modes
function handlePinComplete() {
  var mode = state.pinMode || state._pinMode;
  // Route setup / verify / unlock / change through async path (PinCrypto + unified verify)
  if (mode === 'setup' || mode === 'verify' || mode === 'unlock' || mode === 'change' || mode === 'change_old') {
    if (typeof processPin === 'function') {
      // Ensure buffers synced
      if (!state._pinBuf && state.pinBuffer) state._pinBuf = state.pinBuffer;
      if (!state.pinBuffer && state._pinBuf) state.pinBuffer = state._pinBuf;
      try { processPin(); } catch (e) { console.log(e); }
      return;
    }
    handlePinCompleteAsync();
    return;
  }
  if (_origHandlePinComplete) _origHandlePinComplete();
}


/* ===== Auto-migrate plaintext secrets after PIN success ===== */
function brRestoreWalletFromSecure(pin) {
  return Promise.resolve()
    .then(async function () {
      var pk = '';
      var phrase = '';
      try {
        if (typeof SecureStore !== 'undefined') {
          if (SecureStore.unlock) await SecureStore.unlock(pin);
          if (SecureStore.loadSensitive) {
            var sens = await SecureStore.loadSensitive();
            if (sens) {
              phrase = sens.mnemonic || '';
              pk = sens.pk || '';
            }
          }
        }
      } catch (e) {}
      try {
        if ((!pk || !phrase) && typeof SecureLocal !== 'undefined' && SecureLocal.unlockEncrypted) {
          var data = await SecureLocal.unlockEncrypted(pin);
          if (data) {
            phrase =
              phrase ||
              data.br_mnemonic ||
              data.mnemonic ||
              data.br_phrase ||
              data.__wallet_v3_mnemonic ||
              data.__wallet_v3_phrase ||
              '';
            pk = pk || data.br_pk || data.privateKey || data.__wallet_v3_pk || '';
            Object.keys(data).forEach(function (k) {
              if (!pk && /_pk/.test(k)) pk = data[k];
              if (!phrase && /(phrase|mnemonic)/.test(k)) phrase = data[k];
            });
          }
        }
      } catch (e2) {}
      if (!pk && !phrase) return false;
      try {
        if (typeof ethers !== 'undefined') {
          var w = null;
          if (phrase) {
            try {
              w = ethers.Wallet.fromPhrase(String(phrase).trim());
            } catch (e3) {}
          }
          if (!w && pk) {
            try {
              w = new ethers.Wallet(pk);
            } catch (e4) {}
          }
          if (w) {
            state.wallet = w;
            state.address = w.address;
            state.phrase = phrase || null;
            state.privateKey = null; // keep out of state dump if possible
            state._unlocked = true;
            try {
              localStorage.setItem('br_active_addr', w.address);
            } catch (e5) {}
            // Persist shell only (no secrets)
            if (typeof persistWallet === 'function') {
              try {
                persistWallet();
              } catch (e6) {}
            }
            return true;
          }
        }
      } catch (e7) {}
      return false;
    });
}

function brAutoMigrateSecrets(pin) {
  try {
    if (!pin || String(pin).length < 4) return;
    var chain = Promise.resolve();
    if (typeof SecureLocal !== 'undefined') {
      var run = SecureLocal.autoMigrateOnUnlock || SecureLocal.ensureSecureAfterPin;
      if (typeof run === 'function') {
        chain = Promise.resolve(run.call(SecureLocal, pin));
      }
    }
    chain
      .then(function (r) {
        if (window.BR_DEBUG && r && r.migrated && r.migrated.length) {
          console.log('[Security] Migrated secrets:', r.migrated.length, 'wiped:', r.wiped);
        }
        if (r && r.ok && r.migrated && r.migrated.length && typeof showToast === 'function') {
          showToast('Rahasia wallet dienkripsi');
        }
        return brRestoreWalletFromSecure(pin);
      })
      .catch(function (e) {
        if (window.BR_DEBUG) console.warn('[Security] migrate', e);
        return brRestoreWalletFromSecure(pin);
      });
  } catch (e) {}
}

// processPin path (second PIN system) — hook unlock success
var _origProcessPin = typeof processPin === 'function' ? processPin : null;
async function processPin() {
  var pin = state._pinBuf || state.pinBuffer || '';
  var mode = state._pinMode || state.pinMode;
  var err = document.getElementById('pinErr');
  if (err) err.textContent = '';

  // --- CHANGE PIN: verify old PIN first ---
  if (mode === 'change' || mode === 'change_old') {
    var okOld = false;
    try {
      if (typeof PinCrypto !== 'undefined' && PinCrypto.verify) {
        okOld = await PinCrypto.verify(pin);
      }
    } catch (e) {}
    if (!okOld) {
      // Legacy fallbacks
      try {
        var stored = localStorage.getItem('br_pin_hash') || localStorage.getItem('br_pin_v6') || localStorage.getItem(typeof PIN_KEY !== 'undefined' ? PIN_KEY : 'br_pin');
        if (stored && typeof verifyPinHash === 'function' && verifyPinHash(pin, stored)) okOld = true;
        else if (stored && typeof hashPin === 'function' && hashPin(pin) === stored) okOld = true;
        else if (typeof simpleHash === 'function' && simpleHash(pin) === (state.pinHash || localStorage.getItem('br_pin_hash'))) okOld = true;
      } catch (e2) {}
    }
    if (!okOld) {
      if (err) err.textContent = 'PIN lama salah';
      state._pinBuf = '';
      state.pinBuffer = '';
      if (typeof updatePinDots === 'function') updatePinDots();
      return;
    }
    // Old PIN OK → switch to new PIN setup
    state._pinTemp = '';
    state.pinTemp = '';
    state._pinBuf = '';
    state.pinBuffer = '';
    state._pinMode = 'setup';
    state.pinMode = 'setup';
    state._changePinFlow = true; // flag: after setup, show "PIN diubah"
    if (typeof updatePinDots === 'function') updatePinDots();
    var t = document.getElementById('pinTitle');
    var h = document.getElementById('pinHint');
    if (t) t.textContent = 'PIN baru';
    if (h) h.textContent = 'Masukkan 6 digit PIN baru';
    return;
  }

  if (mode === 'setup') {
    if (!state._pinTemp && !state.pinTemp) {
      state._pinTemp = pin;
      state.pinTemp = pin;
      state._pinBuf = '';
      state.pinBuffer = '';
      if (typeof updatePinDots === 'function') updatePinDots();
      var t1 = document.getElementById('pinTitle');
      var h1 = document.getElementById('pinHint');
      if (t1) t1.textContent = 'Konfirmasi PIN';
      if (h1) h1.textContent = 'Ulangi PIN yang sama';
      return;
    }
    var first = state._pinTemp || state.pinTemp;
    if (pin !== first) {
      if (err) err.textContent = 'PIN tidak cocok';
      state._pinTemp = '';
      state.pinTemp = '';
      state._pinBuf = '';
      state.pinBuffer = '';
      if (typeof updatePinDots === 'function') updatePinDots();
      var t2 = document.getElementById('pinTitle');
      if (t2) t2.textContent = state._changePinFlow ? 'PIN baru' : 'Buat PIN baru';
      return;
    }
    try {
      await PinCrypto.setup(pin);
      state._unlocked = true;
      state._lastActive = Date.now();
      try { brAutoMigrateSecrets(pin); } catch (eM) {}
      if (typeof hidePinOverlay === 'function') hidePinOverlay();
      var msg = state._changePinFlow ? 'PIN berhasil diubah' : 'PIN terenkripsi aktif';
      state._changePinFlow = false;
      // Resume the action that requested PIN setup (for example switching to
      // Solana). Do this before opening another modal, so the network change
      // feels like a single uninterrupted action.
      if (state._pinCallback) {
        var cbSetup = state._pinCallback;
        state._pinCallback = null;
        try { await cbSetup(); } catch (eCb) { console.warn('[PIN] resume callback failed', eCb); }
      } else {
        showToast(msg);
        try { openSecurityCenter(); } catch (e) {}
      }
    } catch (e) {
      if (err) err.textContent = 'Gagal enkripsi';
      console.log(e);
    }
    return;
  }

  if (mode === 'unlock' || mode === 'verify') {
    var ok = false;
    try {
      if (typeof PinCrypto !== 'undefined' && PinCrypto.verify) {
        ok = await PinCrypto.verify(pin);
      }
    } catch (e) {}
    // Extra legacy fallback if PinCrypto path failed
    if (!ok) {
      try {
        var stored2 = localStorage.getItem('br_pin_hash') || localStorage.getItem('br_pin_v6') || localStorage.getItem(typeof PIN_KEY !== 'undefined' ? PIN_KEY : 'br_pin');
        if (stored2 && typeof verifyPinHash === 'function' && verifyPinHash(pin, stored2)) ok = true;
        else if (stored2 && typeof hashPin === 'function' && hashPin(pin) === stored2) ok = true;
        else if (typeof simpleHash === 'function' && simpleHash(pin) === (state.pinHash || localStorage.getItem('br_pin_hash'))) ok = true;
      } catch (e3) {}
    }
    if (ok) {
      state._unlocked = true;
      state._lastActive = Date.now();
      if (typeof hidePinOverlay === 'function') hidePinOverlay();
      // Encrypt any leftover plaintext secrets
      try { brAutoMigrateSecrets(pin); } catch (e) {}
      if (state._pinCallback) {
        var cb = state._pinCallback;
        state._pinCallback = null;
        cb();
      } else {
        showToast('Dompet terbuka');
      }
    } else {
      if (err) err.textContent = 'PIN salah';
      state._pinBuf = '';
      state.pinBuffer = '';
      if (typeof updatePinDots === 'function') updatePinDots();
    }
    return;
  }

  if (_origProcessPin) return _origProcessPin();
}

/* ---------- Biometric UI ---------- */
async function openBiometricSettings() {
  var on = Biometric.isEnabled();
  var support = Biometric.supported();
  var platform = support ? await Biometric.platformAvailable() : false;

  var html = '<div class="modal-handle"></div><h3>Autentikasi biometrik</h3>';
  if (!support) {
    html += '<div class="sec-card sec-warn"><p class="sec-desc" style="margin:0">Browser ini tidak mendukung WebAuthn / biometrik.</p></div>';
    html += '<button class="btn btn-ghost" style="max-width:none" onclick="openSecurityCenter()">Kembali</button>';
    openModal(html);
    return;
  }
  if (!platform) {
    html += '<div class="sec-card sec-warn"><p class="sec-desc" style="margin:0">Authenticator platform (sidik jari / wajah) tidak terdeteksi. Coba di perangkat mobile atau laptop dengan Windows Hello / Touch ID.</p></div>';
    html += '<button class="btn btn-ghost" style="max-width:none" onclick="openSecurityCenter()">Kembali</button>';
    openModal(html);
    return;
  }

  html += '<div class="sec-card ' + (on ? 'sec-ok' : '') + '">';
  html += '<div class="sec-card-head"><span class="sec-badge ' + (on ? 'ok' : 'warn') + '">' + (on ? 'Biometrik aktif' : 'Belum diaktifkan') + '</span></div>';
  html += '<p class="sec-desc">Gunakan sidik jari atau wajah perangkat untuk membuka dompet. PIN tetap diperlukan sebagai cadangan.</p>';
  html += '<div class="sec-actions">';
  if (on) {
    html += '<button type="button" class="btn btn-primary btn-sm" onclick="testBiometric()">Uji biometrik</button>';
    html += '<button type="button" class="btn btn-ghost btn-sm" onclick="disableBiometric()">Nonaktifkan</button>';
  } else {
    html += '<button type="button" class="btn btn-primary btn-sm" onclick="enableBiometric()">Aktifkan</button>';
  }
  html += '</div></div>';
  html += '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="openSecurityCenter()">Kembali</button>';
  openModal(html);
}

async function enableBiometric() {
  // Require PIN first if set
  var needPin = !!(localStorage.getItem(PIN_KEY) || localStorage.getItem('br_pin_verifier_v2'));
  function doReg() {
    showToast('Ikuti prompt biometrik perangkat…');
    Biometric.register(state.address || 'user').then(function() {
      showToast('Biometrik diaktifkan');
      openBiometricSettings();
    }).catch(function(e) {
      showToast((e && e.message) || 'Gagal mendaftar biometrik');
    });
  }
  if (needPin && !PinCrypto._unlocked) {
    requirePin(doReg);
  } else {
    doReg();
  }
}

function disableBiometric() {
  if (!confirm('Nonaktifkan autentikasi biometrik?')) return;
  Biometric.disable();
  showToast('Biometrik dinonaktifkan');
  openBiometricSettings();
}

async function testBiometric() {
  try {
    showToast('Verifikasi biometrik…');
    await Biometric.authenticate();
    showToast('Biometrik valid ✓');
  } catch (e) {
    showToast((e && e.message) || 'Gagal');
  }
}

