/* ============================================================
   Adaptive PBKDF2 + End-to-End Encrypted Vault
   ============================================================ */

var CryptoTune = (function() {
  var CACHE_KEY = 'br_pbkdf2_iters_v1';
  var TARGET_MS = 120;       // faster on mobile
  var MIN_ITERS = 30000;
  var MAX_ITERS = 120000;
  var DEFAULT_ITERS = 45000;

  function getCached() {
    var n = parseInt(localStorage.getItem(CACHE_KEY) || '0', 10);
    if (n >= MIN_ITERS && n <= MAX_ITERS) return n;
    return 0;
  }

  /** Benchmark ~50ms sample then extrapolate to TARGET_MS */
  async function calibrate() {
    var cached = getCached();
    if (cached) return cached;

    var sampleIters = 40000;
    var salt = crypto.getRandomValues(new Uint8Array(16));
    var enc = new TextEncoder();
    var base = await crypto.subtle.importKey('raw', enc.encode('bench-pin-0000'), 'PBKDF2', false, ['deriveKey']);

    var t0 = performance.now();
    await crypto.subtle.deriveKey(
      { name: 'PBKDF2', salt: salt, iterations: sampleIters, hash: 'SHA-256' },
      base,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
    var dt = Math.max(1, performance.now() - t0);
    var perIter = dt / sampleIters;
    var ideal = Math.floor(TARGET_MS / perIter);
    // Round to 10k
    ideal = Math.round(ideal / 10000) * 10000;
    if (ideal < MIN_ITERS) ideal = MIN_ITERS;
    if (ideal > MAX_ITERS) ideal = MAX_ITERS;
    localStorage.setItem(CACHE_KEY, String(ideal));
    brLog('%cPBKDF2 calibrated: ' + ideal + ' iterations (~' + TARGET_MS + 'ms target, sample ' + dt.toFixed(0) + 'ms)', 'color:#00e6b8');
    return ideal;
  }

  function getIterations() {
    return getCached() || DEFAULT_ITERS;
  }

  // Fire-and-forget calibration after idle
  if (typeof requestIdleCallback === 'function') {
    requestIdleCallback(function() { calibrate().catch(function(){}); }, { timeout: 3000 });
  } else {
    setTimeout(function() { calibrate().catch(function(){}); }, 1500);
  }

  return { calibrate: calibrate, getIterations: getIterations, TARGET_MS: TARGET_MS };
})();

/* End-to-end vault — encrypts wallet blob at rest */
var E2EVault = (function() {
  var VAULT_KEY = 'br_vault_e2e_v1';
  var META_KEY = 'br_vault_meta_v1';

  function b64encode(buf) {
    var bytes = buf instanceof ArrayBuffer ? new Uint8Array(buf) : buf;
    var s = '';
    for (var i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return btoa(s);
  }
  function b64decode(str) {
    var bin = atob(str);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  async function derive(pin, salt, iterations) {
    var enc = new TextEncoder();
    var base = await crypto.subtle.importKey('raw', enc.encode(String(pin)), 'PBKDF2', false, ['deriveKey']);
    return crypto.subtle.deriveKey(
      { name: 'PBKDF2', salt: salt, iterations: iterations, hash: 'SHA-256' },
      base,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  }

  async function seal(plaintext, key) {
    var iv = crypto.getRandomValues(new Uint8Array(12));
    var data = new TextEncoder().encode(plaintext);
    var cipher = await crypto.subtle.encrypt({ name: 'AES-GCM', iv: iv }, key, data);
    var packed = new Uint8Array(iv.length + cipher.byteLength);
    packed.set(iv, 0);
    packed.set(new Uint8Array(cipher), iv.length);
    return b64encode(packed);
  }

  async function open(b64, key) {
    var packed = b64decode(b64);
    var iv = packed.slice(0, 12);
    var data = packed.slice(12);
    var dec = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: iv }, key, data);
    return new TextDecoder().decode(dec);
  }

  /** Encrypt full wallet payload with current session / PIN */
  async function encryptWalletPayload(payload, pin) {
    var iterations = CryptoTune.getIterations();
    await CryptoTune.calibrate().catch(function(){});
    iterations = CryptoTune.getIterations();

    var salt = crypto.getRandomValues(new Uint8Array(16));
    var key = pin
      ? await derive(pin, salt, iterations)
      : (PinCrypto && PinCrypto._sessionKey);

    if (!key && pin) key = await derive(pin, salt, iterations);
    if (!key) throw new Error('No encryption key — set PIN first');

    var json = typeof payload === 'string' ? payload : JSON.stringify(payload);
    var cipher = await seal(json, key);

    var meta = {
      v: 1,
      alg: 'AES-GCM-256',
      kdf: 'PBKDF2-SHA256',
      iterations: iterations,
      salt: b64encode(salt),
      at: Date.now()
    };
    localStorage.setItem(VAULT_KEY, cipher);
    localStorage.setItem(META_KEY, JSON.stringify(meta));
    return meta;
  }

  async function decryptWalletPayload(pin) {
    var cipher = localStorage.getItem(VAULT_KEY);
    var metaRaw = localStorage.getItem(META_KEY);
    if (!cipher || !metaRaw) return null;
    var meta = JSON.parse(metaRaw);
    var salt = b64decode(meta.salt);
    var iterations = meta.iterations || CryptoTune.getIterations();
    var key = await derive(pin, salt, iterations);
    var plain = await open(cipher, key);
    return JSON.parse(plain);
  }

  function hasVault() {
    return !!localStorage.getItem(VAULT_KEY);
  }

  function clear() {
    localStorage.removeItem(VAULT_KEY);
    localStorage.removeItem(META_KEY);
  }

  /**
   * Persist wallet end-to-end encrypted when PIN session active.
   * Falls back to legacy plaintext only if no PIN configured.
   */
  async function securePersist() {
    if (!state.wallet && !state.address) return false;

    var entry = {
      address: state.address,
      privateKey: (state.wallet && state.wallet.privateKey) || state.privateKey || null,
      phrase: state.phrase || state.mnemonic || null,
      hasMnemonic: !!(state.phrase || state.mnemonic),
      name: state.walletName || 'Wallet',
      network: state.network || 'base',
      created: Date.now()
    };

    var pinOn = !!(localStorage.getItem('br_pin_verifier_v2') || localStorage.getItem(PIN_KEY));

    if (pinOn && PinCrypto && PinCrypto._sessionKey) {
      // Encrypt secrets into SecureStore + vault; store public shell only in STORAGE_KEY
      try {
        if (typeof SecureStore !== 'undefined' && SecureStore._key) {
          await SecureStore.setSensitive(entry.phrase || '', entry.privateKey || '');
        }
        await encryptWalletPayload({
          address: entry.address,
          privateKey: entry.privateKey,
          phrase: entry.phrase,
          name: entry.name,
          network: entry.network,
          created: entry.created
        });
        // Public non-secret shell
        var shell = {
          address: entry.address,
          name: entry.name,
          hasMnemonic: entry.hasMnemonic,
          encrypted: true,
          created: entry.created
        };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(shell));
        // Strip plaintext private keys from multi-wallet list
        try {
          var all = JSON.parse(localStorage.getItem('br_wallets_v3') || '[]');
          all = all.map(function(w) {
            if (w.address && entry.address && w.address.toLowerCase() === entry.address.toLowerCase()) {
              return {
                address: entry.address,
                name: entry.name,
                hasMnemonic: entry.hasMnemonic,
                encrypted: true,
                created: entry.created
              };
            }
            if (w.privateKey) {
              var copy = Object.assign({}, w);
              delete copy.privateKey;
              copy.encrypted = true;
              return copy;
            }
            return w;
          });
          localStorage.setItem('br_wallets_v3', JSON.stringify(all));
        } catch (e) {}
        // Remove legacy plaintext keys
        ['br_pk', 'privateKey', 'br_mnemonic', 'mnemonic', 'br_phrase'].forEach(function(k) {
          try { localStorage.removeItem(k); } catch (e) {}
        });
        return true;
      } catch (e) {
        console.log('E2E persist fail', e);
      }
    }

    // Legacy plaintext path (no PIN)
    if (typeof persistWallet === 'function') {
      // call original behavior via direct write
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({
          address: entry.address,
          privateKey: entry.privateKey,
          hasMnemonic: entry.hasMnemonic,
          name: entry.name,
          created: entry.created
        }));
      } catch (e) {}
    }
    return false;
  }

  async function secureLoad(pin) {
    // Prefer E2E vault
    if (hasVault() && pin) {
      try {
        var data = await decryptWalletPayload(pin);
        if (data && data.privateKey) {
          var w = new ethers.Wallet(data.privateKey);
          state.wallet = w;
          state.address = w.address;
          state.phrase = data.phrase || null;
          state.mnemonic = data.phrase || null;
          state.privateKey = data.privateKey;
          state.walletName = data.name || 'Wallet';
          state.network = data.network || state.network || 'base';
          return true;
        }
      } catch (e) {
        if(window.BR_DEBUG) console.warn('vault load fail', e);
      }
    }
    // SecureStore
    if (typeof SecureStore !== 'undefined' && pin) {
      try {
        await SecureStore.unlock(pin);
        var sens = await SecureStore.loadSensitive();
        if (sens.pk) {
          var w2 = new ethers.Wallet(sens.pk);
          state.wallet = w2;
          state.address = w2.address;
          state.phrase = sens.mnemonic || null;
          state.privateKey = sens.pk;
          return true;
        }
      } catch (e) {}
    }
    return false;
  }

  return {
    encryptWalletPayload: encryptWalletPayload,
    decryptWalletPayload: decryptWalletPayload,
    securePersist: securePersist,
    secureLoad: secureLoad,
    hasVault: hasVault,
    clear: clear
  };
})();

/* Patch SecureStore + PinCrypto to use adaptive iterations */
(function patchAdaptivePbkdf2() {
  if (typeof SecureStore !== 'undefined' && SecureStore.deriveKey) {
    var _origDerive = SecureStore.deriveKey.bind(SecureStore);
    SecureStore.deriveKey = async function(pin, salt) {
      var iterations = CryptoTune.getIterations();
      var enc = new TextEncoder();
      var base = await crypto.subtle.importKey('raw', enc.encode(pin), 'PBKDF2', false, ['deriveKey']);
      return crypto.subtle.deriveKey(
        { name: 'PBKDF2', salt: salt, iterations: iterations, hash: 'SHA-256' },
        base,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt']
      );
    };
  }

  if (typeof PinCrypto !== 'undefined') {
    // Override derive inside setup/verify by wrapping setup
    var _setup = PinCrypto.setup;
    PinCrypto.setup = async function(pin) {
      await CryptoTune.calibrate().catch(function(){});
      var result = await _setup.call(PinCrypto, pin);
      // After setup, E2E-encrypt current wallet
      try { await E2EVault.securePersist(); } catch (e) {}
      return result;
    };
    var _verify = PinCrypto.verify;
    PinCrypto.verify = async function(pin) {
      var ok = await _verify.call(PinCrypto, pin);
      if (ok) {
        try {
          if (E2EVault.hasVault()) await E2EVault.secureLoad(pin);
        } catch (e) {}
      }
      return ok;
    };
  }
})();

/* Override persistWallet to prefer E2E */
var _origPersistWallet = typeof persistWallet === 'function' ? persistWallet : null;
function persistWallet() {
  if (PinCrypto && PinCrypto._sessionKey) {
    E2EVault.securePersist().catch(function(e) {
      console.log('securePersist', e);
      if (_origPersistWallet) _origPersistWallet();
    });
    // Also keep token list
    try {
      var custom = (state.tokens || []).filter(function(t) {
        return !(typeof DEFAULT_TOKENS !== 'undefined' && DEFAULT_TOKENS.find(function(d) { return d.id === t.id; }));
      });
      localStorage.setItem(TOKENS_KEY, JSON.stringify(custom));
    } catch (e) {}
    return;
  }
  if (_origPersistWallet) return _origPersistWallet();
}

window.CryptoTune = CryptoTune;
window.E2EVault = E2EVault;

