/* ===== PIN overlay — bulletproof (fixes Atur PIN) ===== */
function updatePinDots() {
  var len = 0;
  if (state._pinBuf) len = state._pinBuf.length;
  else if (state.pinBuffer) len = state.pinBuffer.length;
  var dots = document.querySelectorAll('#pinDots span, #pinDots .pin-dot');
  dots.forEach(function(d, i) {
    d.classList.toggle('on', i < len);
  });
}

function buildPinPad() {
  var pad = document.getElementById('pinPad');
  if (!pad) return;
  var keys = ['1','2','3','4','5','6','7','8','9','','0','⌫'];
  pad.innerHTML = keys.map(function(k) {
    if (k === '') return '<span></span>';
    return '<button type="button" class="pin-key" data-pk="' + k + '">' + k + '</button>';
  }).join('');
  pad.querySelectorAll('button').forEach(function(b) {
    b.onclick = function(e) {
      e.preventDefault();
      e.stopPropagation();
      pinKeyPress(b.getAttribute('data-pk'));
    };
  });
}

function pinKeyPress(k) {
  // Keep both buffers in sync for dual PIN systems
  if (!state._pinBuf) state._pinBuf = '';
  if (!state.pinBuffer) state.pinBuffer = '';

  if (k === '⌫') {
    state._pinBuf = state._pinBuf.slice(0, -1);
    state.pinBuffer = state.pinBuffer.slice(0, -1);
    updatePinDots();
    return;
  }
  if (!/^[0-9]$/.test(k)) return;
  if (state._pinBuf.length >= 6) return;
  state._pinBuf += k;
  state.pinBuffer += k;
  updatePinDots();
  if (state._pinBuf.length === 6) {
    setTimeout(function() {
      // Prefer processPin (newer) if mode set there, else handlePinComplete
      if (state._pinMode && typeof processPin === 'function') {
        try { processPin(); } catch (e) { console.log(e); }
      } else if (typeof handlePinComplete === 'function') {
        try { handlePinComplete(); } catch (e) { console.log(e); }
      }
    }, 100);
  }
}

function showPinOverlay(title, hint) {
  var ov = document.getElementById('pinOverlay');
  if (!ov) {
    showToast('Overlay PIN tidak ditemukan');
    return;
  }
  var t = document.getElementById('pinTitle');
  var h = document.getElementById('pinHint');
  var err = document.getElementById('pinErr');
  if (t) t.textContent = title || 'Masukkan PIN';
  if (h) h.textContent = hint || '';
  if (err) err.textContent = '';
  state._pinBuf = '';
  state.pinBuffer = '';
  buildPinPad();
  updatePinDots();
  // Close any modal so it doesn't block
  try {
    var mb = document.getElementById('modalBackdrop');
    if (mb) mb.classList.remove('show');
  } catch (e) {}
  ov.classList.add('show');
  ov.style.display = 'flex';
  ov.style.zIndex = '500';
}

function hidePinOverlay() {
  var ov = document.getElementById('pinOverlay');
  if (ov) {
    ov.classList.remove('show');
    ov.style.display = 'none';
  }
  state._pinBuf = '';
  state.pinBuffer = '';
}

function setupPin() {
  // Close security sheet first
  try {
    var mb = document.getElementById('modalBackdrop');
    if (mb) mb.classList.remove('show');
  } catch (e) {}

  state.pinMode = 'setup';
  state._pinMode = 'setup';
  state.pinBuffer = '';
  state.pinTemp = '';
  state._pinBuf = '';
  state._pinTemp = '';

  showPinOverlay('Buat PIN baru', 'Masukkan 6 digit PIN');
}

function changePin() {
  try {
    var mb = document.getElementById('modalBackdrop');
    if (mb) mb.classList.remove('show');
  } catch (e) {}
  state.pinMode = 'change_old';
  state._pinMode = 'change';
  state.pinBuffer = '';
  state._pinBuf = '';
  state._pinTemp = '';
  showPinOverlay('Ubah PIN', 'Masukkan PIN lama');
}

