/* ============================================================
   Input Validation · Seed Phrase (BIP39) · MPC / Keyless Wallet
   ============================================================ */

var InputValidator = (function() {
  function isEmpty(v) {
    return v == null || String(v).trim() === '';
  }

  function isAddress(v) {
    try { return ethers.isAddress(String(v).trim()); } catch (e) { return false; }
  }

  function isPrivateKey(v) {
    var s = String(v || '').trim().replace(/\s+/g, '');
    if (/^0x[0-9a-fA-F]{64}$/.test(s)) return true;
    if (/^[0-9a-fA-F]{64}$/.test(s)) return true;
    return false;
  }

  function normalizePrivateKey(v) {
    var s = String(v || '').trim().replace(/\s+/g, '');
    if (!isPrivateKey(s)) return null;
    return s.startsWith('0x') ? s : ('0x' + s);
  }

  function isEmail(v) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v || '').trim());
  }

  function isPin(v) {
    return /^\d{6}$/.test(String(v || '').trim());
  }

  function isPositiveAmount(v, maxDecimals) {
    var s = String(v || '').trim().replace(',', '.');
    if (!/^\d+(\.\d+)?$/.test(s)) return false;
    var n = Number(s);
    if (!isFinite(n) || n <= 0) return false;
    if (maxDecimals != null) {
      var parts = s.split('.');
      if (parts[1] && parts[1].length > maxDecimals) return false;
    }
    return true;
  }

  function isHexData(v) {
    return /^(0x)?[0-9a-fA-F]*$/.test(String(v || '').trim());
  }

  function clampName(v, maxLen) {
    maxLen = maxLen || 24;
    return String(v || '').trim().slice(0, maxLen);
  }

  /** Returns { ok, error, value } */
  function field(type, value, opts) {
    opts = opts || {};
    var v = value;
    switch (type) {
      case 'address':
        if (isEmpty(v)) return { ok: false, error: 'Alamat wajib diisi', value: null };
        if (!isAddress(v)) return { ok: false, error: 'Alamat tidak valid', value: null };
        return { ok: true, error: null, value: ethers.getAddress(String(v).trim()) };
      case 'privateKey':
        if (isEmpty(v)) return { ok: false, error: 'Private key wajib diisi', value: null };
        var pk = normalizePrivateKey(v);
        if (!pk) return { ok: false, error: 'Private key harus 64 karakter hex', value: null };
        return { ok: true, error: null, value: pk };
      case 'email':
        if (isEmpty(v)) return { ok: false, error: 'Email wajib diisi', value: null };
        if (!isEmail(v)) return { ok: false, error: 'Format email tidak valid', value: null };
        return { ok: true, error: null, value: String(v).trim().toLowerCase() };
      case 'pin':
        if (!isPin(v)) return { ok: false, error: 'PIN harus 6 digit angka', value: null };
        return { ok: true, error: null, value: String(v).trim() };
      case 'amount':
        if (!isPositiveAmount(v, opts.decimals)) return { ok: false, error: 'Jumlah tidak valid', value: null };
        return { ok: true, error: null, value: String(v).trim().replace(',', '.') };
      case 'name':
        var n = clampName(v, opts.maxLen || 24);
        if (!n) return { ok: false, error: 'Nama wajib diisi', value: null };
        return { ok: true, error: null, value: n };
      default:
        if (isEmpty(v)) return { ok: false, error: 'Wajib diisi', value: null };
        return { ok: true, error: null, value: String(v).trim() };
    }
  }

  return {
    isEmpty: isEmpty,
    isAddress: isAddress,
    isPrivateKey: isPrivateKey,
    normalizePrivateKey: normalizePrivateKey,
    isEmail: isEmail,
    isPin: isPin,
    isPositiveAmount: isPositiveAmount,
    isHexData: isHexData,
    clampName: clampName,
    field: field
  };
})();

/* ----- BIP39 Seed validation ----- */
var SeedValidator = (function() {
  var _wordset = null;

  function getWordset() {
    if (_wordset) return _wordset;
    try {
      // ethers v6 wordlist
      if (ethers.Mnemonic && ethers.Mnemonic.entropyToPhrase) {
        // Build set from common approach: validate via try/catch per word isn't ideal
        // Use Wordlist if available
        if (ethers.WordlistOwl || ethers.wordlists) {
          var wl = (ethers.wordlists && (ethers.wordlists.en || ethers.wordlists.get('en'))) || null;
          if (wl && wl._words) {
            _wordset = {};
            String(wl._words).split(/[\s,]+/).forEach(function(w) {
              if (w) _wordset[w.toLowerCase()] = true;
            });
            if (Object.keys(_wordset).length > 1000) return _wordset;
          }
        }
      }
    } catch (e) {}
    _wordset = null;
    return null;
  }

  function normalize(phrase) {
    return String(phrase || '')
      .trim()
      .toLowerCase()
      .replace(/[^a-z\s]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function splitWords(phrase) {
    return normalize(phrase).split(' ').filter(Boolean);
  }

  /**
   * Validate seed phrase
   * @returns {{ ok, error, words, invalidWords, phrase }}
   */
  function validate(phrase) {
    var words = splitWords(phrase);
    if (!words.length) {
      return { ok: false, error: 'Seed phrase kosong', words: [], invalidWords: [], phrase: '' };
    }
    if (words.length !== 12 && words.length !== 15 && words.length !== 18 && words.length !== 21 && words.length !== 24) {
      return {
        ok: false,
        error: 'Jumlah kata harus 12, 15, 18, 21, atau 24 (sekarang: ' + words.length + ')',
        words: words,
        invalidWords: [],
        phrase: words.join(' ')
      };
    }

    // Wordlist check when available
    var set = getWordset();
    var invalid = [];
    if (set) {
      words.forEach(function(w, i) {
        if (!set[w]) invalid.push({ index: i, word: w });
      });
      if (invalid.length) {
        return {
          ok: false,
          error: 'Kata tidak dikenal: ' + invalid.slice(0, 3).map(function(x) { return x.word; }).join(', '),
          words: words,
          invalidWords: invalid,
          phrase: words.join(' ')
        };
      }
    }

    // Full BIP39 checksum via ethers
    try {
      var joined = words.join(' ');
      if (ethers.Mnemonic && typeof ethers.Mnemonic.fromPhrase === 'function') {
        ethers.Mnemonic.fromPhrase(joined);
      } else {
        ethers.Wallet.fromPhrase(joined);
      }
      return { ok: true, error: null, words: words, invalidWords: [], phrase: joined };
    } catch (e) {
      return {
        ok: false,
        error: 'Checksum BIP39 gagal — cek ejaan / urutan kata',
        words: words,
        invalidWords: [],
        phrase: words.join(' ')
      };
    }
  }

  /** Live feedback for UI */
  function analyzeLive(phrase) {
    var words = splitWords(phrase);
    var set = getWordset();
    var details = words.map(function(w, i) {
      var known = set ? !!set[w] : null;
      return { index: i, word: w, known: known };
    });
    var v = words.length ? validate(phrase) : { ok: false, error: '', words: [], invalidWords: [] };
    return {
      count: words.length,
      expected: [12, 15, 18, 21, 24],
      countOk: [12, 15, 18, 21, 24].indexOf(words.length) >= 0,
      details: details,
      valid: v.ok,
      error: v.error
    };
  }

  return {
    normalize: normalize,
    splitWords: splitWords,
    validate: validate,
    analyzeLive: analyzeLive
  };
})();

/* ----- MPC / Keyless-style wallet (client-side 2-of-3 shares) ----- */
var MPCWallet = (function() {
  var STORE = 'br_mpc_vault_v1';

  function randomBytes(n) {
    var b = new Uint8Array(n);
    crypto.getRandomValues(b);
    return b;
  }

  function toHex(buf) {
    return Array.from(buf).map(function(x) { return x.toString(16).padStart(2, '0'); }).join('');
  }
  function fromHex(hex) {
    var s = hex.replace(/^0x/, '');
    var out = new Uint8Array(s.length / 2);
    for (var i = 0; i < out.length; i++) out[i] = parseInt(s.substr(i * 2, 2), 16);
    return out;
  }

  function xorBytes(a, b) {
    var n = Math.max(a.length, b.length);
    var out = new Uint8Array(n);
    for (var i = 0; i < n; i++) out[i] = (a[i] || 0) ^ (b[i] || 0);
    return out;
  }

  /**
   * Split private key into 3 shares (2-of-3 style via XOR pads):
   * pk = s1 XOR s2 XOR s3  → any 2 insufficient alone; we store:
   * Actually simple: s1 random, s2 random, s3 = pk XOR s1 XOR s2
   * Reconstruct: need all 3 for full XOR scheme OR we do 2-of-3 shamir-lite:
   * For practicality: shareA = s1, shareB = s2, shareC = pk XOR s1 XOR s2
   * Recovery needs any combination that covers — user keeps email share + device share + backup share.
   */
  function splitPrivateKey(pkHex) {
    var pk = fromHex(pkHex);
    var s1 = randomBytes(pk.length);
    var s2 = randomBytes(pk.length);
    var s3 = xorBytes(pk, xorBytes(s1, s2));
    return {
      device: toHex(s1),
      cloud: toHex(s2),
      recovery: toHex(s3)
    };
  }

  function combineShares(a, b, c) {
    var x = xorBytes(fromHex(a), fromHex(b));
    var pk = xorBytes(x, fromHex(c));
    return '0x' + toHex(pk);
  }

  async function hashPin(pin, saltHex) {
    var enc = new TextEncoder();
    var base = await crypto.subtle.importKey('raw', enc.encode(String(pin)), 'PBKDF2', false, ['deriveBits']);
    var salt = saltHex ? fromHex(saltHex) : randomBytes(16);
    var bits = await crypto.subtle.deriveBits(
      { name: 'PBKDF2', salt: salt, iterations: (typeof CryptoTune !== 'undefined' ? CryptoTune.getIterations() : 100000), hash: 'SHA-256' },
      base,
      256
    );
    return { hash: toHex(new Uint8Array(bits)), salt: toHex(salt) };
  }

  /** Create MPC-style wallet: generates key, splits shares, stores device share */
  async function create(email, pin) {
    var ev = InputValidator.field('email', email);
    if (!ev.ok) throw new Error(ev.error);
    var pv = InputValidator.field('pin', pin);
    if (!pv.ok) throw new Error(pv.error);

    var w = ethers.Wallet.createRandom();
    var shares = splitPrivateKey(w.privateKey);
    var pinData = await hashPin(pv.value);

    var vault = {
      v: 1,
      type: 'mpc-xor-3',
      address: w.address,
      email: ev.value,
      deviceShare: shares.device,
      // cloud share "uploaded" — simulated local cloud slot (encrypted marker)
      cloudShare: shares.cloud,
      // recovery share shown once to user
      recoveryShare: shares.recovery,
      pinSalt: pinData.salt,
      pinHash: pinData.hash,
      created: Date.now()
    };

    // Persist without recovery share (user must backup recovery)
    var stored = Object.assign({}, vault);
    localStorage.setItem(STORE, JSON.stringify({
      v: stored.v,
      type: stored.type,
      address: stored.address,
      email: stored.email,
      deviceShare: stored.deviceShare,
      cloudShare: stored.cloudShare,
      pinSalt: stored.pinSalt,
      pinHash: stored.pinHash,
      created: stored.created
    }));

    return {
      address: w.address,
      recoveryShare: shares.recovery,
      wallet: w,
      phrase: w.mnemonic ? w.mnemonic.phrase : null
    };
  }

  /** Unlock with email + pin (+ optional recovery if cloud missing) */
  async function unlock(email, pin, recoveryShare) {
    var raw = localStorage.getItem(STORE);
    if (!raw) throw new Error('Tidak ada dompet MPC tersimpan');
    var vault = JSON.parse(raw);
    if (email && vault.email && email.toLowerCase() !== vault.email) {
      throw new Error('Email tidak cocok');
    }
    var pinData = await hashPin(pin, vault.pinSalt);
    if (pinData.hash !== vault.pinHash) throw new Error('PIN salah');

    var cloud = vault.cloudShare;
    var device = vault.deviceShare;
    var recovery = recoveryShare || vault.recoveryShare;
    if (!recovery) throw new Error('Recovery share diperlukan');

    var pk = combineShares(device, cloud, recovery);
    var w = new ethers.Wallet(pk);
    if (w.address.toLowerCase() !== vault.address.toLowerCase()) {
      throw new Error('Gagal merekonstruksi kunci');
    }
    return w;
  }

  function hasVault() {
    return !!localStorage.getItem(STORE);
  }

  function getMeta() {
    try {
      var v = JSON.parse(localStorage.getItem(STORE) || 'null');
      if (!v) return null;
      return { address: v.address, email: v.email, created: v.created, type: v.type };
    } catch (e) { return null; }
  }

  function clear() {
    localStorage.removeItem(STORE);
  }

  return {
    create: create,
    unlock: unlock,
    hasVault: hasVault,
    getMeta: getMeta,
    clear: clear,
    splitPrivateKey: splitPrivateKey,
    combineShares: combineShares
  };
})();

