/** Live validation hint under import textarea */
function bindSeedLiveValidation() {
  var el = document.getElementById('importPhrase');
  if (!el || el._seedLive) return;
  el._seedLive = true;
  var hint = document.getElementById('importSeedHint');
  if (!hint) {
    hint = document.createElement('div');
    hint.id = 'importSeedHint';
    hint.className = 'imp-seed-hint';
    el.parentNode.appendChild(hint);
  }
  el.addEventListener('input', function() {
    var v = el.value.trim();
    if (!v) { hint.textContent = ''; hint.className = 'imp-seed-hint'; return; }
    if (InputValidator.isPrivateKey(v)) {
      hint.textContent = 'Format private key terdeteksi';
      hint.className = 'imp-seed-hint ok';
      return;
    }
    var a = SeedValidator.analyzeLive(v);
    if (a.valid) {
      hint.textContent = 'Seed phrase valid (' + a.count + ' kata)';
      hint.className = 'imp-seed-hint ok';
    } else if (a.count > 0) {
      hint.textContent = (a.error || (a.count + ' kata')) + '';
      hint.className = 'imp-seed-hint ' + (a.countOk ? 'err' : '');
    } else {
      hint.textContent = '';
    }
  });
}

// MPC UI
function openMpcCreate() {
  closeObSheets();
  openModal(
    '<div class="modal-handle"></div><h3>Dompet MPC / Keyless</h3>' +
    '<p class="hint">Kunci dipecah menjadi 3 share (perangkat + cloud lokal + recovery). Simpan recovery share dengan aman.</p>' +
    '<div class="field"><label>Email</label><input id="mpcEmail" type="email" placeholder="nama@email.com" autocomplete="email"></div>' +
    '<div class="field"><label>PIN 6 digit</label><input id="mpcPin" inputmode="numeric" maxlength="6" placeholder="000000" autocomplete="off"></div>' +
    '<button class="btn btn-primary" style="max-width:none" onclick="runMpcCreate()">Buat dompet MPC</button>' +
    '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="closeModal()">Batal</button>'
  );
}

async function runMpcCreate() {
  var email = ((document.getElementById('mpcEmail') || {}).value || '').trim();
  var pin = ((document.getElementById('mpcPin') || {}).value || '').trim();
  var ev = InputValidator.field('email', email);
  if (!ev.ok) return showToast(ev.error);
  var pv = InputValidator.field('pin', pin);
  if (!pv.ok) return showToast(pv.error);
  try {
    setLoading(true);
    var res = await MPCWallet.create(ev.value, pv.value);
    state.wallet = res.wallet;
    state.address = res.address;
    state.phrase = res.phrase;
    state.privateKey = res.wallet.privateKey;
    state.walletName = ev.value.split('@')[0].slice(0, 16);
    persistWallet();
    setLoading(false);
    openModal(
      '<div class="modal-handle"></div><h3>Recovery Share</h3>' +
      '<div class="sec-card sec-warn"><p style="margin:0 0 8px;font-size:.8rem">Simpan kode ini offline. Diperlukan untuk memulihkan dompet MPC.</p>' +
      '<p style="margin:0;word-break:break-all;font-family:var(--mono);font-size:.72rem" id="mpcRecoveryOut">' + res.recoveryShare + '</p></div>' +
      '<button class="btn btn-primary" style="max-width:none;margin-top:12px" onclick="navigator.clipboard.writeText(document.getElementById(\'mpcRecoveryOut\').textContent).then(function(){showToast(\'Disalin\')})">Salin recovery share</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="closeModal();showScreen(\'home\');refreshBalances(true)">Selesai</button>'
    );
  } catch (e) {
    setLoading(false);
    showToast((e && e.message) || 'Gagal buat MPC');
  }
}

function openMpcUnlock() {
  closeObSheets();
  openModal(
    '<div class="modal-handle"></div><h3>Buka dompet MPC</h3>' +
    '<div class="field"><label>Email</label><input id="mpcUnlockEmail" type="email" placeholder="nama@email.com"></div>' +
    '<div class="field"><label>PIN</label><input id="mpcUnlockPin" inputmode="numeric" maxlength="6" placeholder="000000"></div>' +
    '<div class="field"><label>Recovery share</label><textarea id="mpcUnlockRecovery" placeholder="hex recovery share" style="min-height:72px"></textarea></div>' +
    '<button class="btn btn-primary" style="max-width:none" onclick="runMpcUnlock()">Buka</button>' +
    '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="closeModal()">Batal</button>'
  );
}

async function runMpcUnlock() {
  var email = ((document.getElementById('mpcUnlockEmail') || {}).value || '').trim();
  var pin = ((document.getElementById('mpcUnlockPin') || {}).value || '').trim();
  var rec = ((document.getElementById('mpcUnlockRecovery') || {}).value || '').trim();
  try {
    setLoading(true);
    var w = await MPCWallet.unlock(email, pin, rec);
    state.wallet = w;
    state.address = w.address;
    state.privateKey = w.privateKey;
    state.phrase = null;
    persistWallet();
    setLoading(false);
    closeModal();
    showToast('Dompet MPC dibuka');
    showScreen('home');
    if (typeof refreshBalances === 'function') refreshBalances(true);
  } catch (e) {
    setLoading(false);
    showToast((e && e.message) || 'Gagal buka MPC');
  }
}

