/* ===== Fix: import screen clicks & overlays ===== */
function dismissAllOverlays() {
  try {
    closeObSheets();
  } catch (e) {}
  try {
    var mb = document.getElementById('modalBackdrop');
    if (mb) mb.classList.remove('show');
  } catch (e) {}
  try {
    var pin = document.getElementById('pinOverlay');
    if (pin && !state.pinMode && state._pinMode !== 'unlock') {
      /* don't force-close if locking */
    }
  } catch (e) {}
  // Kill any full-screen blockers left with .show except pin when needed
  document.querySelectorAll('.ob-sheet-bg.show').forEach(function(el) {
    el.classList.remove('show');
  });
}

function importSecretUnified() {
  try {
    var el = document.getElementById('importPhrase');
    var raw = (el && el.value ? el.value : '').trim();
    if (!raw) {
      showToast('Masukkan seed phrase atau private key');
      return;
    }

    // Private key
    if (typeof InputValidator !== 'undefined' && InputValidator.isPrivateKey(raw)) {
      var pk = InputValidator.normalizePrivateKey(raw);
      var w = new ethers.Wallet(pk);
      state.wallet = w;
      state.address = w.address;
      state.phrase = null;
      state.privateKey = pk;
      state._unlocked = true;
      try { persistWallet(); } catch (e) {}
      dismissAllOverlays();
      showToast('Private key diimpor');
      showScreen('home');
      setTimeout(function() {
        if (typeof refreshBalances === 'function') refreshBalances(true);
      }, 100);
      return;
    }

    // Seed phrase
    var phrase = raw.replace(/\s+/g, ' ').toLowerCase();
    var words = phrase.split(' ').filter(Boolean);
    if (words.length !== 12 && words.length !== 24 && words.length !== 15 && words.length !== 18 && words.length !== 21) {
      showToast('Seed harus 12 atau 24 kata (sekarang: ' + words.length + ')');
      return;
    }

    var w2;
    try {
      if (typeof SeedValidator !== 'undefined') {
        var check = SeedValidator.validate(phrase);
        if (!check.ok) {
          showToast(check.error || 'Seed tidak valid');
          return;
        }
        phrase = check.phrase;
      }
      w2 = ethers.Wallet.fromPhrase(phrase);
    } catch (err) {
      showToast('Seed phrase tidak valid');
      console.log(err);
      return;
    }

    state.wallet = w2;
    state.address = w2.address;
    state.phrase = phrase;
    state.privateKey = w2.privateKey;
    state._unlocked = true;
    try { persistWallet(); } catch (e) { console.log(e); }
    dismissAllOverlays();
    showToast('Dompet diimpor');
    showScreen('home');
    setTimeout(function() {
      if (typeof refreshBalances === 'function') refreshBalances(true);
      if (typeof renderHome === 'function') renderHome();
    }, 100);
  } catch (e) {
    console.log('importSecretUnified error', e);
    showToast((e && e.message) ? e.message.slice(0, 80) : 'Import gagal');
  }
}

function openKeylessImport() {
  try {
    dismissAllOverlays();
    if (typeof MPCWallet !== 'undefined' && MPCWallet.hasVault()) {
      openMpcUnlock();
    } else if (typeof openMpcCreate === 'function') {
      openMpcCreate();
    } else {
      showToast('Modul MPC belum siap');
    }
  } catch (e) {
    showToast((e && e.message) || 'MPC error');
  }
}

function goHardwareFromImport() {
  dismissAllOverlays();
  showScreen('hardware');
}

// Robust showScreen — always close sheets, bind import UI
(function patchShowScreenFinal() {
  var base = window.showScreen || showScreen;
  window.showScreen = function(name) {
    try { dismissAllOverlays(); } catch (e) {}
    base(name);
    if (name === 'import') {
      setTimeout(function() {
        try { bindSeedLiveValidation(); } catch (e) {}
        wireImportButtons();
      }, 30);
    }
    if (name === 'hardware') {
      // Fix back button target when coming from import
      var back = document.querySelector('#screen-hardware .back, #screen-hardware .back-btn');
      if (back && !state.address) {
        back.setAttribute('onclick', "showScreen('import')");
      }
    }
  };
})();

function wireImportButtons() {
  var btn = document.querySelector('#screen-import .ob-btn-primary');
  if (btn) {
    btn.onclick = function(e) {
      e.preventDefault();
      importSecretUnified();
    };
  }
  var paste = document.querySelector('#screen-import .imp-paste');
  if (paste) {
    paste.onclick = function(e) {
      e.preventDefault();
      pasteImportSecret();
    };
  }
  var mpc = document.querySelector('#screen-import .ob-option');
  // wire all options by text
  document.querySelectorAll('#screen-import .ob-option').forEach(function(opt) {
    var label = (opt.textContent || '').toLowerCase();
    if (label.indexOf('tanpa kunci') >= 0 || label.indexOf('mpc') >= 0) {
      opt.onclick = function(e) { e.preventDefault(); openKeylessImport(); };
    } else if (label.indexOf('hardware') >= 0 || label.indexOf('ledger') >= 0) {
      opt.onclick = function(e) { e.preventDefault(); goHardwareFromImport(); };
    }
  });
  var back = document.querySelector('#screen-import .imp-back');
  if (back) {
    back.onclick = function(e) {
      e.preventDefault();
      showScreen('onboard');
    };
  }
}

// Wire on load if already on import
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function() {
    setTimeout(wireImportButtons, 200);
  });
} else {
  setTimeout(wireImportButtons, 200);
}

window.importSecretUnified = importSecretUnified;
window.openKeylessImport = openKeylessImport;
window.goHardwareFromImport = goHardwareFromImport;
window.dismissAllOverlays = dismissAllOverlays;
window.wireImportButtons = wireImportButtons;

