/* ===== Robust Tempel (clipboard + fallback) ===== */
function applyPasteFallback() {
  var a = document.getElementById('pasteFallbackArea');
  var el = document.getElementById('importPhrase');
  var text = (a && a.value ? a.value : '').trim();
  if (!text) {
    showToast('Belum ada teks');
    return;
  }
  if (el) {
    el.value = text;
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }
  closeModal();
  showToast('Ditempel');
  try { bindSeedLiveValidation(); } catch (e) {}
}

