/* ============================================================
   Clipboard alternatives + permission debug (browser / mobile)
   ============================================================ */

var ClipboardKit = (function() {
  var lastError = null;
  var lastMethod = null;

  function isSecure() {
    try {
      if (typeof window.isSecureContext === 'boolean') return window.isSecureContext;
      return location.protocol === 'https:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1';
    } catch (e) {
      return false;
    }
  }

  function isMobile() {
    return /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || '');
  }

  async function queryPermission() {
    var result = { name: 'clipboard-read', state: 'unknown', supported: false };
    try {
      if (navigator.permissions && navigator.permissions.query) {
        result.supported = true;
        // Some browsers throw for clipboard-read
        var st = await navigator.permissions.query({ name: 'clipboard-read' });
        result.state = st.state; // granted | denied | prompt
        result.onchange = true;
      }
    } catch (e) {
      result.error = (e && e.message) || String(e);
      // Firefox / Safari often don't support this permission name
      result.state = 'unsupported-query';
    }
    return result;
  }

  async function diagnostics() {
    var perm = await queryPermission();
    return {
      secureContext: isSecure(),
      protocol: location.protocol,
      host: location.host,
      mobile: isMobile(),
      userAgent: (navigator.userAgent || '').slice(0, 120),
      hasClipboardAPI: !!(navigator.clipboard && navigator.clipboard.readText),
      hasWriteAPI: !!(navigator.clipboard && navigator.clipboard.writeText),
      hasPermissionsAPI: !!(navigator.permissions && navigator.permissions.query),
      permission: perm,
      lastError: lastError,
      lastMethod: lastMethod
    };
  }

  /** Read text using multiple strategies */
  async function readText() {
    lastError = null;
    lastMethod = null;

    // A) Async Clipboard API
    if (navigator.clipboard && typeof navigator.clipboard.readText === 'function') {
      try {
        var t = await navigator.clipboard.readText();
        lastMethod = 'clipboard.readText';
        return String(t || '');
      } catch (e) {
        lastError = 'readText: ' + ((e && e.message) || e);
      }
    }

    // B) clipboard.read() with ClipboardItem
    if (navigator.clipboard && typeof navigator.clipboard.read === 'function') {
      try {
        var items = await navigator.clipboard.read();
        for (var i = 0; i < items.length; i++) {
          var item = items[i];
          if (item.types && item.types.indexOf('text/plain') >= 0) {
            var blob = await item.getType('text/plain');
            var text = await blob.text();
            lastMethod = 'clipboard.read/ClipboardItem';
            return String(text || '');
          }
        }
      } catch (e) {
        lastError = (lastError ? lastError + ' | ' : '') + 'read: ' + ((e && e.message) || e);
      }
    }

    // C) Legacy execCommand('paste') — rare, needs editable focus
    try {
      var ta = document.createElement('textarea');
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;z-index:99999';
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      var ok = document.execCommand('paste');
      var val = ta.value;
      document.body.removeChild(ta);
      if (ok && val) {
        lastMethod = 'execCommand(paste)';
        return val;
      }
    } catch (e) {
      lastError = (lastError ? lastError + ' | ' : '') + 'execCommand: ' + ((e && e.message) || e);
    }

    // D) Failed — caller should show manual UI
    lastMethod = null;
    throw new Error(lastError || 'Clipboard tidak dapat dibaca');
  }

  /** Write text with fallbacks */
  async function writeText(text) {
    lastError = null;
    lastMethod = null;
    text = String(text == null ? '' : text);

    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      try {
        await navigator.clipboard.writeText(text);
        lastMethod = 'clipboard.writeText';
        return true;
      } catch (e) {
        lastError = 'writeText: ' + ((e && e.message) || e);
      }
    }

    try {
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;left:-9999px;top:0';
      document.body.appendChild(ta);
      ta.select();
      ta.setSelectionRange(0, text.length);
      var ok = document.execCommand('copy');
      document.body.removeChild(ta);
      if (ok) {
        lastMethod = 'execCommand(copy)';
        return true;
      }
    } catch (e) {
      lastError = (lastError ? lastError + ' | ' : '') + 'copy: ' + ((e && e.message) || e);
    }

    throw new Error(lastError || 'Clipboard tidak dapat ditulis');
  }

  /** Paste into a target input/textarea with full fallback UI */
  async function pasteInto(selectorOrEl, opts) {
    opts = opts || {};
    var el = typeof selectorOrEl === 'string'
      ? document.querySelector(selectorOrEl)
      : selectorOrEl;
    if (!el) throw new Error('Target element tidak ditemukan');

    try {
      var text = await readText();
      if (text && String(text).trim()) {
        el.value = String(text).trim();
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        if (opts.onSuccess) opts.onSuccess(text);
        return text;
      }
    } catch (e) {
      // continue to manual
    }

    if (opts.silent) throw new Error(lastError || 'Paste gagal');

    // Manual fallback sheet
    return new Promise(function(resolve, reject) {
      openModal(
        '<div class="modal-handle"></div>' +
        '<h3>Tempel manual</h3>' +
        '<p class="hint" id="clipDebugHint">Clipboard otomatis diblokir. Tempel di bawah (Ctrl+V / tahan lama).</p>' +
        '<div class="field"><textarea id="clipManualArea" placeholder="Tempel di sini…" style="min-height:120px" autocomplete="off" spellcheck="false"></textarea></div>' +
        '<button type="button" class="btn btn-primary" style="max-width:none" id="clipManualApply">Gunakan teks ini</button>' +
        '<button type="button" class="btn btn-ghost" style="max-width:none;margin-top:8px" id="clipManualDebug">Debug izin clipboard</button>' +
        '<button type="button" class="btn btn-ghost" style="max-width:none;margin-top:6px" onclick="closeModal()">Batal</button>'
      );

      setTimeout(async function() {
        var area = document.getElementById('clipManualArea');
        var apply = document.getElementById('clipManualApply');
        var dbg = document.getElementById('clipManualDebug');
        if (area) {
          area.focus();
          // Mobile: try paste event capture
          area.addEventListener('paste', function(ev) {
            try {
              var cd = ev.clipboardData || window.clipboardData;
              if (cd) {
                var t = cd.getData('text/plain') || cd.getData('text');
                if (t) {
                  // let default paste happen
                  setTimeout(function() {
                    if (!area.value) area.value = t;
                  }, 0);
                }
              }
            } catch (err) {}
          });
        }
        if (apply) {
          apply.onclick = function() {
            var t = (area && area.value || '').trim();
            if (!t) {
              showToast('Belum ada teks');
              return;
            }
            el.value = t;
            el.dispatchEvent(new Event('input', { bubbles: true }));
            closeModal();
            lastMethod = 'manual-modal';
            if (opts.onSuccess) opts.onSuccess(t);
            resolve(t);
          };
        }
        if (dbg) {
          dbg.onclick = function() { showClipboardDebug(); };
        }
        // Show short reason
        var hint = document.getElementById('clipDebugHint');
        if (hint) {
          var d = await diagnostics();
          var reason = !d.secureContext
            ? 'Halaman tidak secure context (perlu HTTPS/localhost).'
            : (d.permission && d.permission.state === 'denied')
              ? 'Izin clipboard ditolak browser.'
              : 'Browser/WebView memblokir baca clipboard.';
          hint.textContent = reason + ' Tempel manual di bawah.';
        }
      }, 150);
    });
  }

  async function showClipboardDebug() {
    var d = await diagnostics();
    var lines = [
      'Secure context: ' + d.secureContext,
      'Protocol: ' + d.protocol,
      'Host: ' + d.host,
      'Mobile: ' + d.mobile,
      'clipboard.readText: ' + d.hasClipboardAPI,
      'clipboard.writeText: ' + d.hasWriteAPI,
      'permissions API: ' + d.hasPermissionsAPI,
      'Permission state: ' + (d.permission && d.permission.state),
      'Last method: ' + (d.lastMethod || '—'),
      'Last error: ' + (d.lastError || '—'),
      'UA: ' + d.userAgent
    ];
    openModal(
      '<div class="modal-handle"></div><h3>Debug Clipboard</h3>' +
      '<pre style="text-align:left;font-size:.72rem;white-space:pre-wrap;background:rgba(0,0,0,.25);padding:12px;border-radius:10px;max-height:50vh;overflow:auto">' +
      lines.map(function(l) { return l.replace(/</g, '&lt;'); }).join('\n') +
      '</pre>' +
      '<button class="btn btn-primary" style="max-width:none" onclick="ClipboardKit.copyDebug()">Salin laporan</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="closeModal()">Tutup</button>'
    );
  }

  async function copyDebug() {
    var d = await diagnostics();
    try {
      await writeText(JSON.stringify(d, null, 2));
      showToast('Laporan disalin');
    } catch (e) {
      showToast('Gagal salin laporan');
    }
  }

  return {
    isSecure: isSecure,
    isMobile: isMobile,
    queryPermission: queryPermission,
    diagnostics: diagnostics,
    readText: readText,
    writeText: writeText,
    pasteInto: pasteInto,
    showClipboardDebug: showClipboardDebug,
    copyDebug: copyDebug,
    getLastError: function() { return lastError; },
    getLastMethod: function() { return lastMethod; }
  };
})();

// Override pasteImportSecret to use ClipboardKit
// Safer copy helpers used across app
