/* ============================================================
   Manual paste fallback (hardened) + Web clipboard security
   ============================================================ */

var SecureClipboard = (function() {
  var SENSITIVE_HINT = /seed|phrase|mnemonic|private|secret|key|recovery|pin/i;
  var _autoClearTimer = null;

  function looksSensitive(text) {
    if (!text) return false;
    var t = String(text).trim();
    // private key
    if (/^(0x)?[0-9a-fA-F]{64}$/.test(t.replace(/\s+/g, ''))) return true;
    // seed-like: 12+ words
    var words = t.toLowerCase().split(/\s+/).filter(Boolean);
    if (words.length >= 12 && words.length <= 24 && words.every(function(w) { return /^[a-z]+$/.test(w); })) return true;
    return false;
  }

  /** Manual paste UI — always available, no clipboard permission needed */
  function openManualPaste(options) {
    options = options || {};
    var title = options.title || 'Tempel manual';
    var hint = options.hint || 'Tempel teks di bawah (Ctrl+V / Cmd+V / tahan lama di mobile).';
    var sensitive = options.sensitive !== false;

    return new Promise(function(resolve, reject) {
      openModal(
        '<div class="modal-handle"></div>' +
        '<h3>' + title + '</h3>' +
        '<p class="hint">' + hint + '</p>' +
        (sensitive
          ? '<div class="sec-card sec-warn" style="margin-bottom:10px"><p class="sec-desc" style="margin:0">Jangan tempel seed/private key di aplikasi chat atau catatan cloud. Field ini hanya di perangkatmu.</p></div>'
          : '') +
        '<div class="field" style="position:relative">' +
          '<textarea id="secClipManual" class="sec-clip-area" placeholder="Tempel di sini…" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-form-type="other"></textarea>' +
        '</div>' +
        '<label class="sec-check-row" style="display:flex;align-items:center;gap:8px;margin:10px 0;font-size:.8rem;color:var(--muted)">' +
          '<input type="checkbox" id="secClipClear" ' + (sensitive ? 'checked' : '') + '> Hapus teks dari field setelah dipakai' +
        '</label>' +
        '<button type="button" class="btn btn-primary" style="max-width:none" id="secClipApply">Gunakan</button>' +
        '<button type="button" class="btn btn-ghost" style="max-width:none;margin-top:8px" id="secClipCancel">Batal</button>'
      );

      setTimeout(function() {
        var area = document.getElementById('secClipManual');
        var apply = document.getElementById('secClipApply');
        var cancel = document.getElementById('secClipCancel');
        if (!area || !apply) {
          reject(new Error('UI tempel gagal'));
          return;
        }
        area.focus();

        // Capture paste event (works on mobile without clipboard permission)
        area.addEventListener('paste', function(ev) {
          try {
            var cd = ev.clipboardData || window.clipboardData;
            if (!cd) return;
            var t = cd.getData('text/plain') || cd.getData('text') || '';
            if (t && looksSensitive(t)) {
              // Soft warning only — still allow paste
              console.info('[SecureClipboard] sensitive content pasted into manual field');
            }
          } catch (err) {}
        });

        function finish(ok) {
          var val = (area.value || '').trim();
          var clear = !!(document.getElementById('secClipClear') || {}).checked;
          if (!ok) {
            if (clear) area.value = '';
            closeModal();
            reject(new Error('Dibatalkan'));
            return;
          }
          if (!val) {
            showToast('Belum ada teks');
            return;
          }
          var out = val;
          if (clear) area.value = '';
          closeModal();
          resolve(out);
        }

        apply.onclick = function() { finish(true); };
        cancel.onclick = function() { finish(false); };
      }, 120);
    });
  }

  /**
   * Paste into target with: API → paste event → manual fallback
   * Security: never logs secret values; optional field auto-clear
   */
  async function securePasteInto(target, opts) {
    opts = opts || {};
    var el = typeof target === 'string' ? document.querySelector(target) : target;
    if (!el) throw new Error('Target tidak ditemukan');

    var text = null;

    // Try ClipboardKit / API first (user gesture required)
    if (typeof ClipboardKit !== 'undefined') {
      try {
        text = await ClipboardKit.readText();
        if (text && String(text).trim()) {
          text = String(text).trim();
        } else {
          text = null;
        }
      } catch (e) {
        text = null;
      }
    }

    // Manual fallback
    if (!text) {
      text = await openManualPaste({
        title: opts.title || 'Tempel seed / kunci',
        hint: opts.hint || 'Clipboard otomatis tidak tersedia. Tempel manual di bawah.',
        sensitive: opts.sensitive !== false
      });
    }

    el.value = text;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));

    // Auto-clear target after delay (reduces shoulder-surfing / residual UI)
    if (opts.autoClearMs && opts.autoClearMs > 0) {
      scheduleFieldClear(el, opts.autoClearMs);
    }

    // Best-effort: clear OS clipboard after reading sensitive data (often blocked)
    if (opts.clearOsClipboard && looksSensitive(text)) {
      tryClearOsClipboard();
    }

    return text;
  }

  function scheduleFieldClear(el, ms) {
    if (_autoClearTimer) clearTimeout(_autoClearTimer);
    _autoClearTimer = setTimeout(function() {
      try {
        if (el && document.body.contains(el)) {
          // Only clear if user navigated away from import or finished
          // Soft: don't clear while still on import screen focused
          if (document.activeElement !== el) {
            el.value = '';
          }
        }
      } catch (e) {}
    }, ms);
  }

  async function tryClearOsClipboard() {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText('');
        return true;
      }
    } catch (e) {
      // Expected on most browsers — no permission to clear
    }
    return false;
  }

  /** Copy with security note for sensitive payloads */
  async function secureCopy(text, opts) {
    opts = opts || {};
    text = String(text == null ? '' : text);
    var sensitive = opts.sensitive != null ? opts.sensitive : looksSensitive(text);

    if (typeof ClipboardKit !== 'undefined') {
      try {
        await ClipboardKit.writeText(text);
        showToast(opts.okMsg || (sensitive ? 'Disalin — hapus clipboard setelah dipakai' : 'Disalin'));
        if (sensitive && opts.warn !== false) {
          setTimeout(function() {
            showToast('Jangan bagikan clipboard dengan aplikasi lain');
          }, 1600);
        }
        return true;
      } catch (e) {}
    }

    // Fallback: show selectable modal (no silent failure of secrets)
    openModal(
      '<div class="modal-handle"></div><h3>Salin manual</h3>' +
      '<p class="hint">Clipboard diblokir. Pilih teks lalu salin.</p>' +
      '<div class="field"><textarea id="secCopyOut" readonly style="min-height:100px">' +
      text.replace(/</g, '&lt;') +
      '</textarea></div>' +
      '<button class="btn btn-primary" style="max-width:none" onclick="var e=document.getElementById(\'secCopyOut\');e.select();document.execCommand(\'copy\');showToast(\'Disalin\');closeModal()">Pilih & salin</button>' +
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="closeModal()">Tutup</button>'
    );
    return false;
  }

  /** Security checklist for UI */
  function securityTipsHtml() {
    return (
      '<ul class="sec-tips-list">' +
      '<li>Gunakan HTTPS — clipboard API tidak aman di <code>file://</code></li>' +
      '<li>Jangan tempel seed di chat, email, atau password manager berbagi</li>' +
      '<li>Tutup tab wallet setelah selesai di perangkat bersama</li>' +
      '<li>Browser bisa menyimpan clipboard history — hapus setelah pakai</li>' +
      '<li>Mobile WebView sering memblokir baca clipboard (itu normal)</li>' +
      '</ul>'
    );
  }

  return {
    looksSensitive: looksSensitive,
    openManualPaste: openManualPaste,
    securePasteInto: securePasteInto,
    secureCopy: secureCopy,
    tryClearOsClipboard: tryClearOsClipboard,
    securityTipsHtml: securityTipsHtml
  };
})();

// Wire Tempel button → SecureClipboard
async function pasteImportSecret() {
  try {
    await SecureClipboard.securePasteInto('#importPhrase', {
      title: 'Tempel seed / private key',
      hint: 'Tempel di sini jika tombol otomatis diblokir browser.',
      sensitive: true,
      clearOsClipboard: false, // clearing often fails; avoid false sense of security
      autoClearMs: 0
    });
    showToast('Ditempel');
    try { bindSeedLiveValidation(); } catch (e) {}
  } catch (e) {
    if ((e && e.message) !== 'Dibatalkan') {
      showToast((e && e.message) || 'Tempel gagal');
    }
  }
}

window.SecureClipboard = SecureClipboard;
window.pasteImportSecret = pasteImportSecret;

// Optional: settings entry for clipboard security tips
