/* ===== Onboard fix: sheets + createWallet + dog slides ===== */
function closeObSheets() {
  ['createSheetBg', 'importSheetBg'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) {
      el.classList.remove('show');
      el.style.display = '';
    }
  });
}

function openCreateWalletSheet() {
  try {
    // Do NOT call dismissAllOverlays fully — only close other sheets
    var other = document.getElementById('importSheetBg');
    if (other) other.classList.remove('show');
    var el = document.getElementById('createSheetBg');
    if (!el) {
      showToast('Sheet buat dompet tidak ditemukan');
      return;
    }
    el.classList.add('show');
    el.style.display = 'flex';
    el.onclick = function(e) {
      if (e.target === el) closeObSheets();
    };
  } catch (e) {
    console.log(e);
    showToast('Gagal buka sheet');
  }
}

function openImportWalletSheet() {
  try {
    var other = document.getElementById('createSheetBg');
    if (other) other.classList.remove('show');
    var el = document.getElementById('importSheetBg');
    if (!el) {
      showToast('Sheet import tidak ditemukan');
      return;
    }
    el.classList.add('show');
    el.style.display = 'flex';
    el.onclick = function(e) {
      if (e.target === el) closeObSheets();
    };
  } catch (e) {
    showToast('Gagal buka sheet');
  }
}

function createWallet() {
  try {
    if (typeof closeObSheets === 'function') closeObSheets();
    if (typeof ethers === 'undefined' || !ethers.Wallet) {
      showToast('SDK belum siap', 'error');
      return;
    }
    var w = ethers.Wallet.createRandom();
    state.phrase = w.mnemonic.phrase;
    state.wallet = w;
    state.address = w.address;
    state.privateKey = w.privateKey;
    state._unlocked = true;
    try { localStorage.setItem('br_active_addr', w.address); } catch (e) {}
    // Persist after user confirms seed backup (nextConfirmStep → persistWallet).
    // Keep phrase/PK in memory until then for backup screen.
    if (typeof renderSeed === 'function') {
      renderSeed(state.phrase);
    } else {
      var grid = document.getElementById('seedGrid');
      if (grid) {
        grid.innerHTML = state.phrase.split(' ').map(function(word, i) {
          return '<div class="seed-word"><span>' + (i + 1) + '.</span>' + word + '</div>';
        }).join('');
      }
    }
    showScreen('seed');
    showToast('Wallet dibuat — backup seed!', 'success');
  } catch (e) {
    console.warn('createWallet', e);
    showToast('Gagal: ' + ((e && e.message) || 'unknown'), 'error');
  }
}
window.createWallet = createWallet;

function wireOnboardButtons() {
  var map = [
    ['btnCreateWallet', function() { openCreateWalletSheet(); }],
    ['btnHasWallet', function() { openImportWalletSheet(); }],
    ['btnCreateSeed', function() { createWallet(); }],
    ['btnCreateEmail', function() { if (typeof openEmailCreate === 'function') openEmailCreate(); else showToast('Email setup'); }],
    ['btnCreateGoogle', function() { showToast('Login Google segera hadir — pakai seed phrase'); }],
    ['btnImportSeed', function() { closeObSheets(); showScreen('import'); }],
    ['btnImportEmail', function() { if (typeof openEmailImport === 'function') openEmailImport(); else { closeObSheets(); showScreen('import'); } }],
    ['btnImportGoogle', function() { showToast('Login Google segera hadir'); }]
  ];
  map.forEach(function(pair) {
    var el = document.getElementById(pair[0]);
    if (el) {
      el.onclick = function(e) {
        e.preventDefault();
        e.stopPropagation();
        pair[1]();
      };
    }
  });
}

// Headline carousel
(function startObSlides() {
  var idx = 0;
  setInterval(function() {
    var slides = document.querySelectorAll('#obSlides .ob-slide');
    var dots = document.querySelectorAll('#obDots span');
    if (!slides.length) return;
    slides.forEach(function(s) { s.classList.remove('active'); });
    dots.forEach(function(d) { d.classList.remove('on'); });
    idx = (idx + 1) % slides.length;
    slides[idx].classList.add('active');
    if (dots[idx]) dots[idx].classList.add('on');
  }, 3200);
})();

// Prevent dismissAllOverlays from killing sheet right after open
var _dismissAllOverlays = typeof dismissAllOverlays === 'function' ? dismissAllOverlays : null;
window.dismissAllOverlays = function() {
  // Only close sheets if not just opened (guard flag)
  if (window._keepObSheet) return;
  if (_dismissAllOverlays) _dismissAllOverlays();
  else closeObSheets();
};

// Bind on load
function bootOnboardUI() {
  wireOnboardButtons();
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function() { setTimeout(bootOnboardUI, 50); });
} else {
  setTimeout(bootOnboardUI, 50);
}

window.openCreateWalletSheet = openCreateWalletSheet;
window.openImportWalletSheet = openImportWalletSheet;
window.createWallet = createWallet;
window.closeObSheets = closeObSheets;
window.wireOnboardButtons = wireOnboardButtons;

brLog('%cOnboard fixed: create wallet + running dog + slides', 'color:#00e6b8;font-weight:bold');

