/* ============================================================
   Per-wallet notifications v6.6.17
   br_notifs stored as { [addressLower]: [notif, ...] }
   ============================================================ */
(function PerWalletNotifs() {
  'use strict';

  function meKey() {
    return ((state && state.address) || '').toLowerCase();
  }

  function loadAll() {
    try {
      var raw = JSON.parse(localStorage.getItem('br_notifs') || 'null');
      // migrate legacy array → map under current address
      if (Array.isArray(raw)) {
        var map = {};
        var k = meKey() || '_legacy';
        map[k] = raw;
        localStorage.setItem('br_notifs', JSON.stringify(map));
        return map;
      }
      return raw && typeof raw === 'object' ? raw : {};
    } catch (e) {
      return {};
    }
  }

  function saveAll(map) {
    try { localStorage.setItem('br_notifs', JSON.stringify(map)); } catch (e) {}
  }

  window.getWalletNotifs = function () {
    var map = loadAll();
    var k = meKey();
    if (!k) return [];
    return Array.isArray(map[k]) ? map[k] : [];
  };

  window.pushWalletNotif = function (title, body, kind, extra) {
    var k = meKey();
    if (!k) return;
    var map = loadAll();
    var list = Array.isArray(map[k]) ? map[k] : [];
    var now = Date.now();
    // de-dupe same title+body within 60s
    if (list[0] && list[0].title === title && list[0].body === body && now - (list[0].time || 0) < 60000) {
      return;
    }
    var item = {
      id: 'n' + now,
      title: title || 'Notifikasi',
      body: body || '',
      kind: kind || 'info',
      time: now,
      read: false,
      address: k
    };
    if (extra && extra.hash) item.hash = extra.hash;
    list.unshift(item);
    map[k] = list.slice(0, 40);
    saveAll(map);
  };

  // Patch openProfileMenu notif fill to use getWalletNotifs
  var _opm = window.openProfileMenu;
  if (typeof _opm === 'function') {
    window.openProfileMenu = function () {
      var r = _opm.apply(this, arguments);
      try {
        var notifs = document.getElementById('profNotifs');
        if (!notifs) return r;
        var items = getWalletNotifs();
        var htmlN = '';
        if (items.length) {
          items.slice(0, 6).forEach(function (n) {
            var ico = n.kind === 'receive' ? '📥' : (n.kind === 'send' ? '📤' : '🔔');
            var tag = n.read ? '' : 'Baru';
            if (n.kind === 'receive') tag = tag || 'Masuk';
            if (n.kind === 'send') tag = tag || ((typeof I18N!=='undefined'&&I18N.t)?I18N.t('tx_send'):'Send');
            var when = '';
            try {
              when = n.time ? new Date(n.time).toLocaleString('id-ID', {
                day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit'
              }) : '';
            } catch (e) {}
            htmlN += '<div class="prof-notif"><span>' + ico + '</span><div class="t">' +
              (n.title || 'Notifikasi') + '<div class="d">' + (n.body || '') +
              (when ? ' · ' + when : '') + '</div></div><div class="d">' + tag + '</div></div>';
          });
        } else {
          htmlN =
            '<div class="prof-notif"><span>🔔</span><div class="t">Belum ada notifikasi' +
            '<div class="d">Aktivitas transfer akan muncul di sini</div></div><div class="d">—</div></div>';
        }
        notifs.innerHTML = htmlN;
      } catch (e) {}
      return r;
    };
  }

  // Patch openNotifications
  window.openNotifications = function () {
    var items = getWalletNotifs();
    var html = '<div class="modal-handle"></div><h3>Notifikasi</h3>';
    if (!items.length) {
      html += '<div class="prof-notif"><span>🔔</span><div class="t">Belum ada notifikasi transaksi' +
        '<div class="d">Kirim atau terima token di dompet ini</div></div></div>';
    } else {
      items.slice(0, 30).forEach(function (n) {
        var ico = n.kind === 'receive' ? '📥' : (n.kind === 'send' ? '📤' : '🔔');
        var when = '';
        try {
          when = n.time ? new Date(n.time).toLocaleString('id-ID', {
            day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit'
          }) : '';
        } catch (e) {}
        html += '<div class="prof-notif"><span>' + ico + '</span><div class="t">' +
          (n.title || 'Notifikasi') + '<div class="d">' + (n.body || '') +
          (when ? ' · ' + when : '') + '</div></div></div>';
      });
    }
    html += '<div class="toggle-row" style="margin-top:12px"><span>Notifikasi harga</span>' +
      '<label class="toggle"><input type="checkbox" id="notifPrice"><span class="slider"></span></label></div>';
    if (typeof openModal === 'function') openModal(html);
    // mark read for this wallet only
    try {
      var map = loadAll();
      var k = meKey();
      if (k && Array.isArray(map[k])) {
        map[k].forEach(function (n) { n.read = true; });
        saveAll(map);
      }
    } catch (e) {}
  };

  // recordLocalTx → only notify for CURRENT wallet (sender sees send)
  var prevRec = window.recordLocalTx;
  window.recordLocalTx = function (tx) {
    if (typeof prevRec === 'function') prevRec(tx);
    try {
      if (!tx || !meKey()) return;
      var sym = tx.symbol || 'TOKEN';
      var val = tx.value != null ? tx.value : '';
      var from = (tx.from || '').toLowerCase();
      var to = (tx.to || '').toLowerCase();
      var me = meKey();
      // Only push if this wallet is the actor
      if (from === me || tx.dir === 'out') {
        pushWalletNotif(
          'Transfer terkirim',
          val + ' ' + sym + ' → ' + ((tx.to || '').slice(0, 6) + '…' + (tx.to || '').slice(-4)),
          'send',
          { hash: tx.hash }
        );
      } else if (to === me || tx.dir === 'in') {
        pushWalletNotif(
          'Dana masuk',
          val + ' ' + sym + ' dari ' + ((tx.from || '').slice(0, 6) + '…' + (tx.from || '').slice(-4)),
          'receive',
          { hash: tx.hash }
        );
      }
    } catch (e) {}
  };

  // One-time clean: split legacy mixed list is already handled in loadAll migrate
  brLog('%cPer-wallet notifications v6.6.17', 'color:#00D4AA;font-weight:bold');
})();

/* ============================================================
   Stability: no random onboard + receive notif on correct wallet
   v6.6.18
   ============================================================ */
(function StabilityNotifFix() {
  'use strict';

  // Keep activity alive for BOTH auto-lock systems
  function bumpAll() {
    try { state._lastActive = Date.now(); } catch (e) {}
    try { if (typeof window._lastActivity !== 'undefined') window._lastActivity = Date.now(); } catch (e) {}
    try { if (typeof touchActivityV6 === 'function') touchActivityV6(); } catch (e) {}
  }
  ['click', 'touchstart', 'keydown', 'scroll', 'pointerdown'].forEach(function (ev) {
    document.addEventListener(ev, bumpAll, { passive: true });
  });
  // Prevent lock while transfer flow open
  var _origLock = window.lockWallet;
  window.lockWallet = function () {
    if (document.body && document.body.classList.contains('tf-open')) {
      bumpAll();
      return;
    }
    return _origLock.apply(this, arguments);
  };

  // Guard showScreen('onboard') if wallet data still exists & unlocked
  var _ss = window.showScreen;
  if (typeof _ss === 'function') {
    window.showScreen = function (name) {
      if (name === 'onboard') {
        try {
          var has = !!(localStorage.getItem(typeof STORAGE_KEY !== 'undefined' ? STORAGE_KEY : 'br_wallet') ||
            localStorage.getItem('br_wallets_v3'));
          if (has && state && state.address && state._unlocked !== false && state.wallet) {
            // Don't bounce to onboard while session valid
            return _ss.call(this, 'home');
          }
        } catch (e) {}
      }
      return _ss.apply(this, arguments);
    };
  }

  // On wallet switch: clear UI notifs and reload history for THAT address
  function afterSwitch() {
    try {
      if (typeof loadHistoryEnhanced === 'function') {
        loadHistoryEnhanced(true).then(function () {
          // notifyNewIncoming will seed per-wallet notifs
        }).catch(function () {});
      }
      if (typeof refreshBalances === 'function') refreshBalances(true);
    } catch (e) {}
  }

  // Hook common switch entry points
  ['switchToWallet', 'selectWallet', 'activateWallet', 'setActiveWallet'].forEach(function (fn) {
    if (typeof window[fn] === 'function') {
      var prev = window[fn];
      window[fn] = function () {
        var r = prev.apply(this, arguments);
        setTimeout(afterSwitch, 300);
        return r;
      };
    }
  });

  // Default auto-lock to 15 min if still aggressive 5
  try {
    var al = parseInt(localStorage.getItem('br_auto_lock_min') || localStorage.getItem('br_autolock') || '5', 10);
    if (al > 0 && al < 10) {
      localStorage.setItem('br_auto_lock_min', '15');
      localStorage.setItem('br_autolock', '15');
      if (state) state.autoLockMin = 15;
    }
  } catch (e) {}

  brLog('%cStability + per-wallet notif guard v6.6.18', 'color:#00D4AA;font-weight:bold');
})();

