/* ============================================================
   Trust Wallet Assets API + image perf + SVG fallbacks
   v6.6.26
   ============================================================ */
(function TrustWalletIcons() {
  'use strict';

  // jsDelivr is faster/more cacheable than raw.githubusercontent.com
  var TW_CDN = 'https://cdn.jsdelivr.net/gh/trustwallet/assets@master/blockchains/';
  var TW_RAW = 'https://raw.githubusercontent.com/trustwallet/assets/master/blockchains/';

  var CHAIN_DIR = {
    ethereum: 'ethereum', eth: 'ethereum',
    base: 'base',
    bsc: 'smartchain', bnb: 'smartchain', smartchain: 'smartchain',
    polygon: 'polygon', matic: 'polygon',
    arbitrum: 'arbitrum', arb: 'arbitrum',
    optimism: 'optimism', op: 'optimism',
    avalanche: 'avalanchec', avax: 'avalanchec',
    solana: 'solana', sol: 'solana',
    tron: 'tron', trx: 'tron',
    bitcoin: 'bitcoin', btc: 'bitcoin'
  };

  // EIP-55-ish checksum (best effort without full keccak if ethers available)
  function checksumAddress(addr) {
    if (!addr || typeof addr !== 'string') return addr;
    try {
      if (typeof ethers !== 'undefined' && ethers.getAddress) return ethers.getAddress(addr);
    } catch (e) {}
    return addr;
  }

  function chainLogo(chain, useRaw) {
    var dir = CHAIN_DIR[(chain || 'ethereum').toLowerCase()] || 'ethereum';
    var base = useRaw ? TW_RAW : TW_CDN;
    return base + dir + '/info/logo.png';
  }

  function tokenLogo(chain, address, useRaw) {
    var dir = CHAIN_DIR[(chain || 'ethereum').toLowerCase()] || 'ethereum';
    var addr = checksumAddress(address);
    var base = useRaw ? TW_RAW : TW_CDN;
    return base + dir + '/assets/' + addr + '/logo.png';
  }

  // Known DApp → token/chain mapping for Trust Wallet assets
  var DAPP_TW = {
    uni: { chain: 'ethereum', address: '0x1f9840a85d5aF5bf1D1762F925BDADdC4201F984' },
    aave: { chain: 'ethereum', address: '0x7Fc66500c84A76Ad7e9c93437bFc5Ac33E2DDaE9' },
    curve: { chain: 'ethereum', address: '0xD533a949740bb3306d119CC777fa900bA034cd52' },
    sushi: { chain: 'ethereum', address: '0x6B3595068778DD592e39A122f4f5a5cF09C90fE2' },
    stargate: { chain: 'ethereum', address: '0xAf5191B0De278C7286d6C7CC6ab6BB8A73bA2Cd6' },
    aero: { chain: 'base', address: '0x940181a94A35A4569E4529A3CDfB74e38FD98631' },
    pancake: { chain: 'smartchain', address: '0x0E09FaBB73Bd3Ade0a17ECC321fD13a19e81cE82' },
    basebridge: { chain: 'base' },
    baserocky: { chain: 'base' }
  };

  var DAPP_CHAIN_BADGE = {
    uni: 'ethereum', pancake: 'bsc', hyper: 'ethereum', aero: 'base',
    curve: 'ethereum', aave: 'ethereum', lido: 'ethereum', jumper: 'base',
    stargate: 'ethereum', opensea: 'ethereum', basebridge: 'base',
    sushi: 'ethereum', baserocky: 'base'
  };

  // ---- SVG fallbacks (inline, zero network) ----
  function svgIcon(opts) {
    opts = opts || {};
    var size = opts.size || 80;
    var bg = opts.bg || '#2A2D3A';
    var fg = opts.fg || '#fff';
    var label = (opts.label || '?').slice(0, 2);
    var rx = Math.round(size * (opts.round || 0.22));
    return 'data:image/svg+xml,' + encodeURIComponent(
      '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '">' +
      '<rect width="' + size + '" height="' + size + '" rx="' + rx + '" fill="' + bg + '"/>' +
      '<text x="50%" y="52%" dominant-baseline="middle" text-anchor="middle" ' +
      'font-family="system-ui,-apple-system,sans-serif" font-weight="700" font-size="' +
      Math.round(size * 0.36) + '" fill="' + fg + '">' + label + '</text></svg>'
    );
  }

  function chainSvg(chain) {
    var map = {
      ethereum: { bg: '#627EEA', label: 'ETH' },
      base: { bg: '#0052FF', label: 'BASE' },
      bsc: { bg: '#F0B90B', label: 'BNB' },
      polygon: { bg: '#8247E5', label: 'POL' },
      arbitrum: { bg: '#28A0F0', label: 'ARB' },
      optimism: { bg: '#FF0420', label: 'OP' },
      solana: { bg: '#9945FF', label: 'SOL' }
    };
    var m = map[(chain || '').toLowerCase()] || { bg: '#444', label: (chain || '?').slice(0, 3).toUpperCase() };
    return svgIcon({ size: 64, bg: m.bg, label: m.label, round: 0.5 });
  }

  function dappSvg(name) {
    var colors = ['#627EEA', '#FF007A', '#27AE60', '#F0B90B', '#2E7CF6', '#E84142', '#00D4AA', '#8B5CF6'];
    var n = name || 'DApp';
    var code = 0;
    for (var i = 0; i < n.length; i++) code += n.charCodeAt(i);
    return svgIcon({
      size: 80,
      bg: colors[code % colors.length],
      label: n.slice(0, 2).toUpperCase(),
      round: 0.22
    });
  }

  // ---- Image cache + preload ----
  var _ok = {};
  var _fail = {};
  var _inflight = {};

  function probe(url) {
    if (!url) return Promise.resolve(false);
    if (_ok[url]) return Promise.resolve(true);
    if (_fail[url]) return Promise.resolve(false);
    if (_inflight[url]) return _inflight[url];
    _inflight[url] = new Promise(function (resolve) {
      var img = new Image();
      var done = false;
      var t = setTimeout(function () {
        if (done) return;
        done = true;
        _fail[url] = 1;
        resolve(false);
      }, 4000);
      img.onload = function () {
        if (done) return;
        done = true;
        clearTimeout(t);
        _ok[url] = 1;
        resolve(true);
      };
      img.onerror = function () {
        if (done) return;
        done = true;
        clearTimeout(t);
        _fail[url] = 1;
        resolve(false);
      };
      img.decoding = 'async';
      img.src = url;
    });
    return _inflight[url];
  }

  async function resolveDappIcon(id, name) {
    if (id === 'baserocky' && typeof LOGO !== 'undefined' && LOGO) return LOGO;
    var meta = DAPP_TW[id];
    if (meta) {
      if (meta.address) {
        var u1 = tokenLogo(meta.chain, meta.address, false);
        if (await probe(u1)) return u1;
        var u2 = tokenLogo(meta.chain, meta.address, true);
        if (await probe(u2)) return u2;
      } else {
        var c1 = chainLogo(meta.chain, false);
        if (await probe(c1)) return c1;
        var c2 = chainLogo(meta.chain, true);
        if (await probe(c2)) return c2;
      }
    }
    // CoinGecko-ish leftovers from previous map
    if (typeof Web3Icon !== 'undefined' && Web3Icon.dapp) {
      var prev = Web3Icon.dapp(id, name);
      if (prev && prev.indexOf('data:') !== 0 && await probe(prev)) return prev;
    }
    return dappSvg(name || id);
  }

  function resolveChainIconSync(chain) {
    // Prefer CDN URL; onerror in img will swap to SVG
    return chainLogo(chain, false);
  }

  window.TrustWalletAssets = {
    chainLogo: chainLogo,
    tokenLogo: tokenLogo,
    probe: probe,
    svgIcon: svgIcon,
    chainSvg: chainSvg,
    dappSvg: dappSvg,
    resolveDappIcon: resolveDappIcon
  };

  // Enhance Web3Icon if present
  window.Web3Icon = window.Web3Icon || {};
  Web3Icon.chain = function (id) { return resolveChainIconSync(id); };
  Web3Icon.token = function (sym, chain, address) {
    if (address) return tokenLogo(chain || 'ethereum', address, false);
    return null;
  };
  Web3Icon.avatar = dappSvg;
  Web3Icon.dapp = function (id, name) {
    if (id === 'baserocky' && typeof LOGO !== 'undefined' && LOGO) return LOGO;
    var meta = DAPP_TW[id];
    if (meta && meta.address) return tokenLogo(meta.chain, meta.address, false);
    if (meta) return chainLogo(meta.chain, false);
    return dappSvg(name || id);
  };

  // Optimized img tag with multi-fallback
  function iconImg(src, fallbackSvg, cls, size) {
    size = size || 40;
    var fb = fallbackSvg.replace(/'/g, "\\'");
    return (
      '<img class="' + (cls || '') + '" width="' + size + '" height="' + size + '" ' +
      'loading="lazy" decoding="async" referrerpolicy="no-referrer" src="' + src + '" ' +
      'onerror="this.onerror=null;this.src=\'' + fb + '\'">'
    );
  }

  window.renderDiscover = function () {
    var q = ((document.getElementById('dappSearch') || {}).value || '').toLowerCase();
    var tab = state.discTab || 'populer';
    var list = (typeof DAPPS !== 'undefined' ? DAPPS : []).filter(function (d) {
      if (tab === 'mine') return (state.myDapps || []).indexOf(d.id) >= 0;
      if (tab !== 'populer' && (d.cat || []).indexOf(tab) < 0) return false;
      if (q && (d.name + ' ' + d.desc + ' ' + d.url).toLowerCase().indexOf(q) < 0) return false;
      return true;
    });
    var box = document.getElementById('dappList');
    if (!box) return;
    if (!list.length) {
      box.innerHTML = '<div class="empty" style="padding:24px;text-align:center;color:var(--muted)">Tidak ada DApp</div>';
      return;
    }

    var html = '<div class="dapp-sec-head"><span>DEX Teratas</span><span class="dapp-sec-more">›</span></div>';
    html += list.map(function (d) {
      var chain = DAPP_CHAIN_BADGE[d.id] || d.chain || 'ethereum';
      var iconSrc = Web3Icon.dapp(d.id, d.name);
      var chainSrc = chainLogo(chain, false);
      var fbApp = dappSvg(d.name);
      var fbChain = chainSvg(chain);
      return (
        '<div class="dapp-row bg-dapp-row" data-url="' + d.url + '" data-id="' + d.id + '">' +
        '<div class="dapp-ico-wrap">' +
        iconImg(iconSrc, fbApp, 'dapp-ico', 40) +
        '</div>' +
        '<div class="info"><div class="n">' + d.name + '</div><div class="d">' + d.desc + '</div></div>' +
        '<div class="dapp-chain">' + iconImg(chainSrc, fbChain, '', 22) + '</div>' +
        '</div>'
      );
    }).join('');
    box.innerHTML = html;

    // Background resolve better icons (swap if CDN ok / better source)
    list.forEach(function (d) {
      resolveDappIcon(d.id, d.name).then(function (url) {
        if (!url) return;
        var row = box.querySelector('.dapp-row[data-id="' + d.id + '"] .dapp-ico');
        if (row && row.src !== url && url.indexOf('data:') !== 0) {
          // only upgrade if current is also remote or failed
          row.src = url;
        }
      }).catch(function () {});
    });

    box.querySelectorAll('.dapp-row').forEach(function (el) {
      el.onclick = function () {
        var id = el.getAttribute('data-id');
        var url = el.getAttribute('data-url');
        state.myDapps = state.myDapps || [];
        if (state.myDapps.indexOf(id) < 0) {
          state.myDapps.unshift(id);
          state.myDapps = state.myDapps.slice(0, 20);
          localStorage.setItem('br_my_dapps', JSON.stringify(state.myDapps));
        }
        window.open(url, '_blank');
      };
    });

    document.querySelectorAll('#discTabs span').forEach(function (sp) {
      sp.classList.toggle('on', sp.getAttribute('data-tab') === tab);
      sp.onclick = function () {
        state.discTab = sp.getAttribute('data-tab');
        renderDiscover();
      };
    });
  };

  // Prefetch popular chain logos
  ['ethereum', 'base', 'bsc', 'polygon'].forEach(function (c) {
    probe(chainLogo(c, false));
  });

  setTimeout(function () {
    try { if (typeof renderDiscover === 'function') renderDiscover(); } catch (e) {}
  }, 250);

  brLog('%cTrustWalletAssets + SVG fallback + image cache v6.6.26', 'color:#00D4AA;font-weight:bold');
})();

