/* ============================================================
   QR Scanner (BarcodeDetector + getUserMedia)
   Fixes: bgTfScan + apScan "coming soon" stubs
   ============================================================ */
(function QRScannerKit() {
  'use strict';

  var _stream = null;
  var _raf = null;
  var _detector = null;
  var _active = false;
  var _onResult = null;

  function stopStream() {
    _active = false;
    if (_raf) {
      try { cancelAnimationFrame(_raf); } catch (e) {}
      _raf = null;
    }
    if (_stream) {
      try {
        _stream.getTracks().forEach(function (t) { t.stop(); });
      } catch (e) {}
      _stream = null;
    }
    _detector = null;
  }

  function closeScannerUI() {
    stopStream();
    var overlay = document.getElementById('brQrScanOverlay');
    if (overlay) {
      try { overlay.remove(); } catch (e) {}
    }
  }

  function extractAddress(raw) {
    if (!raw) return '';
    var s = String(raw).trim();
    // ethereum:0x... or bitcoin-style URI
    var m = s.match(/(?:ethereum:)?(0x[a-fA-F0-9]{40})/i);
    if (m) return m[1];
    // plain 0x address
    if (/^0x[a-fA-F0-9]{40}$/i.test(s)) return s;
    // ENS-like
    if (/\.(eth|base|crypto)$/i.test(s) && s.length < 80) return s;
    // fallback: whole payload if short enough
    if (s.length <= 120) return s;
    return '';
  }

  async function startCamera(videoEl) {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      throw new Error('Kamera tidak didukung di browser ini');
    }
    var constraints = {
      audio: false,
      video: {
        facingMode: { ideal: 'environment' },
        width: { ideal: 1280 },
        height: { ideal: 720 }
      }
    };
    try {
      _stream = await navigator.mediaDevices.getUserMedia(constraints);
    } catch (e1) {
      // fallback without facingMode
      _stream = await navigator.mediaDevices.getUserMedia({ audio: false, video: true });
    }
    videoEl.srcObject = _stream;
    videoEl.setAttribute('playsinline', 'true');
    videoEl.muted = true;
    await videoEl.play();
  }

  function createDetector() {
    if (typeof BarcodeDetector === 'undefined') return null;
    try {
      return new BarcodeDetector({ formats: ['qr_code'] });
    } catch (e) {
      try { return new BarcodeDetector(); } catch (e2) { return null; }
    }
  }

  function tick(videoEl, statusEl) {
    if (!_active || !videoEl) return;
    if (videoEl.readyState < 2) {
      _raf = requestAnimationFrame(function () { tick(videoEl, statusEl); });
      return;
    }
    if (_detector) {
      _detector.detect(videoEl).then(function (codes) {
        if (!_active) return;
        if (codes && codes.length) {
          var raw = codes[0].rawValue || codes[0].raw || '';
          var addr = extractAddress(raw) || raw;
          if (addr) {
            stopStream();
            closeScannerUI();
            if (typeof _onResult === 'function') {
              try { _onResult(addr, raw); } catch (e) {}
            }
            if (typeof showToast === 'function') showToast('QR terdeteksi', 'success');
            return;
          }
        }
        _raf = requestAnimationFrame(function () { tick(videoEl, statusEl); });
      }).catch(function () {
        if (_active) _raf = requestAnimationFrame(function () { tick(videoEl, statusEl); });
      });
    } else {
      // No BarcodeDetector — show manual fallback message once
      if (statusEl && !statusEl.dataset.warned) {
        statusEl.dataset.warned = '1';
        statusEl.textContent = 'Browser tidak mendukung deteksi QR otomatis. Gunakan Tempel atau browser Chrome/Edge terbaru.';
      }
    }
  }

  /**
   * Open scanner modal.
   * @param {function(string, string)} onResult  (parsedAddress, rawPayload)
   */
  window.openQrScanner = function (onResult) {
    closeScannerUI();
    _onResult = onResult || null;

    var overlay = document.createElement('div');
    overlay.id = 'brQrScanOverlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-label', 'Pindai QR');
    overlay.innerHTML =
      '<div class="br-qr-scan-backdrop"></div>' +
      '<div class="br-qr-scan-sheet">' +
        '<div class="br-qr-scan-handle"></div>' +
        '<div class="br-qr-scan-head">' +
          '<h3>Pindai QR Code</h3>' +
          '<button type="button" class="br-qr-scan-close" id="brQrScanClose" aria-label="Tutup">✕</button>' +
        '</div>' +
        '<div class="br-qr-scan-stage">' +
          '<video id="brQrScanVideo" playsinline muted></video>' +
          '<div class="br-qr-scan-frame"></div>' +
        '</div>' +
        '<p class="br-qr-scan-status" id="brQrScanStatus">Arahkan kamera ke QR code alamat wallet…</p>' +
        '<div class="br-qr-scan-actions">' +
          '<button type="button" class="btn btn-ghost" id="brQrScanPaste">Tempel dari clipboard</button>' +
        '</div>' +
      '</div>';

    // Minimal styles (scoped)
    if (!document.getElementById('brQrScanStyles')) {
      var st = document.createElement('style');
      st.id = 'brQrScanStyles';
      st.textContent =
        '#brQrScanOverlay{position:fixed;inset:0;z-index:99999;display:flex;align-items:flex-end;justify-content:center;font-family:inherit}' +
        '#brQrScanOverlay .br-qr-scan-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.72)}' +
        '#brQrScanOverlay .br-qr-scan-sheet{position:relative;width:100%;max-width:480px;background:#0b1220;border-radius:18px 18px 0 0;padding:12px 16px 28px;color:#e8eef8;box-shadow:0 -8px 40px rgba(0,0,0,.45)}' +
        '#brQrScanOverlay .br-qr-scan-handle{width:40px;height:4px;border-radius:2px;background:rgba(255,255,255,.2);margin:0 auto 10px}' +
        '#brQrScanOverlay .br-qr-scan-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}' +
        '#brQrScanOverlay .br-qr-scan-head h3{margin:0;font-size:17px;font-weight:700}' +
        '#brQrScanOverlay .br-qr-scan-close{background:rgba(255,255,255,.08);border:0;color:#fff;width:36px;height:36px;border-radius:50%;font-size:16px;cursor:pointer}' +
        '#brQrScanOverlay .br-qr-scan-stage{position:relative;border-radius:14px;overflow:hidden;background:#000;aspect-ratio:1;max-height:56vh}' +
        '#brQrScanOverlay video{width:100%;height:100%;object-fit:cover;display:block}' +
        '#brQrScanOverlay .br-qr-scan-frame{position:absolute;inset:14%;border:2px solid #00c9a0;border-radius:12px;box-shadow:0 0 0 9999px rgba(0,0,0,.35);pointer-events:none}' +
        '#brQrScanOverlay .br-qr-scan-status{margin:12px 0 8px;font-size:13px;color:rgba(255,255,255,.65);text-align:center;min-height:36px}' +
        '#brQrScanOverlay .br-qr-scan-actions{display:flex;gap:8px}' +
        '#brQrScanOverlay .br-qr-scan-actions .btn{flex:1;max-width:none}';
      document.head.appendChild(st);
    }

    document.body.appendChild(overlay);

    document.getElementById('brQrScanClose').onclick = closeScannerUI;
    overlay.querySelector('.br-qr-scan-backdrop').onclick = closeScannerUI;

    document.getElementById('brQrScanPaste').onclick = async function () {
      try {
        var t = await navigator.clipboard.readText();
        t = (t || '').trim().replace(/\s+/g, '');
        if (!t) {
          if (typeof showToast === 'function') showToast('Clipboard kosong', 'warn');
          return;
        }
        var addr = extractAddress(t) || t;
        closeScannerUI();
        if (typeof _onResult === 'function') _onResult(addr, t);
        if (typeof showToast === 'function') showToast('Ditempel', 'success');
      } catch (e) {
        if (typeof showToast === 'function') showToast('Tidak bisa akses clipboard', 'error');
      }
    };

    var video = document.getElementById('brQrScanVideo');
    var statusEl = document.getElementById('brQrScanStatus');
    _active = true;

    startCamera(video).then(function () {
      _detector = createDetector();
      if (!_detector && statusEl) {
        statusEl.textContent = 'Deteksi otomatis tidak tersedia. Gunakan Tempel, atau buka di Chrome/Edge Android.';
      } else if (statusEl) {
        statusEl.textContent = 'Arahkan kamera ke QR code alamat wallet…';
      }
      tick(video, statusEl);
    }).catch(function (err) {
      if (statusEl) {
        statusEl.textContent = 'Kamera ditolak / tidak tersedia. Izinkan akses kamera atau gunakan Tempel.';
      }
      if (typeof showToast === 'function') {
        showToast('Kamera tidak tersedia — gunakan Tempel', 'warn');
      }
      console.warn('[QRScanner]', err);
    });
  };

  // Wire transfer flow scan button
  window.bgTfScan = function () {
    window.openQrScanner(function (addr) {
      var inp = document.getElementById('bgTfToInput');
      if (inp) {
        inp.value = addr;
        try {
          inp.dispatchEvent(new Event('input', { bubbles: true }));
        } catch (e) {}
      }
      // Bitget transfer internal state
      try {
        if (typeof syncRecipientUI === 'function') syncRecipientUI();
      } catch (e) {}
    });
  };

  // Wire address picker scan
  function rewireApScan() {
    var scan = document.getElementById('apScan');
    if (scan) {
      scan.onclick = function () {
        window.openQrScanner(function (addr) {
          var inp = document.getElementById('apInput');
          if (inp) {
            inp.value = addr;
            try {
              if (typeof apSyncInputTools === 'function') apSyncInputTools();
            } catch (e) {}
          }
        });
      };
    }
  }

  // Override wireAddressPicker's scan binding when it runs, and also bind now
  var _origWire = window.wireAddressPicker;
  if (typeof _origWire === 'function') {
    window.wireAddressPicker = function () {
      var r = _origWire.apply(this, arguments);
      rewireApScan();
      return r;
    };
  }
  // Also try immediate bind (DOM may already exist)
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', rewireApScan);
  } else {
    setTimeout(rewireApScan, 300);
  }

  brLog('%cQR Scanner ready (BarcodeDetector)', 'color:#00e6b8;font-weight:bold');
})();

/* ============================================================
   Swap Aggregator — Odos (primary) + Uniswap V3 (fallback)
   Multi-DEX routing on Base / ETH / Arb / OP / Polygon
   ============================================================ */
(function SwapAggregator() {
  'use strict';

  /* ---- Fee / treasury (BaseRocky partner revenue) ---- */
  var BR_SWAP_FEE = {
    enabled: true,
    /* Wallet penerima fee */
    treasury: '0xd6192B52cFdFD3774027f88F2dd6a729800bB435',
    /* Fee % dari volume swap (0.5 = 0.5%). Saran: 0.3–0.5 */
    percent: 0.5,
    /* Odos V3 body params (jika API menerima tanpa portal) */
    odosReferralFee: 0.005, // 0.5% as decimal for Odos
    /* OpenOcean referrerFee is in percent units e.g. 0.5 = 0.5% */
    openOceanReferrerFee: 0.5,
    /* 1inch Classic Swap — fee max 3%. API key: set via setOneInchApiKey() atau localStorage br_1inch_api_key */
    oneInchFee: 0.5,
    oneInchApiKey: '' // diisi user; fallback baca localStorage
  };

  var ODOS_QUOTE = 'https://api.odos.xyz/sor/quote/v2';
  var ODOS_ASSEMBLE = 'https://api.odos.xyz/sor/assemble';
  var OO_BASE = 'https://open-api.openocean.finance/v4';
  var NATIVE = '0x0000000000000000000000000000000000000000';
  var SLIPPAGE_PCT = 0.5; // 0.5%
  var _aggQuote = null;
  var _aggTimer = null;
  var _aggInflight = 0;

  var CHAIN_MAP = {
    eth: 1, base: 8453, arb: 42161, op: 10, pol: 137, bnb: 56
  };

  var WETH = {
    1: '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2',
    8453: '0x4200000000000000000000000000000000000006',
    42161: '0x82aF49447D8a07e3bd95BD0d56f35241523fBab1',
    10: '0x4200000000000000000000000000000000000006',
    137: '0x0d500B1d8E8eF31E21C99d1Db9A6444d3ADf1270',
    56: '0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c'
  };

  function chainId() {
    if (typeof getChainIdNum === 'function') {
      try { return getChainIdNum(); } catch (e) {}
    }
    return CHAIN_MAP[state.network || 'base'] || 8453;
  }

  function tokenAddr(token, cid) {
    if (!token) return null;
    if (token.address) return ethers.getAddress(token.address);
    // native
    return NATIVE;
  }

  function decOf(token) {
    return token && token.decimals != null ? Number(token.decimals) : 18;
  }

  function toUnits(amount, decimals) {
    try {
      return ethers.parseUnits(String(amount), decimals);
    } catch (e) {
      return 0n;
    }
  }

  function fromUnits(amount, decimals) {
    try {
      return Number(ethers.formatUnits(amount, decimals));
    } catch (e) {
      return 0;
    }
  }

  function setRouteLabel(text, kind) {
    var el = document.getElementById('swapRouteLabel') ||
             document.getElementById('swapPoolFee') ||
             document.getElementById('swapRate');
    if (!el) return;
    if (el.id === 'swapRate' && kind === 'route') {
      // keep rate; put route in pool fee if present
      var feeEl = document.getElementById('swapPoolFee');
      if (feeEl) {
        feeEl.textContent = text;
        return;
      }
    }
    el.textContent = text;
  }

  function setQuoteUI(amountOutHuman, rateText, routeText) {
    var outEl = document.getElementById('swapAmtTo');
    if (outEl) outEl.value = amountOutHuman > 0 ? fmtAmt(amountOutHuman) : '';
    var prev = document.getElementById('swapAmtToPreview');
    if (prev) prev.textContent = amountOutHuman > 0 ? fmtAmt(amountOutHuman) : '—';
    var rateEl = document.getElementById('swapRate');
    if (rateEl && rateText) rateEl.textContent = rateText;
    var toUsd = document.getElementById('swapToUsd');
    if (toUsd && _aggQuote && _aggQuote.toToken) {
      var p = (state.prices && state.prices[_aggQuote.toToken.id]) || 0;
      toUsd.textContent = (amountOutHuman * p).toFixed(2);
    }
    if (routeText) setRouteLabel(routeText, 'route');
    try {
      if (typeof updateCta === 'function') updateCta();
    } catch (e) {}
  }

  /* ---------- Odos quote ---------- */
  async function quoteOdos(from, to, amountHuman, userAddr) {
    var cid = chainId();
    var decIn = decOf(from);
    var amountIn = toUnits(amountHuman, decIn);
    if (amountIn <= 0n) throw new Error('Jumlah tidak valid');

    var body = {
      chainId: cid,
      inputTokens: [{
        tokenAddress: tokenAddr(from, cid),
        amount: amountIn.toString()
      }],
      outputTokens: [{
        tokenAddress: tokenAddr(to, cid),
        proportion: 1
      }],
      slippageLimitPercent: SLIPPAGE_PCT,
      userAddr: userAddr || state.address || NATIVE,
      compact: true,
      disableRFQs: true
    };
    // Partner fee → treasury (Odos V3 style; ignored if API rejects)
    if (BR_SWAP_FEE.enabled && BR_SWAP_FEE.treasury) {
      try {
        body.referralFee = BR_SWAP_FEE.odosReferralFee;
        body.referralFeeRecipient = ethers.getAddress(BR_SWAP_FEE.treasury);
      } catch (eFee) {}
    }

    var res = await fetch(ODOS_QUOTE, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify(body)
    });
    if (!res.ok) {
      var errTxt = await res.text().catch(function () { return ''; });
      throw new Error('Odos quote ' + res.status + (errTxt ? ': ' + errTxt.slice(0, 80) : ''));
    }
    var data = await res.json();
    if (!data || !data.pathId) throw new Error('Odos: tidak ada rute');

    var outRaw = (data.outAmounts && data.outAmounts[0]) || '0';
    var outBn = BigInt(outRaw);
    var outHuman = fromUnits(outBn, decOf(to));
    var gasEst = data.gasEstimate || data.gasEstimateValue || null;

    return {
      source: 'odos',
      pathId: data.pathId,
      amountIn: amountIn,
      amountOut: outBn,
      amountOutHuman: outHuman,
      amountInHuman: Number(amountHuman),
      fromToken: from,
      toToken: to,
      gasEstimate: gasEst,
      priceImpact: data.priceImpact,
      percentDiff: data.percentDiff,
      raw: data,
      tokenIn: tokenAddr(from, cid),
      tokenOut: tokenAddr(to, cid)
    };
  }

  async function assembleOdos(pathId, userAddr) {
    var res = await fetch(ODOS_ASSEMBLE, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({
        userAddr: userAddr,
        pathId: pathId,
        simulate: false
      })
    });
    if (!res.ok) {
      var errTxt = await res.text().catch(function () { return ''; });
      throw new Error('Odos assemble ' + res.status + (errTxt ? ': ' + errTxt.slice(0, 100) : ''));
    }
    var data = await res.json();
    if (!data || !data.transaction) throw new Error('Odos: assemble gagal');
    return data;
  }



  /* ---------- 1inch Classic Swap v6.1 ---------- */
  var ONEINCH_NATIVE = '0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE';
  var ONEINCH_BASE = 'https://api.1inch.com/swap/v6.1';

  function getOneInchApiKey() {
    try {
      var k = (BR_SWAP_FEE.oneInchApiKey || '').trim();
      if (k) return k;
      k = (localStorage.getItem('br_1inch_api_key') || '').trim();
      return k || '';
    } catch (e) {
      return '';
    }
  }

  window.setOneInchApiKey = function (key) {
    key = String(key || '').trim();
    BR_SWAP_FEE.oneInchApiKey = key;
    try {
      if (key) localStorage.setItem('br_1inch_api_key', key);
      else localStorage.removeItem('br_1inch_api_key');
    } catch (e) {}
    if (typeof showToast === 'function') {
      showToast(key ? '1inch API key disimpan' : '1inch API key dihapus', 'success');
    }
    return !!key;
  };

  function inchToken(token) {
    if (!token || !token.address) return ONEINCH_NATIVE;
    return ethers.getAddress(token.address);
  }

  async function inchFetch(path, params) {
    var key = getOneInchApiKey();
    if (!key) throw new Error('1inch: set API key dulu (setOneInchApiKey)');
    var qs = new URLSearchParams(params).toString();
    var url = ONEINCH_BASE + path + (qs ? '?' + qs : '');
    var res = await fetch(url, {
      method: 'GET',
      headers: {
        Accept: 'application/json',
        Authorization: 'Bearer ' + key
      }
    });
    if (!res.ok) {
      var errTxt = await res.text().catch(function () { return ''; });
      var msg = '1inch ' + res.status;
      try {
        var ej = JSON.parse(errTxt);
        if (ej.description) msg += ': ' + ej.description;
        else if (ej.message) msg += ': ' + ej.message;
        else if (errTxt) msg += ': ' + errTxt.slice(0, 100);
      } catch (e) {
        if (errTxt) msg += ': ' + errTxt.slice(0, 100);
      }
      throw new Error(msg);
    }
    return res.json();
  }

  async function quote1inch(from, to, amountHuman, userAddr) {
    var cid = chainId();
    var amountIn = toUnits(amountHuman, decOf(from));
    if (amountIn <= 0n) throw new Error('Jumlah tidak valid');
    var addr = userAddr || state.address;
    if (!addr) throw new Error('Tidak ada alamat wallet');

    var params = {
      src: inchToken(from),
      dst: inchToken(to),
      amount: amountIn.toString(),
      from: addr,
      origin: addr,
      slippage: String(SLIPPAGE_PCT),
      disableEstimate: 'false',
      allowPartialFill: 'false'
    };
    if (BR_SWAP_FEE.enabled && BR_SWAP_FEE.treasury) {
      params.fee = String(BR_SWAP_FEE.oneInchFee);
      params.referrer = ethers.getAddress(BR_SWAP_FEE.treasury);
    }

    // Prefer /swap (quote + tx) so we can execute immediately
    var data;
    try {
      data = await inchFetch('/' + cid + '/swap', params);
    } catch (eSwap) {
      // fallback quote-only then will need second call at exec
      var q = await inchFetch('/' + cid + '/quote', {
        src: params.src,
        dst: params.dst,
        amount: params.amount,
        fee: params.fee,
        // quote may not need referrer on all versions
      });
      var outQ = q.dstAmount || q.toAmount || '0';
      return {
        source: '1inch',
        amountIn: amountIn,
        amountOut: BigInt(String(outQ)),
        amountOutHuman: fromUnits(BigInt(String(outQ)), decOf(to)),
        amountInHuman: Number(amountHuman),
        fromToken: from,
        toToken: to,
        tokenIn: params.src,
        tokenOut: params.dst,
        needsSwapCall: true,
        swapParams: params,
        feeTo: BR_SWAP_FEE.treasury,
        feePercent: BR_SWAP_FEE.oneInchFee,
        raw: q
      };
    }

    var outRaw = data.dstAmount || (data.toTokenAmount) || '0';
    var outBn = BigInt(String(outRaw));
    var tx = data.tx || {};
    if (!tx.to || !tx.data) throw new Error('1inch: calldata kosong');

    return {
      source: '1inch',
      amountIn: amountIn,
      amountOut: outBn,
      amountOutHuman: fromUnits(outBn, decOf(to)),
      amountInHuman: Number(amountHuman),
      fromToken: from,
      toToken: to,
      tokenIn: params.src,
      tokenOut: params.dst,
      tx: {
        to: tx.to,
        data: tx.data,
        value: tx.value != null ? String(tx.value) : '0',
        gas: tx.gas || tx.gasLimit || null
      },
      feeTo: BR_SWAP_FEE.treasury,
      feePercent: BR_SWAP_FEE.oneInchFee,
      raw: data
    };
  }

  async function execute1inchSwap(quote) {
    var q = quote;
    if (q.needsSwapCall && q.swapParams) {
      var data = await inchFetch('/' + chainId() + '/swap', q.swapParams);
      var outRaw = data.dstAmount || '0';
      q.amountOut = BigInt(String(outRaw));
      q.amountOutHuman = fromUnits(q.amountOut, decOf(q.toToken));
      var tx0 = data.tx || {};
      if (!tx0.to || !tx0.data) throw new Error('1inch: calldata kosong');
      q.tx = {
        to: tx0.to,
        data: tx0.data,
        value: tx0.value != null ? String(tx0.value) : '0',
        gas: tx0.gas || tx0.gasLimit || null
      };
    }
    if (!q.tx) throw new Error('1inch: tidak ada transaksi');

    var { signer } = await ensureSigner();
    var from = q.fromToken;
    var addr = state.address;

    // Approve Aggregation Router if ERC-20
    if (from && from.address) {
      var erc = new ethers.Contract(from.address, [
        'function approve(address spender,uint256 amount) returns (bool)',
        'function allowance(address owner,address spender) view returns (uint256)'
      ], signer);
      var allowance = await erc.allowance(addr, q.tx.to);
      if (allowance < q.amountIn) {
        if (typeof showToast === 'function') showToast('Approve ' + from.symbol + '…');
        var txA = await erc.approve(q.tx.to, ethers.MaxUint256);
        await txA.wait();
      }
    }

    if (typeof showToast === 'function') showToast('Mengirim swap (1inch)…');
    var txReq = {
      to: q.tx.to,
      data: q.tx.data,
      value: q.tx.value ? BigInt(q.tx.value) : 0n
    };
    if (q.tx.gas) {
      try { txReq.gasLimit = BigInt(q.tx.gas); } catch (e) {}
    }
    var tx = await signer.sendTransaction(txReq);
    if (typeof showToast === 'function') showToast('Menunggu konfirmasi…');
    var receipt = await tx.wait();
    if (!receipt || (receipt.status !== 1 && receipt.status !== true)) {
      throw new Error('Swap gagal di chain');
    }
    return { hash: tx.hash, quote: q, source: '1inch' };
  }

  /* ---------- OpenOcean quote (reliable referrer fee) ---------- */
  var OO_CHAIN = {
    1: 'eth',
    8453: 'base',
    42161: 'arbitrum',
    10: 'optimism',
    137: 'polygon',
    56: 'bsc'
  };

  function ooToken(token, cid) {
    if (!token) return NATIVE;
    if (!token.address) return NATIVE;
    return ethers.getAddress(token.address);
  }

  async function quoteOpenOcean(from, to, amountHuman, userAddr) {
    var cid = chainId();
    var chain = OO_CHAIN[cid];
    if (!chain) throw new Error('OpenOcean: chain tidak didukung');
    var amountIn = toUnits(amountHuman, decOf(from));
    if (amountIn <= 0n) throw new Error('Jumlah tidak valid');

    var params = new URLSearchParams({
      inTokenAddress: ooToken(from, cid),
      outTokenAddress: ooToken(to, cid),
      amountDecimals: amountIn.toString(),
      gasPriceDecimals: '1000000000',
      slippage: String(SLIPPAGE_PCT),
      account: userAddr || state.address || NATIVE
    });
    if (BR_SWAP_FEE.enabled && BR_SWAP_FEE.treasury) {
      params.set('referrer', ethers.getAddress(BR_SWAP_FEE.treasury));
      params.set('referrerFee', String(BR_SWAP_FEE.openOceanReferrerFee));
    }

    var url = OO_BASE + '/' + chain + '/swap?' + params.toString();
    var res = await fetch(url, { method: 'GET', headers: { Accept: 'application/json' } });
    if (!res.ok) {
      var errTxt = await res.text().catch(function () { return ''; });
      throw new Error('OpenOcean ' + res.status + (errTxt ? ': ' + errTxt.slice(0, 80) : ''));
    }
    var data = await res.json();
    // API returns { code, data: { ... } } or direct
    var d = data.data || data;
    if (!d || (!d.outAmount && !d.toAmount && !d.minOutAmount)) {
      throw new Error('OpenOcean: tidak ada rute');
    }
    var outRaw = d.outAmount || d.toAmount || d.minOutAmount || '0';
    var outBn = BigInt(String(outRaw));
    var outHuman = fromUnits(outBn, decOf(to));
    var txData = d.data || d.calldata || null;
    var toAddr = d.to || d.contractAddress || null;
    var value = d.value != null ? String(d.value) : '0';
    var gas = d.estimatedGas || d.gas || null;

    if (!txData || !toAddr) {
      // quote-only endpoint fallback
      var qUrl = OO_BASE + '/' + chain + '/quote?' + params.toString();
      var qRes = await fetch(qUrl, { method: 'GET', headers: { Accept: 'application/json' } });
      if (qRes.ok) {
        var qd = await qRes.json();
        var q = qd.data || qd;
        outRaw = q.outAmount || q.toAmount || outRaw;
        outBn = BigInt(String(outRaw));
        outHuman = fromUnits(outBn, decOf(to));
      }
      throw new Error('OpenOcean: calldata kosong (coba lagi)');
    }

    return {
      source: 'openocean',
      amountIn: amountIn,
      amountOut: outBn,
      amountOutHuman: outHuman,
      amountInHuman: Number(amountHuman),
      fromToken: from,
      toToken: to,
      gasEstimate: gas,
      tokenIn: ooToken(from, cid),
      tokenOut: ooToken(to, cid),
      tx: {
        to: toAddr,
        data: txData,
        value: value,
        gas: gas
      },
      feeTo: BR_SWAP_FEE.treasury,
      feePercent: BR_SWAP_FEE.openOceanReferrerFee,
      raw: d
    };
  }

  async function executeOpenOceanSwap(quote) {
    if (!quote || !quote.tx) throw new Error('OpenOcean: tidak ada transaksi');
    var { signer } = await ensureSigner();
    var from = quote.fromToken;
    var addr = state.address;

    if (from && from.address) {
      var erc = new ethers.Contract(from.address, [
        'function approve(address spender,uint256 amount) returns (bool)',
        'function allowance(address owner,address spender) view returns (uint256)'
      ], signer);
      var allowance = await erc.allowance(addr, quote.tx.to);
      if (allowance < quote.amountIn) {
        if (typeof showToast === 'function') showToast('Approve ' + from.symbol + '…');
        var txA = await erc.approve(quote.tx.to, ethers.MaxUint256);
        await txA.wait();
      }
    }

    if (typeof showToast === 'function') showToast('Mengirim swap (OpenOcean)…');
    var txReq = {
      to: quote.tx.to,
      data: quote.tx.data,
      value: quote.tx.value ? BigInt(quote.tx.value) : 0n
    };
    if (quote.tx.gas) {
      try { txReq.gasLimit = BigInt(quote.tx.gas); } catch (e) {}
    }
    var tx = await signer.sendTransaction(txReq);
    if (typeof showToast === 'function') showToast('Menunggu konfirmasi…');
    var receipt = await tx.wait();
    if (!receipt || (receipt.status !== 1 && receipt.status !== true)) {
      throw new Error('Swap gagal di chain');
    }
    return { hash: tx.hash, quote: quote, source: 'openocean' };
  }

  /* ---------- Uniswap fallback quote (reuse existing if available) ---------- */
  async function quoteUniswapFallback(from, to, amountHuman) {
    // Prefer existing scheduleUniswapQuote / _lastQuote machinery
    if (typeof window.getUniswapQuote === 'function') {
      return window.getUniswapQuote(from, to, amountHuman);
    }
    // Minimal on-chain QuoterV2 path
    var cid = chainId();
    var QUOTER = {
      1: '0x61fFE014bA17989E743c5F6cB21bF9697530B21e',
      8453: '0x3d4e44Eb1374240CE5F1B871ab261CD16335B76a',
      42161: '0x61fFE014bA17989E743c5F6cB21bF9697530B21e',
      10: '0x61fFE014bA17989E743c5F6cB21bF9697530B21e',
      137: '0x61fFE014bA17989E743c5F6cB21bF9697530B21e'
    };
    var quoterAddr = QUOTER[cid];
    if (!quoterAddr) throw new Error('Quoter tidak tersedia di chain ini');

    var provider = typeof getProvider === 'function' ? await getProvider() : null;
    if (!provider) throw new Error('Provider tidak tersedia');

    var tokenIn = from.address || WETH[cid];
    var tokenOut = to.address || WETH[cid];
    if (!from.address) tokenIn = WETH[cid];
    if (!to.address) tokenOut = WETH[cid];
    tokenIn = ethers.getAddress(tokenIn);
    tokenOut = ethers.getAddress(tokenOut);

    var amountIn = toUnits(amountHuman, decOf(from));
    var fees = [500, 3000, 10000, 100];
    var abi = [
      'function quoteExactInputSingle((address tokenIn,address tokenOut,uint256 amountIn,uint24 fee,uint160 sqrtPriceLimitX96)) external returns (uint256 amountOut,uint160 sqrtPriceX96After,uint32 initializedTicksCrossed,uint256 gasEstimate)'
    ];
    var quoter = new ethers.Contract(quoterAddr, abi, provider);
    var best = null;

    for (var i = 0; i < fees.length; i++) {
      try {
        var r = await quoter.quoteExactInputSingle.staticCall({
          tokenIn: tokenIn,
          tokenOut: tokenOut,
          amountIn: amountIn,
          fee: fees[i],
          sqrtPriceLimitX96: 0
        });
        var out = r.amountOut != null ? r.amountOut : r[0];
        if (out && (!best || out > best.amountOut)) {
          best = { amountOut: out, fee: fees[i] };
        }
      } catch (e) { /* try next fee */ }
    }
    if (!best) throw new Error('Tidak ada pool Uniswap');

    return {
      source: 'uniswap',
      amountIn: amountIn,
      amountOut: best.amountOut,
      amountOutHuman: fromUnits(best.amountOut, decOf(to)),
      amountInHuman: Number(amountHuman),
      fromToken: from,
      toToken: to,
      fee: best.fee,
      tokenIn: tokenIn,
      tokenOut: tokenOut
    };
  }

  /* ---------- Public quote scheduler ---------- */
  window.scheduleAggregatorQuote = function () {
    if (_aggTimer) clearTimeout(_aggTimer);
    _aggTimer = setTimeout(function () {
      runAggregatorQuote();
    }, 380);
  };

  async function runAggregatorQuote() {
    var from = typeof getToken === 'function' ? getToken(state.swapFrom) : null;
    var to = typeof getToken === 'function' ? getToken(state.swapTo) : null;
    var amtEl = document.getElementById('swapAmtFrom');
    var amt = parseFloat((amtEl && amtEl.value) || '0') || 0;
    if (!from || !to || !(amt > 0)) {
      _aggQuote = null;
      setQuoteUI(0, '1 ' + (from ? from.symbol : '?') + ' ≈ —', '');
      return;
    }
    if (from.id === to.id) {
      _aggQuote = null;
      setQuoteUI(0, 'Pilih token berbeda', '');
      return;
    }

    var seq = ++_aggInflight;
    setRouteLabel('Mencari rute terbaik…', 'route');

    // 1) 1inch — bila API key tersedia (fee → treasury)
    if (getOneInchApiKey()) {
      try {
        var qi = await quote1inch(from, to, amt, state.address);
        if (seq !== _aggInflight) return;
        _aggQuote = qi;
        var rateI = qi.amountOutHuman / amt;
        var rateTxtI = '1 ' + from.symbol + ' ≈ ' + fmtAmt(rateI) + ' ' + to.symbol;
        var routeI = '1inch · fee ' + BR_SWAP_FEE.oneInchFee + '%';
        setQuoteUI(qi.amountOutHuman, rateTxtI, routeI);
        return;
      } catch (e1) {
        console.warn('[Agg] 1inch quote failed', e1);
      }
    }

    // 2) OpenOcean — referrer fee ke treasury
    try {
      var qo = await quoteOpenOcean(from, to, amt, state.address);
      if (seq !== _aggInflight) return;
      _aggQuote = qo;
      var rateO = qo.amountOutHuman / amt;
      var rateTxtO = '1 ' + from.symbol + ' ≈ ' + fmtAmt(rateO) + ' ' + to.symbol;
      var routeO = 'OpenOcean · fee ' + BR_SWAP_FEE.openOceanReferrerFee + '%';
      setQuoteUI(qo.amountOutHuman, rateTxtO, routeO);
      return;
    } catch (eOO) {
      console.warn('[Agg] OpenOcean quote failed', eOO);
    }

    // 3) Odos (+ referralFee ke treasury bila API menerima)
    try {
      var q = await quoteOdos(from, to, amt, state.address);
      if (seq !== _aggInflight) return;
      _aggQuote = q;
      var rate = q.amountOutHuman / amt;
      var rateTxt = '1 ' + from.symbol + ' ≈ ' + fmtAmt(rate) + ' ' + to.symbol;
      var routeTxt = 'Odos · multi-DEX';
      if (BR_SWAP_FEE.enabled) routeTxt += ' · fee ' + BR_SWAP_FEE.percent + '%';
      if (q.priceImpact != null) routeTxt += ' · impact ' + Number(q.priceImpact).toFixed(2) + '%';
      setQuoteUI(q.amountOutHuman, rateTxt, routeTxt);
      return;
    } catch (eOdos) {
      console.warn('[Agg] Odos quote failed', eOdos);
    }

    // 4) Uniswap fallback (tanpa partner fee)
    try {
      var uq = await quoteUniswapFallback(from, to, amt);
      if (seq !== _aggInflight) return;
      _aggQuote = uq;
      var rate2 = uq.amountOutHuman / amt;
      var rateTxt2 = '1 ' + from.symbol + ' ≈ ' + fmtAmt(rate2) + ' ' + to.symbol;
      var feeLabel = uq.fee ? (uq.fee / 10000) + '%' : '';
      setQuoteUI(uq.amountOutHuman, rateTxt2, 'Uniswap V3' + (feeLabel ? ' · fee ' + feeLabel : '') + ' · no partner fee');
      return;
    } catch (eUni) {
      console.warn('[Agg] Uniswap quote failed', eUni);
    }

    if (seq !== _aggInflight) return;
    _aggQuote = null;
    setQuoteUI(0, 'Rute tidak ditemukan', '—');
  }

  window.getAggregatorQuote = function () { return _aggQuote; };

  /* ---------- Execute ---------- */
  async function ensureSigner() {
    var provider = typeof getProvider === 'function' ? await getProvider() : null;
    if (!provider) throw new Error('RPC tidak tersedia');
    var signer = null;
    if (state.wallet && state.wallet.privateKey) {
      signer = new ethers.Wallet(state.wallet.privateKey, provider);
    } else if (state.privateKey) {
      signer = new ethers.Wallet(state.privateKey, provider);
    } else if (typeof getSigner === 'function') {
      signer = await getSigner();
    }
    if (!signer) throw new Error('Wallet terkunci — buka dengan PIN');
    return { provider: provider, signer: signer };
  }

  async function executeOdosSwap(quote) {
    var addr = state.address;
    if (!addr) throw new Error('Tidak ada alamat wallet');
    var assembled = await assembleOdos(quote.pathId, addr);
    var txReq = assembled.transaction;
    var { signer } = await ensureSigner();

    // Approve if ERC-20 input
    var from = quote.fromToken;
    if (from && from.address) {
      var routerTo = txReq.to;
      var erc = new ethers.Contract(from.address, [
        'function approve(address spender,uint256 amount) returns (bool)',
        'function allowance(address owner,address spender) view returns (uint256)'
      ], signer);
      var allowance = await erc.allowance(addr, routerTo);
      if (allowance < quote.amountIn) {
        if (typeof showToast === 'function') showToast('Approve ' + from.symbol + '…');
        var txA = await erc.approve(routerTo, ethers.MaxUint256);
        await txA.wait();
      }
    }

    if (typeof showToast === 'function') showToast('Mengirim swap (Odos)…');
    var tx = await signer.sendTransaction({
      to: txReq.to,
      data: txReq.data,
      value: txReq.value ? BigInt(txReq.value) : 0n,
      gasLimit: txReq.gas ? BigInt(txReq.gas) : undefined
    });
    if (typeof showToast === 'function') showToast('Menunggu konfirmasi…');
    var receipt = await tx.wait();
    if (!receipt || (receipt.status !== 1 && receipt.status !== true)) {
      throw new Error('Swap gagal di chain');
    }
    return { hash: tx.hash, quote: quote, source: 'odos' };
  }

  async function executeUniswapSwap(quote) {
    // Prefer existing on-chain engine
    if (typeof window.executeSwapOnChain === 'function') {
      // Ensure _lastQuote-like shape if needed — call existing
      return window.executeSwapOnChain();
    }
    throw new Error('Uniswap engine tidak tersedia');
  }

  window.executeAggregatorSwap = async function () {
    var from = typeof getToken === 'function' ? getToken(state.swapFrom) : null;
    var to = typeof getToken === 'function' ? getToken(state.swapTo) : null;
    var amt = parseFloat((document.getElementById('swapAmtFrom') || {}).value) || 0;
    if (!from || !to) throw new Error('Pilih pasangan token');
    if (!(amt > 0)) throw new Error('Masukkan jumlah');
    var bal = (state.balances && state.balances[from.id]) || 0;
    if (amt > bal + 1e-12) throw new Error('Saldo tidak cukup');

    // Refresh quote if stale / missing
    if (!_aggQuote || _aggQuote.fromToken.id !== from.id || _aggQuote.toToken.id !== to.id) {
      await runAggregatorQuote();
    }
    if (!_aggQuote) throw new Error('Tidak ada rute swap');

    var result;
    if (_aggQuote.source === '1inch') {
      try {
        result = await execute1inchSwap(_aggQuote);
      } catch (e1) {
        console.warn('[Agg] 1inch exec failed, try OpenOcean/Odos', e1);
        try {
          var qo2 = await quoteOpenOcean(from, to, amt, state.address);
          _aggQuote = qo2;
          result = await executeOpenOceanSwap(qo2);
        } catch (eOO2) {
          try {
            var qO = await quoteOdos(from, to, amt, state.address);
            _aggQuote = qO;
            result = await executeOdosSwap(qO);
          } catch (eO2) {
            var uq1 = await quoteUniswapFallback(from, to, amt);
            _aggQuote = uq1;
            result = await executeUniswapSwap(uq1);
            result.source = result.source || 'uniswap';
          }
        }
      }
    } else if (_aggQuote.source === 'openocean' && _aggQuote.tx) {
      try {
        result = await executeOpenOceanSwap(_aggQuote);
      } catch (eOO) {
        console.warn('[Agg] OpenOcean exec failed, try Odos/Uniswap', eOO);
        try {
          var q2 = await quoteOdos(from, to, amt, state.address);
          _aggQuote = q2;
          result = await executeOdosSwap(q2);
        } catch (e2) {
          var uq = await quoteUniswapFallback(from, to, amt);
          _aggQuote = uq;
          result = await executeUniswapSwap(uq);
          result.source = result.source || 'uniswap';
        }
      }
    } else if (_aggQuote.source === 'odos' && _aggQuote.pathId) {
      try {
        result = await executeOdosSwap(_aggQuote);
      } catch (eOdos) {
        console.warn('[Agg] Odos exec failed, try Uniswap', eOdos);
        var uq2 = await quoteUniswapFallback(from, to, amt);
        _aggQuote = uq2;
        result = await executeUniswapSwap(uq2);
        result.source = result.source || 'uniswap';
      }
    } else {
      result = await executeUniswapSwap(_aggQuote);
      result.source = result.source || 'uniswap';
    }

    // History
    try {
      if (typeof recordSwapHistory === 'function') {
        recordSwapHistory({
          hash: result.hash || '',
          fromSym: from.symbol,
          toSym: to.symbol,
          fromId: from.id,
          toId: to.id,
          amountIn: amt,
          amountOut: _aggQuote.amountOutHuman,
          source: result.source || _aggQuote.source,
          time: Date.now(),
          success: true,
          network: state.network || 'base',
          kind: 'swap'
        });
      }
    } catch (e) {}

    // Optimistic balances
    try {
      if (state.balances) {
        state.balances[from.id] = Math.max(0, bal - amt);
        state.balances[to.id] = (Number(state.balances[to.id]) || 0) + Number(_aggQuote.amountOutHuman || 0);
      }
    } catch (e) {}

    return result;
  };

  /* ---------- Wire into existing UI ---------- */
  // Prefer aggregator for live quotes
  var _prevSched = window.scheduleUniswapQuote;
  window.scheduleUniswapQuote = function () {
    window.scheduleAggregatorQuote();
    // still allow legacy path to run lightly
    if (typeof _prevSched === 'function') {
      try { /* skip to avoid double network */ } catch (e) {}
    }
  };

  // Input listeners
  function bindSwapInputs() {
    var inp = document.getElementById('swapAmtFrom');
    if (inp && !inp.dataset.aggBound) {
      inp.dataset.aggBound = '1';
      inp.addEventListener('input', function () {
        window.scheduleAggregatorQuote();
      });
    }
  }

  // Override executeSwap
  var _prevExec = window.executeSwap;
  window.executeSwap = function () {
    return (async function () {
      var from = typeof getToken === 'function' ? getToken(state.swapFrom) : null;
      var to = typeof getToken === 'function' ? getToken(state.swapTo) : null;
      var amt = parseFloat((document.getElementById('swapAmtFrom') || {}).value) || 0;
      if (!from || !to) return showToast('Pilih pasangan token', 'warn');
      if (!(amt > 0)) return showToast('Masukkan jumlah', 'warn');

      var btn = document.getElementById('swapCtaBtn');
      var label = document.getElementById('swapCtaLabel');
      if (btn) btn.disabled = true;
      if (label) label.textContent = 'Memproses…';

      var run = async function () {
        try {
          var result = await window.executeAggregatorSwap();
          showToast('Swap berhasil' + (result.source ? ' · ' + result.source : ''), 'success');
          if (label) label.textContent = 'Berhasil ✓';
          var inp = document.getElementById('swapAmtFrom');
          if (inp) inp.value = '';
          var out = document.getElementById('swapAmtTo');
          if (out) out.value = '';
          _aggQuote = null;
          if (typeof renderSwapUI === 'function') renderSwapUI();
          setTimeout(function () {
            if (typeof refreshBalances === 'function') refreshBalances(true);
          }, 1500);
          return result;
        } catch (e) {
          var msg = (e && (e.reason || e.shortMessage || e.message)) || String(e);
          msg = String(msg).slice(0, 140);
          showToast(msg, 'error');
          try {
            if (typeof recordSwapHistory === 'function') {
              recordSwapHistory({
                hash: '',
                fromSym: from.symbol,
                toSym: to.symbol,
                amountIn: amt,
                success: false,
                error: msg,
                time: Date.now(),
                network: state.network || 'base'
              });
            }
          } catch (e2) {}
          // Last resort: open Uniswap web
          try {
            if (typeof _prevExec === 'function' && /rute|quote|odos|network|fetch/i.test(msg)) {
              // don't auto-open; user can retry
            }
          } catch (e3) {}
          throw e;
        } finally {
          if (btn) btn.disabled = false;
          if (label) {
            setTimeout(function () {
              if (label.textContent === 'Berhasil ✓') label.textContent = 'Tukar';
              else if (label.textContent === 'Memproses…') label.textContent = 'Tukar';
            }, 2000);
          }
          try { if (typeof updateCta === 'function') updateCta(); } catch (e) {}
        }
      };

      if (typeof requirePin === 'function') {
        requirePin(function () { run(); });
      } else {
        return run();
      }
    })();
  };

  // Hook showScreen('swap')
  var _ss = window.showScreen;
  if (typeof _ss === 'function') {
    window.showScreen = function (name) {
      var r = _ss.apply(this, arguments);
      if (name === 'swap') {
        setTimeout(function () {
          bindSwapInputs();
          try {
            if (typeof renderSwapUI === 'function') renderSwapUI();
          } catch (e) {}
          window.scheduleAggregatorQuote();
        }, 80);
      }
      return r;
    };
  }

  setTimeout(bindSwapInputs, 600);

  // Ensure route label element exists near rate
  setTimeout(function () {
    var rateEl = document.getElementById('swapRate');
    if (rateEl && !document.getElementById('swapRouteLabel') && !document.getElementById('swapPoolFee')) {
      var span = document.createElement('div');
      span.id = 'swapRouteLabel';
      span.className = 'hint';
      span.style.cssText = 'margin-top:4px;font-size:12px;opacity:.7;text-align:center';
      span.textContent = '';
      if (rateEl.parentNode) rateEl.parentNode.insertBefore(span, rateEl.nextSibling);
    }
  }, 1000);

  window.BR_SWAP_FEE = BR_SWAP_FEE;
  window.getOneInchApiKey = getOneInchApiKey;
  brLog('%cSwap Aggregator · 1inch + OpenOcean + Odos + Uniswap', 'color:#00D4AA;font-weight:bold');
  brLog('%cFee treasury: ' + BR_SWAP_FEE.treasury + ' · ' + BR_SWAP_FEE.percent + '%', 'color:#00e6b8');
  brLog('%c1inch API key: ' + (getOneInchApiKey() ? 'set' : 'BELUM — panggil setOneInchApiKey("YOUR_KEY")'), 'color:#f0b90b');
})();


/* Hook calcSwapOut → aggregator quote (price estimate first, then real route) */
(function () {
  var _calc = typeof calcSwapOut === 'function' ? calcSwapOut : null;
  window.calcSwapOut = function () {
    if (_calc) {
      try { _calc(); } catch (e) {}
    }
    if (typeof window.scheduleAggregatorQuote === 'function') {
      window.scheduleAggregatorQuote();
    }
  };
  // flip / max should also refresh route
  var _flip = typeof flipSwap === 'function' ? flipSwap : null;
  if (_flip) {
    window.flipSwap = function () {
      var r = _flip.apply(this, arguments);
      if (typeof window.scheduleAggregatorQuote === 'function') window.scheduleAggregatorQuote();
      return r;
    };
  }
  var _max = typeof setMaxSwap === 'function' ? setMaxSwap : null;
  if (_max) {
    window.setMaxSwap = function () {
      var r = _max.apply(this, arguments);
      if (typeof window.scheduleAggregatorQuote === 'function') window.scheduleAggregatorQuote();
      return r;
    };
  }
})();


/* ============================================================
   Jupiter Swap API — Solana
   Quote: lite-api / api.jup.ag  |  Sign: Phantom or imported key
   ============================================================ */
(function JupiterSolana() {
  'use strict';

  var SOL_MINT = 'So11111111111111111111111111111111111111112';
  // Keyless lite endpoint (rate limited) + paid api.jup.ag
  var JUP_QUOTE = 'https://lite-api.jup.ag/swap/v1/quote';
  var JUP_SWAP = 'https://lite-api.jup.ag/swap/v1/swap';
  var JUP_QUOTE_PAID = 'https://api.jup.ag/swap/v1/quote';
  var JUP_SWAP_PAID = 'https://api.jup.ag/swap/v1/swap';
  var SLIPPAGE_BPS = 50; // 0.5%
  var _jupQuote = null;
  var _solWeb3Loading = null;

  function isSolNetwork() {
    return (state && state.network) === 'sol';
  }

  function getJupApiKey() {
    try {
      return (localStorage.getItem('br_jup_api_key') || '').trim();
    } catch (e) {
      return '';
    }
  }

  window.setJupiterApiKey = function (key) {
    key = String(key || '').trim();
    try {
      if (key) localStorage.setItem('br_jup_api_key', key);
      else localStorage.removeItem('br_jup_api_key');
    } catch (e) {}
    if (typeof showToast === 'function') {
      showToast(key ? 'Jupiter API key disimpan' : 'Jupiter API key dihapus', 'success');
    }
    return !!key;
  };

  function jupHeaders() {
    var h = { Accept: 'application/json', 'Content-Type': 'application/json' };
    var k = getJupApiKey();
    if (k) h['x-api-key'] = k;
    return h;
  }

  function mintOf(token) {
    if (!token) return SOL_MINT;
    if (token.mint) return token.mint;
    if (!token.address) return SOL_MINT;
    return token.address;
  }

  function solDecimals(token) {
    return token && token.decimals != null ? Number(token.decimals) : 9;
  }

  function toBaseUnits(amount, decimals) {
    var s = String(amount);
    if (!/^\d+(\.\d+)?$/.test(s)) return '0';
    var parts = s.split('.');
    var whole = parts[0] || '0';
    var frac = (parts[1] || '').slice(0, decimals);
    while (frac.length < decimals) frac += '0';
    var raw = whole + frac;
    raw = raw.replace(/^0+(?=\d)/, '');
    return raw || '0';
  }

  function fromBaseUnits(raw, decimals) {
    try {
      var s = String(raw);
      if (s.length <= decimals) s = s.padStart(decimals + 1, '0');
      var i = s.length - decimals;
      var out = s.slice(0, i) + '.' + s.slice(i);
      return parseFloat(out) || 0;
    } catch (e) {
      return 0;
    }
  }

  async function loadSolanaWeb3() {
    if (window.solanaWeb3) return window.solanaWeb3;
    if (_solWeb3Loading) return _solWeb3Loading;
    _solWeb3Loading = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = 'https://cdn.jsdelivr.net/npm/@solana/web3.js@1.95.4/lib/index.iife.min.js';
      s.async = true;
      s.onload = function () {
        // umd exposes solanaWeb3
        if (window.solanaWeb3) resolve(window.solanaWeb3);
        else reject(new Error('solanaWeb3 tidak termuat'));
      };
      s.onerror = function () { reject(new Error('Gagal muat @solana/web3.js')); };
      document.head.appendChild(s);
    });
    return _solWeb3Loading;
  }

  function getSolPublicKey() {
    try {
      if (state.solAddress) return state.solAddress;
      if (window.solana && window.solana.publicKey) {
        return window.solana.publicKey.toString();
      }
      var stored = localStorage.getItem('br_sol_pubkey');
      if (stored) return stored;
    } catch (e) {}
    return null;
  }

  /** Import Solana secret key (base58 or JSON byte array) */
  window.importSolanaKey = async function (secret) {
    var web3 = await loadSolanaWeb3();
    secret = String(secret || '').trim();
    var kp;
    try {
      if (secret.startsWith('[')) {
        var arr = JSON.parse(secret);
        kp = web3.Keypair.fromSecretKey(Uint8Array.from(arr));
      } else {
        // base58
        var bs58Mod = null;
        try {
          // minimal base58 decode via solana web3 internal if available
          kp = web3.Keypair.fromSecretKey(
            // fallback: try decode with built-in
            (function () {
              if (typeof web3.Keypair.fromSecretKey !== 'function') throw new Error('no');
              // use experimental: many builds need bs58
              throw new Error('use json array');
            })()
          );
        } catch (e) {
          throw new Error('Gunakan format JSON array 64-byte, contoh dari Phantom export');
        }
      }
    } catch (e) {
      // try bs58 from CDN
      await new Promise(function (res, rej) {
        if (window.bs58) return res();
        var s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/bs58@5.0.0/dist/bs58.bundle.js';
        s.onload = res;
        s.onerror = rej;
        document.head.appendChild(s);
      }).catch(function () {});
      if (window.bs58) {
        var decoded = window.bs58.decode(secret);
        kp = web3.Keypair.fromSecretKey(decoded);
      } else {
        throw new Error('Format key tidak dikenali. Export JSON secret key dari Phantom/CLI.');
      }
    }
    state.solKeypair = kp;
    state.solAddress = kp.publicKey.toString();
    try {
      localStorage.setItem('br_sol_pubkey', state.solAddress);
    } catch (e) {}
    if (typeof showToast === 'function') {
      showToast('Solana wallet: ' + state.solAddress.slice(0, 4) + '…' + state.solAddress.slice(-4), 'success');
    }
    return state.solAddress;
  };

  window.connectPhantom = async function () {
    var provider = window.solana || window.phantom?.solana;
    if (!provider) {
      if (typeof showToast === 'function') showToast('Install Phantom / Solflare', 'warn');
      throw new Error('Wallet Solana tidak ditemukan');
    }
    var resp = await provider.connect();
    var pk = (resp && resp.publicKey) ? resp.publicKey.toString() : provider.publicKey.toString();
    state.solAddress = pk;
    state.solProvider = provider;
    try { localStorage.setItem('br_sol_pubkey', pk); } catch (e) {}
    if (typeof showToast === 'function') showToast('Phantom terhubung', 'success');
    return pk;
  };

  async function quoteJupiter(from, to, amountHuman) {
    var inputMint = mintOf(from);
    var outputMint = mintOf(to);
    var amount = toBaseUnits(amountHuman, solDecimals(from));
    if (amount === '0') throw new Error('Jumlah tidak valid');

    var params = new URLSearchParams({
      inputMint: inputMint,
      outputMint: outputMint,
      amount: amount,
      slippageBps: String(SLIPPAGE_BPS),
      restrictIntermediateTokens: 'true'
    });
    // Optional platform fee (butuh feeAccount ATA Solana — lihat docs)
    // params.set('platformFeeBps', '50');

    var key = getJupApiKey();
    var url = (key ? JUP_QUOTE_PAID : JUP_QUOTE) + '?' + params.toString();
    var res = await fetch(url, { headers: jupHeaders() });
    if (!res.ok) {
      var t = await res.text().catch(function () { return ''; });
      throw new Error('Jupiter quote ' + res.status + (t ? ': ' + t.slice(0, 100) : ''));
    }
    var data = await res.json();
    if (!data || !data.outAmount) throw new Error('Jupiter: tidak ada rute');

    var outHuman = fromBaseUnits(data.outAmount, solDecimals(to));
    return {
      source: 'jupiter',
      quoteResponse: data,
      amountInHuman: Number(amountHuman),
      amountOutHuman: outHuman,
      amountOut: data.outAmount,
      fromToken: from,
      toToken: to,
      priceImpactPct: data.priceImpactPct,
      routePlan: data.routePlan
    };
  }

  async function buildJupiterSwap(quote, userPublicKey) {
    var key = getJupApiKey();
    var url = key ? JUP_SWAP_PAID : JUP_SWAP;
    var body = {
      quoteResponse: quote.quoteResponse,
      userPublicKey: userPublicKey,
      wrapAndUnwrapSol: true,
      dynamicComputeUnitLimit: true,
      prioritizationFeeLamports: 'auto'
    };
    var res = await fetch(url, {
      method: 'POST',
      headers: jupHeaders(),
      body: JSON.stringify(body)
    });
    if (!res.ok) {
      var t = await res.text().catch(function () { return ''; });
      throw new Error('Jupiter swap ' + res.status + (t ? ': ' + t.slice(0, 120) : ''));
    }
    return res.json();
  }

  async function executeJupiterSwap(quote) {
    var pk = getSolPublicKey();
    if (!pk) {
      // try phantom
      try {
        pk = await window.connectPhantom();
      } catch (e) {
        throw new Error('Hubungkan Phantom atau import Solana key dulu');
      }
    }

    var built = await buildJupiterSwap(quote, pk);
    if (!built.swapTransaction) throw new Error('Jupiter: tidak ada transaksi');

    var web3 = await loadSolanaWeb3();
    var txBuf = Uint8Array.from(atob(built.swapTransaction), function (c) { return c.charCodeAt(0); });
    var tx = web3.VersionedTransaction.deserialize(txBuf);

    // Sign
    if (state.solProvider && state.solProvider.signTransaction) {
      tx = await state.solProvider.signTransaction(tx);
    } else if (state.solKeypair) {
      tx.sign([state.solKeypair]);
    } else if (window.solana && window.solana.signTransaction) {
      tx = await window.solana.signTransaction(tx);
    } else {
      throw new Error('Tidak bisa tanda tangani — hubungkan Phantom');
    }

    // Send
    var rpcList = ['https://api.mainnet-beta.solana.com', 'https://solana-rpc.publicnode.com'];
    var sig = null;
    var lastErr = null;
    for (var i = 0; i < rpcList.length; i++) {
      try {
        var conn = new web3.Connection(rpcList[i], 'confirmed');
        sig = await conn.sendRawTransaction(tx.serialize(), {
          skipPreflight: false,
          maxRetries: 3
        });
        await conn.confirmTransaction(sig, 'confirmed');
        break;
      } catch (e) {
        lastErr = e;
      }
    }
    if (!sig) throw lastErr || new Error('Gagal kirim tx Solana');

    return { hash: sig, quote: quote, source: 'jupiter' };
  }

  /* Hook aggregator when network is Solana */
  var _prevRun = window.scheduleAggregatorQuote;
  window.scheduleAggregatorQuote = function () {
    if (isSolNetwork()) {
      if (window._jupTimer) clearTimeout(window._jupTimer);
      window._jupTimer = setTimeout(runJupiterQuote, 380);
      return;
    }
    if (typeof _prevRun === 'function') return _prevRun();
  };

  async function runJupiterQuote() {
    if (!isSolNetwork()) return;
    var from = typeof getToken === 'function' ? getToken(state.swapFrom) : null;
    var to = typeof getToken === 'function' ? getToken(state.swapTo) : null;
    var amtEl = document.getElementById('swapAmtFrom');
    var amt = parseFloat((amtEl && amtEl.value) || '0') || 0;
    var rateEl = document.getElementById('swapRate');
    var feeEl = document.getElementById('swapPoolFee');
    if (!from || !to || !(amt > 0)) {
      _jupQuote = null;
      if (rateEl) rateEl.textContent = '1 ' + (from ? from.symbol : '?') + ' ≈ —';
      return;
    }
    if (feeEl) feeEl.textContent = 'Jupiter · mencari rute…';
    try {
      var q = await quoteJupiter(from, to, amt);
      _jupQuote = q;
      // expose to shared aggregator slot
      if (typeof window.getAggregatorQuote === 'function') {
        /* store on module */
      }
      window._aggQuoteSol = q;
      var rate = q.amountOutHuman / amt;
      if (rateEl) rateEl.textContent = '1 ' + from.symbol + ' ≈ ' + (typeof fmtAmt === 'function' ? fmtAmt(rate) : rate.toFixed(6)) + ' ' + to.symbol;
      var outEl = document.getElementById('swapAmtTo');
      if (outEl) outEl.value = typeof fmtAmt === 'function' ? fmtAmt(q.amountOutHuman) : String(q.amountOutHuman);
      var prev = document.getElementById('swapAmtToPreview');
      if (prev) prev.textContent = outEl ? outEl.value : '—';
      var impact = q.priceImpactPct != null ? Number(q.priceImpactPct).toFixed(3) : null;
      if (feeEl) feeEl.textContent = 'Jupiter' + (impact != null ? ' · impact ' + impact + '%' : '');
    } catch (e) {
      console.warn('[Jupiter]', e);
      _jupQuote = null;
      if (feeEl) feeEl.textContent = 'Jupiter: ' + String(e.message || e).slice(0, 40);
    }
  }

  // Override execute when on Solana
  var _prevExec = window.executeSwap;
  window.executeSwap = function () {
    if (!isSolNetwork()) {
      return typeof _prevExec === 'function' ? _prevExec.apply(this, arguments) : null;
    }
    return (async function () {
      var from = typeof getToken === 'function' ? getToken(state.swapFrom) : null;
      var to = typeof getToken === 'function' ? getToken(state.swapTo) : null;
      var amt = parseFloat((document.getElementById('swapAmtFrom') || {}).value) || 0;
      if (!from || !to) return showToast('Pilih pasangan token', 'warn');
      if (!(amt > 0)) return showToast('Masukkan jumlah', 'warn');

      var btn = document.getElementById('swapCtaBtn');
      var label = document.getElementById('swapCtaLabel');
      if (btn) btn.disabled = true;
      if (label) label.textContent = 'Memproses…';

      try {
        if (!_jupQuote) await runJupiterQuote();
        if (!_jupQuote) throw new Error('Tidak ada rute Jupiter');
        if (typeof showToast === 'function') showToast('Swap Solana via Jupiter…');
        var result = await executeJupiterSwap(_jupQuote);
        showToast('Swap Solana berhasil', 'success');
        if (label) label.textContent = 'Berhasil ✓';
        var inp = document.getElementById('swapAmtFrom');
        if (inp) inp.value = '';
        try {
          if (typeof recordSwapHistory === 'function') {
            recordSwapHistory({
              hash: result.hash,
              fromSym: from.symbol,
              toSym: to.symbol,
              amountIn: amt,
              amountOut: _jupQuote.amountOutHuman,
              source: 'jupiter',
              network: 'sol',
              success: true,
              time: Date.now()
            });
          }
        } catch (e) {}
        return result;
      } catch (e) {
        var msg = String((e && e.message) || e).slice(0, 140);
        showToast(msg, 'error');
        throw e;
      } finally {
        if (btn) btn.disabled = false;
        setTimeout(function () {
          if (label && label.textContent === 'Berhasil ✓') label.textContent = 'Tukar';
          else if (label && label.textContent === 'Memproses…') label.textContent = 'Tukar';
        }, 2000);
      }
    })();
  };

  // When switching to sol, load tokens
  var _selNet = window.selectNetwork;
  if (typeof _selNet === 'function') {
    window.selectNetwork = function (id) {
      var r = _selNet.apply(this, arguments);
      if (id === 'sol' || (state && state.network === 'sol')) {
        setTimeout(function () {
          try {
            if (typeof loadNetworkTokens === 'function') loadNetworkTokens('sol');
            if (typeof renderSwapUI === 'function') renderSwapUI();
          } catch (e) {}
        }, 50);
      }
      return r;
    };
  }

  brLog('%cJupiter Solana ready — setJupiterApiKey() · connectPhantom() · importSolanaKey()', 'color:#14F195;font-weight:bold');
})();



/* ============================================================
   Solana receive address — show SOL pubkey instead of 0x EVM
   ============================================================ */
(function SolanaReceiveAddress() {
  'use strict';

  function isSol() {
    return (state && state.network) === 'sol';
  }

  window.getReceiveAddress = function () {
    if (isSol()) {
      var sol = (state && state.solAddress) || null;
      try {
        if (!sol) sol = localStorage.getItem('br_sol_pubkey');
      } catch (e) {}
      try {
        if (!sol && window.solana && window.solana.publicKey) {
          sol = window.solana.publicKey.toString();
        }
      } catch (e) {}
      return sol || '';
    }
    return (state && state.address) || '';
  };

  window.shortenAddr = function (addr, left, right) {
    if (!addr) return '—';
    left = left || 6;
    right = right || 4;
    if (addr.length <= left + right + 3) return addr;
    return addr.slice(0, left) + '...' + addr.slice(-right);
  };

  // Override renderReceive
  var _rr = typeof renderReceive === 'function' ? renderReceive : null;
  window.renderReceive = function () {
    var addr = window.getReceiveAddress();
    var el = document.getElementById('receiveAddr');
    if (el) {
      if (isSol() && !addr) {
        el.textContent = 'Hubungkan Phantom / import Solana key';
      } else {
        el.textContent = addr || '—';
      }
    }
    // Network hint
    var hint = document.getElementById('receiveNetHint');
    if (!hint && el && el.parentNode) {
      hint = document.createElement('p');
      hint.id = 'receiveNetHint';
      hint.className = 'hint';
      hint.style.cssText = 'margin:6px 0 0;font-size:12px;opacity:.7;text-align:center';
      el.parentNode.insertBefore(hint, el.nextSibling);
    }
    if (hint) {
      if (isSol()) {
        hint.textContent = addr
          ? 'Jaringan Solana · kirim hanya SOL / SPL ke alamat ini'
          : 'Belum ada alamat Solana — ketuk untuk hubungkan Phantom';
        hint.style.color = addr ? '#14F195' : '#f0b90b';
        if (!addr) {
          hint.style.cursor = 'pointer';
          hint.onclick = function () {
            if (typeof window.connectPhantom === 'function') {
              window.connectPhantom().then(function () {
                window.renderReceive();
              }).catch(function () {});
            }
          };
        } else {
          hint.onclick = null;
        }
      } else {
        var net = (state && state.network) || 'base';
        hint.textContent = 'Jaringan ' + net.toUpperCase() + ' · alamat EVM (0x…)';
        hint.style.color = '';
        hint.onclick = null;
      }
    }

    var canvas = document.getElementById('qrCanvas');
    if (!canvas) return;
    if (!addr) {
      var ctx0 = canvas.getContext('2d');
      canvas.width = 200;
      canvas.height = 200;
      ctx0.fillStyle = '#ffffff';
      ctx0.fillRect(0, 0, 200, 200);
      ctx0.fillStyle = '#666';
      ctx0.font = '11px sans-serif';
      ctx0.textAlign = 'center';
      ctx0.fillText(isSol() ? 'Connect Phantom' : 'No address', 100, 100);
      return;
    }
    canvas.width = 200;
    canvas.height = 200;
    var ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, 200, 200);
    if (typeof QRCode === 'undefined') {
      ctx.fillStyle = '#000';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Loading QR…', 100, 100);
      setTimeout(function () { window.renderReceive(); }, 400);
      return;
    }
    QRCode.toCanvas(canvas, addr, {
      width: 200,
      margin: 2,
      color: { dark: '#000000', light: '#ffffff' },
      errorCorrectionLevel: 'M'
    }, function (err) {
      if (err) {
        console.error(err);
        ctx.fillStyle = '#000';
        ctx.font = '11px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Gagal QR', 100, 95);
        ctx.fillText('Salin alamat', 100, 112);
      }
    });
    // Also modern QR host if present
    try {
      if (typeof renderModernQR === 'function' && document.getElementById('qrCanvasHost')) {
        renderModernQR('qrCanvasHost', addr, { size: 200, withLogo: true });
      }
    } catch (e) {}
  };

  // Override copyAddress
  window.copyAddress = function () {
    var addr = window.getReceiveAddress();
    if (!addr) {
      if (isSol() && typeof window.connectPhantom === 'function') {
        window.connectPhantom().then(function () {
          window.copyAddress();
        }).catch(function () {
          if (typeof showToast === 'function') showToast('Hubungkan Phantom dulu', 'warn');
        });
        return;
      }
      if (typeof showToast === 'function') showToast('Tidak ada alamat', 'warn');
      return;
    }
    navigator.clipboard.writeText(addr).then(function () {
      if (typeof showToast === 'function') {
        showToast(isSol() ? 'Alamat Solana disalin' : 'Alamat disalin', 'success');
      }
    }).catch(function () {
      if (typeof showToast === 'function') showToast('Gagal salin', 'error');
    });
  };

  // Patch token detail address + copy after showToken paints
  var _showToken = typeof showToken === 'function' ? showToken : null;
  if (_showToken) {
    window.showToken = function () {
      var r = _showToken.apply(this, arguments);
      try {
        var addr = window.getReceiveAddress();
        var el = document.getElementById('tdAddr');
        if (el) {
          if (isSol() && !addr) {
            el.textContent = 'Hubungkan Phantom…';
          } else {
            el.textContent = addr
              ? (addr.slice(0, 8) + '...' + addr.slice(-6))
              : '—';
          }
        }
        var cp = document.getElementById('tdCopy');
        if (cp) {
          cp.onclick = function () {
            window.copyAddress();
          };
        }
      } catch (e) {}
      return r;
    };
  }

  // Refresh receive UI when switching to sol
  var _sel = window.selectNetwork;
  if (typeof _sel === 'function') {
    window.selectNetwork = async function (id) {
      var r = await _sel.apply(this, arguments);
      if (id === 'sol' || (state && state.network === 'sol')) {
        setTimeout(function () {
          try {
            if (typeof window.renderReceive === 'function') window.renderReceive();
          } catch (e) {}
        }, 100);
      }
      return r;
    };
  }

  brLog('%cSolana receive address layer ready', 'color:#14F195');
})();


/* ============================================================
   Solana in-wallet (no Phantom required)
   - Generate / restore keypair inside app
   - SOL + SPL balances via public RPC
   - Sign Jupiter swaps with local key
   ============================================================ */
(function SolanaInWallet() {
  'use strict';

  var SOL_MINT = 'So11111111111111111111111111111111111111112';
  // Secret key is NEVER stored plaintext. It is encrypted with the active PIN-derived
  // AES-GCM session key via PinCrypto and stored as br_sec_sol_secret_v1.
  var ENC_SK_KEY = 'sol_secret_v1';
  var LEGACY_SK_KEY = 'br_sol_secret_v1';
  var PK_KEY = 'br_sol_pubkey';
  var RPCS = [
    'https://solana-rpc.publicnode.com',
    'https://api.mainnet-beta.solana.com',
    'https://rpc.ankr.com/solana'
  ];

  var TOKEN_PROGRAM = 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA';
  var ASSOC_TOKEN = 'ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL';

  function isSol() {
    return (state && state.network) === 'sol';
  }

  async function loadWeb3() {
    if (typeof window.Buffer === 'undefined') {
      try {
        await new Promise(function (res) {
          var s = document.createElement('script');
          s.src = 'https://cdn.jsdelivr.net/npm/buffer@6.0.3/index.js';
          s.onload = function () {
            try {
              if (window.buffer && window.buffer.Buffer) window.Buffer = window.buffer.Buffer;
            } catch (e) {}
            res();
          };
          s.onerror = function () { res(); };
          document.head.appendChild(s);
        });
      } catch (e) {}
    }
    if (window.solanaWeb3) return window.solanaWeb3;
    return new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = 'https://cdn.jsdelivr.net/npm/@solana/web3.js@1.95.4/lib/index.iife.min.js';
      s.async = true;
      s.onload = function () {
        if (window.solanaWeb3) resolve(window.solanaWeb3);
        else reject(new Error('solanaWeb3 missing'));
      };
      s.onerror = function () { reject(new Error('load solanaWeb3 failed')); };
      document.head.appendChild(s);
    });
  }

  function b64encode(u8) {
    var s = '';
    for (var i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i]);
    return btoa(s);
  }
  function b64decode(b64) {
    var s = atob(b64);
    var u8 = new Uint8Array(s.length);
    for (var i = 0; i < s.length; i++) u8[i] = s.charCodeAt(i);
    return u8;
  }

  function hasPinVault() {
    return !!(typeof PinCrypto !== 'undefined' && PinCrypto.isEncrypted && PinCrypto.isEncrypted());
  }

  async function encryptSecretB64(b64) {
    if (!hasPinVault() || !PinCrypto._sessionKey) {
      throw new Error('Atur dan buka PIN sebelum menyimpan wallet Solana');
    }
    await PinCrypto.encryptSecret(ENC_SK_KEY, b64);
  }

  async function decryptSecretB64() {
    if (!hasPinVault() || !PinCrypto._sessionKey) return null;
    try {
      return await PinCrypto.decryptSecret(ENC_SK_KEY);
    } catch (e) {
      return null;
    }
  }

  /**
   * One-way migration of the old Base64-only Solana secret. This runs only after
   * the PIN-derived AES-GCM session key is available. The legacy key is removed
   * only after the encrypted copy has been written successfully.
   */
  window.migrateSolanaSecretToVault = async function () {
    try {
      if (!hasPinVault() || !PinCrypto._sessionKey) return false;
      var legacy = localStorage.getItem(LEGACY_SK_KEY);
      if (!legacy) return false;
      var secret = b64decode(legacy);
      if (secret.length !== 64 && secret.length !== 32) throw new Error('Legacy Solana secret invalid');
      await encryptSecretB64(legacy);
      try { localStorage.removeItem(LEGACY_SK_KEY); } catch (e) {}
      return true;
    } catch (e) {
      if (window.BR_DEBUG) console.warn('[Sol] migrate legacy secret failed', e);
      return false;
    }
  };

  async function saveKeypair(kp) {
    var secret = kp.secretKey;
    var b64 = b64encode(secret);
    await encryptSecretB64(b64);
    try { localStorage.setItem(PK_KEY, kp.publicKey.toString()); } catch (e) {}
    state.solKeypair = kp;
    state.solAddress = kp.publicKey.toString();
  }

  async function loadKeypairFromStorage() {
    var web3 = await loadWeb3();
    try {
      var b64 = await decryptSecretB64();
      if (!b64) return null;
      var secret = b64decode(b64);
      if (secret.length !== 64 && secret.length !== 32) return null;
      var kp = secret.length === 64
        ? web3.Keypair.fromSecretKey(secret)
        : web3.Keypair.fromSeed(secret);
      state.solKeypair = kp;
      state.solAddress = kp.publicKey.toString();
      try { localStorage.setItem(PK_KEY, state.solAddress); } catch (e) {}
      return kp;
    } catch (e) {
      console.warn('[Sol] load encrypted key failed', e);
      return null;
    }
  }

  /** Ensure in-app Solana key exists. Persistence requires an unlocked PIN vault. */
  window.ensureSolanaWallet = async function (opts) {
    opts = opts || {};
    if (state.solKeypair && state.solAddress) return state.solAddress;

    // Existing legacy secret can be migrated only after PIN unlock.
    if (hasPinVault() && PinCrypto._sessionKey) {
      try { await window.migrateSolanaSecretToVault(); } catch (e) {}
    }

    var existing = await loadKeypairFromStorage();
    if (existing) return state.solAddress;

    // Do not silently create a wallet that cannot be persisted. Require PIN first.
    if (!hasPinVault() || !PinCrypto._sessionKey) {
      throw new Error('Wallet Solana memerlukan PIN aktif dan sudah dibuka');
    }

    var web3 = await loadWeb3();
    var kp = web3.Keypair.generate();
    await saveKeypair(kp);
    if (opts.quiet !== true && typeof showToast === 'function') {
      showToast('Wallet Solana dibuat dan disimpan terenkripsi', 'success');
    }
    return state.solAddress;
  };

  /** Export secret (JSON array) — explicit user action only. */
  window.exportSolanaSecret = async function () {
    await window.ensureSolanaWallet({ quiet: true });
    if (!state.solKeypair) throw new Error('Tidak ada key Solana');
    var arr = Array.from(state.solKeypair.secretKey);
    var json = JSON.stringify(arr);
    try {
      await navigator.clipboard.writeText(json);
      if (typeof showToast === 'function') {
        showToast('Secret Solana disalin (JSON) — simpan offline!', 'warn');
      }
    } catch (e) {
      if (typeof showToast === 'function') showToast('Salin manual dari clipboard gagal', 'warn');
    }
    return json;
  };

  // Keep importSolanaKey working; persistence is encrypted and requires an unlocked PIN.
  var _prevImport = window.importSolanaKey;
  window.importSolanaKey = async function (secret) {
    if (!hasPinVault() || !PinCrypto._sessionKey) {
      throw new Error('Atur dan buka PIN sebelum mengimpor wallet Solana');
    }
    if (typeof _prevImport === 'function') {
      try {
        var addr = await _prevImport(secret);
        if (state.solKeypair) await saveKeypair(state.solKeypair);
        return addr;
      } catch (e) {
        /* fall through to local parser */
      }
    }
    var web3 = await loadWeb3();
    secret = String(secret || '').trim();
    var kp;
    if (secret.startsWith('[')) {
      var arr = JSON.parse(secret);
      kp = web3.Keypair.fromSecretKey(Uint8Array.from(arr));
    } else {
      try {
        var u8 = b64decode(secret);
        kp = u8.length === 64 ? web3.Keypair.fromSecretKey(u8) : web3.Keypair.fromSeed(u8.slice(0, 32));
      } catch (e2) {
        throw new Error('Format secret tidak dikenali (pakai JSON array 64-byte)');
      }
    }
    await saveKeypair(kp);
    if (typeof showToast === 'function') {
      showToast('Solana diimpor dan disimpan terenkripsi: ' + state.solAddress.slice(0, 4) + '…', 'success');
    }
    return state.solAddress;
  };

  async function rpcCall(method, params) {
    var body = JSON.stringify({ jsonrpc: '2.0', id: 1, method: method, params: params || [] });
    var lastErr = null;
    for (var i = 0; i < RPCS.length; i++) {
      try {
        var res = await fetch(RPCS[i], {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: body
        });
        if (!res.ok) {
          lastErr = new Error('RPC ' + res.status);
          continue;
        }
        var data = await res.json();
        if (data.error) {
          lastErr = new Error(data.error.message || 'RPC error');
          continue;
        }
        return data.result;
      } catch (e) {
        lastErr = e;
      }
    }
    throw lastErr || new Error('Semua RPC Solana gagal');
  }

  window.refreshSolanaBalances = async function () {
    if (!isSol()) return;
    await window.ensureSolanaWallet({ quiet: true });
    var owner = state.solAddress;
    if (!owner) return;

    try {
      // Native SOL
      var lamports = await rpcCall('getBalance', [owner, { commitment: 'confirmed' }]);
      var solBal = (lamports && typeof lamports.value === 'number')
        ? lamports.value / 1e9
        : (typeof lamports === 'number' ? lamports / 1e9 : 0);
      if (!state.balances) state.balances = {};
      state.balances.SOL = solBal;

      // SPL token accounts
      var tokRes = await rpcCall('getTokenAccountsByOwner', [
        owner,
        { programId: TOKEN_PROGRAM },
        { encoding: 'jsonParsed', commitment: 'confirmed' }
      ]);
      var accounts = (tokRes && tokRes.value) || [];
      var mintBal = {};
      accounts.forEach(function (acc) {
        try {
          var info = acc.account.data.parsed.info;
          var mint = info.mint;
          var amt = info.tokenAmount;
          var ui = amt.uiAmount != null ? Number(amt.uiAmount) : Number(amt.amount) / Math.pow(10, amt.decimals || 0);
          mintBal[mint] = (mintBal[mint] || 0) + (ui || 0);
        } catch (e) {}
      });

      // Map to state.tokens
      if (state.tokens && state.tokens.length) {
        state.tokens.forEach(function (t) {
          if (t.id === 'SOL') {
            state.balances.SOL = solBal;
            return;
          }
          var mint = t.mint || t.address;
          if (mint && mintBal[mint] != null) {
            state.balances[t.id] = mintBal[mint];
          } else if (mint) {
            state.balances[t.id] = state.balances[t.id] || 0;
          }
        });
      }

      try {
        if (typeof renderHome === 'function') renderHome();
        if (typeof renderSwapUI === 'function') renderSwapUI();
      } catch (e) {}
    } catch (e) {
      console.warn('[Sol] balance refresh', e);
      if (typeof showToast === 'function') {
        showToast('Gagal muat saldo Solana: ' + String(e.message || e).slice(0, 60), 'warn');
      }
    }
  };

  // Override getReceiveAddress to auto-ensure key
  var _getRecv = window.getReceiveAddress;
  window.getReceiveAddress = function () {
    if (isSol()) {
      if (state.solAddress) return state.solAddress;
      try {
        var pk = localStorage.getItem(PK_KEY);
        if (pk) {
          state.solAddress = pk;
          return pk;
        }
      } catch (e) {}
      // fire and forget ensure
      window.ensureSolanaWallet({ quiet: true }).then(function () {
        try {
          if (typeof window.renderReceive === 'function') window.renderReceive();
          var el = document.getElementById('tdAddr');
          if (el && state.solAddress) {
            el.textContent = state.solAddress.slice(0, 8) + '...' + state.solAddress.slice(-6);
          }
        } catch (e2) {}
      });
      return state.solAddress || '';
    }
    return typeof _getRecv === 'function' ? _getRecv() : (state.address || '');
  };

  // Hook selectNetwork — already allows sol; enhance with ensure + balance
  var _sel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    var r = typeof _sel === 'function' ? await _sel.apply(this, arguments) : null;
    if (id === 'sol' || (state && state.network === 'sol')) {
      try {
        await window.ensureSolanaWallet({ quiet: true });
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens('sol');
        // default swap pair
        state.swapFrom = 'SOL';
        state.swapTo = 'USDC';
        await window.refreshSolanaBalances();
        if (typeof window.renderReceive === 'function') window.renderReceive();
        if (typeof showToast === 'function') {
          var a = state.solAddress || '';
          showToast(
            a ? ('Solana siap · ' + a.slice(0, 4) + '…' + a.slice(-4)) : 'Solana aktif',
            'success'
          );
        }
      } catch (e) {
        console.warn(e);
        if (typeof showToast === 'function') showToast(String(e.message || e).slice(0, 80), 'error');
      }
    }
    return r;
  };

  // Jupiter execute: prefer local keypair, Phantom only as optional fallback
  var _execJup = null;
  // Patch after Jupiter module — re-wrap execute path via executeSwap already checks sol
  // Strengthen: ensure wallet before swap
  var _execSwap = window.executeSwap;
  window.executeSwap = function () {
    if (!isSol()) {
      return typeof _execSwap === 'function' ? _execSwap.apply(this, arguments) : null;
    }
    return (async function () {
      await window.ensureSolanaWallet({ quiet: true });
      if (!state.solKeypair && !state.solProvider) {
        // still allow if only pubkey? need key to sign
        throw new Error('Wallet Solana belum siap');
      }
      // make sure Jupiter module sees address
      if (!state.solAddress && state.solKeypair) {
        state.solAddress = state.solKeypair.publicKey.toString();
      }
      return typeof _execSwap === 'function' ? _execSwap.apply(this, arguments) : null;
    })();
  };

  // Boot: if last network was sol, restore key
  try {
    var lastNet = localStorage.getItem('br_v4_network');
    if (lastNet === 'sol') {
      setTimeout(function () {
        window.ensureSolanaWallet({ quiet: true }).catch(function () {});
      }, 500);
    } else {
      // preload pubkey only
      try {
        var pk = localStorage.getItem(PK_KEY);
        if (pk) state.solAddress = pk;
      } catch (e) {}
    }
  } catch (e) {}

  // Settings helper
  window.solanaWalletInfo = function () {
    return {
      address: state.solAddress || localStorage.getItem(PK_KEY) || null,
      hasSecret: !!localStorage.getItem('br_sec_sol_secret_v1') || !!state.solKeypair,
      network: state.network
    };
  };

  brLog('%cSolana in-wallet ready (no Phantom required)', 'color:#14F195;font-weight:bold');
  console.log('  ensureSolanaWallet() · exportSolanaSecret() · refreshSolanaBalances()');
})();

/* ============================================================
   HOTFIX — 403 / "server response 403" quieter + RPC fallback
   ============================================================ */
(function Fix403Responses() {
  'use strict';

  // Friendlier error map for ethers "server response 403"
  var _map = window.mapTxErrorID;
  window.mapTxErrorID = function (err) {
    var raw = String(
      (err && (err.reason || err.shortMessage || err.message)) || err || ''
    );
    var low = raw.toLowerCase();
    if (/server response\s*403|status code 403|http 403|403 forbidden/.test(low)) {
      return 'RPC ditolak (403) — ganti RPC / coba lagi nanti';
    }
    if (/server response\s*429|429|rate limit|too many requests/.test(low)) {
      return 'Terlalu banyak permintaan — tunggu sebentar';
    }
    if (/cloudflare|cf-ray|attention required/.test(low)) {
      return 'Akses API diblokir sementara — coba lagi';
    }
    if (typeof _map === 'function') return _map(err);
    return raw.slice(0, 140);
  };

  // Throttle identical error toasts (avoid spam on every refresh)
  var _lastErrToast = { msg: '', at: 0 };
  var _st = window.showToast;
  if (typeof _st === 'function') {
    window.showToast = function (msg, type, dur, sub) {
      var m = String(msg || '');
      var low = (m + ' ' + (sub || '')).toLowerCase();
      if (/server response\s*403|rpc ditolak \(403\)|http 403/.test(low)) {
        // Rate-limit 403 toasts: max 1 per 45s
        if (_lastErrToast.msg === '403' && Date.now() - _lastErrToast.at < 45000) {
          return;
        }
        _lastErrToast = { msg: '403', at: Date.now() };
        return _st(
          'RPC/API sementara ditolak',
          'warn',
          3500,
          'Coba refresh atau ganti jaringan'
        );
      }
      // Don't surface raw CoinGecko / price noise
      if (/coingecko|simple\/price/.test(low) && /403|429/.test(low)) {
        return;
      }
      return _st(msg, type, dur, sub);
    };
  }

  // Stronger public RPC lists (browser-friendly)
  var BETTER_RPC = {
    base: [
      'https://mainnet.base.org',
      'https://base.llamarpc.com',
      'https://1rpc.io/base',
      'https://base.meowrpc.com',
      'https://base.publicnode.com'
    ],
    eth: [
      'https://ethereum.publicnode.com',
      'https://eth.llamarpc.com',
      'https://1rpc.io/eth',
      'https://rpc.mevblocker.io'
    ],
    bnb: [
      'https://bsc-dataseed.binance.org',
      'https://bsc.publicnode.com',
      'https://1rpc.io/bnb'
    ],
    pol: [
      'https://polygon-rpc.com',
      'https://polygon.llamarpc.com',
      'https://1rpc.io/matic'
    ],
    arb: [
      'https://arb1.arbitrum.io/rpc',
      'https://arbitrum.llamarpc.com',
      'https://1rpc.io/arb'
    ],
    op: [
      'https://mainnet.optimism.io',
      'https://optimism.llamarpc.com',
      'https://1rpc.io/op'
    ]
  };

  function mergeRpc(netId) {
    var better = BETTER_RPC[netId] || BETTER_RPC.base;
    var cur = (typeof RPCS !== 'undefined' && RPCS && RPCS.length) ? RPCS.slice() : [];
    var out = [];
    better.concat(cur).forEach(function (u) {
      if (u && out.indexOf(u) < 0) out.push(u);
    });
    return out;
  }

  // Patch provider fallback to skip 403 endpoints quickly
  var _gpf = window.getProviderWithFallback || window.getProvider;
  if (typeof _gpf === 'function') {
    window.getProviderWithFallback = async function (force) {
      var net = (state && state.network) || 'base';
      if (net === 'sol') {
        // Solana has no ethers provider
        throw new Error('Solana tidak memakai provider EVM');
      }
      var list = mergeRpc(net);
      try {
        // Prefer global RPCS updated
        if (typeof RPCS !== 'undefined') RPCS = list;
      } catch (e) {}

      var lastErr = null;
      for (var i = 0; i < list.length; i++) {
        try {
          var url = list[i];
          var p = new ethers.JsonRpcProvider(url, typeof getChainIdNum === 'function' ? getChainIdNum() : 8453, {
            staticNetwork: true
          });
          // quick health check with short timeout
          var ctrl = new AbortController();
          var to = setTimeout(function () { ctrl.abort(); }, 3500);
          var res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'eth_blockNumber', params: [] }),
            signal: ctrl.signal
          });
          clearTimeout(to);
          if (res.status === 403 || res.status === 401 || res.status === 429) {
            lastErr = new Error('server response ' + res.status);
            continue;
          }
          if (!res.ok) {
            lastErr = new Error('server response ' + res.status);
            continue;
          }
          // warm provider
          await p.getBlockNumber();
          try {
            window._provider = p;
            window._providerNet = net;
          } catch (e) {}
          return p;
        } catch (e) {
          lastErr = e;
        }
      }
      // fall back to original implementation
      try {
        return await _gpf.call(this, force);
      } catch (e2) {
        throw lastErr || e2;
      }
    };
    window.getProvider = function (force) {
      return window.getProviderWithFallback(force);
    };
  }

  // CoinGecko often 403 from browser — prefer Binance + DefiLlama
  var _fp = typeof fetchPrices === 'function' ? fetchPrices : null;
  window.fetchPrices = async function () {
    if (!state.prices) state.prices = {};
    if (!state.changes) state.changes = {};
    var got = false;

    // 1) DefiLlama (usually open CORS)
    try {
      var coins = [];
      var idMap = {}; // llama key -> token ids
      (state.tokens || []).forEach(function (t) {
        var cg = t.cg || t.coingecko;
        if (!cg) return;
        // llama uses coingecko:ID
        var key = 'coingecko:' + cg;
        if (!idMap[key]) idMap[key] = [];
        idMap[key].push(t.id);
        if (coins.indexOf(key) < 0) coins.push(key);
      });
      if (coins.length) {
        var url =
          'https://coins.llama.fi/prices/current/' +
          encodeURIComponent(coins.join(','));
        var res = await fetch(url, {
          signal: AbortSignal.timeout(8000),
          headers: { Accept: 'application/json' }
        });
        if (res.ok) {
          var data = await res.json();
          var prices = (data && data.coins) || {};
          Object.keys(idMap).forEach(function (k) {
            var p = prices[k];
            if (p && p.price != null) {
              idMap[k].forEach(function (tid) {
                state.prices[tid] = p.price;
                got = true;
              });
            }
          });
        }
      }
    } catch (e) {
      console.log('defillama prices', e && e.message);
    }

    // 2) Binance for majors
    try {
      var pairs = {
        ETH: 'ETHUSDT',
        WETH: 'ETHUSDT',
        BNB: 'BNBUSDT',
        SOL: 'SOLUSDT',
        MATIC: 'MATICUSDT',
        POL: 'MATICUSDT',
        AVAX: 'AVAXUSDT',
        USDC: 'USDCUSDT',
        USDT: 'USDTUSDT'
      };
      await Promise.all(
        Object.keys(pairs).map(async function (sym) {
          if (!(state.tokens || []).some(function (t) { return t.id === sym || t.symbol === sym; })) {
            // still set if symbol used
          }
          try {
            var r = await fetch(
              'https://api.binance.com/api/v3/ticker/24hr?symbol=' + pairs[sym],
              { signal: AbortSignal.timeout(5000) }
            );
            if (!r.ok) return;
            var d = await r.json();
            if (d.lastPrice) {
              state.prices[sym] = parseFloat(d.lastPrice);
              // also map by token id matching symbol
              (state.tokens || []).forEach(function (t) {
                if (t.symbol === sym || t.id === sym) state.prices[t.id] = parseFloat(d.lastPrice);
              });
              got = true;
            }
            if (d.priceChangePercent != null) {
              state.changes[sym] = parseFloat(d.priceChangePercent);
              (state.tokens || []).forEach(function (t) {
                if (t.symbol === sym || t.id === sym) {
                  state.changes[t.id] = parseFloat(d.priceChangePercent);
                }
              });
            }
          } catch (e) {}
        })
      );
    } catch (e) {}

    // 3) Original CoinGecko path only if nothing worked
    if (!got && typeof _fp === 'function') {
      try {
        await _fp();
      } catch (e) {
        console.log('coingecko fallback', e && e.message);
      }
    }

    // Stables default
    ['USDC', 'USDT', 'DAI', 'BUSD'].forEach(function (s) {
      if (state.prices[s] == null) state.prices[s] = 1;
    });
  };

  // Solana RPC: prefer publicnode, soft 403 toast on balance refresh
  var _solBal = window.refreshSolanaBalances;
  if (typeof _solBal === 'function') {
    window.refreshSolanaBalances = async function () {
      try {
        return await _solBal.apply(this, arguments);
      } catch (e) {
        var m = String((e && e.message) || e);
        if (/403|401|429/.test(m)) {
          console.warn('[Sol] RPC limited', m);
          return;
        }
        throw e;
      }
    };
  }

  brLog('%c403 hotfix · RPC fallback · DefiLlama prices', 'color:#f0b90b;font-weight:bold');
})();

/* ============================================================
   HOTFIX Solana UX — RPC, QR, explorer, add token
   ============================================================ */
(function SolanaUxFix() {
  'use strict';

  function isSol() {
    return (state && state.network) === 'sol';
  }

  /* ---- Better Solana RPC list (rotate on 403) ---- */
  var SOL_RPCS = [
    'https://solana-rpc.publicnode.com',
    'https://solana.drpc.org',
    'https://api.mainnet-beta.solana.com',
    'https://endpoints.omniatech.io/v1/sol/mainnet/public',
    'https://solana-mainnet.rpc.extrnode.com',
    'https://rpc.ankr.com/solana',
    'https://1rpc.io/sol',
    'https://solana.public-rpc.com'
  ];
  var _rpcIdx = 0;

  async function solRpc(method, params) {
    var lastErr = null;
    var pool = SOL_RPCS.slice();
    try {
      // Prefer saved custom Sol RPC without recursive getRpcList
      var saved = localStorage.getItem('br_sol_rpc_v1');
      if (saved) {
        var arr = JSON.parse(saved);
        if (Array.isArray(arr) && arr.length) pool = arr.concat(pool.filter(function(u){ return arr.indexOf(u)<0; }));
      }
      var active = localStorage.getItem('br_active_rpc_sol');
      if (active) pool = [active].concat(pool.filter(function(u){ return u !== active; }));
    } catch (e) {}
    if (!pool.length) pool = SOL_RPCS.slice();

    for (var n = 0; n < pool.length; n++) {
      var i = (_rpcIdx + n) % pool.length;
      var url = pool[i];
      try {
        var ctrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
        var to = setTimeout(function () { try { if (ctrl) ctrl.abort(); } catch (e) {} }, 8000);
        var res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
          body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: method, params: params || [] }),
          signal: ctrl ? ctrl.signal : undefined
        });
        clearTimeout(to);
        if (res.status === 403 || res.status === 401 || res.status === 429) {
          lastErr = new Error('RPC ' + res.status);
          continue;
        }
        if (!res.ok) {
          lastErr = new Error('RPC ' + res.status);
          continue;
        }
        var data = await res.json();
        if (data && data.error) {
          lastErr = new Error((data.error && data.error.message) || 'RPC error');
          continue;
        }
        _rpcIdx = i;
        return data ? data.result : null;
      } catch (e) {
        lastErr = e;
      }
    }
    throw lastErr || new Error('Semua RPC Solana gagal');
  }

  // Replace balance refresh with multi-RPC version (quiet on total failure)
  window.refreshSolanaBalances = async function () {
    if (!isSol()) return;
    if (typeof window.ensureSolanaWallet === 'function') {
      await window.ensureSolanaWallet({ quiet: true });
    }
    var owner = state.solAddress || (typeof window.getReceiveAddress === 'function' ? window.getReceiveAddress() : '');
    if (!owner) return;

    try {
      var balRes = await solRpc('getBalance', [owner, { commitment: 'confirmed' }]);
      var lamports = balRes && typeof balRes.value === 'number' ? balRes.value : (typeof balRes === 'number' ? balRes : 0);
      var solBal = lamports / 1e9;
      if (!state.balances) state.balances = {};
      state.balances.SOL = solBal;

      var tokRes = await solRpc('getTokenAccountsByOwner', [
        owner,
        { programId: 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA' },
        { encoding: 'jsonParsed', commitment: 'confirmed' }
      ]);
      var accounts = (tokRes && tokRes.value) || [];
      var mintBal = {};
      accounts.forEach(function (acc) {
        try {
          var info = acc.account.data.parsed.info;
          var mint = info.mint;
          var amt = info.tokenAmount;
          var ui = amt.uiAmount != null ? Number(amt.uiAmount) : Number(amt.amount) / Math.pow(10, amt.decimals || 0);
          mintBal[mint] = (mintBal[mint] || 0) + (ui || 0);
        } catch (e) {}
      });
      (state.tokens || []).forEach(function (t) {
        if (t.id === 'SOL') {
          state.balances.SOL = solBal;
          return;
        }
        var mint = t.mint || t.address;
        if (mint && mintBal[mint] != null) state.balances[t.id] = mintBal[mint];
      });
      try {
        if (typeof renderHome === 'function') renderHome();
      } catch (e) {}
    } catch (e) {
      console.warn('[Sol] balance', e);
      // Quiet toast — only once per minute
      var now = Date.now();
      if (!window._solBalErrAt || now - window._solBalErrAt > 60000) {
        window._solBalErrAt = now;
        if (typeof showToast === 'function') {
          showToast('Saldo Solana sementara tidak tersedia', 'warn', 3200, 'RPC publik sibuk — coba lagi nanti');
        }
      }
    }
  };

  /* ---- Explorer: Solscan when on Solana ---- */
  function explorerBase() {
    if (isSol()) return 'https://solscan.io';
    try {
      if (typeof currentNet === 'function' && currentNet() && currentNet().explorer) {
        return currentNet().explorer;
      }
    } catch (e) {}
    return 'https://basescan.org';
  }

  window.openExplorerAddr = function () {
    var addr = isSol()
      ? (state.solAddress || (typeof getReceiveAddress === 'function' ? getReceiveAddress() : ''))
      : state.address;
    if (!addr) return;
    var url = isSol()
      ? 'https://solscan.io/account/' + addr
      : explorerBase() + '/address/' + addr;
    if (typeof brOpen === 'function') brOpen(url);
    else window.open(url, '_blank');
  };

  window.openExplorer = function () {
    window.openExplorerAddr();
  };

  window.openExplorerTx = function (hash) {
    if (!hash) return;
    var url = isSol()
      ? 'https://solscan.io/tx/' + hash
      : explorerBase() + '/tx/' + hash;
    if (typeof brOpen === 'function') brOpen(url);
    else window.open(url, '_blank');
  };

  function updateReceiveExplorerUi() {
    // Button label under receive
    var buttons = document.querySelectorAll('#screen-receive button, #screen-receive .btn');
    buttons.forEach(function (btn) {
      var t = (btn.textContent || '').trim();
      if (/Basescan|Solscan|Explorer|explorer/i.test(t) || /Lihat di/i.test(t)) {
        btn.textContent = isSol() ? 'Lihat di Solscan' : 'Lihat di Basescan';
        btn.onclick = function () {
          window.openExplorerAddr();
        };
      }
    });
    // Warning footer
    var hints = document.querySelectorAll('#screen-receive p, #screen-receive .hint, #screen-receive .receive-warn');
    hints.forEach(function (el) {
      var t = el.textContent || '';
      if (/Hanya terima aset|Jaringan lain dapat|Base\./i.test(t)) {
        if (isSol()) {
          el.innerHTML =
            'Hanya terima aset di jaringan <strong style="color:#14F195">Solana</strong>. Kirim token SPL/SOL saja.';
        } else {
          el.innerHTML =
            'Hanya terima aset di jaringan <strong style="color:#00c9a0">Base</strong>. Jaringan lain dapat menyebabkan kehilangan dana.';
        }
      }
    });
  }

  /* ---- Reliable QR (no logo on Solana — avoids blank) ---- */
  function drawSimpleQr(hostId, data) {
    var host = document.getElementById(hostId);
    if (!host || !data) return;
    host.innerHTML = '';
    host.style.cssText =
      'width:200px;height:200px;margin:0 auto;background:#fff;border-radius:16px;display:flex;align-items:center;justify-content:center;overflow:hidden';

    var canvas = document.createElement('canvas');
    canvas.width = 200;
    canvas.height = 200;
    host.appendChild(canvas);

    function fail(msg) {
      var ctx = canvas.getContext('2d');
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, 200, 200);
      ctx.fillStyle = '#333';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(msg || 'QR gagal', 100, 100);
    }

    if (typeof QRCode === 'undefined') {
      // load qrcode lib from CDN once
      if (!window._qrLoading) {
        window._qrLoading = true;
        var s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js';
        s.onload = function () {
          window._qrLoading = false;
          drawSimpleQr(hostId, data);
        };
        s.onerror = function () {
          window._qrLoading = false;
          fail('QR lib error');
        };
        document.head.appendChild(s);
      } else {
        setTimeout(function () {
          drawSimpleQr(hostId, data);
        }, 300);
      }
      return;
    }

    QRCode.toCanvas(
      canvas,
      data,
      {
        width: 200,
        margin: 2,
        color: { dark: '#0a1628', light: '#ffffff' },
        errorCorrectionLevel: 'M'
      },
      function (err) {
        if (err) {
          console.warn('QR', err);
          fail('Gagal QR');
        }
      }
    );
  }

  window.renderReceive = function () {
    var addr = typeof window.getReceiveAddress === 'function' ? window.getReceiveAddress() : state.address || '';
    if (isSol() && !addr) {
      if (typeof window.ensureSolanaWallet === 'function') {
        window.ensureSolanaWallet({ quiet: true }).then(function () {
          window.renderReceive();
        });
      }
      addr = state.solAddress || '';
    }

    var addrEl = document.getElementById('receiveAddr');
    if (addrEl) addrEl.textContent = addr || (isSol() ? 'Menyiapkan alamat Solana…' : '—');

    // Network hint
    var hint = document.getElementById('receiveNetHint');
    if (!hint && addrEl && addrEl.parentNode) {
      hint = document.createElement('p');
      hint.id = 'receiveNetHint';
      hint.style.cssText = 'margin:8px 0 0;font-size:12px;text-align:center;color:#14F195';
      addrEl.parentNode.insertBefore(hint, addrEl.nextSibling);
    }
    if (hint) {
      if (isSol()) {
        hint.textContent = 'Jaringan Solana · kirim hanya SOL / SPL ke alamat ini';
        hint.style.color = '#14F195';
      } else {
        hint.textContent = 'Jaringan ' + ((state && state.network) || 'base').toUpperCase() + ' · alamat EVM';
        hint.style.color = '';
      }
    }

    if (addr) {
      drawSimpleQr('qrCanvasHost', addr);
      // also hidden canvas for compatibility
      var canvas = document.getElementById('qrCanvas');
      if (canvas && typeof QRCode !== 'undefined') {
        try {
          QRCode.toCanvas(canvas, addr, { width: 200, margin: 2, errorCorrectionLevel: 'M' }, function () {});
        } catch (e) {}
      }
    }

    updateReceiveExplorerUi();
  };

  /* ---- Add SPL token by mint ---- */
  var _addTok = typeof addCustomToken === 'function' ? addCustomToken : null;
  window.addCustomToken = async function () {
    if (!isSol()) {
      if (typeof _addTok === 'function') return _addTok.apply(this, arguments);
      return;
    }
    var addrEl = document.getElementById('addTokenAddr');
    var symEl = document.getElementById('addTokenSym');
    var decEl = document.getElementById('addTokenDec');
    var mint = ((addrEl && addrEl.value) || '').trim();
    if (!mint || mint.length < 32) {
      if (typeof showToast === 'function') showToast('Masukkan mint address Solana', 'warn');
      return;
    }
    // basic base58 check
    if (!/^[1-9A-HJ-NP-Za-km-z]+$/.test(mint)) {
      if (typeof showToast === 'function') showToast('Mint Solana tidak valid', 'error');
      return;
    }
    var symbol = ((symEl && symEl.value) || '').trim().toUpperCase() || mint.slice(0, 4).toUpperCase();
    var decimals = parseInt((decEl && decEl.value) || '9', 10) || 9;
    var id = symbol + '_' + mint.slice(0, 4);
    if ((state.tokens || []).some(function (t) { return (t.mint || t.address) === mint; })) {
      if (typeof showToast === 'function') showToast('Token sudah ada', 'warn');
      return;
    }
    // Try fetch decimals from chain
    try {
      var info = await solRpc('getAccountInfo', [mint, { encoding: 'jsonParsed' }]);
      if (info && info.value && info.value.data && info.value.data.parsed) {
        var p = info.value.data.parsed;
        if (p.type === 'mint' && p.info && p.info.decimals != null) {
          decimals = p.info.decimals;
        }
      }
    } catch (e) {}

    state.tokens.push({
      id: id,
      symbol: symbol,
      name: symbol,
      decimals: decimals,
      address: mint,
      mint: mint,
      icon: '',
      cg: null
    });
    try {
      if (typeof persistWallet === 'function') persistWallet();
    } catch (e) {}
    if (typeof closeModal === 'function') closeModal();
    if (typeof showToast === 'function') showToast(symbol + ' ditambahkan (Solana)', 'success');
    try {
      await window.refreshSolanaBalances();
    } catch (e) {}
    if (typeof renderHome === 'function') renderHome();
  };

  // Open add-token modal with Solana-aware labels
  var _openAdd = window.openAddToken;
  window.openAddToken = function () {
    if (typeof _openAdd === 'function') {
      _openAdd.apply(this, arguments);
    } else {
      // minimal modal
      var html =
        '<h3>Tambah Token</h3>' +
        '<div class="field"><label id="addTokLabel">Mint address</label>' +
        '<input id="addTokenAddr" placeholder="Mint SPL…"></div>' +
        '<div class="field"><label>Symbol (opsional)</label>' +
        '<input id="addTokenSym" placeholder="USDC"></div>' +
        '<div class="field"><label>Decimals</label>' +
        '<input id="addTokenDec" type="number" value="9"></div>' +
        '<button class="btn btn-primary" style="max-width:none;margin-top:10px" onclick="addCustomToken()">Tambah</button>';
      if (typeof openModal === 'function') openModal(html);
    }
    setTimeout(function () {
      if (!isSol()) return;
      var lab = document.getElementById('addTokLabel');
      if (lab) lab.textContent = 'Mint address (Solana)';
      var inp = document.getElementById('addTokenAddr');
      if (inp) {
        inp.placeholder = 'Contoh: EPjFWdd5… (USDC mint)';
      }
      var dec = document.getElementById('addTokenDec');
      if (dec && !dec.value) dec.value = '9';
    }, 50);
  };

  // When switching to receive / sol network refresh UI
  var _ss = window.showScreen;
  if (typeof _ss === 'function') {
    window.showScreen = function (name) {
      var r = _ss.apply(this, arguments);
      if (name === 'receive') {
        setTimeout(function () {
          try {
            window.renderReceive();
            updateReceiveExplorerUi();
          } catch (e) {}
        }, 60);
      }
      return r;
    };
  }

  // Patch selectNetwork end for sol
  var _sel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    var r = typeof _sel === 'function' ? await _sel.apply(this, arguments) : null;
    if (id === 'sol' || isSol()) {
      setTimeout(function () {
        try {
          updateReceiveExplorerUi();
          if (typeof window.renderReceive === 'function') window.renderReceive();
        } catch (e) {}
      }, 300);
    }
    return r;
  };

  brLog('%cSolana UX fix · multi-RPC · QR · Solscan · SPL token', 'color:#14F195;font-weight:bold');
})();

/* ============================================================
   RPC Config + Solana Wallet Adapter
   ============================================================ */
(function RpcAndWalletAdapter() {
  'use strict';

  var RPC_STORE = 'br_custom_rpc_v1';
  var SOL_RPC_STORE = 'br_sol_rpc_v1';

  var DEFAULT_SOL_RPCS = [
    'https://solana.drpc.org',
    'https://solana-rpc.publicnode.com',
    'https://api.mainnet-beta.solana.com',
    'https://rpc.ankr.com/solana',
    'https://1rpc.io/sol',
    'https://solana.public-rpc.com'
  ];

  var DEFAULT_EVM_RPC = {
    base: ['https://mainnet.base.org', 'https://base.llamarpc.com', 'https://1rpc.io/base', 'https://base.publicnode.com'],
    eth: ['https://ethereum.publicnode.com', 'https://eth.llamarpc.com', 'https://1rpc.io/eth'],
    bnb: ['https://bsc-dataseed.binance.org', 'https://bsc.publicnode.com', 'https://1rpc.io/bnb'],
    pol: ['https://polygon-rpc.com', 'https://polygon.llamarpc.com', 'https://1rpc.io/matic'],
    arb: ['https://arb1.arbitrum.io/rpc', 'https://arbitrum.llamarpc.com', 'https://1rpc.io/arb'],
    op: ['https://mainnet.optimism.io', 'https://optimism.llamarpc.com', 'https://1rpc.io/op'],
    avax: ['https://api.avax.network/ext/bc/C/rpc', 'https://avalanche.public-rpc.com']
  };

  function loadRpcMap() {
    try {
      return JSON.parse(localStorage.getItem(RPC_STORE) || '{}') || {};
    } catch (e) {
      return {};
    }
  }
  function saveRpcMap(map) {
    try {
      localStorage.setItem(RPC_STORE, JSON.stringify(map));
    } catch (e) {}
  }

  function loadSolRpcList() {
    try {
      var arr = JSON.parse(localStorage.getItem(SOL_RPC_STORE) || 'null');
      if (Array.isArray(arr) && arr.length) return arr;
    } catch (e) {}
    return DEFAULT_SOL_RPCS.slice();
  }
  function saveSolRpcList(list) {
    try {
      localStorage.setItem(SOL_RPC_STORE, JSON.stringify(list));
    } catch (e) {}
  }

  /** Public: get ordered RPC URLs for current / given network */
  window.getRpcList = function (netId) {
    netId = netId || (state && state.network) || 'base';
    if (netId === 'sol') return loadSolRpcList();
    var custom = loadRpcMap();
    var base = (DEFAULT_EVM_RPC[netId] || DEFAULT_EVM_RPC.base).slice();
    var extra = custom[netId] || [];
    var out = [];
    [].concat(extra, base).forEach(function (u) {
      if (u && out.indexOf(u) < 0) out.push(u);
    });
    return out;
  };

  window.setCustomRpc = function (netId, url) {
    netId = netId || (state && state.network) || 'base';
    url = String(url || '').trim();
    if (!url) return false;
    if (netId === 'sol') {
      var list = loadSolRpcList();
      list = [url].concat(list.filter(function (x) { return x !== url; }));
      saveSolRpcList(list);
      if (typeof showToast === 'function') showToast('RPC Solana diset', 'success');
      return true;
    }
    var map = loadRpcMap();
    var arr = map[netId] || [];
    arr = [url].concat(arr.filter(function (x) { return x !== url; }));
    map[netId] = arr.slice(0, 6);
    saveRpcMap(map);
    // apply live
    try {
      if (typeof RPCS !== 'undefined') RPCS = window.getRpcList(netId);
      window._provider = null;
      window._providerNet = null;
    } catch (e) {}
    if (typeof showToast === 'function') showToast('RPC ' + netId + ' diset', 'success');
    return true;
  };

  window.resetRpc = function (netId) {
    netId = netId || (state && state.network) || 'base';
    if (netId === 'sol') {
      try { localStorage.removeItem(SOL_RPC_STORE); } catch (e) {}
      if (typeof showToast === 'function') showToast('RPC Solana direset', 'success');
      return;
    }
    var map = loadRpcMap();
    delete map[netId];
    saveRpcMap(map);
    try {
      if (typeof RPCS !== 'undefined') RPCS = window.getRpcList(netId);
      window._provider = null;
    } catch (e) {}
    if (typeof showToast === 'function') showToast('RPC direset ke default', 'success');
  };

  window.testRpc = async function (url) {
    url = String(url || '').trim();
    if (!url) return { ok: false, ms: 0, error: 'empty' };
    var t0 = Date.now();
    try {
      var isSol = /solana|sol\b/i.test(url) || (state && state.network === 'sol');
      var body = isSol
        ? { jsonrpc: '2.0', id: 1, method: 'getHealth', params: [] }
        : { jsonrpc: '2.0', id: 1, method: 'eth_blockNumber', params: [] };
      // some sol endpoints don't support getHealth — fallback getVersion
      var res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(6000)
      });
      var ms = Date.now() - t0;
      if (!res.ok) {
        // retry sol with getSlot
        if (isSol) {
          var res2 = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'getSlot', params: [] }),
            signal: AbortSignal.timeout(6000)
          });
          ms = Date.now() - t0;
          if (!res2.ok) return { ok: false, ms: ms, error: 'HTTP ' + res2.status };
          var j2 = await res2.json();
          if (j2.error) return { ok: false, ms: ms, error: j2.error.message };
          return { ok: true, ms: ms };
        }
        return { ok: false, ms: ms, error: 'HTTP ' + res.status };
      }
      var j = await res.json();
      if (j.error) return { ok: false, ms: ms, error: j.error.message };
      return { ok: true, ms: ms };
    } catch (e) {
      return { ok: false, ms: Date.now() - t0, error: String(e.message || e) };
    }
  };

  /* ---- Settings modal: RPC ---- */
  window.openRpcSettings = function () {
    var net = (state && state.network) || 'base';
    var list = window.getRpcList(net);
    var html = '<div class="modal-handle"></div>';
    html += '<h3 style="margin:0 0 6px">Konfigurasi RPC</h3>';
    html += '<p class="hint" style="margin:0 0 12px">Jaringan: <b id="rpcNetLabel">' + net + '</b></p>';
    html += '<div class="field"><label>RPC URL kustom</label>';
    html += '<input id="rpcCustomInput" placeholder="https://…" style="width:100%"></div>';
    html += '<div style="display:flex;gap:8px;margin:8px 0 14px">';
    html += '<button class="btn btn-primary" style="flex:1" onclick="(async function(){var u=document.getElementById(\'rpcCustomInput\').value;if(!u)return showToast(\'Isi URL\',\'warn\');var r=await testRpc(u);if(!r.ok)return showToast(\'RPC gagal: \'+(r.error||\'\'),\'error\');setCustomRpc(state.network,u);openRpcSettings();})()">Tes & Simpan</button>';
    html += '<button class="btn btn-ghost" style="flex:1" onclick="resetRpc(state.network);openRpcSettings()">Reset</button>';
    html += '</div>';
    html += '<div style="font-size:.72rem;font-weight:700;color:#9ca3af;margin:0 0 6px">DAFTAR RPC AKTIF</div>';
    html += '<div style="display:flex;flex-direction:column;gap:6px;max-height:240px;overflow:auto">';
    list.forEach(function (u, idx) {
      html +=
        '<div class="aw-item" style="align-items:flex-start;cursor:default">' +
        '<div class="aw-text" style="text-align:left;margin:0">' +
        '<div class="aw-title" style="font-size:12px;word-break:break-all">' +
        (idx === 0 ? '★ ' : '') +
        u +
        '</div>' +
        '<div class="aw-desc"><button type="button" class="btn btn-ghost btn-sm" data-test-rpc="' +
        u.replace(/"/g, '') +
        '">Tes latensi</button></div></div></div>';
    });
    html += '</div>';
    if (typeof openModal === 'function') openModal(html);
    setTimeout(function () {
      document.querySelectorAll('[data-test-rpc]').forEach(function (btn) {
        btn.onclick = async function () {
          var url = btn.getAttribute('data-test-rpc');
          btn.textContent = '…';
          var r = await window.testRpc(url);
          btn.textContent = r.ok ? r.ms + ' ms ✓' : 'Gagal';
          btn.style.color = r.ok ? '#00c9a0' : '#f87171';
        };
      });
    }, 50);
  };

  // Inject entry into settings screen if present
  function injectSettingsRow() {
    var screen = document.getElementById('screen-settings');
    if (!screen || document.getElementById('brRpcSettingsRow')) return;
    var row = document.createElement('div');
    row.id = 'brRpcSettingsRow';
    row.className = 'set-row';
    row.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:14px 16px;cursor:pointer;border-bottom:1px solid rgba(255,255,255,.06)';
    row.innerHTML =
      '<div><div style="font-weight:600">RPC / Network</div><div style="font-size:12px;opacity:.65">Ganti endpoint RPC · tes latensi</div></div><span style="opacity:.5">›</span>';
    row.onclick = function () {
      window.openRpcSettings();
    };
    // prefer inside settings list
    var list = screen.querySelector('.set-list, .settings-list, .acc-list') || screen;
    list.appendChild(row);

    var row2 = document.createElement('div');
    row2.id = 'brWalletAdapterRow';
    row2.style.cssText = row.style.cssText;
    row2.innerHTML =
      '<div><div style="font-weight:600">Wallet Adapter (Solana)</div><div style="font-size:12px;opacity:.65">In-app · Phantom · Solflare</div></div><span style="opacity:.5">›</span>';
    row2.onclick = function () {
      window.openSolanaWalletPicker();
    };
    list.appendChild(row2);
  }

  /* ============================================================
     Solana Wallet Adapter (injected wallets + in-app)
     ============================================================ */
  var _adapter = {
    name: 'in-app',
    publicKey: null,
    provider: null
  };

  function detectSolWallets() {
    var list = [];
    list.push({ id: 'in-app', name: 'BaseRocky (in-app)', icon: '🔐' });
    try {
      if (window.phantom && window.phantom.solana) {
        list.push({ id: 'phantom', name: 'Phantom', icon: '👻', provider: window.phantom.solana });
      } else if (window.solana && window.solana.isPhantom) {
        list.push({ id: 'phantom', name: 'Phantom', icon: '👻', provider: window.solana });
      }
    } catch (e) {}
    try {
      if (window.solflare && window.solflare.isSolflare) {
        list.push({ id: 'solflare', name: 'Solflare', icon: '🔥', provider: window.solflare });
      }
    } catch (e) {}
    try {
      if (window.backpack) {
        list.push({ id: 'backpack', name: 'Backpack', icon: '🎒', provider: window.backpack });
      }
    } catch (e) {}
    try {
      // Generic window.solana if not phantom
      if (window.solana && !window.solana.isPhantom && window.solana.connect) {
        list.push({ id: 'injected', name: 'Solana Wallet', icon: '◎', provider: window.solana });
      }
    } catch (e) {}
    return list;
  }

  window.getSolanaAdapter = function () {
    return {
      name: _adapter.name,
      publicKey: _adapter.publicKey || state.solAddress || null,
      provider: _adapter.provider
    };
  };

  window.connectSolanaAdapter = async function (id) {
    id = id || 'in-app';
    if (id === 'in-app') {
      if (typeof window.ensureSolanaWallet === 'function') {
        await window.ensureSolanaWallet({ quiet: false });
      }
      _adapter = {
        name: 'in-app',
        publicKey: state.solAddress,
        provider: null
      };
      state.solProvider = null;
      if (typeof showToast === 'function') {
        showToast('Pakai wallet Solana in-app', 'success', 2800, state.solAddress ? state.solAddress.slice(0, 4) + '…' : '');
      }
      try {
        if (typeof window.renderReceive === 'function') window.renderReceive();
        if (typeof window.refreshSolanaBalances === 'function') await window.refreshSolanaBalances();
      } catch (e) {}
      return state.solAddress;
    }

    var wallets = detectSolWallets();
    var w = wallets.find(function (x) { return x.id === id; });
    if (!w || !w.provider) {
      if (typeof showToast === 'function') {
        showToast('Wallet tidak ditemukan', 'warn', 3000, 'Install ' + id + ' extension');
      }
      throw new Error('Wallet ' + id + ' tidak ada');
    }
    var resp = await w.provider.connect();
    var pk =
      (resp && resp.publicKey && resp.publicKey.toString && resp.publicKey.toString()) ||
      (w.provider.publicKey && w.provider.publicKey.toString());
    if (!pk) throw new Error('Gagal ambil public key');

    _adapter = { name: id, publicKey: pk, provider: w.provider };
    state.solAddress = pk;
    state.solProvider = w.provider;
    // Don't overwrite in-app secret — signing uses provider when present
    try {
      localStorage.setItem('br_sol_adapter', id);
      localStorage.setItem('br_sol_pubkey', pk);
    } catch (e) {}

    if (typeof showToast === 'function') {
      showToast(w.name + ' terhubung', 'success', 2800, pk.slice(0, 4) + '…' + pk.slice(-4));
    }
    try {
      if (typeof window.renderReceive === 'function') window.renderReceive();
      if (typeof window.refreshSolanaBalances === 'function') await window.refreshSolanaBalances();
    } catch (e) {}
    return pk;
  };

  window.disconnectSolanaAdapter = async function () {
    try {
      if (_adapter.provider && _adapter.provider.disconnect) {
        await _adapter.provider.disconnect();
      }
    } catch (e) {}
    _adapter = { name: 'in-app', publicKey: null, provider: null };
    state.solProvider = null;
    try {
      localStorage.removeItem('br_sol_adapter');
    } catch (e) {}
    // restore in-app if secret exists
    if (typeof window.ensureSolanaWallet === 'function') {
      await window.ensureSolanaWallet({ quiet: true });
    }
    if (typeof showToast === 'function') showToast('Adapter diputus · kembali in-app', 'info');
  };

  window.openSolanaWalletPicker = function () {
    var wallets = detectSolWallets();
    var cur = (_adapter && _adapter.name) || 'in-app';
    var html = '<div class="modal-handle"></div>';
    html += '<h3 style="margin:0 0 4px">Wallet Solana</h3>';
    html += '<p class="hint" style="margin:0 0 12px">Pilih adapter untuk sign & alamat receive</p>';
    html += '<div style="display:flex;flex-direction:column;gap:8px">';
    wallets.forEach(function (w) {
      var on = w.id === cur;
      html +=
        '<button type="button" class="aw-item" style="align-items:center' +
        (on ? ';border-color:#14F195' : '') +
        '" onclick="connectSolanaAdapter(\'' +
        w.id +
        '\').then(function(){closeModal()}).catch(function(){})">' +
        '<div style="font-size:22px;width:36px;text-align:center">' +
        w.icon +
        '</div>' +
        '<div class="aw-text" style="margin-left:8px;text-align:left"><div class="aw-title">' +
        w.name +
        (on ? ' ✓' : '') +
        '</div>' +
        '<div class="aw-desc">' +
        (w.id === 'in-app' ? 'Kunci di perangkat ini' : 'Extension / app') +
        '</div></div>' +
        '<span class="aw-chevron">›</span></button>';
    });
    html += '</div>';
    if (cur !== 'in-app') {
      html +=
        '<button class="btn btn-ghost" style="max-width:none;margin-top:12px" onclick="disconnectSolanaAdapter().then(function(){closeModal()})">Putuskan adapter</button>';
    }
    html +=
      '<button class="btn btn-ghost" style="max-width:none;margin-top:8px" onclick="openRpcSettings()">Konfigurasi RPC Solana</button>';
    if (typeof openModal === 'function') openModal(html);
  };

  // Hook Jupiter / execute to prefer adapter provider
  var _prevConnectPhantom = window.connectPhantom;
  window.connectPhantom = async function () {
    return window.connectSolanaAdapter('phantom');
  };

  // Apply custom RPC when selecting network
  var _sel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    var r = typeof _sel === 'function' ? await _sel.apply(this, arguments) : null;
    try {
      if (id && id !== 'sol' && typeof RPCS !== 'undefined') {
        RPCS = window.getRpcList(id);
        window._provider = null;
      }
    } catch (e) {}
    return r;
  };

  // Boot
  setTimeout(function () {
    injectSettingsRow();
    try {
      var pref = localStorage.getItem('br_sol_adapter');
      if (pref && pref !== 'in-app') {
        // don't auto-popup; just remember
      }
    } catch (e) {}
  }, 800);

  // Re-inject when opening settings
  var _ss = window.showScreen;
  if (typeof _ss === 'function') {
    window.showScreen = function (name) {
      var r = _ss.apply(this, arguments);
      if (name === 'settings') setTimeout(injectSettingsRow, 40);
      return r;
    };
  }

  brLog('%cRPC config + Solana wallet adapter ready', 'color:#00D4AA;font-weight:bold');
  console.log('  openRpcSettings() · openSolanaWalletPicker() · setCustomRpc(net,url)');
})();


/* Auto RPC when entering Solana */
(function AutoSolRpc() {
  var _sel = window.selectNetwork;
  if (typeof _sel !== 'function') return;
  window.selectNetwork = async function (id) {
    var r = await _sel.apply(this, arguments);
    if (id === 'sol' || (state && state.network === 'sol')) {
      try {
        if (typeof window.autoSelectRpc === 'function') {
          var best = await window.autoSelectRpc('sol');
          if (best && best.url && typeof showToast === 'function') {
            var host = best.url.replace(/^https?:\/\//, '').split('/')[0];
            showToast('RPC Solana: ' + host, 'success', 2600, (best.ms || '') + ' ms');
          }
        }
        if (typeof window.refreshSolanaBalances === 'function') {
          await window.refreshSolanaBalances();
        }
      } catch (e) {
        console.warn('[RPC auto]', e);
      }
    }
    return r;
  };
  brLog('%cAuto Solana RPC select enabled', 'color:#14F195');
})();

/* ============================================================
   HOTFIX — Solana home tokens + silent EVM provider + QR fallback
   ============================================================ */
(function SolanaHomeAndQrFix() {
  'use strict';

  function isSol() {
    return (state && state.network) === 'sol';
  }

  /* 1) Never throw noisy EVM provider error on Solana */
  var _gpf = window.getProviderWithFallback;
  if (typeof _gpf === 'function') {
    window.getProviderWithFallback = async function (force) {
      if (isSol()) {
        // Return a dummy-incompatible path: callers should not use EVM on sol
        return null;
      }
      return _gpf.apply(this, arguments);
    };
  }
  var _gp = window.getProvider;
  if (typeof _gp === 'function') {
    window.getProvider = async function (force) {
      if (isSol()) return null;
      return _gp.apply(this, arguments);
    };
  }

  /* 2) refreshBalances / softRefresh → Solana path */
  var _rb = window.refreshBalances;
  window.refreshBalances = async function (showLoad) {
    if (isSol()) {
      try {
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens('sol');
        if (typeof window.ensureSolanaWallet === 'function') await window.ensureSolanaWallet({ quiet: true });
        if (typeof window.refreshSolanaBalances === 'function') await window.refreshSolanaBalances();
        if (typeof renderHome === 'function') renderHome();
        updateEmptyTip();
      } catch (e) {
        console.warn('[Sol refresh]', e);
      }
      return;
    }
    if (typeof _rb === 'function') return _rb.apply(this, arguments);
  };
  window.refresh = window.refreshBalances;

  /* 3) Empty tip text for Solana — SINGLE tip only, never rewrite random nodes */
  function updateEmptyTip() {
    try {
      // Remove any loose tip text that is NOT #brEmptyTip
      var home = document.getElementById('screen-home') || document.body;
      if (home) {
        home.querySelectorAll('div, p, section').forEach(function (el) {
          if (el.id === 'brEmptyTip') return;
          if (el.closest && el.closest('#brEmptyTip, #tokenList, .token-row, nav')) return;
          var t = (el.textContent || '').replace(/\s+/g, ' ').trim();
          if (/Saldo masih kosong/i.test(t) && /Receive/i.test(t) && t.length < 280) {
            try { if (el.parentNode) el.parentNode.removeChild(el); } catch (e) {}
          }
        });
      }
      // Only maintain the single official tip
      var tip = document.getElementById('brEmptyTip');
      if (!tip) return;
      if (isSol()) {
        tip.style.display = 'block';
        tip.style.cssText =
          'margin:12px 16px;padding:14px;border-radius:14px;background:rgba(0,212,170,.08);' +
          'border:1px solid rgba(0,212,170,.25);font-size:.85rem;line-height:1.45;color:#c8d0dc;display:block';
        tip.innerHTML =
          '<b style="color:#14F195">Saldo masih kosong</b><br>' +
          'Ketuk <b>Receive</b> untuk menerima SOL / token SPL di jaringan <b>Solana</b>.';
      }
    } catch (e) {}
  }

  /* 4) Ensure SOL tokens list on home after network switch */
  var _sel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    var r = typeof _sel === 'function' ? await _sel.apply(this, arguments) : null;
    if (id === 'sol' || isSol()) {
      try {
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens('sol');
        // force token list ids
        if (!state.tokens || !state.tokens.length || !state.tokens.some(function (t) { return t.id === 'SOL'; })) {
          state.tokens = (typeof NET_TOKENS !== 'undefined' && NET_TOKENS.sol)
            ? NET_TOKENS.sol.map(function (t) { return Object.assign({}, t); })
            : [
                { id: 'SOL', symbol: 'SOL', name: 'Solana', decimals: 9, address: null, mint: 'So11111111111111111111111111111111111111112', icon: 'https://assets.coingecko.com/coins/images/4128/small/solana.png' },
                { id: 'USDC', symbol: 'USDC', name: 'USD Coin', decimals: 6, mint: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', address: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', icon: 'https://assets.coingecko.com/coins/images/6319/small/usdc.png' },
                { id: 'USDT', symbol: 'USDT', name: 'Tether', decimals: 6, mint: 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', address: 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', icon: 'https://assets.coingecko.com/coins/images/325/small/Tether.png' }
              ];
        }
        state.swapFrom = 'SOL';
        state.swapTo = 'USDC';
        if (typeof renderHome === 'function') renderHome();
        updateEmptyTip();
        if (typeof window.refreshSolanaBalances === 'function') {
          window.refreshSolanaBalances().catch(function () {});
        }
      } catch (e) {
        console.warn(e);
      }
    }
    return r;
  };

  /* 5) QR: multi-fallback (local QRCode → CDN → image API) */
  function qrImageUrl(data, size) {
    size = size || 200;
    // qrserver is reliable from browsers
    return (
      'https://api.qrserver.com/v1/create-qr-code/?size=' +
      size +
      'x' +
      size +
      '&margin=8&data=' +
      encodeURIComponent(data)
    );
  }

  function paintQrHost(hostId, data) {
    var host = document.getElementById(hostId);
    if (!host || !data) return;
    host.innerHTML = '';
    host.style.cssText =
      'width:200px;height:200px;margin:0 auto;background:#fff;border-radius:16px;display:flex;align-items:center;justify-content:center;overflow:hidden';

    function useImg() {
      host.innerHTML = '';
      var img = document.createElement('img');
      img.alt = 'QR';
      img.width = 200;
      img.height = 200;
      img.style.display = 'block';
      img.src = qrImageUrl(data, 200);
      img.onerror = function () {
        host.innerHTML =
          '<div style="color:#333;font-size:12px;text-align:center;padding:12px">QR tidak tersedia<br>Salin alamat manual</div>';
      };
      host.appendChild(img);
    }

    function useCanvasLib() {
      var canvas = document.createElement('canvas');
      canvas.width = 200;
      canvas.height = 200;
      host.appendChild(canvas);
      try {
        QRCode.toCanvas(
          canvas,
          data,
          { width: 200, margin: 2, color: { dark: '#0a1628', light: '#ffffff' }, errorCorrectionLevel: 'M' },
          function (err) {
            if (err) useImg();
          }
        );
      } catch (e) {
        useImg();
      }
    }

    if (typeof QRCode !== 'undefined' && QRCode.toCanvas) {
      useCanvasLib();
      return;
    }

    // try load lib once, else image API
    if (!window._brQrLibTried) {
      window._brQrLibTried = true;
      var s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';
      s.onload = function () {
        // qrcodejs uses different API
        try {
          host.innerHTML = '';
          new QRCode(host, {
            text: data,
            width: 200,
            height: 200,
            colorDark: '#0a1628',
            colorLight: '#ffffff',
            correctLevel: QRCode.CorrectLevel ? QRCode.CorrectLevel.M : 0
          });
        } catch (e) {
          useImg();
        }
      };
      s.onerror = function () {
        useImg();
      };
      document.head.appendChild(s);
      // timeout fallback
      setTimeout(function () {
        if (host && !host.querySelector('canvas, img, table')) useImg();
      }, 2000);
    } else {
      useImg();
    }
  }

  window.renderReceive = function () {
    var addr = '';
    if (isSol()) {
      addr = state.solAddress || '';
      if (!addr && typeof window.getReceiveAddress === 'function') addr = window.getReceiveAddress() || '';
      if (!addr && typeof window.ensureSolanaWallet === 'function') {
        window.ensureSolanaWallet({ quiet: true }).then(function () {
          window.renderReceive();
        });
      }
    } else {
      addr =
        (typeof window.getReceiveAddress === 'function' ? window.getReceiveAddress() : null) ||
        state.address ||
        '';
    }

    var addrEl = document.getElementById('receiveAddr');
    if (addrEl) addrEl.textContent = addr || '—';

    var hint = document.getElementById('receiveNetHint');
    if (!hint && addrEl && addrEl.parentNode) {
      hint = document.createElement('p');
      hint.id = 'receiveNetHint';
      hint.style.cssText = 'margin:8px 0 0;font-size:12px;text-align:center';
      addrEl.parentNode.insertBefore(hint, addrEl.nextSibling);
    }
    if (hint) {
      hint.textContent = isSol()
        ? 'Jaringan Solana · kirim hanya SOL / SPL ke alamat ini'
        : 'Jaringan ' + ((state && state.network) || 'base').toUpperCase();
      hint.style.color = isSol() ? '#14F195' : '';
    }

    if (addr) paintQrHost('qrCanvasHost', addr);

    // Explorer button
    try {
      var btn = document.getElementById('receiveExplorerBtn');
      if (btn) {
        btn.textContent = isSol() ? 'Lihat di Solscan' : 'Lihat di Basescan';
        btn.onclick = function () {
          if (typeof openExplorerAddr === 'function') openExplorerAddr();
        };
      }
    } catch (e) {}
  };

  // Patch renderHome to always show current network tokens
  var _rh = typeof renderHome === 'function' ? renderHome : null;
  if (_rh) {
    window.renderHome = function () {
      if (isSol() && (!state.tokens || !state.tokens.some(function (t) { return t.id === 'SOL' || t.symbol === 'SOL'; }))) {
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens('sol');
      }
      var r = _rh.apply(this, arguments);
      updateEmptyTip();
      return r;
    };
  }

  // Suppress toast for the old EVM provider message
  var _st = window.showToast;
  if (typeof _st === 'function') {
    window.showToast = function (msg, type, dur, sub) {
      var m = String(msg || '');
      if (/Solana tidak memakai provider EVM/i.test(m)) return;
      return _st(msg, type, dur, sub);
    };
  }

  brLog('%cSolana home + QR fallback ready', 'color:#14F195;font-weight:bold');
})();

/* ============================================================
   FORCE Solana token list on home (definitive fix)
   ============================================================ */
(function ForceSolanaTokenList() {
  'use strict';

  var SOL_DEFAULTS = [
    { id: 'SOL', symbol: 'SOL', name: 'Solana', decimals: 9, address: null, mint: 'So11111111111111111111111111111111111111112', icon: 'https://assets.coingecko.com/coins/images/4128/small/solana.png', cg: 'solana' },
    { id: 'USDC', symbol: 'USDC', name: 'USD Coin', decimals: 6, address: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', mint: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', icon: 'https://assets.coingecko.com/coins/images/6319/small/usdc.png', cg: 'usd-coin' },
    { id: 'USDT', symbol: 'USDT', name: 'Tether', decimals: 6, address: 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', mint: 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', icon: 'https://assets.coingecko.com/coins/images/325/small/Tether.png', cg: 'tether' },
    { id: 'BONK', symbol: 'BONK', name: 'Bonk', decimals: 5, address: 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263', mint: 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263', icon: 'https://assets.coingecko.com/coins/images/28600/small/bonk.jpg', cg: 'bonk' },
    { id: 'JUP', symbol: 'JUP', name: 'Jupiter', decimals: 6, address: 'JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN', mint: 'JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN', icon: 'https://assets.coingecko.com/coins/images/34188/small/jup.png', cg: 'jupiter-exchange-solana' },
    { id: 'WIF', symbol: 'WIF', name: 'dogwifhat', decimals: 6, address: 'EKpQGSJtjMFqKZ9KQanSqYXRcF8fBopzLHYxdM65zcjm', mint: 'EKpQGSJtjMFqKZ9KQanSqYXRcF8fBopzLHYxdM65zcjm', icon: 'https://assets.coingecko.com/coins/images/33566/small/dogwifhat.jpg', cg: 'dogwifcoin' }
  ];

  function isSol() {
    return (state && state.network) === 'sol';
  }

  function ensureSolTokens() {
    var base =
      typeof NET_TOKENS !== 'undefined' && NET_TOKENS.sol && NET_TOKENS.sol.length
        ? NET_TOKENS.sol
        : SOL_DEFAULTS;
    state.tokens = base.map(function (t) {
      return Object.assign({}, t);
    });
    // merge custom sol tokens
    try {
      var custom = JSON.parse(localStorage.getItem('br_custom_sol') || '[]');
      if (Array.isArray(custom)) {
        custom.forEach(function (c) {
          if (!state.tokens.some(function (x) { return x.id === c.id || (c.mint && x.mint === c.mint); })) {
            state.tokens.push(c);
          }
        });
      }
    } catch (e) {}
    if (!state.balances) state.balances = {};
    state.tokens.forEach(function (t) {
      if (state.balances[t.id] == null) state.balances[t.id] = 0;
    });
    state.swapFrom = 'SOL';
    state.swapTo = 'USDC';
  }

  function escapeHtml(s) {
    return String(s || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function paintSolTokenList() {
    if (!isSol()) return;
    ensureSolTokens();
    var list = document.getElementById('tokenList');
    if (!list) return;

    var html = state.tokens
      .map(function (t) {
        var bal = Number(state.balances[t.id] || 0) || 0;
        var price = Number(state.prices && state.prices[t.id]) || (t.symbol === 'USDC' || t.symbol === 'USDT' ? 1 : 0);
        var usd = bal * price;
        var icon = t.icon || '';
        var balStr = bal > 0 && bal < 0.0001 ? '<0.0001' : String(bal);
        try {
          if (typeof fmtAmt === 'function') balStr = fmtAmt(bal);
        } catch (e) {}
        var usdStr = '$' + (usd > 0 ? usd.toFixed(2) : '0.00');
        return (
          '<div class="token-row" data-tid="' +
          escapeHtml(t.id) +
          '" onclick="if(typeof showToken===\'function\')showToken(\'' +
          escapeHtml(t.id) +
          '\')">' +
          '<div class="token-icon"><img src="' +
          escapeHtml(icon) +
          '" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\'"></div>' +
          '<div class="token-info"><div class="name">' +
          escapeHtml(t.symbol) +
          '</div>' +
          '<div class="sym" style="opacity:.65;font-size:12px">' +
          (price ? '$' + (price >= 1 ? price.toFixed(2) : price.toPrecision(4)) : '—') +
          '</div></div>' +
          '<div class="token-bal" style="text-align:right"><div class="a">' +
          balStr +
          '</div><div class="u" style="opacity:.65;font-size:12px">' +
          usdStr +
          '</div></div></div>'
        );
      })
      .join('');

    list.innerHTML = html || '<div class="empty-state"><p>Tidak ada token Solana</p></div>';
    list.style.display = 'block';
    list.style.minHeight = '120px';

    // Keep empty tip ABOVE list, never replace list
    var tip = document.getElementById('brEmptyTip');
    if (tip) {
      tip.innerHTML =
        '<b style="color:#14F195">Saldo masih kosong</b><br>' +
        'Ketuk <b>Receive</b> untuk menerima SOL / token SPL di jaringan <b>Solana</b>.<br>' +
        '<button type="button" class="btn btn-ghost btn-sm" style="margin-top:10px" onclick="if(window.refreshSolanaBalances)refreshSolanaBalances();else if(window.refreshBalances)refreshBalances(true)">↻ Refresh saldo</button>';
      tip.style.display = 'block';
      // ensure tip is before list
      if (tip.parentNode && list.parentNode && tip.nextSibling !== list) {
        try {
          list.parentNode.insertBefore(tip, list);
        } catch (e) {}
      }
    }

    try {
      var lbl = document.getElementById('tokenTotalLabel');
      if (lbl) lbl.textContent = '$0.00';
    } catch (e) {}
  }

  // Final override — always last in chain
  var prev = window.renderHome;
  window.renderHome = function () {
    if (isSol()) {
      try {
        ensureSolTokens();
      } catch (e) {}
    }
    if (typeof prev === 'function') {
      try {
        prev.apply(this, arguments);
      } catch (e) {
        console.warn('renderHome prev', e);
      }
    }
    if (isSol()) {
      // Force paint AFTER all other overrides
      paintSolTokenList();
    }
  };

  var prevSel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    var r = typeof prevSel === 'function' ? await prevSel.apply(this, arguments) : null;
    if (id === 'sol' || isSol()) {
      ensureSolTokens();
      setTimeout(function () {
        paintSolTokenList();
        if (typeof window.refreshSolanaBalances === 'function') {
          window.refreshSolanaBalances()
            .then(function () {
              paintSolTokenList();
            })
            .catch(function () {
              paintSolTokenList();
            });
        }
      }, 50);
      setTimeout(paintSolTokenList, 300);
      setTimeout(paintSolTokenList, 1000);
    }
    return r;
  };

  // If already on sol when this loads
  setTimeout(function () {
    if (isSol()) {
      ensureSolTokens();
      paintSolTokenList();
    }
  }, 600);

  window.paintSolTokenList = paintSolTokenList;
  window.ensureSolTokens = ensureSolTokens;
  brLog('%cFORCE Solana token list active', 'color:#14F195;font-weight:bold');
})();

/* ============================================================
   HOTFIX — Restore EVM networks after Solana experiments
   ============================================================ */
(function RestoreEvmNetworks() {
  'use strict';

  function isSol() {
    return (state && state.network) === 'sol';
  }

  // On leaving Solana: restore tokens + balances for EVM
  var _sel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    var prevNet = state && state.network;
    var r = typeof _sel === 'function' ? await _sel.apply(this, arguments) : null;
    try {
      if (id && id !== 'sol') {
        // Hide sol panel
        try {
          if (typeof window.__brHideSolPanel === 'function') window.__brHideSolPanel();
          var panel = document.getElementById('brSolTokenPanel');
          if (panel) {
            panel.style.display = 'none';
            panel.innerHTML = '';
          }
        } catch (e) {}
        // Reload EVM tokens
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens(id);
        // Reset provider so new network RPC is used
        try {
          window._provider = null;
          window._providerNet = null;
          if (typeof RPCS !== 'undefined' && typeof window.getRpcList === 'function') {
            RPCS = window.getRpcList(id);
          }
        } catch (e) {}
        // Refresh EVM balances (not sol path)
        if (typeof window.refreshBalances === 'function') {
          // call after tick so isSol() is false
          setTimeout(function () {
            window.refreshBalances(true).catch(function (e) {
              console.warn('[EVM refresh]', e);
            });
          }, 100);
        }
        if (typeof renderHome === 'function') {
          setTimeout(function () {
            try {
              renderHome();
            } catch (e) {}
          }, 200);
        }
      }
    } catch (e) {
      console.warn('[RestoreEVM]', e);
    }
    return r;
  };

  // Safer getProvider: never throw on sol; on EVM use network.js path
  var _netGetProvider = null;
  try {
    // capture from prototype chain if available
  } catch (e) {}

  window.getProvider = async function (force) {
    if (isSol()) return null;
    // Prefer original network helper
    if (typeof getProviderWithFallback === 'function') {
      try {
        var p = await getProviderWithFallback(force);
        if (p) return p;
      } catch (e) {
        console.warn('[getProvider]', e);
      }
    }
    // Manual fallback list
    var net = (state && state.network) || 'base';
    var list =
      typeof window.getRpcList === 'function'
        ? window.getRpcList(net)
        : ['https://mainnet.base.org', 'https://base.llamarpc.com', 'https://1rpc.io/base'];
    var chainId =
      typeof getChainIdNum === 'function'
        ? getChainIdNum()
        : net === 'eth'
          ? 1
          : net === 'bnb'
            ? 56
            : 8453;
    var lastErr = null;
    for (var i = 0; i < list.length; i++) {
      try {
        var prov = new ethers.JsonRpcProvider(list[i], chainId, { staticNetwork: true });
        await Promise.race([
          prov.getBlockNumber(),
          new Promise(function (_, rej) {
            setTimeout(function () {
              rej(new Error('timeout'));
            }, 4000);
          })
        ]);
        return prov;
      } catch (e) {
        lastErr = e;
      }
    }
    throw lastErr || new Error('No RPC');
  };

  // Avoid infinite loop: getProviderWithFallback should not call getProvider
  var _gpfInner = window.getProviderWithFallback;
  window.getProviderWithFallback = async function (force) {
    if (isSol()) return null;
    if (typeof _gpfInner === 'function') {
      try {
        return await _gpfInner(force);
      } catch (e) {
        // fall through to getProvider manual
      }
    }
    return window.getProvider(force);
  };

  brLog('%cEVM networks restored · Sol panel isolated', 'color:#00D4AA;font-weight:bold');
})();

/* Solana switch-in burst */
(function SolSwitchBurst() {
  var _s = window.selectNetwork;
  if (typeof _s !== 'function') return;
  window.selectNetwork = async function (id) {
    var r = await _s.apply(this, arguments);
    if (id === 'sol' || (state && state.network === 'sol')) {
      try {
        if (typeof loadNetworkTokens === 'function') loadNetworkTokens('sol');
        if (typeof window.ensureSolTokens === 'function') window.ensureSolTokens();
        if (typeof window.paintSolTokenList === 'function') window.paintSolTokenList();
        if (typeof window.__brPaintSolTokens === 'function') window.__brPaintSolTokens();
        [100, 300, 700, 1200].forEach(function (ms) {
          setTimeout(function () {
            try {
              if (typeof window.__brPaintSolTokens === 'function') window.__brPaintSolTokens();
              if (typeof window.paintSolTokenList === 'function') window.paintSolTokenList();
            } catch (e) {}
          }, ms);
        });
      } catch (e) {
        console.warn('[SolSwitch]', e);
      }
    }
    return r;
  };
  brLog('%cSol switch-in burst on', 'color:#14F195');
})();

/* ============================================================
   Stabilize Sol balance + keep EVM intact
   ============================================================ */
(function StabilizeSolBal() {
  'use strict';

  // Harden refreshSolanaBalances — never throw to outer UI
  var _rsb = window.refreshSolanaBalances;
  window.refreshSolanaBalances = async function () {
    try {
      if (!state || state.network !== 'sol') return;
      if (typeof _rsb === 'function') {
        await _rsb.apply(this, arguments);
      }
    } catch (e) {
      console.warn('[Sol] balance suppressed', e && e.message ? e.message : e);
    }
    // Always try paint tokens even if RPC failed
    try {
      if (typeof window.__brPaintSolTokens === 'function') window.__brPaintSolTokens();
      if (typeof window.paintSolTokenList === 'function') window.paintSolTokenList();
    } catch (e2) {}
  };

  // Prevent refreshBalances on EVM from going through broken sol path
  var _rb = window.refreshBalances;
  window.refreshBalances = async function (showLoad) {
    try {
      if (state && state.network === 'sol') {
        await window.refreshSolanaBalances();
        return;
      }
      if (typeof _rb === 'function') return await _rb.apply(this, arguments);
    } catch (e) {
      console.warn('[refreshBalances]', e && e.message ? e.message : e);
    }
  };

  brLog('%cSol balance stabilized', 'color:#14F195');
})();

/* ============================================================
   Clean network switch — no mixed tokens / tip mismatch
   ============================================================ */
(function CleanNetworkSwitch() {
  'use strict';

  var SOL_TOKENS = [
    { id: 'SOL', symbol: 'SOL', name: 'Solana', decimals: 9, mint: 'So11111111111111111111111111111111111111112', icon: 'https://assets.coingecko.com/coins/images/4128/small/solana.png' },
    { id: 'USDC', symbol: 'USDC', name: 'USD Coin', decimals: 6, mint: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', address: 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v', icon: 'https://assets.coingecko.com/coins/images/6319/small/usdc.png' },
    { id: 'USDT', symbol: 'USDT', name: 'Tether', decimals: 6, mint: 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', address: 'Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB', icon: 'https://assets.coingecko.com/coins/images/325/small/Tether.png' },
    { id: 'BONK', symbol: 'BONK', name: 'Bonk', decimals: 5, mint: 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263', address: 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263', icon: 'https://assets.coingecko.com/coins/images/28600/small/bonk.jpg' },
    { id: 'JUP', symbol: 'JUP', name: 'Jupiter', decimals: 6, mint: 'JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN', address: 'JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN', icon: 'https://assets.coingecko.com/coins/images/34188/small/jup.png' },
    { id: 'WIF', symbol: 'WIF', name: 'dogwifhat', decimals: 6, mint: 'EKpQGSJtjMFqKZ9KQanSqYXRcF8fBopzLHYxdM65zcjm', address: 'EKpQGSJtjMFqKZ9KQanSqYXRcF8fBopzLHYxdM65zcjm', icon: 'https://assets.coingecko.com/coins/images/33566/small/dogwifhat.jpg' }
  ];

  function applyTokensFor(netId) {
    netId = netId || (state && state.network) || 'base';
    if (!state) return;

    // Reset balances map for clean display
    state.balances = state.balances || {};

    if (netId === 'sol') {
      var list =
        typeof NET_TOKENS !== 'undefined' && NET_TOKENS.sol && NET_TOKENS.sol.length
          ? NET_TOKENS.sol
          : SOL_TOKENS;
      state.tokens = list.map(function (t) {
        return Object.assign({}, t);
      });
      state.tokens.forEach(function (t) {
        if (state.balances[t.id] == null) state.balances[t.id] = 0;
      });
      // Clear EVM-only ids from showing with stale data is OK; filter by token list
      state.swapFrom = 'SOL';
      state.swapTo = 'USDC';
    } else {
      if (typeof loadNetworkTokens === 'function') {
        loadNetworkTokens(netId);
      } else if (typeof NET_TOKENS !== 'undefined' && NET_TOKENS[netId]) {
        state.tokens = NET_TOKENS[netId].map(function (t) {
          return Object.assign({}, t);
        });
      }
      // hide sol panel
      try {
        var panel = document.getElementById('brSolTokenPanel');
        if (panel) {
          panel.style.display = 'none';
          panel.innerHTML = '';
        }
      } catch (e) {}
    }
  }

  function setEmptyTip(netId) {
    var tip = document.getElementById('brEmptyTip');
    if (!tip) return;
    if (netId === 'sol') {
      tip.style.display = 'block';
      tip.innerHTML =
        '<b style="color:#14F195">Saldo masih kosong</b><br>' +
        'Ketuk <b>Receive</b> untuk menerima SOL / token SPL di jaringan <b>Solana</b>.<br>' +
        '<button type="button" class="btn btn-ghost btn-sm" style="margin-top:10px" onclick="if(window.refreshSolanaBalances)refreshSolanaBalances()">↻ Refresh saldo</button>';
    } else {
      var name = (netId || 'base').toUpperCase();
      tip.style.display = 'block';
      tip.innerHTML =
        '<b style="color:#00d4aa">Saldo masih kosong</b><br>' +
        'Ketuk <b>Receive</b> untuk menerima token, atau pastikan jaringan = <b>' +
        name +
        '</b>.<br>' +
        '<button type="button" class="btn btn-ghost btn-sm" style="margin-top:10px" onclick="if(window.refreshBalances)refreshBalances(true)">↻ Refresh saldo</button>';
    }
  }

  function ensureTokenListEl() {
    var list = document.getElementById('tokenList');
    if (list) return list;
    // Recreate if missing from DOM
    var host =
      document.getElementById('homeScroll') ||
      document.querySelector('#screen-home .home-scroll') ||
      document.querySelector('#screen-home') ||
      document.querySelector('.section-token');
    if (!host) {
      // Last resort: create homeScroll under screen-home
      var home = document.getElementById('screen-home');
      if (!home) return null;
      host = document.createElement('div');
      host.id = 'homeScroll';
      host.className = 'home-scroll';
      home.appendChild(host);
    }
    list = document.createElement('div');
    list.id = 'tokenList';
    list.className = 'token-list';
    // Insert before manage button if present
    var manage = host.querySelector('.manage-btn-wrap');
    if (manage) host.insertBefore(list, manage);
    else host.appendChild(list);
    brLog('[ensureTokenListEl] recreated #tokenList');
    return list;
  }
  window.ensureTokenListEl = ensureTokenListEl;

  function paintTokenRows() {
    if (!state || !state.tokens || !state.tokens.length) return;
    var list = ensureTokenListEl();
    if (!list) {
      console.warn('[paintTokenRows] no host for #tokenList');
      return;
    }
    var net = state.network || 'base';
    var html = state.tokens
      .map(function (t) {
        var bal = Number(state.balances[t.id] || 0) || 0;
        var price = Number((state.prices && state.prices[t.id]) || 0) || 0;
        if ((t.symbol === 'USDC' || t.symbol === 'USDT') && !price) price = 1;
        var usd = bal * price;
        var icon = t.icon || '';
        var sub = net === 'sol' ? 'Solana' : String(net).toUpperCase();
        return (
          '<div class="token-row" data-tid="' +
          t.id +
          '" style="display:flex;align-items:center;gap:12px;padding:12px 8px;border-bottom:1px solid rgba(42,49,60,.5)">' +
          '<img src="' +
          icon +
          '" width="36" height="36" style="border-radius:50%;background:#1a1f2e" onerror="this.style.opacity=.3">' +
          '<div style="flex:1"><div style="font-weight:600">' +
          (t.symbol || t.id) +
          '</div><div style="font-size:12px;opacity:.6">' +
          sub +
          '</div></div>' +
          '<div style="text-align:right"><div style="font-weight:600">' +
          bal +
          '</div><div style="font-size:12px;opacity:.6">$' +
          usd.toFixed(2) +
          '</div></div></div>'
        );
      })
      .join('');
    list.innerHTML = html;
    list.style.display = 'flex';
    list.style.flexDirection = 'column';
    list.style.minHeight = '120px';
    list.style.visibility = 'visible';
    list.style.opacity = '1';
  }

  window.applyNetworkUi = function (netId) {
    netId = netId || (state && state.network) || 'base';
    applyTokensFor(netId);
    setEmptyTip(netId);
    paintTokenRows();
  };

  var _sel = window.selectNetwork;
  window.selectNetwork = async function (id) {
    // 1) Instant UI switch (sync) — no wait for RPC
    try {
      if (state) state.network = id;
      window.applyNetworkUi(id);
    } catch (e) {
      console.warn('[switch ui]', e);
    }

    // 2) Run original selectNetwork (rpc, storage, etc.)
    var r = typeof _sel === 'function' ? await _sel.apply(this, arguments) : null;

    // 3) Re-apply tokens (original may have overwritten)
    try {
      window.applyNetworkUi(id);
    } catch (e) {}

    // 4) Async balances
    try {
      if (id === 'sol') {
        if (typeof window.ensureSolanaWallet === 'function') {
          await window.ensureSolanaWallet({ quiet: true });
        }
        if (typeof window.refreshSolanaBalances === 'function') {
          await window.refreshSolanaBalances();
        }
        window.applyNetworkUi('sol');
      } else {
        if (typeof window.refreshBalances === 'function') {
          await window.refreshBalances(false);
        }
        window.applyNetworkUi(id);
      }
    } catch (e) {
      console.warn('[switch bal]', e);
      window.applyNetworkUi(id);
    }

    return r;
  };

  // After renderHome, re-assert correct list for current net (fixes delay/stale)
  var _rh = window.renderHome;
  if (typeof _rh === 'function') {
    window.renderHome = function () {
      var r = _rh.apply(this, arguments);
      try {
        var net = (state && state.network) || 'base';
        // If tokens don't match network, fix immediately
        var hasSol = state.tokens && state.tokens.some(function (t) {
          return t.id === 'SOL' || t.symbol === 'SOL';
        });
        var hasEvmNative = state.tokens && state.tokens.some(function (t) {
          return t.id === 'ETH' || t.id === 'BNB' || t.symbol === 'ETH' || t.symbol === 'BNB';
        });
        if (net === 'sol' && !hasSol) window.applyNetworkUi('sol');
        if (net !== 'sol' && hasSol && !hasEvmNative) window.applyNetworkUi(net);
        // Tip mismatch fix
        setEmptyTip(net);
      } catch (e) {}
      return r;
    };
  }

  brLog('%cClean network switch ready', 'color:#00D4AA;font-weight:bold');
})();

/* ============================================================
   Tab resume + Solana always show tokens even if RPC fails
   ============================================================ */
(function TabResumeSol() {
  'use strict';

  function safePaint() {
    try {
      if (!state) return;
      var net = state.network || 'base';
      if (typeof window.applyNetworkUi === 'function') {
        window.applyNetworkUi(net);
      } else if (net === 'sol' && typeof window.__brPaintSolTokens === 'function') {
        window.__brPaintSolTokens();
      }
    } catch (e) {}
  }

  var _resumeTimer = null;
  var _lastResumeAt = 0;
  function onResume() {
    // Debounce: Acode/localhost fires focus+pageshow+visibility rapidly
    var now = Date.now();
    if (now - _lastResumeAt < 2500) return;
    if (_resumeTimer) clearTimeout(_resumeTimer);
    _resumeTimer = setTimeout(function () {
      _lastResumeAt = Date.now();
      try {
        if (state && state.network === 'sol') {
          safePaint();
          if (typeof window.refreshSolanaBalances === 'function') {
            window.refreshSolanaBalances()
              .then(function () { safePaint(); })
              .catch(function () { safePaint(); });
          }
        } else if (state && state.address && typeof window.refreshBalances === 'function') {
          // Quiet balance refresh on non-sol — no full re-render storm
          window.refreshBalances(false).catch(function () {});
        } else {
          safePaint();
        }
      } catch (e) {
        try { safePaint(); } catch (e2) {}
      }
    }, 300);
  }

  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') onResume();
  });
  window.addEventListener('focus', function () {
    onResume();
  });
  // Acode / iframe resume
  window.addEventListener('pageshow', function () {
    onResume();
  });

  // Boot paint once if already on sol (not twice)
  setTimeout(function () {
    if (state && state.network === 'sol') safePaint();
  }, 600);

  // Soften sol balance toast globally
  var _toast = window.showToast;
  if (typeof _toast === 'function') {
    window.showToast = function (msg, type, dur, sub) {
      var m = String(msg || '');
      if (/Saldo Solana sementara tidak tersedia/i.test(m)) {
        // show only once per session
        if (window._solBalToastShown) return;
        window._solBalToastShown = true;
        return _toast(msg, type, 2500, sub);
      }
      return _toast(msg, type, dur, sub);
    };
  }

  brLog('%cTab resume Solana paint on', 'color:#14F195');
})();

/* ============================================================
   Solana tab-resume: NEVER leave home without token rows
   ============================================================ */
(function SolanaResumeHard() {
  'use strict';

  var ROWS = [
    { id: 'SOL', symbol: 'SOL', icon: 'https://assets.coingecko.com/coins/images/4128/small/solana.png' },
    { id: 'USDC', symbol: 'USDC', icon: 'https://assets.coingecko.com/coins/images/6319/small/usdc.png' },
    { id: 'USDT', symbol: 'USDT', icon: 'https://assets.coingecko.com/coins/images/325/small/Tether.png' },
    { id: 'BONK', symbol: 'BONK', icon: 'https://assets.coingecko.com/coins/images/28600/small/bonk.jpg' },
    { id: 'JUP', symbol: 'JUP', icon: 'https://assets.coingecko.com/coins/images/34188/small/jup.png' },
    { id: 'WIF', symbol: 'WIF', icon: 'https://assets.coingecko.com/coins/images/33566/small/dogwifhat.jpg' }
  ];

  function isSolNet() {
    try {
      return !!(window.state && (state.network === 'sol' || state.network === 'solana'));
    } catch (e) {
      return false;
    }
  }

  function forceSolRows() {
    if (!isSolNet()) return false;
    try {
      // Keep state in sync
      if (window.state) {
        if (typeof NET_TOKENS !== 'undefined' && NET_TOKENS.sol) {
          state.tokens = NET_TOKENS.sol.map(function (t) {
            return Object.assign({}, t);
          });
        }
        if (!state.balances) state.balances = {};
        ROWS.forEach(function (t) {
          if (state.balances[t.id] == null) state.balances[t.id] = 0;
        });
      }
    } catch (e) {}

    var list = document.getElementById('tokenList');
    if (!list) return false;

    // If already has SOL row, still refresh balances numbers only
    var html = ROWS.map(function (t) {
      var bal = 0;
      try {
        bal = Number((state.balances && state.balances[t.id]) || 0) || 0;
      } catch (e) {}
      return (
        '<div class="token-row" data-tid="' +
        t.id +
        '" data-sol="1" style="display:flex;align-items:center;gap:12px;padding:12px 8px;border-bottom:1px solid rgba(42,49,60,.5)">' +
        '<img src="' +
        t.icon +
        '" width="36" height="36" style="border-radius:50%;background:#1a1f2e" onerror="this.style.opacity=.3">' +
        '<div style="flex:1"><div style="font-weight:600;color:#e8edf5">' +
        t.symbol +
        '</div><div style="font-size:12px;color:#8b95a5">Solana</div></div>' +
        '<div style="text-align:right"><div style="font-weight:600;color:#e8edf5">' +
        bal +
        '</div><div style="font-size:12px;color:#8b95a5">$0.00</div></div></div>'
      );
    }).join('');

    list.innerHTML = html;
    list.setAttribute('data-sol-forced', '1');
    list.style.cssText =
      'display:flex!important;flex-direction:column;visibility:visible!important;opacity:1!important;min-height:180px;padding:0 12px 16px;';

    // Ensure only one tip exists
    try {
      if (typeof window.stripDupTips === 'function') window.stripDupTips();
    } catch (e) {}
    var tip = document.getElementById('brEmptyTip');
    if (!tip) {
      tip = document.createElement('div');
      tip.id = 'brEmptyTip';
      var list = document.getElementById('tokenList');
      if (list && list.parentNode) list.parentNode.insertBefore(tip, list);
    }
    tip.style.cssText =
      'margin:12px 16px;padding:14px;border-radius:14px;background:rgba(0,212,170,.08);' +
      'border:1px solid rgba(0,212,170,.25);font-size:.85rem;line-height:1.45;color:#c8d0dc;display:block';
    tip.innerHTML =
      '<b style="color:#14F195">Saldo masih kosong</b><br>Ketuk <b>Receive</b> untuk menerima SOL / token SPL di jaringan <b>Solana</b>.';
    try {
      if (typeof window.stripDupTips === 'function') window.stripDupTips();
    } catch (e) {}
    return true;
  }

  // Guard: if something clears tokenList while on Solana, restore (debounced, no loop)
  var _guardBusy = false;
  function installGuard() {
    var list = document.getElementById('tokenList');
    if (!list || list._solGuard) return;
    var obs = new MutationObserver(function () {
      if (!isSolNet() || _guardBusy) return;
      if (!list.querySelector('.token-row[data-sol="1"], .token-row[data-tid="SOL"]')) {
        _guardBusy = true;
        try { forceSolRows(); } catch (e) {}
        setTimeout(function () { _guardBusy = false; }, 800);
      }
    });
    obs.observe(list, { childList: true, subtree: false });
    list._solGuard = true;
  }

  var _hardResumeAt = 0;
  var _hardResumeTimer = null;
  function onResume() {
    if (!isSolNet()) return;
    var now = Date.now();
    // Debounce hard — prevent rapid forceSolRows storm on Acode tab switch
    if (now - _hardResumeAt < 3000) return;
    if (_hardResumeTimer) clearTimeout(_hardResumeTimer);
    _hardResumeTimer = setTimeout(function () {
      _hardResumeAt = Date.now();
      installGuard();
      forceSolRows();
      // One delayed retry only (not 5)
      setTimeout(function () {
        if (isSolNet()) forceSolRows();
      }, 600);
      try {
        window._solBalToastShown = true;
        if (typeof window.refreshSolanaBalances === 'function') {
          window.refreshSolanaBalances()
            .then(function () { forceSolRows(); })
            .catch(function () { forceSolRows(); });
        }
      } catch (e) {
        forceSolRows();
      }
    }, 200);
  }

  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') onResume();
  });
  window.addEventListener('focus', onResume);
  window.addEventListener('pageshow', onResume);

  // Also when selecting sol
  var _sel = window.selectNetwork;
  if (typeof _sel === 'function') {
    window.selectNetwork = async function (id) {
      var r = await _sel.apply(this, arguments);
      if (id === 'sol' || isSolNet()) {
        installGuard();
        forceSolRows();
        [0, 100, 300, 800].forEach(function (ms) {
          setTimeout(function () {
            if (isSolNet()) forceSolRows();
          }, ms);
        });
      }
      return r;
    };
  }

  // Interval backup only on sol — light
  setInterval(function () {
    if (!isSolNet()) return;
    installGuard();
    var list = document.getElementById('tokenList');
    if (list && !list.querySelector('.token-row')) forceSolRows();
  }, 2000);

  setTimeout(function () {
    if (isSolNet()) {
      installGuard();
      forceSolRows();
    }
  }, 800);

  window.forceSolRows = forceSolRows;
  brLog('%cSolana resume HARD guard on', 'color:#14F195;font-weight:bold');
})();

/* ============================================================
   FINAL: forceSolRows(true) always paints; safe sol balance
   ============================================================ */
(function FinalSolFix() {
  'use strict';

  var ROWS = [
    { id: 'SOL', symbol: 'SOL', icon: 'https://assets.coingecko.com/coins/images/4128/small/solana.png' },
    { id: 'USDC', symbol: 'USDC', icon: 'https://assets.coingecko.com/coins/images/6319/small/usdc.png' },
    { id: 'USDT', symbol: 'USDT', icon: 'https://assets.coingecko.com/coins/images/325/small/Tether.png' },
    { id: 'BONK', symbol: 'BONK', icon: 'https://assets.coingecko.com/coins/images/28600/small/bonk.jpg' },
    { id: 'JUP', symbol: 'JUP', icon: 'https://assets.coingecko.com/coins/images/34188/small/jup.png' },
    { id: 'WIF', symbol: 'WIF', icon: 'https://assets.coingecko.com/coins/images/33566/small/dogwifhat.jpg' }
  ];

  window.forceSolRows = function (force) {
    var net = '';
    try {
      net = (window.state && state.network) || localStorage.getItem('br_v4_network') || '';
    } catch (e) {}
    if (!force && net !== 'sol' && net !== 'solana') {
      console.log('[forceSolRows] skip, network=', net);
      return false;
    }
    // Ensure wallet home screen is visible (tokenList lives there)
    try {
      var home = document.getElementById('screen-home');
      if (home && !home.classList.contains('active')) {
        if (typeof showScreen === 'function') showScreen('home');
        else {
          document.querySelectorAll('.screen').forEach(function(s){ s.classList.remove('active'); });
          home.classList.add('active');
          home.style.display = 'flex';
        }
      }
    } catch (e) {}
    // Ensure state says sol when forcing from sol UI
    try {
      if (force && window.state && state.network !== 'sol') {
        // don't overwrite if user is on another net unless force from selectNetwork
      }
    } catch (e) {}

    try {
      if (window.state) {
        if (typeof NET_TOKENS !== 'undefined' && NET_TOKENS.sol) {
          state.tokens = NET_TOKENS.sol.map(function (t) {
            return Object.assign({}, t);
          });
        } else {
          state.tokens = ROWS.map(function (t) {
            return { id: t.id, symbol: t.symbol, name: t.symbol, decimals: 9, icon: t.icon };
          });
        }
        if (!state.balances) state.balances = {};
        ROWS.forEach(function (t) {
          if (state.balances[t.id] == null) state.balances[t.id] = 0;
        });
      }
    } catch (e) {}

    var list = document.getElementById('tokenList');
    if (!list) {
      // Recreate under home if missing (Acode / partial DOM)
      var host =
        document.getElementById('homeScroll') ||
        document.querySelector('#screen-home .home-scroll') ||
        document.querySelector('#screen-home') ||
        document.querySelector('.section-token') ||
        document.querySelector('.screen.active');
      if (!host) {
        console.warn('[forceSolRows] no host for tokenList');
        return false;
      }
      list = document.createElement('div');
      list.id = 'tokenList';
      list.className = 'token-list';
      list.style.cssText = 'display:flex;flex-direction:column;padding:0 12px 16px;min-height:180px';
      var tip = document.getElementById('brEmptyTip');
      if (tip && tip.parentNode === host) host.insertBefore(list, tip.nextSibling);
      else host.appendChild(list);
      console.log('[forceSolRows] recreated #tokenList');
    }
    var html = ROWS.map(function (t) {
      var bal = 0;
      try {
        bal = Number((state.balances && state.balances[t.id]) || 0) || 0;
      } catch (e) {}
      return (
        '<div class="token-row" data-tid="' +
        t.id +
        '" data-sol="1" role="button" tabindex="0" style="display:flex;align-items:center;gap:12px;padding:12px 8px;border-bottom:1px solid rgba(42,49,60,.5);cursor:pointer;-webkit-tap-highlight-color:transparent">' +
        '<img src="' +
        t.icon +
        '" width="36" height="36" style="border-radius:50%;background:#1a1f2e;pointer-events:none" onerror="this.style.opacity=.3">' +
        '<div style="flex:1;pointer-events:none"><div style="font-weight:600">' +
        t.symbol +
        '</div><div style="font-size:12px;opacity:.65">Solana</div></div>' +
        '<div style="text-align:right;pointer-events:none"><div style="font-weight:600">' +
        bal +
        '</div><div style="font-size:12px;opacity:.65">$0.00</div></div></div>'
      );
    }).join('');
    list.innerHTML = html;
    list.style.display = 'flex';
    list.style.flexDirection = 'column';
    list.style.minHeight = '180px';
    // Click → open send / token detail for Solana
    list.querySelectorAll('.token-row[data-sol="1"]').forEach(function (row) {
      row.onclick = function (ev) {
        ev.preventDefault();
        ev.stopPropagation();
        var tid = row.getAttribute('data-tid') || 'SOL';
        try {
          state.tdToken = (state.tokens || []).find(function (x) { return x.id === tid; }) || {
            id: tid,
            symbol: tid,
            name: tid
          };
          if (typeof openTransfer === 'function') openTransfer(tid);
          else if (typeof openBitgetTransfer === 'function') openBitgetTransfer();
          else if (typeof showScreen === 'function') showScreen('send');
          else if (typeof showToken === 'function') showToken(tid);
        } catch (e) {
          console.warn('[Sol] token click', e);
        }
      };
    });
    if (window.BR_DEBUG) console.log('[forceSolRows] painted', ROWS.length, 'net=', net);
    // Always dedupe tips after Solana paint
    try {
      if (typeof window.stripDupTips === 'function') {
        window.stripDupTips();
        setTimeout(window.stripDupTips, 50);
        setTimeout(window.stripDupTips, 200);
      }
    } catch (e) {}
    return true;
  };

  // Replace balance refresh with ultra-safe version
  window.refreshSolanaBalances = async function () {
    try {
      if (!state || state.network !== 'sol') return;
    } catch (e) {
      return;
    }
    try {
      if (typeof window.ensureSolanaWallet === 'function') {
        try {
          await window.ensureSolanaWallet({ quiet: true });
        } catch (e) {
          console.warn('[Sol] ensureWallet', e && (e.message || e));
        }
      }
      var owner = state.solAddress;
      if (!owner) {
        window.forceSolRows(true);
        return;
      }
      var rpcs = [
        'https://solana-rpc.publicnode.com',
        'https://solana.drpc.org',
        'https://api.mainnet-beta.solana.com',
        'https://endpoints.omniatech.io/v1/sol/mainnet/public'
      ];
      var balLamports = null;
      for (var i = 0; i < rpcs.length; i++) {
        try {
          var res = await fetch(rpcs[i], {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              jsonrpc: '2.0',
              id: 1,
              method: 'getBalance',
              params: [owner]
            })
          });
          if (!res.ok) continue;
          var data = await res.json();
          if (data && data.result && typeof data.result.value === 'number') {
            balLamports = data.result.value;
            break;
          }
        } catch (e) {
          console.warn('[Sol] rpc', rpcs[i], e && e.message);
        }
      }
      if (!state.balances) state.balances = {};
      if (balLamports != null) state.balances.SOL = balLamports / 1e9;
      ROWS.forEach(function (t) {
        if (state.balances[t.id] == null) state.balances[t.id] = 0;
      });
    } catch (e) {
      console.warn('[Sol] balance', e && (e.message || String(e)));
    }
    try {
      window.forceSolRows(true);
    } catch (e2) {}
  };

  // On load if saved network is sol
  setTimeout(function () {
    try {
      var n = (state && state.network) || localStorage.getItem('br_v4_network');
      if (n === 'sol') window.forceSolRows(true);
    } catch (e) {}
  }, 600);

  brLog('%cFINAL Sol fix — forceSolRows(true) · safe balance', 'color:#14F195;font-weight:bold');
})();

/* Deduplicate empty tips on Solana home */
(function DedupTips() {
  function clean() {
    try {
      if (!state || state.network !== 'sol') return;
      var tips = document.querySelectorAll('#brEmptyTip');
      // keep one
      for (var i = 1; i < tips.length; i++) {
        try {
          tips[i].parentNode.removeChild(tips[i]);
        } catch (e) {}
      }
      // remove plain text duplicate above the card (sibling text blocks)
      var list = document.getElementById('tokenList');
      if (!list || !list.parentNode) return;
      var parent = list.parentNode;
      var children = Array.prototype.slice.call(parent.childNodes);
      var seenTip = false;
      children.forEach(function (node) {
        if (node.nodeType === 1 && node.id === 'brEmptyTip') {
          if (seenTip) {
            try {
              parent.removeChild(node);
            } catch (e) {}
          } else seenTip = true;
        }
      });
    } catch (e) {}
  }
  var _f = window.forceSolRows;
  if (typeof _f === 'function') {
    window.forceSolRows = function () {
      var r = _f.apply(this, arguments);
      setTimeout(clean, 0);
      return r;
    };
  }
  setInterval(function () {
    if (state && state.network === 'sol') clean();
  }, 3000);
})();

/* ============================================================
   Single empty-balance tip only (remove duplicates)
   ============================================================ */
(function SingleEmptyTip() {
  'use strict';

  function stripDupTips() {
    try {
      var list = document.getElementById('tokenList');
      var home =
        document.getElementById('homeScroll') ||
        document.querySelector('#screen-home') ||
        document.body;
      if (!home) return;

      // Collect ALL tip-like nodes (id, class, or text content)
      var nodes = [];
      var seen = new Set();
      function addNode(el) {
        if (!el || seen.has(el)) return;
        // skip if inside token row / list structure that is not tip itself
        if (el.id !== 'brEmptyTip' && el.querySelector && el.querySelector('.token-row')) return;
        seen.add(el);
        nodes.push(el);
      }
      home.querySelectorAll('#brEmptyTip, .br-empty-tip, .empty-bal-tip').forEach(addNode);
      home.querySelectorAll('div, p, section, span').forEach(function (el) {
        if (seen.has(el)) return;
        if (el.closest && el.closest('#tokenList, .token-row, .token-list, nav, .bottom-nav')) return;
        var t = (el.textContent || '').replace(/\s+/g, ' ').trim();
        // Match even if not at start (handles nested/extra whitespace)
        if (/Saldo masih kosong/i.test(t) && /Receive/i.test(t) && t.length < 280) {
          // Prefer the outermost tip-like container
          var parent = el.parentElement;
          if (parent && parent !== home && /Saldo masih kosong/i.test((parent.textContent || '').replace(/\s+/g, ' ')) &&
              (parent.textContent || '').replace(/\s+/g, ' ').trim().length < 280 &&
              !parent.querySelector('.token-row, #tokenList')) {
            addNode(parent);
          } else {
            addNode(el);
          }
        }
      });

      // Keep only ONE tip: prefer existing #brEmptyTip
      var keep = document.getElementById('brEmptyTip');
      if (keep && nodes.indexOf(keep) < 0) nodes.unshift(keep);
      if (!keep && nodes.length) {
        keep = nodes[0];
        try { keep.id = 'brEmptyTip'; } catch (e) {}
      }

      nodes.forEach(function (el) {
        if (el === keep) return;
        try {
          if (el.parentNode) el.parentNode.removeChild(el);
        } catch (e) {}
      });

      // If balance is NOT empty, hide/remove tip entirely
      var hasBal = false;
      try {
        if (state && state.balances) {
          Object.keys(state.balances).forEach(function (k) {
            if (parseFloat(state.balances[k]) > 0) hasBal = true;
          });
        }
      } catch (e) {}
      if (hasBal) {
        if (keep && keep.parentNode) keep.parentNode.removeChild(keep);
        return;
      }

      if (keep) {
        keep.style.cssText =
          'margin:12px 16px;padding:14px;border-radius:14px;background:rgba(0,212,170,.08);' +
          'border:1px solid rgba(0,212,170,.25);font-size:.85rem;line-height:1.45;color:#c8d0dc;display:block';
        var net = (state && state.network) || 'base';
        if (net === 'sol') {
          keep.innerHTML =
            '<b style="color:#14F195">Saldo masih kosong</b><br>' +
            'Ketuk <b>Receive</b> untuk menerima SOL / token SPL di jaringan <b>Solana</b>.';
        } else {
          keep.innerHTML =
            '<b style="color:#00d4aa">Saldo masih kosong</b><br>' +
            'Ketuk <b>Receive</b> untuk menerima token di jaringan <b>' +
            String(net).toUpperCase() +
            '</b>.';
        }
        // Place once: before tokenList
        if (list && list.parentNode) {
          if (keep.parentNode !== list.parentNode || keep.nextSibling !== list) {
            list.parentNode.insertBefore(keep, list);
          }
        }
      }
    } catch (e) {}
  }

  window.stripDupTips = stripDupTips;

  // Hook forceSolRows / renderHome / applyNetworkUi
  ['forceSolRows', 'renderHome', 'applyNetworkUi'].forEach(function (name) {
    var orig = window[name];
    if (typeof orig !== 'function' || orig._tipDedup) return;
    window[name] = function () {
      var r = orig.apply(this, arguments);
      setTimeout(stripDupTips, 0);
      setTimeout(stripDupTips, 100);
      return r;
    };
    window[name]._tipDedup = true;
  });

  setInterval(function () {
    try {
      if (document.getElementById('screen-home') && document.getElementById('screen-home').classList.contains('active')) {
        var tips = document.querySelectorAll('#brEmptyTip');
        var loose = 0;
        document.querySelectorAll('#screen-home div, #screen-home p').forEach(function (el) {
          var t = (el.textContent || '').replace(/\s+/g, ' ').trim();
          if (/^Saldo masih kosong/i.test(t) && /Receive/i.test(t) && t.length < 220) loose++;
        });
        if (tips.length > 1 || loose > 1) stripDupTips();
      }
    } catch (e) {}
  }, 1500);

  setTimeout(stripDupTips, 800);
  brLog('%cSingle empty tip enforcer on', 'color:#00D4AA');
})();


/* ===== FIX: ensure home token list never stays blank on boot ===== */
(function ensureHomeTokensBoot() {
  function ensureHomeTokenList(reason) {
    try {
      if (!state) return;
      var netId = state.network || localStorage.getItem('br_v4_network') || 'base';
      state.network = netId;

      // 1) Preferred path: same as network switch (paintTokenRows) — this is what actually works
      if (typeof window.applyNetworkUi === 'function') {
        window.applyNetworkUi(netId);
      } else {
        // Fallback
        if (!state.tokens || !state.tokens.length) {
          if (typeof loadNetworkTokens === 'function') loadNetworkTokens(netId);
          else if (typeof NET_TOKENS !== 'undefined') {
            state.tokens = (NET_TOKENS[netId] || NET_TOKENS.base || []).map(function (t) {
              return Object.assign({}, t);
            });
          }
        }
        if (!state.balances) state.balances = {};
        if (typeof renderHome === 'function') renderHome();
      }

      // 2) Force-paint rows if list still empty (direct DOM write)
      var list = (typeof window.ensureTokenListEl === 'function')
        ? window.ensureTokenListEl()
        : document.getElementById('tokenList');
      if (list && !list.querySelector('.token-row') && state.tokens && state.tokens.length) {
        var html = state.tokens.map(function (t) {
          var bal = Number((state.balances && state.balances[t.id]) || 0) || 0;
          var price = Number((state.prices && state.prices[t.id]) || 0) || 0;
          if ((t.symbol === 'USDC' || t.symbol === 'USDT') && !price) price = 1;
          var usd = bal * price;
          var sub = netId === 'sol' ? 'Solana' : String(netId).toUpperCase();
          return (
            '<div class="token-row" data-tid="' + (t.id || '') + '" style="display:flex;align-items:center;gap:12px;padding:12px 8px;border-bottom:1px solid rgba(42,49,60,.5)">' +
            '<img src="' + (t.icon || '') + '" width="36" height="36" style="border-radius:50%;background:#1a1f2e" onerror="this.style.opacity=.3">' +
            '<div style="flex:1"><div style="font-weight:600">' + (t.symbol || t.id) + '</div>' +
            '<div style="font-size:12px;opacity:.6">' + sub + '</div></div>' +
            '<div style="text-align:right"><div style="font-weight:600">' + bal + '</div>' +
            '<div style="font-size:12px;opacity:.6">$' + usd.toFixed(2) + '</div></div></div>'
          );
        }).join('');
        list.innerHTML = html;
        list.style.display = 'flex';
        list.style.flexDirection = 'column';
        list.style.minHeight = '120px';
        list.style.visibility = 'visible';
        list.style.opacity = '1';
      }

      if (netId === 'sol' && typeof window.forceSolRows === 'function') {
        try { window.forceSolRows(true); } catch (e) {}
      }
      if (reason && window.BR_DEBUG) {
        var nRows = list ? list.querySelectorAll('.token-row').length : -1;
        console.log('[ensureHomeTokenList]', reason, 'net=', netId, 'tokens=', (state.tokens || []).length, 'rows=', nRows);
      }
    } catch (e) {
      console.warn('[ensureHomeTokenList]', e);
    }
  }
  window.ensureHomeTokenList = ensureHomeTokenList;

  // Run after boot at several delays (covers PIN unlock / deferred scripts / late overrides)
  [500, 1200, 2500, 4000].forEach(function (ms) {
    setTimeout(function () {
      try {
        if (state && state.address) ensureHomeTokenList('boot+' + ms);
        else if (state) ensureHomeTokenList('boot-noaddr+' + ms);
      } catch (e) {}
    }, ms);
  });

  // When navigating to home, ensure tokens
  var _hookShow = function () {
    if (typeof showScreen !== 'function') return;
    if (showScreen._ensureHooked) return;
    var _ss = showScreen;
    window.showScreen = function (name) {
      var r = _ss.apply(this, arguments);
      if (name === 'home') {
        setTimeout(function () { ensureHomeTokenList('showScreen-home'); }, 80);
      }
      return r;
    };
    window.showScreen._ensureHooked = true;
  };
  _hookShow();
  setTimeout(_hookShow, 1500);
})();


/* ============================================================
   PIN CONTROLLER FINAL — single path, SHA-256 only
   Overrides all earlier pinKey / processPin / setupPin confusion
   ============================================================ */
(function PinControllerFinal() {
  'use strict';

  async function digestPin(pin) {
    pin = String(pin || '');
    var enc = new TextEncoder();
    var buf = await crypto.subtle.digest(
      'SHA-256',
      enc.encode('BaseRocky.PIN.v1|' + pin + '|' + pin.length)
    );
    return Array.from(new Uint8Array(buf))
      .map(function (b) { return b.toString(16).padStart(2, '0'); })
      .join('');
  }

  async function savePin(pin) {
    pin = String(pin);
    if (pin.length !== 6) throw new Error('PIN must be 6 digits');
    // Fast path: SHA-256 only (instant unlock later)
    var d = await digestPin(pin);
    localStorage.setItem('br_pin_sha256', d);
    localStorage.setItem('br_pin_enabled', '1');
    state.pinEnabled = true;
    state.pinHash = 'sha256';
    state._unlocked = true;
    // Heavy crypto in background — must not block UI / toast
    setTimeout(function () {
      Promise.resolve()
        .then(function () {
          if (typeof PinCrypto !== 'undefined' && PinCrypto.setup) return PinCrypto.setup(pin);
        })
        .then(function () {
          if (typeof brAutoMigrateSecrets === 'function') brAutoMigrateSecrets(pin);
        })
        .catch(function (e) {
          if (window.BR_DEBUG) console.warn('[PIN] bg encrypt', e);
        });
    }, 50);
    return true;
  }

  async function checkPin(pin) {
    pin = String(pin || '');
    var stored = localStorage.getItem('br_pin_sha256');
    if (!stored) {
      // No modern digest — try PinCrypto / legacy once
      try {
        if (typeof verifyPinAny === 'function') return !!(await verifyPinAny(pin));
      } catch (e) {}
      return false;
    }
    var d = await digestPin(pin);
    return d === stored;
  }

  function getPin() {
    return String(state._pinBuf || state.pinBuffer || '');
  }

  function clearBuf() {
    state._pinBuf = '';
    state.pinBuffer = '';
    try {
      if (typeof updatePinDots === 'function') updatePinDots();
    } catch (e) {}
  }

  function setMode(mode) {
    state._pinMode = mode;
    state.pinMode = mode;
  }

  function getMode() {
    return state._pinMode || state.pinMode || 'unlock';
  }

  function showErr(msg) {
    var err = document.getElementById('pinErr');
    if (err) err.textContent = msg || '';
  }

  function hideOverlay() {
    try {
      if (typeof hidePinOverlay === 'function') hidePinOverlay();
      else {
        var ov = document.getElementById('pinOverlay');
        if (ov) {
          ov.classList.remove('show');
          ov.style.display = 'none';
        }
      }
    } catch (e) {}
  }

  async function onComplete() {
    var pin = getPin();
    var mode = getMode();
    showErr('');

    if (pin.length !== 6) {
      showErr('PIN harus 6 digit');
      clearBuf();
      return;
    }

    // --- SETUP ---
    if (mode === 'setup') {
      state._pinTemp = pin;
      state.pinTemp = pin;
      clearBuf();
      setMode('confirm');
      var t = document.getElementById('pinTitle');
      var h = document.getElementById('pinHint');
      if (t) t.textContent = 'Konfirmasi PIN';
      if (h) h.textContent = 'Ulangi PIN yang sama';
      return;
    }

    // --- CONFIRM ---
    if (mode === 'confirm') {
      var first = state._pinTemp || state.pinTemp || '';
      if (pin !== first) {
        showErr('PIN tidak cocok');
        state._pinTemp = '';
        state.pinTemp = '';
        clearBuf();
        setMode('setup');
        var t2 = document.getElementById('pinTitle');
        if (t2) t2.textContent = 'Buat PIN baru';
        return;
      }
      try {
        await savePin(pin);
        hideOverlay();
        clearBuf();
        setMode(null);
        state._pinTemp = '';
        state.pinTemp = '';
        if (typeof showToast === 'function') showToast('PIN berhasil disimpan', 'success');
        try {
          if (typeof openSecurityCenter === 'function') openSecurityCenter();
        } catch (e) {}
      } catch (e) {
        showErr('Gagal simpan PIN');
        clearBuf();
      }
      return;
    }

    // --- CHANGE: verify old ---
    if (mode === 'change' || mode === 'change_old') {
      var okOld = await checkPin(pin);
      if (!okOld) {
        showErr('PIN lama salah');
        clearBuf();
        return;
      }
      clearBuf();
      state._pinTemp = '';
      setMode('setup');
      state._changePinFlow = true;
      var t3 = document.getElementById('pinTitle');
      var h3 = document.getElementById('pinHint');
      if (t3) t3.textContent = 'PIN baru';
      if (h3) h3.textContent = 'Masukkan 6 digit PIN baru';
      return;
    }

    // --- UNLOCK / VERIFY ---
    if (mode === 'unlock' || mode === 'verify' || !mode) {
      var ok = await checkPin(pin);
      if (!ok) {
        showErr('PIN salah');
        clearBuf();
        state._pinFails = (state._pinFails || 0) + 1;
        if (state._pinFails >= 3) {
          var err = document.getElementById('pinErr');
          if (err) {
            err.innerHTML =
              'PIN salah · <a href="#" id="pinResetLink" style="color:#00D4AA">Reset PIN</a>';
            setTimeout(function () {
              var a = document.getElementById('pinResetLink');
              if (a)
                a.onclick = function (ev) {
                  ev.preventDefault();
                  if (confirm('Hapus PIN? Pastikan seed sudah di-backup.')) {
                    try {
                      if (typeof clearPinLock === 'function') clearPinLock();
                      else {
                        localStorage.removeItem('br_pin_sha256');
                        localStorage.removeItem('br_pin_enabled');
                        localStorage.removeItem('br_pin_verifier_v2');
                      }
                      hideOverlay();
                      if (typeof showToast === 'function') showToast('PIN dihapus');
                    } catch (e2) {}
                  }
                };
            }, 30);
          }
        }
        return;
      }
      // Success — unlock UI immediately (no waiting for PBKDF2)
      state._unlocked = true;
      state._lastActive = Date.now();
      state._pinFails = 0;
      hideOverlay();
      clearBuf();
      setMode(null);
      if (state._pinCallback) {
        var cb = state._pinCallback;
        state._pinCallback = null;
        try { cb(); } catch (e) {}
      } else {
        try {
          if (typeof showToast === 'function') showToast('Dompet terbuka', 'success');
        } catch (e) {}
        try {
          if (state.address && typeof goDefaultHomePage === 'function') goDefaultHomePage();
          else if (state.address && typeof showScreen === 'function') showScreen('home');
        } catch (e) {}
      }
      // Background: unlock vault / restore keys (may be slow)
      setTimeout(function () {
        Promise.resolve()
          .then(function () {
            if (typeof PinCrypto !== 'undefined' && PinCrypto.verify) return PinCrypto.verify(pin);
          })
          .then(function () {
            if (typeof restoreWalletAfterPin === 'function') return restoreWalletAfterPin(pin);
          })
          .then(function () {
            if (typeof brAutoMigrateSecrets === 'function') brAutoMigrateSecrets(pin);
          })
          .then(function () {
            if (!state.address && typeof loadWallet === 'function') {
              try { loadWallet(); } catch (e) {}
            }
            if (state.address && typeof refreshBalances === 'function') {
              try { refreshBalances(false); } catch (e) {}
            }
          })
          .catch(function (e) {
            if (window.BR_DEBUG) console.warn('[PIN] bg unlock', e);
          });
      }, 30);
      return;
    }
  }

  // ---- Override input handler ----
  window.pinKeyPress = function (k) {
    if (!state._pinBuf) state._pinBuf = '';
    if (k === '⌫') {
      state._pinBuf = state._pinBuf.slice(0, -1);
      state.pinBuffer = state._pinBuf;
      if (typeof updatePinDots === 'function') updatePinDots();
      return;
    }
    if (!/^[0-9]$/.test(k)) return;
    if (state._pinBuf.length >= 6) return;
    state._pinBuf += k;
    state.pinBuffer = state._pinBuf; // ALWAYS same reference string
    if (typeof updatePinDots === 'function') updatePinDots();
    if (state._pinBuf.length === 6) {
      setTimeout(function () {
        onComplete().catch(function (e) {
          console.warn('[PIN]', e);
          showErr('Error PIN');
          clearBuf();
        });
      }, 80);
    }
  };
  window.pinKey = window.pinKeyPress;

  // ---- Override processPin / handlePinComplete ----
  window.processPin = function () {
    return onComplete();
  };
  window.handlePinComplete = function () {
    return onComplete();
  };

  // ---- Override setupPin ----
  window.setupPin = function () {
    try {
      var mb = document.getElementById('modalBackdrop');
      if (mb) mb.classList.remove('show');
    } catch (e) {}
    setMode('setup');
    state._pinTemp = '';
    state.pinTemp = '';
    clearBuf();
    if (typeof showPinOverlay === 'function') {
      showPinOverlay('Buat PIN baru', 'Masukkan 6 digit PIN');
    } else {
      var ov = document.getElementById('pinOverlay');
      var t = document.getElementById('pinTitle');
      var h = document.getElementById('pinHint');
      if (t) t.textContent = 'Buat PIN baru';
      if (h) h.textContent = 'Masukkan 6 digit PIN';
      if (ov) {
        ov.classList.add('show');
        ov.style.display = 'flex';
      }
      if (typeof buildPinPad === 'function') buildPinPad();
    }
  };

  // Rebuild pad to bind our handler
  if (typeof buildPinPad === 'function') {
    var _bp = buildPinPad;
    window.buildPinPad = function () {
      _bp.apply(this, arguments);
      var pad = document.getElementById('pinPad');
      if (!pad) return;
      pad.querySelectorAll('button[data-pk]').forEach(function (b) {
        b.onclick = function (e) {
          e.preventDefault();
          e.stopPropagation();
          window.pinKeyPress(b.getAttribute('data-pk'));
        };
      });
    };
  }

  // Export helpers for console recovery
  window.PinAuth = {
    setup: savePin,
    verify: checkPin,
    hasPin: function () {
      return !!(localStorage.getItem('br_pin_sha256') || localStorage.getItem('br_pin_enabled'));
    },
    lock: function () {
      state._unlocked = false;
      if (typeof PinCrypto !== 'undefined' && PinCrypto.lock) PinCrypto.lock();
    },
    /** Emergency: set PIN from console — PinAuth.forceSet('123456') */
    forceSet: async function (pin) {
      await savePin(String(pin));
      if (typeof showToast === 'function') showToast('PIN dipaksa disetel', 'success');
      return true;
    },
    digest: digestPin
  };

  console.log('%c[PIN] Controller final aktif (SHA-256)', 'color:#00D4AA');
})();


